/* ---- notes-ks3.js ---- */
/* Geodesic: study notes and ten-problem practice sets, KS3. Shape: WL.notes[id] = {big, sec:[{h,p,eq,after,list,box,warn}], eqs:[[tex, meaning]], how, sum, probs:[{l,q,a,s}]} */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'ks3-speed': {
      big: 'Speed answers one question: how much distance is covered each second? Once you can read it off a graph, a whole journey (when it sped up, when it stopped, how far it went) fits in one picture.',
      sec: [
        { h: 'What speed measures', p: ['Speed is the distance travelled per unit of time. If you walk 140 m in 100 s, every second you cover 1.4 m on average, so your speed is 1.4 m/s. The unit tells you the recipe: metres divided by seconds.', 'The same speed can be written in different units. One kilometre per hour is 1000 m in 3600 s, so 1 m/s = 3.6 km/h. To go from km/h to m/s, divide by 3.6; to go back, multiply by 3.6. Walking pace 1.4 m/s is about 5 km/h.'], eq: R`\text{speed} = \frac{\text{distance}}{\text{time}},\qquad v = \frac{d}{t}`, box: '**Speed or velocity?** Speed is just “how fast”. Velocity is speed in a stated direction. A car going round a roundabout at a steady 20 km/h has constant speed but changing velocity.' },
        { h: 'Distance–time graphs', p: ['Plot distance up the side and time along the bottom. If an object moves at a steady speed, it adds the same distance every second, so the points lie on a straight line.', 'The steepness of that line is the speed. Pick two points on the line and divide the rise (change in distance) by the run (change in time). A steeper line means a faster object; a flat line means it is not moving at all; a line that curves upwards means it is speeding up.'], eq: R`\text{gradient} = \frac{\Delta d}{\Delta t} = v`, after: ['For a curved line the speed is different at every moment. The speed at one instant is the gradient of the tangent, the straight line that just touches the curve there.'] },
        { h: 'Average speed is not the average of the speeds', p: ['Average speed is total distance divided by total time. It is tempting to average the speeds instead, but that is usually wrong, because you spend longer at the slower speed.', 'Drive 30 km to town at 30 km/h (1 hour) and come back at 60 km/h (half an hour). You cover 60 km in 1.5 hours, so the average speed is 40 km/h, not 45 km/h.'] },
        { h: 'Speed–time graphs', p: ['Now put speed up the side. A flat line means constant speed. A sloping line means the speed is changing: its gradient is the acceleration, how many m/s the speed gains each second.', 'The area under a speed–time graph is the distance travelled, because distance = speed × time is a rectangle’s height × width. For a sloping line, split the area into rectangles and triangles.'] },
        { h: 'Measuring speed honestly', p: ['A stopwatch adds your reaction time, about 0.2 s, at the start and at the end. Over a 2 m roll lasting 1.6 s, a 0.2 s error is 12% of the time, so the speed could be anywhere from about 1.1 to 1.4 m/s.', 'Light gates, which time automatically, or a video with a frame counter remove most of that error. Timing over a longer distance also helps: the same 0.2 s is a smaller fraction of a longer time.'], warn: '**Hidden assumption.** “Speed = distance ÷ time” gives the average over the whole interval. It says nothing about what happened in between: a car averaging 50 km/h may have stopped twice and gone 80 km/h in between.' }
      ],
      eqs: [[R`v = \frac{d}{t}`, 'speed v in m/s, distance d in m, time t in s'], [R`d = v\,t`, 'distance covered at a steady speed'], [R`t = \frac{d}{v}`, 'time needed to cover a distance'], [R`\bar v = \frac{\text{total } d}{\text{total } t}`, 'average speed for a whole journey'], [R`1\ \text{m/s} = 3.6\ \text{km/h}`, 'unit conversion'], [R`a = \frac{\Delta v}{\Delta t}`, 'acceleration: gradient of a speed–time graph, in m/s²']],
      how: ['Write down what you know and what you want, with units.', 'Convert so the units match (km and h, or m and s, never a mixture).', 'Pick the arrangement of v = d/t that has the unknown on its own.', 'For graphs, decide first: distance–time (use the gradient) or speed–time (gradient is acceleration, area is distance).', 'Check the answer is sensible: people walk about 1.5 m/s, cars on a motorway about 30 m/s.'],
      sum: ['Speed is distance per unit time: v = d/t, in m/s or km/h (1 m/s = 3.6 km/h).', 'On a distance–time graph the gradient is the speed; flat means stopped.', 'On a speed–time graph the gradient is the acceleration and the area is the distance.', 'Average speed = total distance ÷ total time, never the average of the speeds.', 'Timing by hand adds about 0.2 s of reaction-time error; light gates remove it.'],
      probs: [
        { l: 1, q: 'A cyclist travels 600 m in 2 minutes. What is her average speed in m/s?', a: '5 m/s', s: ['Convert the time: 2 min = 120 s.', 'v = d/t = 600 m ÷ 120 s = 5 m/s.'] },
        { l: 1, q: 'Convert 72 km/h into m/s.', a: '20 m/s', s: ['1 m/s = 3.6 km/h, so divide by 3.6.', '72 ÷ 3.6 = 20 m/s.'] },
        { l: 1, q: 'A train runs at a steady 50 m/s for 30 s. How far does it go?', a: '1500 m', s: ['d = vt = 50 m/s × 30 s = 1500 m (1.5 km).'] },
        { l: 1, q: 'A distance–time graph is a straight line from (0 s, 0 m) to (40 s, 200 m). What is the speed?', a: '5 m/s', s: ['Gradient = rise ÷ run = 200 m ÷ 40 s.', 'v = 5 m/s.'] },
        { l: 2, q: 'A runner jogs 3 km at 10 km/h and then walks 2 km at 5 km/h. Find the total time and the average speed.', a: '0.7 h (42 min); 7.1 km/h', s: ['Jogging time = 3 ÷ 10 = 0.3 h.', 'Walking time = 2 ÷ 5 = 0.4 h.', 'Total: 5 km in 0.7 h, so average speed = 5 ÷ 0.7 = 7.1 km/h.', 'The simple average of the speeds, 7.5 km/h, is wrong because more time is spent walking.'] },
        { l: 2, q: 'A car drives to town at 30 km/h and returns along the same road at 60 km/h. What is its average speed for the round trip?', a: '40 km/h', s: ['Call the one-way distance D.', 'Time out = D/30, time back = D/60, total = D/30 + D/60 = D/20.', 'Average = 2D ÷ (D/20) = 40 km/h, whatever D is.'] },
        { l: 2, q: 'A distance–time graph has three straight sections: 0–10 s rising from 0 to 40 m; 10–20 s flat at 40 m; 20–25 s rising from 40 m to 100 m. Find the speed in each section and the average speed.', a: '4 m/s, 0 m/s, 12 m/s; average 4 m/s', s: ['Section 1: 40 m ÷ 10 s = 4 m/s.', 'Section 2: flat, so 0 m/s (stopped).', 'Section 3: 60 m ÷ 5 s = 12 m/s, the steepest and fastest.', 'Average: 100 m ÷ 25 s = 4 m/s.'] },
        { l: 2, q: 'A speed–time graph shows a scooter speeding up steadily from rest to 8 m/s in 4 s, then moving at 8 m/s for 6 s. How far does it travel?', a: '64 m', s: ['Distance is the area under the graph.', 'Triangle: ½ × 4 s × 8 m/s = 16 m.', 'Rectangle: 6 s × 8 m/s = 48 m.', 'Total = 64 m.'] },
        { l: 3, q: 'You see lightning and hear the thunder 6.0 s later. Sound travels at 340 m/s. How far away is the storm, and why can you ignore the time the light takes?', a: 'About 2.0 km; light takes only about 7 μs', s: ['Distance = 340 m/s × 6.0 s = 2040 m ≈ 2.0 km.', 'Light at 3.0 × 10^8 m/s covers 2040 m in 2040 ÷ (3.0 × 10^8) ≈ 6.8 × 10^{−6} s.', 'That is about a millionth of the 6 s delay, far smaller than your reaction time, so it can be ignored.'] },
        { l: 3, q: 'A student times a ball rolling 2.0 m with a stopwatch and gets 1.6 s. Her total timing could be wrong by up to 0.2 s either way. What range of speeds is possible, and how could she do better?', a: 'About 1.1 to 1.4 m/s (measured 1.25 m/s)', s: ['Measured speed: 2.0 ÷ 1.6 = 1.25 m/s.', 'True time between 1.4 s and 1.8 s.', 'Speeds: 2.0 ÷ 1.8 = 1.11 m/s up to 2.0 ÷ 1.4 = 1.43 m/s.', 'Better: use light gates or a slow-motion video, time over a longer distance, and repeat to average out random errors.'] }
      ]
    },

    'ks3-moments': {
      big: 'Forces do not only push things along; they also turn them. Doors, spanners, seesaws, wheelbarrows and cranes all work by one rule: the turning effect of a force grows with how far from the pivot it acts.',
      sec: [
        { h: 'The moment of a force', p: ['The turning effect of a force about a pivot is called its moment. It equals the force multiplied by the perpendicular distance from the pivot to the line along which the force acts.', 'That is why door handles are on the side away from the hinges: the same push, applied far from the pivot, makes a bigger moment. Push right next to the hinge and the door hardly moves.'], eq: R`M = F \times d\qquad (\text{N m})`, box: '**Perpendicular distance.** Only the distance measured at right angles to the force counts. Pull a spanner along its own length and the perpendicular distance is zero, so there is no turning effect at all.' },
        { h: 'Clockwise and anticlockwise', p: ['Each force tries to turn the object one way or the other about the pivot. On a seesaw a child on the left turns it anticlockwise, a child on the right turns it clockwise. A force acting straight through the pivot turns nothing.'] },
        { h: 'The principle of moments', p: ['If an object is balanced (not starting to turn), the total clockwise moment about any pivot equals the total anticlockwise moment. This is the principle of moments.', 'For two masses on a beam, each weight is mg, and g appears on both sides, so it cancels: you can balance masses directly.'], eq: R`\sum M_{\text{clockwise}} = \sum M_{\text{anticlockwise}}\qquad m_1 d_1 = m_2 d_2` },
        { h: 'Levers: trading force for distance', p: ['A lever lets a small force balance a large one by acting further from the pivot. A wheelbarrow, a crowbar, scissors and your forearm are all levers.', 'Nothing comes for free. If your hand is three times further from the pivot than the load, you push with a third of the force, but your hand moves three times as far. The energy you put in (force × distance moved) is the same as the energy given to the load, minus any friction.'] },
        { h: 'Centre of mass and toppling', p: ['An object’s weight acts as if it all pulled down at one point, the centre of mass. A uniform ruler’s centre of mass is at its middle.', 'An object topples when the line of its weight passes outside its base: the weight then makes a moment that turns it further over. A low centre of mass and a wide base make things stable, which is why racing cars are low and wide, and why a tall loaded bookcase is fixed to the wall.'],
          warn: '**Hidden assumptions, and a surprise from real joints.** The principle of moments assumes a rigid lever that does not bend, a pivot with no friction, and forces acting at single points. It also only works if you include every force, including the lever’s own weight acting at its centre of mass (problem 9). A common mistake is to think a joint only carries the weight above it. When engineers built sensors into artificial hip joints and measured the forces while people walked, they found about two and a half times body weight at each step. The hip muscles pull on very short lever arms, so by the principle of moments they must pull much harder than the weight they balance, and the joint carries both.' }
      ],
      eqs: [[R`M = F d`, 'moment in N m; force F in N; perpendicular distance d in m'], [R`W = m g`, 'weight in N; mass m in kg; g ≈ 9.8 N/kg (often 10 N/kg)'], [R`\sum M_\circlearrowright = \sum M_\circlearrowleft`, 'balance condition (principle of moments)'], [R`m_1 d_1 = m_2 d_2`, 'two masses balancing on a beam (g cancels)']],
      how: ['Mark the pivot and draw every force where it acts, including the weight of the beam at its centre if it is not negligible.', 'Measure each distance from the pivot, at right angles to the force.', 'Sort the forces into clockwise and anticlockwise.', 'Set the totals equal and solve for the unknown.', 'Check: the bigger force must be the one nearer the pivot.'],
      sum: ['Moment = force × perpendicular distance from the pivot, in N m.', 'Balanced object: total clockwise moment = total anticlockwise moment.', 'Levers let a small force balance a large one, at the cost of moving further.', 'Weight acts at the centre of mass; an object topples when that line falls outside its base.', 'Low centre of mass and wide base mean stability.'],
      probs: [
        { l: 1, q: 'A 20 N force pushes at right angles on a lever, 0.5 m from the pivot. What is its moment?', a: '10 N m', s: ['M = Fd = 20 N × 0.5 m = 10 N m.'] },
        { l: 1, q: 'Why is a door handle fixed on the edge furthest from the hinges?', a: 'A larger distance gives a larger moment for the same force', s: ['The moment is F × d. Placing the handle far from the hinge (the pivot) makes d large.', 'So a smaller push produces the turning effect needed to open the door.'] },
        { l: 1, q: 'A spanner is 0.25 m long. A nut needs a moment of 30 N m to undo it. What force must you apply at the end, at right angles?', a: '120 N', s: ['F = M ÷ d = 30 N m ÷ 0.25 m = 120 N.'] },
        { l: 2, q: 'A child weighing 400 N sits 1.5 m from the pivot of a seesaw. Where must an adult weighing 600 N sit to balance?', a: '1.0 m from the pivot, on the other side', s: ['Anticlockwise moment = 400 × 1.5 = 600 N m.', 'Clockwise moment = 600 × d.', 'Balance: 600 d = 600, so d = 1.0 m.'] },
        { l: 2, q: 'A metre rule is pivoted at its 50 cm mark. A 2.0 N weight hangs at the 10 cm mark. Where must a 5.0 N weight hang to balance it?', a: 'At the 66 cm mark', s: ['The 2.0 N weight is 40 cm = 0.40 m left of the pivot: moment 0.80 N m.', 'The 5.0 N weight needs 5.0 × d = 0.80, so d = 0.16 m.', 'That is 16 cm right of the pivot: the 66 cm mark.', 'The rule’s own weight acts at the pivot, so it makes no moment.'] },
        { l: 2, q: 'In a wheelbarrow the load of 600 N acts 0.40 m from the wheel axle, and the handles are 1.2 m from the axle. What upward force at the handles lifts it?', a: '200 N', s: ['The axle is the pivot.', 'Load moment = 600 × 0.40 = 240 N m.', 'F × 1.2 = 240, so F = 200 N: a third of the load, because the hands are three times further away.'] },
        { l: 2, q: 'On one side of a seesaw sit a 300 N child at 2.0 m and a 200 N child at 1.0 m. Where must a 500 N child sit on the other side?', a: '1.6 m from the pivot', s: ['Total anticlockwise moment = 300 × 2.0 + 200 × 1.0 = 800 N m.', '500 × d = 800, so d = 1.6 m.'] },
        { l: 2, q: 'A 3.0 kg mass hangs 0.20 m from a pivot. What mass hung 0.30 m from the pivot on the other side balances it?', a: '2.0 kg', s: ['g cancels, so m₁d₁ = m₂d₂.', '3.0 × 0.20 = m × 0.30, so m = 2.0 kg.'] },
        { l: 3, q: 'A uniform plank 4.0 m long and weighing 200 N rests on a pivot 1.0 m from one end. What weight placed on that short end keeps it balanced?', a: '200 N', s: ['The plank’s weight acts at its centre, 2.0 m from either end.', 'The centre is 1.0 m from the pivot, on the long side: clockwise moment 200 × 1.0 = 200 N m.', 'The weight W on the short end is 1.0 m from the pivot: W × 1.0 = 200, so W = 200 N.', 'Ignoring the plank’s own weight here would give the absurd answer of zero.'] },
        { l: 3, q: 'A crane holds a 2000 N load 12 m from its tower, balanced by a counterweight 4.0 m from the tower on the other side. Find the counterweight. If the load is then moved out to 15 m, what happens?', a: '6000 N; an unbalanced moment of 6000 N m tips the crane towards the load', s: ['Balance: 2000 × 12 = W × 4.0, so W = 6000 N.', 'At 15 m the load’s moment is 2000 × 15 = 30 000 N m, against 6000 × 4.0 = 24 000 N m.', 'The extra 6000 N m must be supplied by the tower and its foundations; if they cannot, the crane topples.', 'This is why cranes carry load-moment limits: the safe load falls as the distance grows.'] }
      ]
    },

    'ks3-waves': {
      big: 'A wave carries energy from one place to another without carrying the material with it. Ripples, sound, light and earthquakes look different, but the same three numbers describe them all: speed, frequency and wavelength.',
      sec: [
        { h: 'What actually moves', p: ['Drop a cork on a pond as a ripple passes. The cork bobs up and down but stays where it is: the water does not travel across the pond, the pattern does. A Mexican wave in a stadium is the same: each person only stands up and sits down, yet the wave runs round the ground.', 'So a wave is a travelling disturbance. What travels is energy and the shape of the disturbance, not the stuff.'] },
        { h: 'Transverse and longitudinal waves', p: ['In a transverse wave the particles move at right angles to the direction the wave travels: ripples on water, waves on a rope, and light.', 'In a longitudinal wave the particles move backwards and forwards along the direction of travel, bunching into compressions and spreading into rarefactions. Sound is longitudinal: a loudspeaker cone pushes and pulls on the air in front of it.'] },
        { h: 'Describing a wave', list: ['Amplitude: the largest distance a particle moves from its rest position. Bigger amplitude carries more energy (louder sound, brighter light).', 'Wavelength λ: the length of one complete wave, for example crest to crest, in metres.', 'Period T: the time for one complete oscillation, in seconds.', 'Frequency f: the number of oscillations each second, in hertz (Hz). f = 1/T.'] },
        { h: 'Why v = fλ', p: ['In one period T, every particle completes one oscillation, and the pattern then looks exactly as it did at the start. So in time T each crest has moved forward by exactly one wavelength λ.', 'Speed is distance over time, so the wave speed is λ/T. Since 1/T = f, the wave speed is frequency times wavelength.'], eq: R`v = \frac{\lambda}{T} = f\lambda`, after: ['For a wave whose speed is fixed by the material (sound in air, about 340 m/s), a higher frequency means a shorter wavelength.'] },
        { h: 'Sound', p: ['Sound needs particles to pass the vibration on, so it cannot cross a vacuum. It travels fastest where particles are tightly linked: about 340 m/s in air, 1500 m/s in water and 5000 m/s in steel.', 'Pitch is set by frequency and loudness by amplitude. Young people hear from about 20 Hz to 20 000 Hz; the top limit falls with age. Sound above 20 000 Hz is ultrasound, used for baby scans and sonar.', 'An echo is a reflected sound. The sound goes there and back, so the distance to the reflector is speed × time ÷ 2.'],
          warn: '**Testing "sound needs particles" is harder than it looks.** In 1660 Robert Boyle put a ticking watch inside a glass jar and pumped the air out: the ticking grew faint, and came back when air was let in. But it never quite vanished. His pump left some air behind, and vibration could still travel through whatever held the watch, because solids carry sound well. Earlier experimenters who rang a bell in a near-vacuum and heard it clearly had concluded that sound needs no air at all: their bells were fixed to the apparatus. Hang the bell on threads and use a good pump, and the sound almost disappears. The other hidden assumption is a fixed speed of sound: it rises by about 0.6 m/s for every degree Celsius (problem 10).' }
      ],
      eqs: [[R`f = \frac{1}{T}`, 'frequency in Hz from period T in s'], [R`v = f\lambda`, 'wave speed in m/s; wavelength λ in m'], [R`v = \frac{d}{t}`, 'speed from distance and time'], [R`d = \frac{v\,t}{2}`, 'distance to a reflector from an echo time t']],
      how: ['List v, f, λ and T with units; at least two must be known.', 'If you are given a period, turn it into a frequency first: f = 1/T.', 'Use v = fλ in the arrangement that isolates the unknown.', 'For echoes, remember the sound travels there and back.', 'Sanity check: audible sound in air has wavelengths from about 2 cm to 17 m.'],
      sum: ['Waves transfer energy, not matter.', 'Transverse: vibration at right angles to travel (light, ripples). Longitudinal: along it (sound).', 'f = 1/T and v = fλ for every wave.', 'Sound needs a medium; it is fastest in solids.', 'Echo distance = speed × time ÷ 2.'],
      probs: [
        { l: 1, q: 'A wave has frequency 5.0 Hz and wavelength 2.0 m. What is its speed?', a: '10 m/s', s: ['v = fλ = 5.0 × 2.0 = 10 m/s.'] },
        { l: 1, q: 'What is the period of a 50 Hz wave?', a: '0.020 s', s: ['T = 1/f = 1/50 = 0.020 s.'] },
        { l: 1, q: 'Is sound a transverse or a longitudinal wave? Explain.', a: 'Longitudinal', s: ['The air particles vibrate backwards and forwards along the direction the sound travels.', 'This makes compressions and rarefactions, which is the mark of a longitudinal wave.'] },
        { l: 2, q: 'Middle C has a frequency of 262 Hz. The speed of sound is 340 m/s. What is its wavelength?', a: '1.30 m', s: ['λ = v/f = 340 ÷ 262 = 1.30 m.'] },
        { l: 2, q: 'A ship’s sonar pulse returns 0.80 s after it was sent. Sound travels at 1500 m/s in sea water. How deep is the sea?', a: '600 m', s: ['The pulse travels down and back: total distance = 1500 × 0.80 = 1200 m.', 'Depth = 1200 ÷ 2 = 600 m.'] },
        { l: 2, q: 'Ripples pass a post at 3 per second, and the crests are 0.15 m apart. How fast are the ripples moving?', a: '0.45 m/s', s: ['f = 3.0 Hz, λ = 0.15 m.', 'v = fλ = 3.0 × 0.15 = 0.45 m/s.'] },
        { l: 2, q: 'Why can light reach us from the Sun, but the sound of its explosions cannot?', a: 'Sound needs a medium; light does not', s: ['Sound is passed on by particles bumping into each other, and space between the Sun and Earth is almost empty.', 'Light is an electromagnetic wave: changing electric and magnetic fields that need no material at all.'] },
        { l: 2, q: 'People hear from 20 Hz to 20 000 Hz. Find the range of wavelengths in air (v = 340 m/s).', a: 'From 17 m down to 1.7 cm', s: ['At 20 Hz: λ = 340 ÷ 20 = 17 m.', 'At 20 000 Hz: λ = 340 ÷ 20 000 = 0.017 m = 1.7 cm.'] },
        { l: 3, q: 'You stand 170 m from a cliff and clap. How long until you hear the echo? If you clap again every time you hear an echo, how many claps do you make in a minute?', a: '1.0 s; 60 claps per minute', s: ['The sound goes 170 m there and 170 m back: 340 m.', 'Time = 340 ÷ 340 = 1.0 s.', 'One clap per second: 60 in a minute. This is a real method Mersenne used in the 1600s to measure the speed of sound.'] },
        { l: 3, q: 'An ultrasonic range-finder works out distance as d = v₀t/2 using v₀ = 331 m/s (air at 0 °C). On a 30 °C day sound actually travels at 349 m/s. By how much is its reading wrong, and in which direction?', a: 'About 5% too small', s: ['The echo comes back sooner on the warm day, because the sound is faster.', 'True distance = 349t/2; the reading = 331t/2.', 'Reading ÷ true = 331 ÷ 349 = 0.948, so the reading is about 5% too small.', 'Hidden assumption exposed: “speed of sound = 340 m/s” is only true near 15–20 °C; good range-finders measure the temperature and correct for it.'] }
      ]
    },

    'ks3-light': {
      big: 'Light travels in straight lines, astonishingly fast, and we see things because light from them enters our eyes. Reflection follows one simple law, the angle of incidence equals the angle of reflection, and that law explains every image in a flat mirror.',
      sec: [
        { h: 'Light travels in straight lines', p: ['Shadows have sharp edges because light travels in straight lines, so we can draw it as rays: straight lines with arrows. Light is also extremely fast: about 300 000 km every second (3.0 × 10^8 m/s). Sunlight takes about 8.3 minutes to reach us.', 'Light can travel through empty space. It does not need air or anything else to carry it.'] },
        { h: 'How we see', p: ['Luminous objects, like the Sun, a flame or a screen, give out their own light. Everything else is seen because light from a source bounces off it and some of that light enters our eyes.', 'Our eyes do not send anything out. Old ideas that sight rays left the eye were tested and rejected: you cannot see in a sealed dark room, however hard you look.'] },
        { h: 'The law of reflection', p: ['Draw the normal, a line at 90° to the mirror where the ray hits it. The angle between the incoming ray and the normal is the angle of incidence i; the angle between the reflected ray and the normal is the angle of reflection r.', 'Experiments always give the same answer: the two angles are equal, and the incoming ray, the reflected ray and the normal all lie in the same flat plane.'], eq: R`i = r`, box: '**Measure from the normal.** The most common mistake is measuring from the mirror surface. A ray hitting the mirror at 20° to the surface has i = 70°.' },
        { h: 'Why i = r: light takes the shortest path', p: ['Reflect the eye’s position B to a point B′ the same distance behind the mirror. Any path from the lamp A to the mirror and then to B is exactly as long as the path to B′. The shortest route from A to B′ is a straight line, and that straight line crosses the mirror exactly where i = r.', 'So reflected light takes the shortest possible route. Hero of Alexandria noticed this two thousand years ago; it is the first example of a deep idea in physics, that nature picks paths that make some quantity smallest.'] },
        { h: 'Mirrors and rough surfaces', p: ['A mirror is very smooth, so parallel rays stay parallel after reflection (specular reflection) and you see a clear image. Paper is rough on a tiny scale: every bit of it still obeys i = r, but the normals point in all directions, so light is scattered everywhere (diffuse reflection). That is why you can see paper from any angle but cannot see your face in it.'] },
        { h: 'Images in a flat mirror', p: ['Rays from an object reflect and spread out as if they came from a point behind the mirror. Your brain traces them back in straight lines and sees an image there.', 'The image is the same size, the same way up, and as far behind the mirror as the object is in front. It is virtual: no light actually reaches the place behind the mirror, so it cannot be caught on a screen. Writing looks reversed because front and back are swapped.'],
          warn: '**Hidden assumptions: perfectly straight and instant.** The ray model assumes light travels in perfectly straight lines and arrives instantly. Neither is exactly true. In 1665 a book by Francesco Grimaldi reported that shadows have faint coloured fringes at their edges: light bends slightly round obstacles (diffraction), which matters when holes or edges are very small. And in 1676 Ole Rømer noticed that eclipses of Jupiter’s moon Io came later than predicted when Earth was farther from Jupiter, by up to about 22 minutes by his estimate: light takes time to cross the extra distance. The modern figure is about 17 minutes to cross Earth’s orbit, consistent with the 500 s light needs to reach us from the Sun (problem 7).' }
      ],
      eqs: [[R`i = r`, 'angle of incidence equals angle of reflection, both measured from the normal'], [R`c = 3.0\times10^{8}\ \text{m/s}`, 'speed of light in a vacuum'], [R`\text{image distance} = \text{object distance}`, 'flat (plane) mirror'], [R`d = c\,t`, 'distance light travels in time t']],
      how: ['Draw the normal at the point where the ray meets the mirror.', 'Measure angles from the normal, never from the mirror.', 'Use i = r for each reflection; with two mirrors, work one reflection at a time.', 'For images, reflect the object to the same distance behind the mirror and draw rays from the image to the eye.'],
      sum: ['Light travels in straight lines at 3.0 × 10^8 m/s and needs no medium.', 'We see objects because light from them enters our eyes.', 'Law of reflection: i = r, measured from the normal.', 'Reflected light takes the shortest path.', 'Plane-mirror images are virtual, upright, same size and as far behind as the object is in front.'],
      probs: [
        { l: 1, q: 'A ray hits a mirror with an angle of incidence of 35°. What is the angle of reflection?', a: '35°', s: ['By the law of reflection, r = i = 35°.'] },
        { l: 1, q: 'A ray strikes a mirror at 20° to the mirror surface. What are the angles of incidence and reflection?', a: '70° and 70°', s: ['Angles are measured from the normal, which is 90° to the surface.', 'i = 90° − 20° = 70°, and r = i = 70°.'] },
        { l: 1, q: 'A book gives out no light of its own. Why can you still see it?', a: 'Light from a source reflects off it into your eyes', s: ['Light from the Sun or a lamp hits the book.', 'Its rough surface reflects light diffusely in all directions, and some of that light enters your eyes.'] },
        { l: 2, q: 'You stand 1.5 m in front of a flat mirror. How far are you from your image?', a: '3.0 m', s: ['The image is 1.5 m behind the mirror.', 'Distance from you to the image = 1.5 + 1.5 = 3.0 m.'] },
        { l: 2, q: 'You walk towards a flat mirror at 1.0 m/s. How fast do you and your image approach each other?', a: '2.0 m/s', s: ['Your image moves towards the mirror at 1.0 m/s as you do.', 'You approach each other at 1.0 + 1.0 = 2.0 m/s.'] },
        { l: 2, q: 'Explain why a whitewashed wall reflects plenty of light but shows no image.', a: 'It reflects diffusely', s: ['Each tiny piece of the wall obeys i = r, but the surface is rough, so the normals point in many directions.', 'Parallel rays leave in all directions, so no set of rays appears to come from a single image point.'] },
        { l: 2, q: 'Light from the Sun takes about 500 s to reach Earth. Estimate the Sun’s distance.', a: '1.5 × 10^{11} m (150 million km)', s: ['d = ct = 3.0 × 10^8 m/s × 500 s = 1.5 × 10^{11} m.'] },
        { l: 3, q: 'Two mirrors meet at 90°. A ray hits the first at an angle of incidence of 30°. Find the angle of incidence at the second mirror and show that the ray leaves travelling back the way it came.', a: '60°; total turn 180°', s: ['After the first reflection the ray makes 60° with the first mirror’s surface.', 'The mirrors are perpendicular, so the ray meets the second mirror with an angle of incidence of 60°.', 'Each reflection turns the ray through 180° − 2i: 120° at the first and 60° at the second, 180° in total.', 'So the ray returns antiparallel to its original direction. Corner reflectors left on the Moon by Apollo astronauts use this to send laser beams straight back to Earth.'] },
        { l: 3, q: 'A person 1.60 m tall wants to see their whole body in a flat mirror on the wall. What is the shortest mirror that works, and does it depend on how far away they stand?', a: '0.80 m (half their height), at any distance', s: ['Light from the feet reflects to the eyes from a point halfway between the eyes and the feet, in height.', 'Light from the top of the head reflects from halfway between the eyes and the top of the head.', 'So the mirror must span half the person’s height: 0.80 m.', 'Moving away changes the angles but not these halfway heights, so the answer does not depend on distance.'] },
        { l: 3, q: 'A periscope has two parallel mirrors, each at 45° to the vertical tube. A horizontal ray enters the top. Trace it through.', a: 'It turns 90° at each mirror and leaves horizontal, lower down', s: ['At the top mirror the horizontal ray has i = 45°, so r = 45°: it turns through 90° and travels straight down the tube.', 'At the bottom mirror the vertical ray again has i = 45°: it turns 90° and leaves horizontally.', 'It exits travelling in its original direction, displaced downwards by the length of the tube, so you see over a wall.'] }
      ]
    },

    'ks3-circuits': {
      big: 'An electric circuit is an energy delivery system. Current tells you how much charge flows past each second; potential difference (voltage) tells you how much energy each unit of charge carries from the cell to the components. Multiply them and you get the power.',
      sec: [
        { h: 'Charge and current', p: ['Electric charge is measured in coulombs (C). In metal wires the charge is carried by electrons, each with a tiny negative charge: one coulomb is about 6.24 × 10^18 electrons.', 'Current is the rate at which charge flows past a point, measured in amperes (A). A current of 1 A means 1 C passes each second. Current is measured with an ammeter connected in series, so the charge flows through it.'], eq: R`I = \frac{Q}{t}`, box: '**Conventional current** is drawn from + to −. Electrons actually flow the other way. The convention was fixed before electrons were discovered, and the maths works either way.' },
        { h: 'Potential difference: energy per charge', p: ['A cell gives energy to each coulomb that passes through it; components such as bulbs take that energy and transfer it as light and heat. Potential difference (p.d., or voltage) is the energy transferred per coulomb, measured in volts. A 1.5 V cell gives 1.5 J to every coulomb.', 'Voltage is a difference between two points, so a voltmeter is connected in parallel, across the component.'], eq: R`V = \frac{E}{Q}\quad\Longrightarrow\quad E = QV = VIt` },
        { h: 'Power', p: ['Power is energy transferred per second, in watts (W). Since E = VIt, the power is simply voltage times current.', 'A 230 V kettle drawing 10 A transfers 2300 J every second. Electricity bills count energy in kilowatt-hours: 1 kWh is 1000 W for one hour, 3.6 million joules.'], eq: R`P = \frac{E}{t} = VI` },
        { h: 'Series circuits', p: ['With components in a single loop, the same current flows through each one: there is nowhere else for the charge to go.', 'The energy each coulomb picks up in the cell is shared between the components, so their voltages add up to the cell’s voltage. Two identical bulbs each get half the voltage, and also carry less current than one bulb would, so they glow much dimmer. If one breaks, the loop is broken and both go out.'], eq: R`I_1 = I_2 = I,\qquad V = V_1 + V_2` },
        { h: 'Parallel circuits', p: ['With components on separate branches, each branch connects straight across the cell, so each gets the full voltage. The current splits at a junction and rejoins later: the branch currents add up to the current from the cell.', 'Each bulb glows as brightly as if it were alone, and one can be switched off without affecting the others, which is why houses are wired in parallel. The cell supplies more current in total, so it runs down sooner.'], eq: R`V_1 = V_2 = V,\qquad I = I_1 + I_2` },
        { h: 'A first look at resistance', p: ['Resistance measures how hard it is to push current through a component: R = V/I, in ohms (Ω). A bigger resistance means less current for the same voltage.'], warn: '**Hidden assumptions.** The pipe-and-water picture breaks in one place: electrons drift slowly, only millimetres per second, yet a lamp lights the instant you switch on, because the electric field that pushes them spreads round the circuit at nearly the speed of light. And real cells have internal resistance, so their terminal voltage drops when they supply a large current.' }
      ],
      eqs: [[R`I = \frac{Q}{t}`, 'current in A; charge in C; time in s'], [R`V = \frac{E}{Q}`, 'potential difference in V (J per C)'], [R`E = VIt`, 'energy transferred in J'], [R`P = VI`, 'power in W'], [R`R = \frac{V}{I}`, 'resistance in Ω'], [R`\text{series: } V = V_1 + V_2`, 'same current everywhere'], [R`\text{parallel: } I = I_1 + I_2`, 'same voltage across each branch']],
      how: ['Redraw the circuit and decide which parts are in series and which in parallel.', 'Series: current is the same, voltages add. Parallel: voltage is the same, currents add.', 'Use I = Q/t, V = E/Q, P = VI or R = V/I as needed, with SI units.', 'Check: no branch can have more voltage than the cell provides.'],
      sum: ['Current = charge per second (A); measured in series.', 'Voltage = energy per coulomb (V); measured in parallel.', 'Energy E = VIt; power P = VI.', 'Series: one current, shared voltage. Parallel: one voltage, shared current.', 'Resistance R = V/I in ohms.'],
      probs: [
        { l: 1, q: 'A charge of 30 C flows through a wire in 10 s. What is the current?', a: '3.0 A', s: ['I = Q/t = 30 ÷ 10 = 3.0 A.'] },
        { l: 1, q: 'A 1.5 V cell moves 2.0 C of charge round a circuit. How much energy does it give to that charge?', a: '3.0 J', s: ['E = QV = 2.0 × 1.5 = 3.0 J.'] },
        { l: 1, q: 'How should an ammeter and a voltmeter be connected to measure a bulb’s current and voltage?', a: 'Ammeter in series; voltmeter in parallel', s: ['The current has to flow through the ammeter, so it goes in the loop with the bulb.', 'The voltmeter compares two points, so it connects across the bulb.'] },
        { l: 2, q: 'A 12 V lamp draws a current of 2.0 A. Find its power and the energy it transfers in one minute.', a: '24 W; 1440 J', s: ['P = VI = 12 × 2.0 = 24 W.', 'E = Pt = 24 × 60 = 1440 J.'] },
        { l: 2, q: 'Two identical bulbs are connected in series to a 6.0 V battery. What is the voltage across each bulb?', a: '3.0 V each', s: ['In series the voltages add to the battery voltage.', 'The bulbs are identical, so they share it equally: 3.0 V each.'] },
        { l: 2, q: 'Two branches of a parallel circuit carry 0.40 A and 0.60 A. What current flows from the cell?', a: '1.0 A', s: ['Currents add at a junction: 0.40 + 0.60 = 1.0 A.'] },
        { l: 2, q: 'A 230 V kettle draws 10 A. What is its power, and how much energy does it transfer in 3.0 minutes?', a: '2300 W; 414 kJ', s: ['P = VI = 230 × 10 = 2300 W.', 'E = Pt = 2300 × 180 = 414 000 J = 414 kJ.'] },
        { l: 2, q: 'There is 6.0 V across a component and 0.50 A through it. What is its resistance?', a: '12 Ω', s: ['R = V/I = 6.0 ÷ 0.50 = 12 Ω.'] },
        { l: 3, q: 'Each of two identical bulbs has resistance R. Compare the power in one bulb when the two are connected in series across a cell of voltage V with the power when they are connected in parallel.', a: 'In series each bulb gets a quarter of the power it gets in parallel', s: ['In parallel each bulb has the full V across it: P = VI = V × (V/R) = V²/R.', 'In series each bulb has V/2 across it, and the current is V/(2R).', 'Power per bulb = (V/2) × V/(2R) = V²/(4R), a quarter as much.', 'That is why bulbs in series look so much dimmer.'] },
        { l: 3, q: 'A bulb carries a current of 0.50 A. How many electrons pass through it each second? (Charge of one electron: 1.6 × 10^{−19} C)', a: 'About 3.1 × 10^18 per second', s: ['In one second 0.50 C passes.', 'Number of electrons = 0.50 ÷ (1.6 × 10^{−19}) = 3.1 × 10^18.'] }
      ]
    },

    'ks3-particles': {
      big: 'Everything is made of tiny particles that never stop moving. Solids, liquids and gases are the same particles arranged and moving in different ways, and that one idea explains density, squashing, melting, boiling and smells spreading across a room.',
      sec: [
        { h: 'Three states, one set of particles', list: ['Solid: particles packed closely in a regular pattern, held by strong forces. They vibrate about fixed positions, so a solid keeps its shape.', 'Liquid: particles still touching but arranged randomly. They slide past one another, so a liquid flows and takes the shape of its container but keeps its volume.', 'Gas: particles far apart, moving fast in all directions, with only weak forces between them. A gas spreads to fill any container and is easy to squash.'] },
        { h: 'Density', p: ['Density is the mass of each cubic metre (or cubic centimetre) of a material. It tells you how tightly the matter is packed.', 'Water has a density of 1000 kg/m³, which is 1 g/cm³. Objects denser than a liquid sink in it; less dense ones float.'], eq: R`\rho = \frac{m}{V},\qquad 1\ \text{g/cm}^3 = 1000\ \text{kg/m}^3` },
        { h: 'Why gases are so much less dense', p: ['In a solid or liquid the particles touch, so each takes up about its own size d cubed. In a gas each particle has a much bigger cube of space, s cubed, where s is the spacing.', 'The mass is the same particles either way, so the ratio of densities is the spacing ratio cubed. Liquid water (958 kg/m³ at 100 °C) is 1600 times denser than steam (0.6 kg/m³), so the steam molecules are about 12 times further apart than their own size, because 12³ ≈ 1700.'], eq: R`\frac{\rho_{\text{liquid}}}{\rho_{\text{gas}}} \approx \left(\frac{s}{d}\right)^3` },
        { h: 'Changing state', p: ['Melting, boiling, evaporating, condensing, freezing and subliming all rearrange the same particles: no mass is created or destroyed.', 'While a substance is changing state its temperature stays constant even though you keep heating it. The energy goes into pulling the particles apart against the forces between them, not into making them move faster.'] },
        { h: 'Evidence that particles move', p: ['A smell spreads across a room by diffusion: scent particles collide with air particles and wander randomly outwards.', 'Under a microscope, specks of smoke or pollen jiggle about for no visible reason. This Brownian motion is caused by invisible air or water molecules hitting them unevenly. Einstein worked out the maths in 1905, and Perrin’s measurements of it convinced the last doubters that atoms are real.'] },
        { h: 'Measuring density', list: ['Regular solid: measure the sides, work out the volume, weigh it.', 'Irregular solid: lower it into water and measure the rise in level (or the overflow from a displacement can); that is its volume.', 'Liquid: weigh an empty measuring cylinder, add a known volume, weigh again.'], warn: '**Where the simple model fails.** The particle model says solids are densest. Water breaks this rule: ice (917 kg/m³) is less dense than liquid water (1000 kg/m³), so ice floats and ponds freeze from the top. Hydrogen bonds hold the molecules in an open hexagonal lattice that takes up more room than the jumbled liquid.' }
      ],
      eqs: [[R`\rho = \frac{m}{V}`, 'density in kg/m³; mass in kg; volume in m³'], [R`m = \rho V`, 'mass from density and volume'], [R`1\ \text{g/cm}^3 = 1000\ \text{kg/m}^3`, 'unit conversion'], [R`1\ \text{m}^3 = 10^{6}\ \text{cm}^3`, 'volume conversion']],
      how: ['Write mass and volume in matching units (g and cm³, or kg and m³).', 'Use ρ = m/V, or rearrange for the unknown.', 'For irregular objects, the volume is the rise in water level.', 'Compare with water (1 g/cm³) to decide whether it floats.'],
      sum: ['All matter is made of moving particles.', 'Solids: close, regular, vibrating. Liquids: close, random, sliding. Gases: far apart, fast, random.', 'Density ρ = m/V; gases are hundreds to thousands of times less dense than liquids because their particles are far apart.', 'During a change of state the temperature stays constant: the energy breaks bonds.', 'Diffusion and Brownian motion are evidence that particles move.'],
      probs: [
        { l: 1, q: 'A block has a mass of 540 g and a volume of 200 cm³. What is its density?', a: '2.7 g/cm³ (aluminium)', s: ['ρ = m/V = 540 ÷ 200 = 2.7 g/cm³.'] },
        { l: 1, q: 'Convert 2.7 g/cm³ into kg/m³.', a: '2700 kg/m³', s: ['1 g/cm³ = 1000 kg/m³, so 2.7 g/cm³ = 2700 kg/m³.'] },
        { l: 1, q: 'In which state are the particles touching but arranged randomly and able to slide past each other?', a: 'Liquid', s: ['Solids are regular, gases are far apart: only a liquid fits.'] },
        { l: 2, q: 'A stone of mass 120 g is lowered into a measuring cylinder and the water level rises from 50 cm³ to 90 cm³. Find its density. Will it float in water?', a: '3.0 g/cm³; it sinks', s: ['Volume = 90 − 50 = 40 cm³.', 'ρ = 120 ÷ 40 = 3.0 g/cm³.', 'That is more than water’s 1.0 g/cm³, so it sinks.'] },
        { l: 2, q: 'A room measures 5.0 m × 4.0 m × 2.5 m. Air has a density of 1.2 kg/m³. What mass of air does the room hold?', a: '60 kg', s: ['V = 5.0 × 4.0 × 2.5 = 50 m³.', 'm = ρV = 1.2 × 50 = 60 kg, about the mass of an adult.'] },
        { l: 2, q: 'Gold has a density of 19 300 kg/m³. What is the mass of a gold cube 1.0 cm along each side?', a: '19.3 g', s: ['19 300 kg/m³ = 19.3 g/cm³.', 'V = 1.0 cm³, so m = 19.3 g.'] },
        { l: 2, q: 'Explain why a gas can easily be squashed into a smaller volume but a liquid hardly at all.', a: 'Gas particles have large gaps between them', s: ['In a gas the particles are far apart, so pushing them closer just shrinks the empty space.', 'In a liquid the particles already touch; squeezing would mean pushing particles into each other, which their repulsion resists strongly.'] },
        { l: 2, q: 'Ice at 0 °C is heated and melts, but the thermometer stays at 0 °C until all the ice has gone. Where does the energy go?', a: 'Into breaking the bonds between particles', s: ['The energy weakens and breaks the forces holding the particles in the solid pattern.', 'It raises their potential energy, not their speed, so the temperature does not rise until melting is complete.'] },
        { l: 3, q: 'Liquid nitrogen has a density of 808 kg/m³; nitrogen gas at room temperature has 1.17 kg/m³. Estimate how many times further apart the molecules are in the gas.', a: 'About 9 times', s: ['Density ratio = 808 ÷ 1.17 ≈ 690.', 'The spacing ratio is the cube root: ∛690 ≈ 8.8.', 'So the gas molecules are about 9 molecule-widths apart.'] },
        { l: 3, q: 'Ice has a density of 917 kg/m³ and fresh water 1000 kg/m³. What fraction of a floating block of ice is below the surface? Why is this a problem for the simple particle model?', a: 'About 92%; ice should be denser than water, but it is not', s: ['A floating object displaces its own weight of water: ρ_{ice} V g = ρ_{water} V_{under} g.', 'V_{under} ÷ V = 917 ÷ 1000 = 0.917, so about 92% is under water.', 'The simple model says the solid, with particles packed tightly, should be densest and sink.', 'Water’s hydrogen bonds force an open crystal structure in ice, so the solid is less dense: a real exception the basic model cannot explain.'] }
      ]
    },

    'ks3-pressure': {
      big: 'Pressure tells you how concentrated a force is. The same push spread over a small area cuts and sinks in; spread over a large area it hardly marks the ground. In liquids and gases pressure comes from the weight of the fluid above, and it pushes in every direction.',
      sec: [
        { h: 'Force spread over an area', p: ['Pressure is force divided by the area it acts on. Its unit is the pascal: 1 Pa = 1 N/m², a very small pressure (about a sheet of paper resting on a table).', 'A sharp knife has a tiny edge area, so a modest force makes an enormous pressure that parts the food. Snowshoes and tractor tyres do the opposite: a large area keeps the pressure low so they do not sink in.'], eq: R`p = \frac{F}{A}` },
        { h: 'Pressure in a liquid', p: ['Imagine a column of liquid of cross-section A reaching down to depth h. Its volume is Ah, its mass ρAh and its weight ρAhg. Divide by the area and the area cancels: the pressure depends only on the depth and the liquid, not on the width or shape of the container.', 'Pressure at a point in a fluid pushes equally in all directions: on the bottom, the sides, and up on anything submerged. That is why water squirts sideways out of a hole in a bottle, faster from holes lower down.'], eq: R`p = \rho g h,\qquad p_{\text{total}} = p_{\text{atm}} + \rho g h`, box: '**Every 10 m of water adds about one atmosphere.** 1000 × 9.8 × 10 ≈ 98 000 Pa, almost exactly the pressure of the whole atmosphere above us.' },
        { h: 'The atmosphere', p: ['Air has weight too. The column of air above each square metre of ground weighs about 101 000 N, so atmospheric pressure at sea level is about 101 kPa. We do not feel it because it pushes on us from all sides and from inside our bodies too.', 'Higher up there is less air above you, so the pressure is lower; your ears pop as the pressure difference across your eardrum changes.'] },
        { h: 'Upthrust and floating', p: ['The pressure on the bottom of a submerged object is greater than on its top, because the bottom is deeper. The difference pushes the object up: upthrust.', 'Archimedes’ principle: the upthrust equals the weight of the fluid the object pushes aside. An object floats when it can displace its own weight of fluid before it is fully under.'], eq: R`\text{upthrust} = \rho_{\text{fluid}}\,V_{\text{submerged}}\,g` },
        { h: 'Hydraulics: multiplying force', p: ['Liquids barely compress, so a pressure applied at one place is passed on through the whole liquid. Push a small piston with a small force and the same pressure acts on a large piston, giving a large force.', 'As with levers, you pay with distance: the small piston must move much further than the large one. Car brakes and hydraulic jacks use this.'], eq: R`\frac{F_1}{A_1} = \frac{F_2}{A_2}`, warn: '**Hidden assumption: an incompressible fluid.** p = ρgh assumes the density is the same at every depth. Air is compressible. With sea-level density (1.2 kg/m³), p = ρgh predicts the atmosphere ends at about 8.6 km, yet at the top of Everest (8.85 km) the pressure is still about a third of sea level. Real air gets thinner gradually, roughly halving every 5.5 km.' }
      ],
      eqs: [[R`p = \frac{F}{A}`, 'pressure in Pa (N/m²); force in N; area in m²'], [R`p = \rho g h`, 'pressure due to a liquid at depth h; density ρ in kg/m³'], [R`p_{\text{atm}} \approx 101\ \text{kPa}`, 'atmospheric pressure at sea level'], [R`F_2 = F_1\frac{A_2}{A_1}`, 'hydraulic force multiplication'], [R`U = \rho_f V g`, 'upthrust (Archimedes)']],
      how: ['Convert areas to m² (1 cm² = 10^{−4} m²) before dividing.', 'For liquids, use the vertical depth below the surface, not the distance along a slope.', 'Decide whether the question wants the pressure from the liquid alone or the total including the atmosphere.', 'For hydraulics, the pressure is the same on both pistons.'],
      sum: ['p = F/A in pascals; small area, big pressure.', 'In a liquid p = ρgh: depth matters, shape does not.', 'Fluid pressure acts in all directions.', 'Upthrust = weight of fluid displaced.', 'Hydraulics pass pressure on to multiply force.'],
      probs: [
        { l: 1, q: 'A 600 N person stands on two feet with a total area of 0.040 m². What pressure do they exert?', a: '15 000 Pa', s: ['p = F/A = 600 ÷ 0.040 = 15 000 Pa = 15 kPa.'] },
        { l: 1, q: 'Why does a sharp knife cut better than a blunt one?', a: 'Its edge has a smaller area, so the same force gives a larger pressure', s: ['p = F/A: halving the edge area doubles the pressure for the same push.'] },
        { l: 1, q: 'Write the pascal in terms of newtons and metres.', a: '1 Pa = 1 N/m²', s: ['Pressure is force per area, so its unit is N/m², named the pascal.'] },
        { l: 2, q: 'Find the pressure due to water at a depth of 10 m (ρ = 1000 kg/m³, g = 9.8 N/kg), and the total pressure there if the atmosphere adds 101 kPa.', a: '98 kPa from the water; 199 kPa in total', s: ['p = ρgh = 1000 × 9.8 × 10 = 98 000 Pa.', 'Total = 98 + 101 = 199 kPa, about twice atmospheric pressure.'] },
        { l: 2, q: 'A 60 kg person balances on one stiletto heel of area 1.0 cm². An elephant of mass 5000 kg stands on four feet, each 0.10 m². Compare the pressures (g = 10 N/kg).', a: 'Stiletto 6.0 × 10^6 Pa; elephant 1.25 × 10^5 Pa', s: ['Heel: F = 600 N, A = 1.0 × 10^{−4} m², p = 6.0 × 10^6 Pa.', 'Elephant: F = 50 000 N, A = 0.40 m², p = 1.25 × 10^5 Pa.', 'The heel presses about 48 times harder on the floor, which is why such heels dent wooden floors.'] },
        { l: 2, q: 'A hydraulic jack has a small piston of area 2.0 cm² and a large piston of 200 cm². A force of 50 N pushes the small piston. What force does the large piston exert?', a: '5000 N', s: ['Pressure = 50 ÷ 2.0 = 25 N/cm².', 'F = 25 × 200 = 5000 N, a hundred times more because the area is a hundred times larger.'] },
        { l: 2, q: 'A diver descends from 5.0 m to 15 m in sea water (ρ = 1030 kg/m³, g = 9.8 N/kg). By how much does the pressure on her increase?', a: 'About 101 kPa (about one atmosphere)', s: ['Δp = ρgΔh = 1030 × 9.8 × 10 = 101 000 Pa.'] },
        { l: 2, q: 'A tall narrow vase and a wide fish tank are both filled with water to a depth of 0.50 m. Which has the greater pressure at the bottom?', a: 'They are equal', s: ['p = ρgh depends only on the depth and the liquid.', 'Both are 0.50 m of water: p = 1000 × 9.8 × 0.50 = 4900 Pa in each.'] },
        { l: 3, q: 'A stone of volume 0.0020 m³ and weight 50 N is fully under water. Find the upthrust on it and its apparent weight.', a: 'Upthrust 19.6 N; apparent weight 30.4 N', s: ['Upthrust = weight of water displaced = 1000 × 0.0020 × 9.8 = 19.6 N.', 'Apparent weight = 50 − 19.6 = 30.4 N, which is why stones feel lighter under water.'] },
        { l: 3, q: 'If air had the same density everywhere (1.2 kg/m³), how tall would the atmosphere need to be to make 101 kPa at sea level? Explain why this cannot be right, given that the top of Everest (8.85 km) still has about a third of sea-level pressure.', a: 'About 8.6 km; air is compressible, so it thins out gradually instead of ending', s: ['h = p ÷ (ρg) = 101 000 ÷ (1.2 × 9.8) ≈ 8600 m.', 'That would put the top of Everest above the air.', 'But air is compressible: the air near the ground is squashed by the air above, and higher air is much less dense.', 'So the pressure falls gradually, roughly halving every 5.5 km, and the formula p = ρgh (which assumes constant density) fails for air over large heights.'] }
      ]
    },

    'ks3-space': {
      big: 'Gravity pulls every mass towards every other mass. It gives you weight, makes things fall, holds the Moon and the planets in their paths, and explains the surprising fact that an orbit is just falling sideways so fast that the ground keeps curving away beneath you.',
      sec: [
        { h: 'Mass and weight', p: ['Mass is the amount of matter in something, measured in kilograms, and it is the same everywhere. Weight is the force of gravity on that mass, measured in newtons, and it depends on where you are.', 'The gravitational field strength g tells you how many newtons of weight each kilogram has: 9.8 N/kg on Earth, 1.6 N/kg on the Moon, 3.7 N/kg on Mars. Bathroom scales measure your weight but display it as a mass.'], eq: R`W = m\,g` },
        { h: 'Everything falls the same way', p: ['Without air resistance, all objects fall with the same acceleration, whatever their mass. A heavy object has more weight but also more mass to get moving, and the two effects cancel exactly.', 'Astronaut David Scott dropped a hammer and a feather on the Moon in 1971 and they landed together. On Earth the feather drifts because of air resistance, not because gravity treats it differently.', 'Starting from rest, anything falls 4.9 m in the first second, 19.6 m in two seconds: distance grows with the square of the time.'], eq: R`s = \tfrac12 g t^2` },
        { h: 'Newton’s cannonball: why orbits happen', p: ['Fire a cannonball horizontally from a mountain. The faster it goes, the further it lands. Earth’s surface curves: over a horizontal distance d it drops away by about d²/2R, where R is Earth’s radius.', 'Fire it fast enough and the ground curves away exactly as fast as the ball falls. It keeps falling but never gets any closer to the ground: it is in orbit. For a low orbit this needs about 7.9 km/s, and one lap takes about 85 minutes.'], eq: R`\frac{v^2}{2R} = \tfrac12 g\quad\Longrightarrow\quad v = \sqrt{gR} \approx 7.9\ \text{km/s}` },
        { h: 'Weightless, but not gravity-free', p: ['At the height of the International Space Station (about 400 km) gravity is still about 90% as strong as on the ground. Astronauts float because they and the station are falling together: nothing pushes up on them, so they feel weightless.'] },
        { h: 'Gravity across the Solar System', p: ['Gravity gets weaker with distance: double the distance and the pull drops to a quarter. The Sun’s gravity holds the planets; the further out a planet is, the weaker the pull, the slower it moves and the longer its year (Mercury 88 days, Earth 1 year, Neptune 165 years).', 'Seasons come from the tilt of Earth’s axis, not from its distance to the Sun: Earth is actually closest to the Sun in early January.'], warn: '**Hidden assumptions in the cannonball estimate.** It used the surface value of g and ignored air. Real orbits must be above about 200 km to escape air drag, where g is a little smaller; the ISS at 400 km takes 92.7 minutes, not 85. The simple model gets the right size but not the exact number.' }
      ],
      eqs: [[R`W = mg`, 'weight in N; mass in kg; g in N/kg'], [R`s = \tfrac12 g t^2`, 'distance fallen from rest in time t (no air resistance)'], [R`\text{drop} \approx \frac{d^2}{2R}`, 'how far a curved surface falls away over a distance d'], [R`v = \sqrt{gR}`, 'speed for a low circular orbit'], [R`T = \frac{2\pi R}{v}`, 'time for one orbit']],
      how: ['Separate mass (kg, never changes) from weight (N, depends on g).', 'Use the g for the right place: Earth, Moon or another planet.', 'For falling objects, check whether air resistance can really be ignored.', 'For orbits, use v = √(gR), then the period from the circumference divided by the speed.'],
      sum: ['Weight W = mg; mass stays the same everywhere.', 'Without air, everything falls with the same acceleration.', 'An orbit is falling while moving sideways fast enough for the ground to curve away.', 'Low Earth orbit: about 7.9 km/s, about 90 minutes per lap.', 'Astronauts feel weightless because they are in free fall, not because gravity has vanished.'],
      probs: [
        { l: 1, q: 'What is the weight of a 50 kg person on Earth (g = 9.8 N/kg) and on the Moon (g = 1.6 N/kg)?', a: '490 N on Earth; 80 N on the Moon', s: ['W = mg = 50 × 9.8 = 490 N.', 'On the Moon: 50 × 1.6 = 80 N. The mass is still 50 kg.'] },
        { l: 1, q: 'Which stays the same when you travel to Mars: your mass or your weight?', a: 'Your mass', s: ['Mass is the amount of matter in you; weight depends on the local gravitational field strength.'] },
        { l: 1, q: 'A hammer and a feather dropped on the Moon hit the ground together. Why?', a: 'There is no air resistance, and gravity accelerates all masses equally', s: ['Gravity gives every object the same acceleration.', 'On Earth the feather is slowed by air; on the Moon there is no air.'] },
        { l: 2, q: 'An astronaut weighs 784 N on Earth (g = 9.8 N/kg). What is her mass, and her weight on Mars (g = 3.7 N/kg)?', a: '80 kg; 296 N', s: ['m = W/g = 784 ÷ 9.8 = 80 kg.', 'On Mars W = 80 × 3.7 = 296 N.'] },
        { l: 2, q: 'A stone is dropped from rest and falls for 2.0 s. How far does it fall, ignoring air resistance?', a: '19.6 m', s: ['s = ½gt² = ½ × 9.8 × 2.0² = 19.6 m.'] },
        { l: 2, q: 'Gravity at the International Space Station is about 90% of its value on the ground. Why do the astronauts float?', a: 'They are in free fall with the station', s: ['The station and everyone in it fall towards Earth together while moving sideways fast enough to stay in orbit.', 'Nothing pushes up on the astronauts, so they feel no weight, though gravity is still pulling.'] },
        { l: 2, q: 'Estimate the speed needed for a low orbit round Earth using v = √(gR), with g = 9.8 N/kg and R = 6.4 × 10^6 m.', a: 'About 7.9 km/s', s: ['gR = 9.8 × 6.4 × 10^6 = 6.27 × 10^7 m²/s².', 'v = √(6.27 × 10^7) ≈ 7900 m/s.'] },
        { l: 2, q: 'The Moon has g = 1.6 N/kg and radius 1.74 × 10^6 m. Find the speed and period of a low orbit round the Moon.', a: 'About 1.7 km/s and 109 minutes', s: ['v = √(1.6 × 1.74 × 10^6) ≈ 1670 m/s.', 'T = 2πR/v = 2π × 1.74 × 10^6 ÷ 1670 ≈ 6550 s ≈ 109 min.', 'Apollo command modules orbited the Moon in about two hours, close to this.'] },
        { l: 3, q: 'A ball is fired horizontally at 7.9 km/s. In the first second it travels 7.9 km sideways. How far does Earth’s surface drop away over that distance (R = 6.37 × 10^6 m)? Compare with how far the ball falls.', a: 'Both are 4.9 m, so the ball stays at the same height above the ground', s: ['Drop of the surface ≈ d²/2R = (7900)² ÷ (2 × 6.37 × 10^6) ≈ 4.9 m.', 'Distance fallen in 1 s = ½ × 9.8 × 1² = 4.9 m.', 'They match, so the ball falls but never gets closer to the ground: an orbit.'] },
        { l: 3, q: 'The ISS orbits 400 km up, where g ≈ 8.7 N/kg and the distance from Earth’s centre is r = 6.77 × 10^6 m. Use v = √(gr) to find its speed and period. Compare with the real period of 92.7 minutes.', a: 'About 7.7 km/s and 92 minutes, within 1% of the real value', s: ['v = √(8.7 × 6.77 × 10^6) ≈ 7680 m/s.', 'T = 2πr/v = 2π × 6.77 × 10^6 ÷ 7680 ≈ 5540 s ≈ 92.4 min.', 'Using the right g for that height fixes most of the gap left by the surface-gravity estimate of 85 minutes.'] }
      ]
    }
  });
})();
/* ---- notes-gcse.js ---- */
/* Geodesic: study notes and ten-problem practice sets, GCSE (IGCSE 0625 / GCSE). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'gcse-suvat': {
      big: 'When the acceleration is constant, five quantities describe the motion: displacement s, initial velocity u, final velocity v, acceleration a and time t. Four equations tie them together, so knowing any three gives you the other two. All four come from reading one velocity–time graph.',
      sec: [
        { h: 'Direction matters: vectors and signs', p: ['Displacement, velocity and acceleration are vectors: they have a direction as well as a size. In a straight line we handle direction with a sign. Choose which way is positive at the start and stick to it.', 'If up is positive, a ball thrown upwards has u = +14 m/s but its acceleration is a = −9.8 m/s² all the way up and all the way down, even at the top where it is momentarily at rest.'], box: '**Velocity zero does not mean acceleration zero.** At the top of its flight a ball has v = 0 but is still accelerating downwards at 9.8 m/s²; that is why it does not stay there.' },
        { h: 'Reading a velocity–time graph', p: ['The gradient of a velocity–time graph is the acceleration: how much the velocity changes each second. A straight line means constant acceleration.', 'The area between the line and the time axis is the displacement. Area below the axis counts as negative displacement (moving backwards).'], eq: R`a = \frac{v - u}{t},\qquad s = \text{area under the } v\text{–}t \text{ graph}` },
        { h: 'The four equations and where they come from', p: ['Rearranging the gradient gives v = u + at. The area under a straight v–t line is a trapezium: a rectangle ut plus a triangle ½(v − u)t. Using v − u = at turns that into s = ut + ½at². Treating the trapezium as average height × width gives s = ½(u + v)t. Eliminating t gives the time-free equation v² = u² + 2as.', 'Each equation leaves out one quantity. Pick the one that leaves out the quantity you neither know nor want.'], eq: R`v = u + at\quad[\text{no } s],\qquad s = ut + \tfrac12at^2\quad[\text{no } v],\qquad s = \tfrac12(u+v)t\quad[\text{no } a],\qquad v^2 = u^2 + 2as\quad[\text{no } t]` },
        { h: 'Free fall', p: ['Near Earth’s surface, and ignoring air resistance, everything falls with a = g = 9.8 m/s² downwards. For a ball thrown straight up at speed u: it reaches the top after t = u/g, rises to a height u²/2g, and comes back down to the same height with the same speed, taking the same time.'] },
        { h: 'Stopping distances', p: ['A driver’s stopping distance is the thinking distance plus the braking distance. Thinking distance is speed × reaction time (typically 0.7 s, longer if tired or distracted). Braking distance comes from v² = u² + 2as with v = 0: s = u²/2a.', 'Because braking distance grows with the square of the speed, doubling your speed quadruples it. That is the physics behind speed limits near schools.'], warn: '**Hidden assumption: constant acceleration.** All four equations fail when a changes. A falling skydiver is the classic case: air resistance grows with speed until it balances the weight, the acceleration falls to zero and the speed levels off at terminal velocity (about 55 m/s belly-down). Using s = ½gt² for a 30 s skydive predicts 4.4 km and over 290 m/s; the real figures are nearer 1.5 km and 55 m/s.' }
      ],
      eqs: [[R`v = u + at`, 'final velocity v and initial velocity u in m/s; acceleration a in m/s²; time t in s'], [R`s = ut + \tfrac12 at^2`, 'displacement s in m'], [R`s = \tfrac12(u + v)\,t`, 'average velocity × time'], [R`v^2 = u^2 + 2as`, 'no time needed'], [R`g = 9.8\ \text{m/s}^2`, 'free-fall acceleration near Earth’s surface']],
      how: ['List s, u, v, a, t; mark the three you know and the one you want.', 'Choose a positive direction and give every vector its sign.', 'Use the equation that does not contain the fifth quantity.', 'Solve, then check the sign and size make sense (a car cannot brake at 50 m/s²).', 'If the acceleration is not constant, stop: these equations do not apply.'],
      sum: ['Constant acceleration only.', 'v–t graph: gradient = acceleration, area = displacement.', 'Four equations, each missing one of s, u, v, a, t.', 'Free fall: a = 9.8 m/s² downwards; the top of the flight has v = 0, not a = 0.', 'Braking distance ∝ speed²; thinking distance ∝ speed.'],
      probs: [
        { l: 1, q: 'A car accelerates from rest at 2.0 m/s² for 5.0 s. What is its final speed?', a: '10 m/s', s: ['u = 0, a = 2.0, t = 5.0; want v.', 'v = u + at = 0 + 2.0 × 5.0 = 10 m/s.'] },
        { l: 1, q: 'A ball speeds up from 3.0 m/s to 7.0 m/s in 2.0 s. What is its acceleration?', a: '2.0 m/s²', s: ['a = (v − u)/t = (7.0 − 3.0)/2.0 = 2.0 m/s².'] },
        { l: 1, q: 'A velocity–time graph rises in a straight line from 0 to 12 m/s in 4.0 s. How far does the object travel?', a: '24 m', s: ['Area of the triangle = ½ × 4.0 × 12 = 24 m.'] },
        { l: 2, q: 'A car braking from 20 m/s stops in 40 m. Find the deceleration and the stopping time.', a: '5.0 m/s²; 4.0 s', s: ['u = 20, v = 0, s = 40.', 'v² = u² + 2as: 0 = 400 + 80a, so a = −5.0 m/s² (a deceleration of 5.0 m/s²).', 't = (v − u)/a = (0 − 20)/(−5.0) = 4.0 s.'] },
        { l: 2, q: 'A stone is dropped from the top of a 45 m cliff. How long does it take to reach the bottom, and how fast is it going? (Ignore air resistance.)', a: '3.0 s; 30 m/s', s: ['Take down as positive: u = 0, a = 9.8, s = 45.', 's = ½at²: t = √(2 × 45 ÷ 9.8) = 3.03 s.', 'v = u + at = 9.8 × 3.03 = 29.7 m/s (check: v² = 2 × 9.8 × 45 = 882).'] },
        { l: 2, q: 'A ball is thrown straight up at 14 m/s. How high does it go and how long does it take to reach the top?', a: '10 m; 1.43 s', s: ['Up positive: u = 14, v = 0 at the top, a = −9.8.', 'v² = u² + 2as: 0 = 196 − 19.6s, so s = 10 m.', 't = (0 − 14)/(−9.8) = 1.43 s.'] },
        { l: 2, q: 'A train accelerates uniformly from 10 m/s to 30 m/s over 400 m. Find its acceleration and the time taken.', a: '1.0 m/s²; 20 s', s: ['v² = u² + 2as: 900 = 100 + 800a, so a = 1.0 m/s².', 's = ½(u + v)t: 400 = 20t, so t = 20 s.'] },
        { l: 2, q: 'A driver travelling at 30 m/s has a reaction time of 0.70 s and brakes at 7.5 m/s². What is the total stopping distance?', a: '81 m', s: ['Thinking distance = 30 × 0.70 = 21 m.', 'Braking distance = u²/2a = 900 ÷ 15 = 60 m.', 'Total = 81 m.'] },
        { l: 3, q: 'The same driver now travels at 15 m/s (half the speed). Find the new stopping distance, and explain why it falls by more than half.', a: '25.5 m, less than a third of 81 m', s: ['Thinking: 15 × 0.70 = 10.5 m (halved).', 'Braking: 225 ÷ 15 = 15 m (a quarter, because it depends on u²).', 'Total = 25.5 m.', 'The braking part scales with the square of the speed, so halving the speed cuts it to a quarter.'] },
        { l: 3, q: 'A ball is thrown upwards at 20 m/s from the edge of a roof 15 m above the ground. It rises, falls past the roof and lands on the ground. When does it land, and how fast is it moving?', a: 'After 4.7 s, at 26 m/s', s: ['Up positive: u = 20, a = −9.8, and the ground is s = −15 m.', 's = ut + ½at²: −15 = 20t − 4.9t², so 4.9t² − 20t − 15 = 0.', 't = [20 + √(400 + 294)] ÷ 9.8 = 4.73 s (the negative root is before the throw).', 'v² = u² + 2as = 400 + 294 = 694, so the speed is 26.3 m/s, downwards.'] }
      ]
    },

    'gcse-energy': {
      big: 'Energy is never created or destroyed; it only moves between stores. Kinetic energy ½mv² and gravitational potential energy mgh are the two stores in every drop, swing and roller-coaster ride, and conservation of energy lets you find speeds without knowing the shape of the path.',
      sec: [
        { h: 'Stores and transfers', p: ['It helps to picture energy sitting in stores: kinetic (moving things), gravitational potential (raised things), elastic (stretched things), thermal (hot things), chemical (fuel, food, batteries) and nuclear. Energy moves between stores by forces doing work, by heating, by electric currents and by radiation.', 'The total never changes. When it seems to vanish, it has usually gone into the thermal store of the surroundings, spread out and hard to use.'] },
        { h: 'Work: how forces transfer energy', p: ['When a force moves something, it does work, and that work is the energy transferred. Work equals force times the distance moved in the direction of the force. One joule is the work done by a force of one newton moving one metre.', 'Carrying a bag along a level corridor at steady speed does (almost) no work on the bag: your upward force is at right angles to the motion.'], eq: R`W = F\,s` },
        { h: 'Gravitational potential energy', p: ['To lift a mass m at steady speed you must push up with a force equal to its weight, mg. Lifting it through a height h does work mg × h, which is stored as gravitational potential energy.'], eq: R`\Delta E_p = m g h` },
        { h: 'Kinetic energy', p: ['Push a mass from rest with a constant net force F over a distance s. The work done is Fs = (ma)s. From v² = u² + 2as with u = 0, as = ½v², so the work done, now stored as kinetic energy, is ½mv².', 'The square matters: double the speed and the kinetic energy is four times bigger, which is why a crash at 60 km/h is so much worse than at 30 km/h.'], eq: R`E_k = \tfrac12 m v^2` },
        { h: 'Conservation in action', p: ['With no friction, potential energy lost equals kinetic energy gained. For anything falling or sliding down through a height h from rest, mgh = ½mv², so v = √(2gh). The mass cancels and the shape of the slope does not matter: a steep drop and a long gentle ramp of the same height give the same speed at the bottom.'], eq: R`mgh = \tfrac12 m v^2\;\Longrightarrow\; v = \sqrt{2gh}` },
        { h: 'Efficiency, power and elastic energy', p: ['Efficiency is the fraction of the input energy that ends up where you want it. Power is the rate of transferring energy, in watts (J/s). A stretched spring with spring constant k and extension e stores ½ke².'], eq: R`\text{efficiency} = \frac{\text{useful output}}{\text{total input}},\qquad P = \frac{E}{t},\qquad E_e = \tfrac12 k e^2`, warn: '**Hidden assumptions.** mgh assumes g is the same at every height, which is excellent for buildings and hills but wrong for rockets: for orbits you need −GMm/r. ½mv² is the low-speed limit of Einstein’s formula and fails close to the speed of light (accelerated electrons in a 1 MV machine move at 0.94c, not the 2c that ½mv² would predict).' }
      ],
      eqs: [[R`W = F s`, 'work done in J; force in N; distance along the force in m'], [R`E_p = m g h`, 'gravitational potential energy (uniform g)'], [R`E_k = \tfrac12 m v^2`, 'kinetic energy'], [R`E_e = \tfrac12 k e^2`, 'elastic energy; k in N/m; extension e in m'], [R`P = \frac{E}{t}`, 'power in W'], [R`\eta = \frac{E_{\text{useful}}}{E_{\text{in}}}`, 'efficiency (no units)']],
      how: ['Identify the start and end states and list the stores at each.', 'Write total energy at the start = total at the end + energy dissipated.', 'Cancel the mass if it appears in every term.', 'Use v = √(2gh) only when friction is negligible and the object starts from rest.', 'For power, divide the energy by the time; for efficiency, divide useful by total.'],
      sum: ['Energy is conserved: it moves between stores.', 'Work W = Fs is energy transferred by a force.', 'Ep = mgh; Ek = ½mv²; Ee = ½ke².', 'Without friction v = √(2gh), whatever the mass or path.', 'Efficiency = useful ÷ total; power = energy ÷ time.'],
      probs: [
        { l: 1, q: 'Find the kinetic energy of a 2.0 kg ball moving at 3.0 m/s.', a: '9.0 J', s: ['Ek = ½mv² = ½ × 2.0 × 3.0² = 9.0 J.'] },
        { l: 1, q: 'A 50 kg student climbs stairs 3.0 m high. How much gravitational potential energy does she gain? (g = 9.8 N/kg)', a: '1470 J', s: ['Ep = mgh = 50 × 9.8 × 3.0 = 1470 J.'] },
        { l: 1, q: 'You push a box 4.0 m across a floor with a horizontal force of 25 N. How much work do you do?', a: '100 J', s: ['W = Fs = 25 × 4.0 = 100 J.'] },
        { l: 2, q: 'A ball is dropped from a height of 5.0 m. How fast is it moving just before it lands? (Ignore air resistance.)', a: '9.9 m/s', s: ['mgh = ½mv², so v = √(2gh).', 'v = √(2 × 9.8 × 5.0) = √98 = 9.9 m/s. The mass is not needed.'] },
        { l: 2, q: 'A 1200 kg car brakes from 20 m/s to rest. How much energy do the brakes transfer? How much if it had been doing 40 m/s?', a: '240 kJ; 960 kJ', s: ['Ek = ½ × 1200 × 20² = 240 000 J.', 'At 40 m/s: ½ × 1200 × 40² = 960 000 J, four times as much for twice the speed.'] },
        { l: 2, q: 'A pendulum bob is released from 0.20 m above its lowest point. How fast is it moving at the bottom?', a: '2.0 m/s', s: ['v = √(2gh) = √(2 × 9.8 × 0.20) = 1.98 m/s.'] },
        { l: 2, q: 'A motor lifts a 200 kg load through 12 m in 30 s, using 40 kJ of electrical energy. Find the useful energy output, the efficiency and the useful power.', a: '23.5 kJ; 59%; 784 W', s: ['Useful energy = mgh = 200 × 9.8 × 12 = 23 520 J.', 'Efficiency = 23 520 ÷ 40 000 = 0.59 = 59%.', 'Useful power = 23 520 ÷ 30 = 784 W.'] },
        { l: 2, q: 'A spring with k = 400 N/m is compressed by 0.10 m and launches a 50 g ball. How fast does the ball leave?', a: '8.9 m/s', s: ['Ee = ½ke² = ½ × 400 × 0.10² = 2.0 J.', 'All of it becomes kinetic: ½ × 0.050 × v² = 2.0, so v² = 80 and v = 8.9 m/s.'] },
        { l: 3, q: 'A roller-coaster car starts from rest 40 m above the ground. Find its speed at the top of a later hill 25 m high (a) with no friction, (b) if friction has by then dissipated 20% of its starting potential energy.', a: '(a) 17 m/s (b) 12 m/s', s: ['(a) It has dropped 15 m: v = √(2 × 9.8 × 15) = 17.1 m/s.', '(b) Energy per kg available: 0.80 × 9.8 × 40 = 313.6 J/kg; still stored at 25 m: 9.8 × 25 = 245 J/kg.', 'Kinetic per kg = 68.6 J/kg = ½v², so v = √137 = 11.7 m/s.', 'The mass cancels again, because every term is proportional to m.'] },
        { l: 3, q: 'A 70 kg skydiver falls at a steady 55 m/s. Each second, what happens to her gravitational potential energy and her kinetic energy, and where does the energy go? What power is that?', a: 'About 38 kJ of GPE lost every second; KE unchanged; it heats the air (about 38 kW)', s: ['In one second she falls 55 m, so she loses mgh = 70 × 9.8 × 55 = 37 700 J of potential energy.', 'Her speed is constant, so her kinetic energy does not change.', 'All 37.7 kJ per second is transferred by the drag force to the thermal store of the air: a power of about 38 kW.'] }
      ]
    },

    'gcse-circuits': {
      big: 'Resistances in series add because the charge has to get through each one in turn; in parallel their reciprocals add because each branch is another route. With V = IR and these two rules you can work out the current and voltage anywhere in a simple circuit.',
      sec: [
        { h: 'Resistance and Ohm’s law', p: ['Resistance is the ratio of the voltage across a component to the current through it: R = V/I, in ohms (Ω). For a metal wire at constant temperature the ratio is constant, so a graph of current against voltage is a straight line through the origin. That is Ohm’s law.', 'Many components are not ohmic. A filament lamp’s resistance rises as it heats up, so its I–V graph curves over. A diode lets current through in one direction only. A thermistor’s resistance falls when it gets hotter; a light-dependent resistor’s falls in brighter light.'], eq: R`V = I R` },
        { h: 'Series: one path', p: ['In series there is only one route, so the same current flows through everything. The battery’s voltage is shared, in proportion to the resistances: a resistor with twice the resistance gets twice the voltage. Adding up the voltages gives the total resistance.'], eq: R`V = IR_1 + IR_2 = I(R_1 + R_2)\;\Longrightarrow\; R_{\text{series}} = R_1 + R_2 + \cdots` },
        { h: 'Parallel: several paths', p: ['In parallel each branch is connected across the same two points, so each has the same voltage. The current splits between the branches, more going through the smaller resistance. Adding the branch currents shows the reciprocals add.', 'The total resistance of a parallel group is always less than the smallest single resistance: every extra branch is an extra route for the charge. For two resistors, R = R₁R₂/(R₁ + R₂).'], eq: R`I = \frac{V}{R_1} + \frac{V}{R_2}\;\Longrightarrow\;\frac{1}{R_{\text{parallel}}} = \frac{1}{R_1} + \frac{1}{R_2} + \cdots` },
        { h: 'Power in a resistor', p: ['Power is P = VI. Combining with V = IR gives two more forms: P = I²R (handy in series, where I is shared) and P = V²/R (handy in parallel, where V is shared).'], eq: R`P = VI = I^2R = \frac{V^2}{R}` },
        { h: 'Potential dividers', p: ['Two resistors in series across a supply split its voltage in the ratio of their resistances. Replace one with a thermistor or LDR and the output voltage changes with temperature or light: that is how simple sensors and automatic night-lights work.'], eq: R`V_{\text{out}} = V_{\text{in}}\,\frac{R_2}{R_1 + R_2}` },
        { h: 'Mains electricity', p: ['UK mains is 230 V alternating current at 50 Hz. Appliances are wired in parallel so each gets the full voltage. The fuse, in the live wire, melts if the current is too large; the earth wire protects you if a metal case becomes live.'], warn: '**Ohm’s law is not a law of nature.** It is a property of some materials at a fixed temperature. A 60 W, 230 V lamp has a resistance of about 880 Ω when glowing but only about a tenth of that when cold, so it draws a surge of current at the moment it is switched on, which is when old bulbs usually blew.' }
      ],
      eqs: [[R`V = IR`, 'p.d. in V; current in A; resistance in Ω'], [R`R_s = R_1 + R_2 + \cdots`, 'resistors in series'], [R`\frac{1}{R_p} = \frac{1}{R_1} + \frac{1}{R_2} + \cdots`, 'resistors in parallel'], [R`P = VI = I^2R = \frac{V^2}{R}`, 'power in W'], [R`V_{\text{out}} = V_{\text{in}}\frac{R_2}{R_1 + R_2}`, 'potential divider (output across R₂)'], [R`Q = It,\quad E = VIt`, 'charge in C; energy in J']],
      how: ['Simplify the circuit: replace parallel groups by their single equivalent resistance, then add series parts.', 'Find the total current from the supply: I = V/R_{total}.', 'Work back out: series parts share I, parallel parts share V.', 'Check: voltages round any loop add to the supply; currents into a junction equal currents out.'],
      sum: ['V = IR; R is constant only for ohmic conductors at fixed temperature.', 'Series: same current, voltages add, R = R₁ + R₂.', 'Parallel: same voltage, currents add, 1/R = 1/R₁ + 1/R₂, total below the smallest.', 'P = VI = I²R = V²/R.', 'A potential divider shares the voltage in the ratio of the resistances.'],
      probs: [
        { l: 1, q: 'A 4.0 Ω resistor has 12 V across it. What current flows?', a: '3.0 A', s: ['I = V/R = 12 ÷ 4.0 = 3.0 A.'] },
        { l: 1, q: 'What is the total resistance of 3.0 Ω and 5.0 Ω in series?', a: '8.0 Ω', s: ['Series resistances add: 3.0 + 5.0 = 8.0 Ω.'] },
        { l: 1, q: 'What is the total resistance of 6.0 Ω and 3.0 Ω in parallel?', a: '2.0 Ω', s: ['1/R = 1/6 + 1/3 = 1/6 + 2/6 = 3/6, so R = 2.0 Ω.', 'Or: product over sum = 18 ÷ 9 = 2.0 Ω.'] },
        { l: 2, q: 'A 9.0 V battery drives current through 2.0 Ω and 4.0 Ω in series. Find the current and the voltage across each resistor.', a: '1.5 A; 3.0 V and 6.0 V', s: ['R = 6.0 Ω, so I = 9.0 ÷ 6.0 = 1.5 A.', 'V₁ = 1.5 × 2.0 = 3.0 V, V₂ = 1.5 × 4.0 = 6.0 V. They add to 9.0 V.'] },
        { l: 2, q: '4.0 Ω and 12 Ω are connected in parallel across 12 V. Find each branch current, the total current and the total resistance.', a: '3.0 A and 1.0 A; 4.0 A; 3.0 Ω', s: ['Each branch has 12 V: 12 ÷ 4.0 = 3.0 A and 12 ÷ 12 = 1.0 A.', 'Total current = 4.0 A.', 'R = 12 ÷ 4.0 = 3.0 Ω, less than either resistor.'] },
        { l: 2, q: 'A 6.0 Ω resistor is in series with a parallel pair of 6.0 Ω and 3.0 Ω, across a 12 V supply. Find the current from the supply and the current in each parallel branch.', a: '1.5 A; 0.50 A and 1.0 A', s: ['Parallel pair: 6 × 3 ÷ 9 = 2.0 Ω. Total = 8.0 Ω.', 'Supply current = 12 ÷ 8.0 = 1.5 A.', 'Voltage across the pair = 1.5 × 2.0 = 3.0 V.', 'Branches: 3.0 ÷ 6.0 = 0.50 A and 3.0 ÷ 3.0 = 1.0 A (they add to 1.5 A).'] },
        { l: 2, q: 'A 2.3 kW heater runs on 230 V mains. Find the current and its resistance. Which fuse should it have: 3 A, 5 A or 13 A?', a: '10 A; 23 Ω; 13 A', s: ['I = P/V = 2300 ÷ 230 = 10 A.', 'R = V/I = 23 Ω.', 'The fuse must be just above the normal current: 13 A.'] },
        { l: 2, q: 'A 10 Ω resistor carries 0.50 A. How much power does it dissipate?', a: '2.5 W', s: ['P = I²R = 0.50² × 10 = 2.5 W.'] },
        { l: 3, q: 'A 10 kΩ resistor and a thermistor form a potential divider across 9.0 V, with the output taken across the thermistor. The thermistor is 10 kΩ at 25 °C and 3.6 kΩ at 50 °C. Find the output at each temperature and say what the circuit could be used for.', a: '4.5 V at 25 °C; 2.4 V at 50 °C', s: ['At 25 °C the resistances are equal: Vout = 9.0 × 10/20 = 4.5 V.', 'At 50 °C: Vout = 9.0 × 3.6/(10 + 3.6) = 2.4 V.', 'The output falls as the temperature rises, so it can switch on a fan or alarm when it drops below a set value.'] },
        { l: 3, q: 'A 60 W, 230 V filament lamp has a resistance of about 60 Ω when cold. Find its resistance and current when glowing normally, and the current at the instant it is switched on. Why do such lamps usually fail at switch-on?', a: '880 Ω and 0.26 A when hot; about 3.8 A cold', s: ['Hot: R = V²/P = 230² ÷ 60 ≈ 880 Ω, I = P/V = 0.26 A.', 'Cold: I = 230 ÷ 60 ≈ 3.8 A, roughly fifteen times larger for a moment.', 'The surge heats the thinnest point of the filament fastest; it is the usual moment of failure.', 'This is the clearest everyday example of a component that does not obey Ohm’s law.'] }
      ]
    },

    'gcse-newton': {
      big: 'Newton’s three laws explain why things start moving, stop and change direction. Momentum, p = mv, is the quantity forces change, and in any collision or explosion the total momentum stays the same, so you can predict the outcome without knowing the forces in between.',
      sec: [
        { h: 'First law: inertia', p: ['If the resultant force on an object is zero, its velocity does not change: it stays at rest or keeps moving in a straight line at constant speed. Moving things do not need a force to keep going; they need a force to speed up, slow down or turn.', 'That is why passengers lurch forward when a bus brakes: their bodies keep moving until the seat belt applies a force.'] },
        { h: 'Second law: F = ma', p: ['The resultant force equals mass times acceleration. A bigger force gives a bigger acceleration; a bigger mass needs a bigger force for the same acceleration, so mass measures inertia. One newton gives 1 kg an acceleration of 1 m/s².', 'Written with momentum, force is the rate of change of momentum. This form is more general: it covers rockets, which lose mass as they burn fuel.'], eq: R`F = ma = \frac{\Delta (mv)}{\Delta t} = \frac{\Delta p}{\Delta t}` },
        { h: 'Third law: forces come in pairs', p: ['When object A pushes on object B, B pushes back on A with a force of the same size, in the opposite direction, of the same type, at the same time. The two forces act on different objects, so they never cancel each other out.'], box: '**Common mistake.** A book on a table: its weight (Earth pulls the book down) and the table’s push up are equal and opposite but they are **not** a third-law pair; both act on the book. The partner of the book’s weight is the book’s gravitational pull **up on the Earth**.' },
        { h: 'Conservation of momentum', p: ['In a collision, the two objects push on each other with equal and opposite forces for the same time, so their momentum changes are equal and opposite. The total momentum of the pair is unchanged, provided no outside force acts.'], eq: R`m_1u_1 + m_2u_2 = m_1v_1 + m_2v_2`, after: ['Kinetic energy is different: it is conserved only in perfectly elastic collisions. When objects stick together, some kinetic energy always becomes heat, sound and deformation.'] },
        { h: 'Impulse and safety', p: ['Force × time equals the change in momentum, the impulse. For a given change of momentum (stopping a car passenger, say), a longer stopping time means a smaller force. Crumple zones, airbags, seat belts, cycle helmets and soft playground surfaces all work by stretching out the time of the impact.'], eq: R`F\,\Delta t = \Delta p` },
        { h: 'Terminal velocity', p: ['Air resistance grows with speed. A falling object speeds up until the drag equals its weight; the resultant force is then zero and, by the first law, it falls at constant terminal velocity.'], warn: '**Where Newton’s laws need care.** They hold in non-accelerating (inertial) frames: on a spinning roundabout, objects seem to be flung outwards by no physical force. And p = mv is the low-speed limit: in particle accelerators momentum is γmv, which grows without limit as v approaches c, which is why protons never reach light speed however long they are pushed.' }
      ],
      eqs: [[R`F = ma`, 'resultant force in N; mass in kg; acceleration in m/s²'], [R`p = mv`, 'momentum in kg m/s'], [R`F = \frac{\Delta p}{\Delta t}`, 'force as rate of change of momentum'], [R`F\Delta t = \Delta p`, 'impulse in N s'], [R`m_1u_1 + m_2u_2 = m_1v_1 + m_2v_2`, 'momentum conservation (no external force)'], [R`W = mg`, 'weight']],
      how: ['Draw a free-body diagram: every force on the one object you care about.', 'Find the resultant force, then use F = ma.', 'For collisions, choose a positive direction and write total momentum before = total after.', 'If the question mentions kinetic energy, check whether the collision is elastic before assuming it is conserved.', 'For impacts, use F = Δp/Δt.'],
      sum: ['No resultant force: no change in velocity.', 'F = ma = Δp/Δt.', 'Third-law pairs act on different objects and are the same type of force.', 'Total momentum is conserved in collisions and explosions; kinetic energy only in elastic ones.', 'Longer impact time, smaller force: the principle behind every safety feature.'],
      probs: [
        { l: 1, q: 'What resultant force gives a 1200 kg car an acceleration of 2.5 m/s²?', a: '3000 N', s: ['F = ma = 1200 × 2.5 = 3000 N.'] },
        { l: 1, q: 'What is the momentum of a 0.16 kg cricket ball moving at 30 m/s?', a: '4.8 kg m/s', s: ['p = mv = 0.16 × 30 = 4.8 kg m/s.'] },
        { l: 1, q: 'A book rests on a table. What is the third-law partner of the book’s weight?', a: 'The book’s gravitational pull upwards on the Earth', s: ['The weight is Earth pulling the book down by gravity.', 'Its partner must be the same type of force on the other object: the book pulling Earth up by gravity.', 'The table’s upward push on the book is a different force (a contact force) on the same object.'] },
        { l: 2, q: 'Two skaters stand at rest. The 60 kg skater pushes the 40 kg skater, who moves off at 3.0 m/s. How fast does the 60 kg skater move, and which way?', a: '2.0 m/s in the opposite direction', s: ['Total momentum before = 0.', 'After: 40 × 3.0 + 60 × v = 0, so v = −2.0 m/s.', 'The minus sign means the opposite direction.'] },
        { l: 2, q: 'A 1000 kg car at 15 m/s hits a stationary 1500 kg car and the two lock together. Find their speed just after the crash and the kinetic energy lost.', a: '6.0 m/s; 67.5 kJ (60% of the original)', s: ['Momentum: 1000 × 15 = 2500 × v, so v = 6.0 m/s.', 'KE before = ½ × 1000 × 15² = 112.5 kJ.', 'KE after = ½ × 2500 × 6.0² = 45 kJ.', 'Lost: 67.5 kJ, mostly as heat, sound and crumpled metal.'] },
        { l: 2, q: 'A 58 g tennis ball arrives at 25 m/s and leaves the racket at 35 m/s in the opposite direction. Contact lasts 4.0 ms. What is the average force on the ball?', a: '870 N', s: ['Take the leaving direction as positive: Δp = 0.058 × (35 − (−25)) = 0.058 × 60 = 3.48 kg m/s.', 'F = Δp/Δt = 3.48 ÷ 0.0040 = 870 N.'] },
        { l: 2, q: 'A 70 kg driver is brought to rest from 20 m/s. Find the average force on him if the stop takes 0.10 s (hitting the dashboard) and if it takes 1.0 s (seat belt and airbag).', a: '14 000 N and 1400 N', s: ['Δp = 70 × 20 = 1400 kg m/s in both cases.', 'F = 1400 ÷ 0.10 = 14 000 N, or 1400 ÷ 1.0 = 1400 N.', 'Ten times the time gives a tenth of the force.'] },
        { l: 2, q: 'A 2.0 kg trolley is pulled with a 10 N force while friction of 4.0 N acts against it. Find its acceleration.', a: '3.0 m/s²', s: ['Resultant force = 10 − 4.0 = 6.0 N.', 'a = F/m = 6.0 ÷ 2.0 = 3.0 m/s².'] },
        { l: 3, q: 'A 5.0 kg rifle fires a 10 g bullet at 400 m/s. Find the recoil speed of the rifle and compare the kinetic energies of the bullet and the rifle. Why are they so different when the momenta are equal?', a: '0.80 m/s; 800 J against 1.6 J', s: ['Momentum: 0.010 × 400 = 5.0 × v, so v = 0.80 m/s backwards.', 'Bullet: ½ × 0.010 × 400² = 800 J. Rifle: ½ × 5.0 × 0.80² = 1.6 J.', 'Ek = p²/2m: with equal momenta, the lighter object gets far more kinetic energy.'] },
        { l: 3, q: 'A ball moving at speed u hits an identical ball at rest, head-on, in a perfectly elastic collision. Show that the first ball stops and the second moves off at u, as in a Newton’s cradle.', a: 'v₁ = 0, v₂ = u', s: ['Momentum (masses equal): u = v₁ + v₂.', 'Kinetic energy (elastic): u² = v₁² + v₂².', 'Square the first: u² = v₁² + 2v₁v₂ + v₂². Comparing with the second gives v₁v₂ = 0.', 'v₂ = 0 would mean the first ball passes through the second, so v₁ = 0 and v₂ = u.'] }
      ]
    },

    'gcse-em-spectrum': {
      big: 'Light is one member of a family: radio waves, microwaves, infrared, visible light, ultraviolet, X-rays and gamma rays are all electromagnetic waves, travelling at the same speed in a vacuum and differing only in wavelength. When light changes speed at a boundary it changes direction, and that one fact explains lenses, rainbows, mirages and optical fibres.',
      sec: [
        { h: 'One family of waves', p: ['Electromagnetic waves are transverse oscillations of electric and magnetic fields. They need no medium and all travel at c = 3.0 × 10^8 m/s in a vacuum. In order of decreasing wavelength: radio (metres to kilometres), microwaves (centimetres), infrared (micrometres), visible light (about 400–700 nm, violet to red), ultraviolet, X-rays and gamma rays.', 'Since v = fλ with the same v for all, shorter wavelength means higher frequency, and higher frequency means each photon carries more energy.'] },
        { h: 'Uses and dangers', list: ['Radio: broadcasting and communications. Microwaves: satellite links, mobile networks, cooking.', 'Infrared: heaters, remote controls, thermal imaging cameras, optical fibre signals.', 'Visible: sight, photography, fibre-optic endoscopes.', 'Ultraviolet: sterilising water, security marks; causes sunburn and skin cancer.', 'X-rays and gamma rays: medical imaging, cancer treatment, sterilising equipment. They are ionising: each photon has enough energy to knock electrons off atoms and damage DNA.'] },
        { h: 'Refraction: light changes speed', p: ['Light travels more slowly in glass or water than in a vacuum. The refractive index n says how much slower: v = c/n. Glass has n ≈ 1.5, water 1.33, diamond 2.42.', 'At the boundary the frequency cannot change (each wave crest arriving must produce one crest leaving), so the wavelength shrinks by the factor n. Colour is set by frequency, so the colour is unchanged.'], eq: R`v = \frac{c}{n},\qquad \lambda_{\text{glass}} = \frac{\lambda_{\text{air}}}{n}` },
        { h: 'Why the ray bends: Snell’s law', p: ['Follow a straight wavefront hitting glass at an angle. The end that reaches the glass first slows down while the other end is still in air, so the wavefront swings round, like a line of marching soldiers stepping onto mud. Geometry on the wavefronts gives Snell’s law: entering a slower medium, the ray bends towards the normal.'], eq: R`n_1\sin\theta_1 = n_2\sin\theta_2` },
        { h: 'Total internal reflection', p: ['Going from glass into air, the ray bends away from the normal. At the critical angle the refracted ray would skim along the surface at 90°; beyond it no light escapes and all of it reflects. Optical fibres trap light this way over kilometres, and diamonds sparkle because their critical angle is only 24°.'], eq: R`\sin\theta_c = \frac{n_2}{n_1} = \frac{1}{n}\ \ (\text{into air})` },
        { h: 'Dispersion', p: ['The refractive index is slightly different for each colour (higher for violet than red), so a prism or a raindrop spreads white light into a spectrum.'], warn: '**A popular myth.** Microwave ovens do not heat food by hitting a “resonance” of water molecules. They run at 2.45 GHz, while liquid water absorbs most strongly near 20 GHz. The lower frequency is chosen because it penetrates several centimetres into food; at the absorption peak the outside would burn while the inside stayed cold.' }
      ],
      eqs: [[R`v = f\lambda`, 'wave speed, frequency (Hz), wavelength (m)'], [R`c = 3.0\times10^{8}\ \text{m/s}`, 'speed of every EM wave in a vacuum'], [R`n = \frac{c}{v}`, 'refractive index (no units)'], [R`n_1\sin\theta_1 = n_2\sin\theta_2`, 'Snell’s law, angles from the normal'], [R`\sin\theta_c = \frac{1}{n}`, 'critical angle from a medium of index n into air']],
      how: ['Measure every angle from the normal.', 'Decide which medium the light starts in; that is n₁.', 'For speed or wavelength inside a material, divide the vacuum value by n; the frequency stays the same.', 'For total internal reflection, check the light is going from the higher index to the lower and compare the angle with the critical angle.'],
      sum: ['All EM waves travel at c in a vacuum; they differ in wavelength and frequency.', 'Higher frequency, more energy per photon; UV, X-rays and gamma are ionising.', 'Refraction is caused by a change of speed: v = c/n, frequency unchanged.', 'Snell: n₁ sin θ₁ = n₂ sin θ₂.', 'Beyond the critical angle, total internal reflection traps light (fibres, diamonds).'],
      probs: [
        { l: 1, q: 'An FM radio station broadcasts at 100 MHz. What is the wavelength?', a: '3.0 m', s: ['λ = c/f = 3.0 × 10^8 ÷ 1.0 × 10^8 = 3.0 m.'] },
        { l: 1, q: 'Put these in order of increasing wavelength: X-rays, radio waves, visible light, microwaves.', a: 'X-rays, visible, microwaves, radio', s: ['X-rays have the shortest wavelengths (around 10^{−10} m), then visible (≈ 5 × 10^{−7} m), microwaves (≈ cm) and radio (m to km).'] },
        { l: 1, q: 'How fast does light travel in glass of refractive index 1.5?', a: '2.0 × 10^8 m/s', s: ['v = c/n = 3.0 × 10^8 ÷ 1.5 = 2.0 × 10^8 m/s.'] },
        { l: 2, q: 'Light in air hits glass (n = 1.50) at an angle of incidence of 40°. Find the angle of refraction.', a: '25°', s: ['sin θ₂ = sin 40° ÷ 1.50 = 0.643 ÷ 1.50 = 0.429.', 'θ₂ = 25.4°, bent towards the normal.'] },
        { l: 2, q: 'Find the critical angle for light going from water (n = 1.33) into air.', a: '48.8°', s: ['sin θc = 1 ÷ 1.33 = 0.752.', 'θc = 48.8°.'] },
        { l: 2, q: 'Red light of wavelength 650 nm in air enters glass with n = 1.5. Find its frequency, speed and wavelength in the glass.', a: '4.6 × 10^{14} Hz (unchanged); 2.0 × 10^8 m/s; 433 nm', s: ['f = c/λ = 3.0 × 10^8 ÷ 650 × 10^{−9} = 4.6 × 10^{14} Hz, the same in the glass.', 'v = c/n = 2.0 × 10^8 m/s.', 'λ = v/f = 650 ÷ 1.5 = 433 nm. It still looks red, because colour follows frequency.'] },
        { l: 2, q: 'Why are X-rays dangerous even at low power, while radio waves are harmless even from a powerful transmitter?', a: 'X-ray photons are energetic enough to ionise; radio photons are not', s: ['Each X-ray photon carries enough energy to knock an electron off an atom, breaking chemical bonds in DNA.', 'A radio photon carries about a billion times less energy; a strong radio beam can warm things but cannot ionise.'] },
        { l: 2, q: 'A swimming pool looks shallower than it really is. Explain why.', a: 'Light from the bottom bends away from the normal as it leaves the water', s: ['Rays from the pool floor refract away from the normal at the surface.', 'Your brain traces them back in straight lines, to a point higher than the real floor.', 'Looking straight down, the apparent depth is the real depth divided by n: about three-quarters.'] },
        { l: 3, q: 'An optical fibre has a core of index 1.48 surrounded by cladding of index 1.46. Find the critical angle at the core–cladding boundary. What does it tell you about the rays that the fibre can carry?', a: '80.6°: only rays travelling almost along the fibre are trapped', s: ['sin θc = 1.46 ÷ 1.48 = 0.986, so θc = 80.6°.', 'A ray must hit the wall at more than 80.6° from the normal, within about 9° of the fibre’s axis.', 'Keeping the indices close means rays that zig-zag steeply are lost, which reduces the spread of travel times and keeps pulses sharp.'] },
        { l: 3, q: 'A microwave oven works at 2.45 GHz. Find the wavelength. Hot spots form about half a wavelength apart: how far apart is that? Is the oven tuned to a resonance of water?', a: '12.2 cm; about 6 cm; no', s: ['λ = c/f = 3.0 × 10^8 ÷ 2.45 × 10^9 = 0.122 m.', 'Half a wavelength is about 6 cm, which is why ovens have turntables.', 'Liquid water absorbs most strongly near 20 GHz. 2.45 GHz is chosen because it penetrates deeper into food and lies in a band set aside for such appliances.'] }
      ]
    },

    'gcse-magnetism': {
      big: 'A wire carrying a current in a magnetic field feels a force at right angles to both the current and the field: F = BIL. Every electric motor, loudspeaker and moving-coil meter is built on this one effect.',
      sec: [
        { h: 'Magnetic fields', p: ['A magnetic field is the region where a magnet or a moving charge feels a force. Field lines run from north to south outside a magnet; where they crowd together the field is stronger. Earth’s field is about 50 μT; a fridge magnet a few mT; a hospital MRI scanner 1.5 to 3 T.', 'A current makes its own field: circles round a straight wire (the right-hand grip rule gives the direction), and a field like a bar magnet’s from a coil, or solenoid.'] },
        { h: 'The force on a moving charge', p: ['A charge q moving at speed v straight across a field B feels a force qvB, at right angles to its motion. In a wire, the current is many charge carriers drifting along. Add up the force on every carrier in a length L and you get the force on the wire.'], eq: R`F = qvB\;\Longrightarrow\; F = N q v_d B = BIL` },
        { h: 'Size and direction', p: ['The force is biggest when the wire is at right angles to the field and zero when it runs along the field; in between, only the perpendicular part of the field counts.', 'Fleming’s left-hand rule gives the direction: hold thumb, first finger and second finger at right angles. First finger = Field (N to S), seCond finger = Current (+ to −), thuMb = Motion (force).'], eq: R`F = BIL\sin\theta` },
        { h: 'The tesla', p: ['Rearranging, B = F/(IL): a field of one tesla pushes with one newton on each metre of wire carrying one ampere. The tesla is a big unit, which is why everyday fields are quoted in mT and μT.'] },
        { h: 'How a motor works', p: ['Put a rectangular coil in a field. The current goes one way along one side and the other way along the opposite side, so the forces on those sides are opposite: a turning effect. A split-ring commutator reverses the current every half turn, so the coil keeps turning the same way.', 'Make it turn harder with more current, a stronger magnet or more turns of wire.'] },
        { h: 'Loudspeakers', p: ['In a loudspeaker a coil sits in the field of a permanent magnet. The audio signal is an alternating current, so the force on the coil changes direction in time with the music, pushing the cone back and forth to make sound waves.'], warn: '**Where the energy really comes from.** The magnetic force on a charge is always at right angles to its velocity, so it does no work on the charge itself. In a running motor the spinning coil also acts as a generator, producing a back-e.m.f. that opposes the supply; the work the supply does pushing current against it is what drives the motor. A stalled motor has no back-e.m.f., draws a large current and can overheat.' }
      ],
      eqs: [[R`F = BIL`, 'force in N; flux density B in T; current I in A; length L in m (wire ⊥ field)'], [R`F = BIL\sin\theta`, 'wire at angle θ to the field'], [R`F = qvB`, 'force on a charge q moving at v ⊥ B'], [R`\tau_{\max} = NBIA`, 'largest torque on a coil of N turns and area A']],
      how: ['Check the angle between the wire and the field; use sin θ if it is not 90°.', 'Convert lengths to metres and fields to teslas (1 mT = 10^{−3} T).', 'Use Fleming’s left-hand rule for the direction; remember conventional current runs + to −.', 'For a coil, find the force on each side, then torque = force × perpendicular distance.'],
      sum: ['A current in a magnetic field feels a force F = BIL sin θ.', 'Biggest at 90°, zero along the field.', 'Direction: Fleming’s left-hand rule.', 'Motors: forces on opposite sides of a coil make a turning effect; the commutator keeps it turning one way.', '1 T = 1 N per ampere per metre.'],
      probs: [
        { l: 1, q: 'A 0.20 m wire carrying 3.0 A lies at right angles to a 0.50 T field. What force acts on it?', a: '0.30 N', s: ['F = BIL = 0.50 × 3.0 × 0.20 = 0.30 N.'] },
        { l: 1, q: 'What happens to the force if the current is reversed?', a: 'Same size, opposite direction', s: ['Reversing the current reverses one finger in the left-hand rule, so the force reverses.'] },
        { l: 1, q: 'A current-carrying wire lies along the direction of a magnetic field. What force acts on it?', a: 'None', s: ['F = BIL sin θ with θ = 0 gives F = 0.'] },
        { l: 2, q: 'What field strength gives a force of 0.050 N on a 0.10 m wire carrying 2.5 A at right angles to the field?', a: '0.20 T', s: ['B = F/(IL) = 0.050 ÷ (2.5 × 0.10) = 0.20 T.'] },
        { l: 2, q: 'A 0.25 m wire carrying 5.0 A makes an angle of 30° with a 0.40 T field. Find the force.', a: '0.25 N', s: ['F = BIL sin θ = 0.40 × 5.0 × 0.25 × sin 30° = 0.25 N.'] },
        { l: 2, q: 'A horizontal wire on this page carries current to the right, in a field pointing into the page. Which way is the force?', a: 'Up the page', s: ['Left hand: first finger into the page (field), second finger to the right (current).', 'The thumb points up the page.', 'Check with vectors: F = IL × B, right × into = up.'] },
        { l: 2, q: 'An electron moves at 2.0 × 10^6 m/s at right angles to a 0.010 T field. What force acts on it? (e = 1.6 × 10^{−19} C)', a: '3.2 × 10^{−15} N', s: ['F = qvB = 1.6 × 10^{−19} × 2.0 × 10^6 × 0.010 = 3.2 × 10^{−15} N.'] },
        { l: 2, q: 'Give three ways to make a simple d.c. motor turn faster, and explain why it needs a commutator.', a: 'More current, stronger field, more turns; the commutator keeps the torque in one direction', s: ['The turning effect is proportional to N, B and I, so increase any of them.', 'Without a commutator the forces would reverse their turning effect every half turn and the coil would just rock back and forth.', 'The split ring reverses the current each half turn so the coil keeps turning the same way.'] },
        { l: 3, q: 'A rectangular coil of 50 turns has sides of 4.0 cm (perpendicular to the field) and 3.0 cm, carries 0.20 A and sits in a 0.30 T field. Find the largest turning effect on it.', a: '3.6 × 10^{−3} N m', s: ['Force on each 4.0 cm side: F = NBIL = 50 × 0.30 × 0.20 × 0.040 = 0.12 N.', 'The two forces are 3.0 cm apart, making a couple: τ = 0.12 × 0.030 = 3.6 × 10^{−3} N m.', 'Equivalently τ = NBIA with A = 1.2 × 10^{−3} m².'] },
        { l: 3, q: 'Earth’s magnetic field is about 5.0 × 10^{−5} T. Find the force on 1.0 m of mains cable carrying 10 A at right angles to it. Why do cables never twitch?', a: '5.0 × 10^{−4} N, about a thousandth of the cable’s weight', s: ['F = BIL = 5.0 × 10^{−5} × 10 × 1.0 = 5.0 × 10^{−4} N.', 'A metre of cable weighs around 1 N, two thousand times more.', 'Also the live and neutral wires carry equal and opposite currents side by side, so their forces cancel, and the a.c. reverses 100 times a second.'] }
      ]
    },

    'gcse-shc': {
      big: 'Heating a substance does one of two things: it raises the temperature, making the particles move faster, or it changes the state, breaking bonds at a constant temperature. Two material constants, the specific heat capacity and the specific latent heat, tell you how much energy each takes.',
      sec: [
        { h: 'Temperature and internal energy', p: ['Temperature measures the average kinetic energy of the particles. Internal energy is the total energy of all the particles: their kinetic energy plus the potential energy stored in the bonds between them.', 'So a bath of warm water has far more internal energy than a red-hot pin, even though the pin is much hotter.'] },
        { h: 'Specific heat capacity', p: ['The specific heat capacity c is the energy needed to raise 1 kg of a substance by 1 °C. Water’s is unusually large, 4200 J/(kg °C), five to ten times that of most metals. That is why the sea warms and cools slowly, keeping coastal climates mild, and why water is used in radiators and cooling systems.'], eq: R`E = m\,c\,\Delta\theta` },
        { h: 'Specific latent heat', p: ['While a substance melts or boils, its temperature stays fixed: the energy goes into breaking bonds, not speeding particles up. The specific latent heat L is the energy needed to change the state of 1 kg without a temperature change.', 'For water, melting takes 334 kJ/kg (fusion) but boiling takes 2260 kJ/kg (vaporisation), almost seven times as much, because boiling separates the molecules completely.'], eq: R`E = m\,L` },
        { h: 'Reading a heating curve', p: ['Heat ice at a steady rate and plot temperature against time. Sloping parts are heating within one state; the slope is P/(mc), so a steeper slope means a smaller heat capacity. Flat parts are changes of state; their length is mL/P. The boiling plateau is about seven times longer than the melting plateau.'] },
        { h: 'Measuring c in the lab', p: ['Put an electric heater in a metal block or beaker of water, measure the energy supplied (E = VIt or a joulemeter) and the temperature rise, then c = E/(mΔθ). Insulate the block and stir water to reduce errors.'], warn: '**Hidden assumption: no energy lost to the surroundings.** In school experiments the measured c usually comes out 10–20% too high, because part of the energy heated the room, not the sample. The constants themselves are not quite constant either: water boils at about 71 °C on Everest, where the pressure is a third of sea level, and its latent heat changes with the boiling temperature.' }
      ],
      eqs: [[R`E = mc\Delta\theta`, 'energy in J; mass in kg; c in J/(kg °C); temperature change in °C'], [R`E = mL`, 'energy to change state; L in J/kg'], [R`E = Pt = VIt`, 'energy from an electric heater'], [R`c_{\text{water}} = 4200\ \text{J/(kg °C)}`, 'specific heat capacity of water'], [R`L_f = 3.34\times10^{5},\ L_v = 2.26\times10^{6}\ \text{J/kg}`, 'water: fusion and vaporisation']],
      how: ['Split the process into stages: warming, melting, warming, boiling, warming.', 'Use mcΔθ for each temperature change and mL for each change of state.', 'Add the stages; for a heater, time = energy ÷ power.', 'For mixtures, energy lost by the hot part = energy gained by the cold part.'],
      sum: ['Temperature is average particle kinetic energy; internal energy is the total.', 'E = mcΔθ when the temperature changes.', 'E = mL when the state changes, at constant temperature.', 'Water: c = 4200 J/(kg °C); boiling takes about seven times the energy of melting.', 'Heat losses make measured c too high.'],
      probs: [
        { l: 1, q: 'How much energy raises 2.0 kg of water by 10 °C? (c = 4200 J/(kg °C))', a: '84 000 J', s: ['E = mcΔθ = 2.0 × 4200 × 10 = 84 000 J.'] },
        { l: 1, q: 'How much energy melts 0.50 kg of ice at 0 °C? (L_f = 334 000 J/kg)', a: '167 000 J', s: ['E = mL = 0.50 × 334 000 = 167 000 J.'] },
        { l: 1, q: 'Water keeps boiling at 100 °C even though the kettle is still heating it. Where does the energy go?', a: 'Into separating the molecules (latent heat)', s: ['The energy breaks the bonds between water molecules to turn liquid into gas.', 'It increases their potential energy, not their average kinetic energy, so the temperature stays the same.'] },
        { l: 2, q: 'A 2.0 kW kettle heats 1.5 kg of water from 20 °C to 100 °C. How long does it take, ignoring losses?', a: '252 s (4.2 minutes)', s: ['E = 1.5 × 4200 × 80 = 504 000 J.', 't = E/P = 504 000 ÷ 2000 = 252 s.'] },
        { l: 2, q: 'A 1.0 kg aluminium block is heated by a 50 W heater for 5.0 minutes and warms by 15 °C. What value of c does this give? The accepted value is 900 J/(kg °C); explain the difference.', a: '1000 J/(kg °C), too high because of heat losses', s: ['E = 50 × 300 = 15 000 J.', 'c = E/(mΔθ) = 15 000 ÷ (1.0 × 15) = 1000 J/(kg °C).', 'Some of the energy warmed the air and bench, so the block warmed less than it would have, which makes c look bigger.'] },
        { l: 2, q: 'How much energy is needed to turn 0.20 kg of water at 100 °C into steam? (L_v = 2.26 × 10^6 J/kg)', a: '452 kJ', s: ['E = mL = 0.20 × 2.26 × 10^6 = 452 000 J.'] },
        { l: 2, q: 'Compare the energy given to your skin by 1.0 g of steam at 100 °C condensing and cooling to 37 °C with that from 1.0 g of water at 100 °C cooling to 37 °C.', a: 'About 2530 J against 265 J: steam delivers nearly ten times more', s: ['Steam: condensing gives 0.001 × 2.26 × 10^6 = 2260 J; cooling then gives 0.001 × 4200 × 63 = 265 J. Total 2525 J.', 'Water: only the 265 J.', 'That is why steam scalds are so much worse.'] },
        { l: 2, q: 'A 100 W heater warms 0.10 kg of ice that has reached 0 °C. How long does the ice take to melt?', a: '334 s', s: ['E = mL = 0.10 × 334 000 = 33 400 J.', 't = E/P = 334 s, during which the temperature stays at 0 °C.'] },
        { l: 3, q: 'How much energy turns 0.50 kg of ice at −20 °C into steam at 120 °C? (c_{ice} = 2100, c_{water} = 4200, c_{steam} = 2000 J/(kg °C); L_f = 3.34 × 10^5, L_v = 2.26 × 10^6 J/kg.) Which stage takes the most?', a: '1.55 MJ; boiling (about 73%)', s: ['Warm ice: 0.50 × 2100 × 20 = 21 000 J.', 'Melt: 0.50 × 334 000 = 167 000 J.', 'Warm water: 0.50 × 4200 × 100 = 210 000 J.', 'Boil: 0.50 × 2.26 × 10^6 = 1 130 000 J.', 'Warm steam: 0.50 × 2000 × 20 = 20 000 J.', 'Total 1 548 000 J ≈ 1.55 MJ; boiling is 1.13 ÷ 1.55 = 73% of it.'] },
        { l: 3, q: '0.20 kg of water at 80 °C is mixed with 0.30 kg of water at 20 °C in an insulated cup. What is the final temperature?', a: '44 °C', s: ['Energy lost by hot water = energy gained by cold water.', '0.20 × 4200 × (80 − T) = 0.30 × 4200 × (T − 20).', '16 − 0.20T = 0.30T − 6, so 0.50T = 22 and T = 44 °C.', 'c cancels, so it works for any liquid mixed with itself.'] }
      ]
    },

    'gcse-radioactivity': {
      big: 'An unstable nucleus decays at a random moment that nobody can predict. Yet a large sample always halves in the same time, the half-life. Pure chance, repeated over billions of nuclei, produces one of the most precise clocks in nature.',
      sec: [
        { h: 'Nuclei and isotopes', p: ['A nucleus contains protons (number Z) and neutrons; the total is the mass number A. Isotopes of an element have the same Z but different numbers of neutrons. Some combinations are unstable and decay, giving out radiation.'], eq: R`{}^{A}_{Z}\mathrm{X}:\quad {}^{14}_{6}\mathrm{C}\ \text{has 6 protons and 8 neutrons}` },
        { h: 'Three kinds of radiation', list: ['Alpha (α): a helium nucleus, two protons and two neutrons. Heavily ionising, stopped by a sheet of paper or a few centimetres of air.', 'Beta (β⁻): a fast electron, made when a neutron turns into a proton. Moderately ionising, stopped by a few millimetres of aluminium.', 'Gamma (γ): a high-energy electromagnetic wave, emitted when a nucleus drops to a lower energy state. Weakly ionising but very penetrating; reduced by thick lead or concrete.'], after: ['Decay equations must balance both the mass numbers (top) and the proton numbers (bottom).'] },
        { h: 'Random decay and half-life', p: ['Each nucleus has the same fixed chance λ per second of decaying, whatever its neighbours are doing. With N nuclei, about λN decay each second, so the more there are, the faster they go: the number left falls exponentially.', 'The half-life is the time for half of the nuclei (or half the activity) to go. After n half-lives a fraction (½)^n remains. Activity is measured in becquerels: 1 Bq = 1 decay per second.'], eq: R`N = N_0\left(\tfrac12\right)^{t/T_{1/2}},\qquad A = \lambda N,\qquad \lambda = \frac{\ln 2}{T_{1/2}}` },
        { h: 'Background radiation and counting', p: ['Radiation is all around us: radon gas from rocks, cosmic rays, food and medical scans. Before working out a half-life, measure the background count and subtract it from every reading.', 'Because decay is random, counts fluctuate: a count of N is uncertain by about √N. Longer counting times give more reliable rates.'] },
        { h: 'Uses', list: ['Carbon dating: living things keep a fixed level of carbon-14; after death it decays with T½ = 5730 years.', 'Medical tracers: technetium-99m emits gamma rays that escape the body and has a 6-hour half-life, so it is gone in a few days.', 'Smoke alarms: americium-241 alpha particles ionise air in a small gap; smoke stops the current.', 'Sterilising: gamma rays kill bacteria on sealed medical equipment.'] },
        { h: 'Contamination and irradiation', p: ['Irradiation is being exposed to radiation from a source outside the body; it stops when you move away. Contamination is having the radioactive material on or inside you, so the exposure continues. Alpha sources are fairly harmless outside the body but very dangerous if swallowed or breathed in.'], warn: '**Is the half-life really constant?** The model assumes λ never changes. Experiments heating, cooling, squeezing and chemically combining radioactive samples find the rates unchanged to high precision; the only known exceptions, all well under 1%, involve electron capture, where the chemistry slightly changes the electrons near the nucleus. Claims around 2008 of decay rates varying with Earth’s distance from the Sun were not confirmed by later, better-controlled measurements.' }
      ],
      eqs: [[R`N = N_0\left(\tfrac12\right)^{n}`, 'nuclei left after n half-lives'], [R`A = \lambda N`, 'activity in Bq; decay constant λ in s⁻¹'], [R`\lambda = \frac{\ln 2}{T_{1/2}}`, 'decay constant from half-life'], [R`{}^{A}_{Z}\mathrm{X}\to{}^{A-4}_{Z-2}\mathrm{Y}+{}^{4}_{2}\mathrm{He}`, 'alpha decay'], [R`{}^{A}_{Z}\mathrm{X}\to{}^{A}_{Z+1}\mathrm{Y}+{}^{\ \ 0}_{-1}\mathrm{e}`, 'beta-minus decay']],
      how: ['Subtract the background count first.', 'Count how many halvings get from the start value to the end value; time ÷ that number = half-life.', 'If the fraction is not a neat power of ½, use logarithms: n = log(N₀/N) ÷ log 2.', 'Balance decay equations top (A) and bottom (Z).'],
      sum: ['Alpha: helium nucleus, stopped by paper. Beta: electron, stopped by aluminium. Gamma: EM wave, reduced by lead.', 'Decay is random, but large samples halve in a fixed half-life.', 'N = N₀(½)^{t/T½}; A = λN; λ = ln 2/T½.', 'Subtract background; counts fluctuate by about √N.', 'Choose isotopes for a job by their radiation type and half-life.'],
      probs: [
        { l: 1, q: 'A source has an activity of 800 Bq and a half-life of 6.0 hours. What is its activity after 18 hours?', a: '100 Bq', s: ['18 h is 3 half-lives.', '800 → 400 → 200 → 100 Bq.'] },
        { l: 1, q: 'Uranium-238 (Z = 92) decays by alpha emission to thorium. Write the decay equation.', a: '²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He', s: ['The alpha particle takes away 4 from A and 2 from Z.', '238 − 4 = 234 and 92 − 2 = 90, which is thorium.'] },
        { l: 1, q: 'Which type of radiation is stopped by a sheet of paper?', a: 'Alpha', s: ['Alpha particles are large and heavily ionising, so they lose their energy very quickly.'] },
        { l: 2, q: 'A count rate falls from 640 to 40 counts per minute in 2.0 hours (background already subtracted). What is the half-life?', a: '30 minutes', s: ['640 → 320 → 160 → 80 → 40 is four halvings.', 'Half-life = 120 min ÷ 4 = 30 min.'] },
        { l: 2, q: 'Carbon-14 (Z = 6) decays by beta-minus emission. Write the equation and name the product.', a: '¹⁴₆C → ¹⁴₇N + ⁰₋₁e (nitrogen-14)', s: ['A neutron becomes a proton: A stays 14, Z goes up to 7.', 'Z = 7 is nitrogen. (An antineutrino is also emitted.)'] },
        { l: 2, q: 'The background count is 30 counts/min. A source reads 270 counts/min, and 20 minutes later 90 counts/min. Find the half-life.', a: '10 minutes', s: ['Corrected rates: 270 − 30 = 240 and 90 − 30 = 60.', '240 → 120 → 60 is two half-lives in 20 min.', 'Half-life = 10 min. Forgetting the background would give the wrong answer.'] },
        { l: 2, q: 'A bone contains one-eighth as much carbon-14 per gram of carbon as living tissue. How old is it? (T½ = 5730 years)', a: 'About 17 000 years', s: ['1/8 = (½)³, so three half-lives have passed.', '3 × 5730 = 17 190 years.'] },
        { l: 2, q: 'Why is technetium-99m (gamma emitter, half-life 6 hours) a good medical tracer, and why would an alpha emitter with a 1000-year half-life be a bad one?', a: 'Gamma escapes to the detector and the short half-life limits the dose', s: ['Gamma rays pass out of the body to the camera and ionise little on the way.', 'A 6-hour half-life gives time to take images but the activity is nearly gone within a few days.', 'Alpha particles would not get out of the body to be detected and would damage nearby cells; a long half-life keeps the patient radioactive for life.'] },
        { l: 3, q: 'Iodine-131 has a half-life of 8.0 days. How long until only 10% of a sample remains?', a: 'About 27 days', s: ['(½)^n = 0.10 means 2^n = 10, so n = log 10 ÷ log 2 = 3.32 half-lives.', 't = 3.32 × 8.0 = 26.6 days.'] },
        { l: 3, q: 'A sample contains 1.0 × 10^{20} nuclei of radium-226 (half-life 1600 years). What is its activity? (1 year = 3.16 × 10^7 s)', a: 'About 1.4 × 10^9 Bq', s: ['T½ = 1600 × 3.16 × 10^7 = 5.06 × 10^{10} s.', 'λ = 0.693 ÷ 5.06 × 10^{10} = 1.37 × 10^{−11} s⁻¹.', 'A = λN = 1.37 × 10^{−11} × 1.0 × 10^{20} = 1.4 × 10^9 Bq.', 'Even a slow-decaying isotope gives a huge activity because N is so large.'] }
      ]
    },

    'gcse-orbits': {
      big: 'Light from distant galaxies arrives stretched to longer wavelengths, and the further away a galaxy is, the more its light is stretched. Read with Hubble’s law, that is evidence that the universe is expanding, and running the expansion backwards gives an age of about 14 billion years.',
      sec: [
        { h: 'Spectral fingerprints', p: ['Each element absorbs and emits light only at particular wavelengths, seen as dark absorption lines in a star’s spectrum. Hydrogen, for example, has a strong red line at 656.3 nm in the laboratory. The pattern of lines identifies the element even when the whole pattern is shifted.'] },
        { h: 'Red-shift', p: ['A source moving away from us stretches the waves it sends, so every line moves to a longer (redder) wavelength. The fractional shift is the red-shift z. For speeds much less than light, z is approximately v/c. An approaching source is blue-shifted: the Andromeda galaxy is coming towards us at about 300 km/s.'], eq: R`z = \frac{\lambda_{\text{obs}} - \lambda_{\text{lab}}}{\lambda_{\text{lab}}}\approx\frac{v}{c}` },
        { h: 'Hubble’s law', p: ['In 1929 Hubble found that more distant galaxies have bigger red-shifts: their recession speed is proportional to their distance. The constant is the Hubble constant, about 70 km/s for every megaparsec of distance (1 Mpc = 3.26 million light-years = 3.09 × 10^{19} km).'], eq: R`v = H_0\,d` },
        { h: 'An age for the universe', p: ['If every galaxy’s speed is proportional to its distance, they all took the same time to get where they are: d/v = 1/H₀. With H₀ = 70 km/s/Mpc that is about 14 billion years. The fuller calculation, which allows for the expansion speeding up and slowing down, gives 13.8 billion.'], eq: R`t \approx \frac{1}{H_0} \approx 1.4\times10^{10}\ \text{years}` },
        { h: 'Evidence for the Big Bang', list: ['Red-shifts: distant galaxies are moving apart, as if from a hot dense beginning.', 'The cosmic microwave background (found by Penzias and Wilson in 1965): faint microwaves from every direction, the cooled afterglow of the early universe, now at 2.7 K.', 'Light elements: about a quarter of the ordinary matter is helium, the amount predicted to form in the first few minutes.'] },
        { h: 'Space itself is stretching', p: ['The Big Bang was not an explosion into empty space with a centre. Space itself is expanding, carrying galaxies apart, and the light’s wavelength stretches with it: 1 + z equals how much bigger the universe is now than when the light set out.'], eq: R`1 + z = \frac{a_{\text{now}}}{a_{\text{then}}}`, warn: '**An open contradiction: the Hubble tension.** Measuring H₀ from nearby supernovae gives about 73 km/s/Mpc; inferring it from the cosmic microwave background with the standard model gives 67.4 km/s/Mpc. The gap is far larger than either team’s quoted uncertainty. Either some measurement has an unknown error or the standard model of cosmology is missing something.' }
      ],
      eqs: [[R`z = \frac{\Delta\lambda}{\lambda}`, 'red-shift (no units)'], [R`v \approx c\,z`, 'recession speed, valid only for z ≪ 1'], [R`v = H_0 d`, 'Hubble’s law; H₀ ≈ 70 km/s/Mpc'], [R`t \approx 1/H_0`, 'age estimate'], [R`1 + z = a_{\text{now}}/a_{\text{then}}`, 'cosmological red-shift as stretching of space']],
      how: ['Find Δλ = observed − lab wavelength, then z = Δλ/λ_{lab}.', 'For small z, v = cz; keep units consistent (km/s with H₀ in km/s/Mpc).', 'Use d = v/H₀ for distance in Mpc.', 'For the age, convert 1/H₀ to seconds (1 Mpc = 3.09 × 10^{19} km), then to years.'],
      sum: ['Red-shift z = Δλ/λ; for slow sources v ≈ cz.', 'Hubble’s law: v = H₀d, with H₀ ≈ 70 km/s/Mpc.', '1/H₀ ≈ 14 billion years; the careful value is 13.8.', 'Evidence for the Big Bang: red-shifts, the 2.7 K microwave background, light-element abundances.', 'Cosmological red-shift is space stretching; H₀ measurements currently disagree.'],
      probs: [
        { l: 1, q: 'Hydrogen’s 656.3 nm line is observed at 662.9 nm in a galaxy’s spectrum. Find z and the galaxy’s speed.', a: 'z = 0.010; 3.0 × 10^6 m/s (3000 km/s), moving away', s: ['Δλ = 662.9 − 656.3 = 6.6 nm.', 'z = 6.6 ÷ 656.3 = 0.0101.', 'v = cz = 3.0 × 10^8 × 0.0101 = 3.0 × 10^6 m/s.'] },
        { l: 1, q: 'What does it mean if a galaxy’s lines are blue-shifted?', a: 'It is moving towards us', s: ['Motion towards us squashes the waves, shortening their wavelength.'] },
        { l: 1, q: 'Give two pieces of evidence for the Big Bang.', a: 'Galaxy red-shifts (Hubble’s law) and the cosmic microwave background', s: ['Red-shifts increasing with distance show the universe is expanding.', 'The CMB is the predicted afterglow of a hot, dense early universe. (A third: the amount of helium.)'] },
        { l: 2, q: 'A galaxy is 100 Mpc away. Using H₀ = 70 km/s/Mpc, find its recession speed and red-shift.', a: '7000 km/s; z ≈ 0.023', s: ['v = H₀d = 70 × 100 = 7000 km/s.', 'z = v/c = 7000 ÷ 300 000 = 0.023.'] },
        { l: 2, q: 'A galaxy is receding at 14 000 km/s. How far away is it?', a: '200 Mpc', s: ['d = v/H₀ = 14 000 ÷ 70 = 200 Mpc (about 650 million light-years).'] },
        { l: 2, q: 'Estimate the age of the universe from H₀ = 70 km/s/Mpc. (1 Mpc = 3.09 × 10^{19} km; 1 year = 3.16 × 10^7 s)', a: 'About 14 billion years', s: ['1/H₀ = 3.09 × 10^{19} km ÷ 70 km/s = 4.41 × 10^{17} s.', 'In years: 4.41 × 10^{17} ÷ 3.16 × 10^7 = 1.40 × 10^{10} years.'] },
        { l: 2, q: 'Hubble’s own 1929 value of H₀ was about 500 km/s/Mpc. What age does that give, and why was it a problem?', a: 'About 2 billion years, younger than the Earth', s: ['Age ≈ 14 billion × 70/500 ≈ 2.0 billion years.', 'Rocks were already known to be older than that (Earth is 4.5 billion years old), a direct contradiction.', 'The fault was in Hubble’s distance scale; once the distances were corrected, H₀ fell and the age rose.'] },
        { l: 2, q: 'Why is the cosmic microwave background taken as evidence for the Big Bang?', a: 'It is the stretched afterglow of a hot, dense early universe', s: ['The Big Bang model predicts that the early universe was hot enough to glow, and that expansion would stretch that light to microwaves.', 'The radiation was found coming equally from every direction with the spectrum of a 2.7 K object, as predicted.'] },
        { l: 3, q: 'A quasar has z = 2.0. Using v = cz would give v = 2c. Why is this not a contradiction with relativity, and what does z = 2.0 actually tell us?', a: 'v ≈ cz only works for small z; 1 + z = 3 means the universe has tripled in size since the light left', s: ['The formula v ≈ cz is an approximation for nearby galaxies.', 'Cosmological red-shift measures how much space has stretched: 1 + z = a_{now}/a_{then} = 3.', 'So when the light left, distances between galaxies were a third of today’s. Distant galaxies can recede faster than light because space itself is expanding; nothing overtakes light locally.'] },
        { l: 3, q: 'One method gives H₀ = 67.4 km/s/Mpc and another 73.0 km/s/Mpc. Find 1/H₀ in billions of years for each (1/(1 km/s/Mpc) = 977.8 billion years). What could the difference mean?', a: '14.5 and 13.4 billion years; an unexplained 8% disagreement', s: ['1/H₀ = 977.8 ÷ 67.4 = 14.5 billion years.', '1/H₀ = 977.8 ÷ 73.0 = 13.4 billion years.', 'The difference is about 8%, many times the quoted uncertainties: the Hubble tension.', 'Either one method has an unrecognised error, or the standard model of the universe needs new physics.'] }
      ]
    }
  });
})();
/* ---- notes-al1.js ---- */
/* Geodesic: study notes and ten-problem practice sets, A Level part 1 (Cambridge 9702 standard). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'al-projectile': {
      big: 'A thrown ball looks like it follows one complicated curve, but it is really two simple motions happening at once: steady sideways drift and uniformly accelerated fall. Treat them separately, recombine them, and the parabola, the range formula and the famous 45° all fall out.',
      sec: [
        { h: 'Two independent motions', p: ['Gravity pulls straight down, so it changes only the vertical part of the velocity. Ignoring air, nothing acts sideways, so the horizontal part never changes. Galileo’s key insight was that these two motions do not interfere: a bullet fired horizontally and one dropped at the same moment from the same height land at the same time.', 'So resolve the launch velocity v₀ at angle θ into a horizontal component v₀cos θ and a vertical component v₀sin θ, solve each direction on its own, and use time t to link them.'], eq: R`x = v_0\cos\theta\,t,\qquad y = v_0\sin\theta\,t - \tfrac12 g t^2,\qquad v_x = v_0\cos\theta,\qquad v_y = v_0\sin\theta - g t` },
        { h: 'The shape of the path', p: ['Eliminate t using t = x/(v₀cos θ) and the height becomes a quadratic in x: the path is a parabola. At the top the vertical velocity is zero but the horizontal velocity is not, so the speed there is v₀cos θ, the slowest point of the flight.'], eq: R`y = x\tan\theta - \frac{g\,x^2}{2v_0^2\cos^2\theta}` },
        { h: 'Time of flight, height and range on level ground', p: ['Setting y = 0 gives the time of flight. Half of it is spent rising, and the maximum height comes from v_y² = (v₀ sin θ)² − 2gH = 0. The range is the horizontal speed times the flight time; the double-angle identity makes it compact.', 'Because sin 2θ is largest at 2θ = 90°, the range is greatest at θ = 45°, and complementary angles (30° and 60°) give the same range: one high and slow, one low and fast.'], eq: R`T = \frac{2v_0\sin\theta}{g},\qquad H = \frac{v_0^2\sin^2\theta}{2g},\qquad R = \frac{v_0^2\sin 2\theta}{g}` },
        { h: 'The energy shortcut', p: ['If you only need a speed at some height, energy conservation skips the components: v² = v₀² − 2gΔy, whatever the launch angle. Two balls thrown from the same point at the same speed, one up and one down, hit the ground with the same speed.'] },
        { h: 'Launching from a height', p: ['From a cliff of height h the ball has extra time to fly, so the best angle is less than 45°. The optimum satisfies tan θ = v₀/√(v₀² + 2gh), and the maximum range is (v₀/g)√(v₀² + 2gh). Shot-putters, who release above the ground, use about 37–40°, partly for this reason and partly because they can push harder at lower angles.'], warn: '**Hidden assumptions: no air, no spin, uniform g, flat ground.** Drag ∝ v² shortens and steepens the descent, so real optimum angles for fast balls are well below 45°. Spin adds lift (the Magnus effect): a tour golfer’s drive leaves at about 75 m/s and 11°, for which the vacuum formula gives about 210 m, yet it carries about 250 m. The parabola is wrong in both directions at once, and only measurement tells which effect wins.' }
      ],
      eqs: [[R`u_x = v_0\cos\theta,\ u_y = v_0\sin\theta`, 'resolving the launch velocity'], [R`x = u_x t`, 'horizontal: constant velocity'], [R`y = u_y t - \tfrac12 g t^2`, 'vertical: constant acceleration g downwards'], [R`T = \frac{2v_0\sin\theta}{g}`, 'time of flight on level ground'], [R`H = \frac{v_0^2\sin^2\theta}{2g}`, 'maximum height'], [R`R = \frac{v_0^2\sin 2\theta}{g}`, 'range on level ground; maximum at 45°']],
      how: ['Draw the path, mark the launch point as the origin, choose up as positive.', 'Resolve the initial velocity into horizontal and vertical components.', 'Find the time from the vertical motion (the only direction with acceleration).', 'Use that time in the horizontal motion.', 'Recombine components for the final speed and direction: v = √(v_x² + v_y²), angle = tan⁻¹(v_y/v_x).'],
      sum: ['Horizontal and vertical motions are independent; time links them.', 'Horizontal velocity is constant; vertical acceleration is g downwards.', 'The path is a parabola; at the top only the vertical velocity is zero.', 'Level ground: T = 2v₀sin θ/g, H = v₀²sin²θ/2g, R = v₀²sin 2θ/g, best angle 45°.', 'Air drag and spin change everything for fast balls; check before trusting the parabola.'],
      probs: [
        { l: 1, q: 'A ball rolls off a 1.8 m high wall at 12 m/s horizontally. How long does it take to land and how far from the wall does it land? (g = 9.81 m/s²)', a: '0.61 s; 7.3 m', s: ['Vertical: 1.8 = ½ × 9.81 × t², so t = √(3.6/9.81) = 0.606 s.', 'Horizontal: x = 12 × 0.606 = 7.27 m.'] },
        { l: 1, q: 'A ball is launched at 20 m/s at 30° above the horizontal. Find its horizontal and vertical velocity components.', a: '17.3 m/s and 10.0 m/s', s: ['u_x = 20 cos 30° = 17.3 m/s.', 'u_y = 20 sin 30° = 10.0 m/s.'] },
        { l: 1, q: 'What are the velocity and acceleration of a projectile at the highest point of its flight?', a: 'Velocity horizontal (= v₀cos θ); acceleration g downwards', s: ['The vertical component is momentarily zero, but the horizontal component is unchanged.', 'Gravity still acts, so the acceleration is still 9.81 m/s² downwards.'] },
        { l: 2, q: 'A ball is kicked at 25 m/s at 40° above level ground. Find the time of flight, the maximum height and the range.', a: '3.28 s; 13.2 m; 62.7 m', s: ['T = 2 × 25 sin 40° / 9.81 = 3.28 s.', 'H = (25 sin 40°)² / (2 × 9.81) = 13.2 m.', 'R = 25² sin 80° / 9.81 = 62.7 m.'] },
        { l: 2, q: 'Show that launches at 30° and at 60° with the same speed of 20 m/s reach the same range on level ground.', a: 'Both 35.3 m', s: ['R = v₀² sin 2θ / g.', '30°: sin 60° = 0.866; 60°: sin 120° = 0.866.', 'Both give R = 400 × 0.866 / 9.81 = 35.3 m; the 60° flight takes √3 times longer.'] },
        { l: 2, q: 'A stone thrown horizontally from the top of a 45 m cliff lands 60 m from its base. Find its launch speed, and its speed and direction just before landing.', a: '19.8 m/s; 35.7 m/s at 56° below the horizontal', s: ['Fall time: t = √(2 × 45/9.81) = 3.03 s.', 'Launch speed: 60/3.03 = 19.8 m/s.', 'Vertical speed at landing: 9.81 × 3.03 = 29.7 m/s.', 'Speed = √(19.8² + 29.7²) = 35.7 m/s; angle = tan⁻¹(29.7/19.8) = 56.3° below horizontal.'] },
        { l: 2, q: 'A ball is thrown at 15 m/s at 60° above the horizontal. How high is it when it has travelled 10 m horizontally?', a: '8.6 m', s: ['y = x tan θ − g x² / (2 v₀² cos² θ).', 'y = 10 × 1.732 − 9.81 × 100 / (2 × 225 × 0.25) = 17.32 − 8.72 = 8.6 m.'] },
        { l: 2, q: 'A hunter aims directly at a monkey hanging in a tree. At the instant the gun fires, the monkey lets go. Explain why the bullet still hits it (if it has enough range).', a: 'Both fall the same ½gt² below their straight-line paths', s: ['Without gravity, the bullet would travel straight to the monkey’s original position.', 'With gravity, after time t the bullet is ½gt² below that straight line.', 'The monkey, dropping from rest, is also ½gt² below its starting point. They stay level and meet.'] },
        { l: 3, q: 'A ball is launched at 20 m/s from the top of a 30 m cliff. Find the launch angle that gives the greatest horizontal range, and that range.', a: 'About 32.5°; 64 m', s: ['For launch height h, tan θ* = v₀/√(v₀² + 2gh) = 20/√(400 + 588.6) = 20/31.4 = 0.636.', 'θ* = 32.5°, below 45° because the extra fall time favours a flatter launch.', 'R_{max} = (v₀/g)√(v₀² + 2gh) = (20/9.81) × 31.4 = 64.1 m.'] },
        { l: 3, q: 'A golf drive leaves the club at 75 m/s and 11° above the horizontal with strong backspin. What carry does the drag-free formula predict? Measured carries for such shots are about 250 m. Which hidden assumptions fail, and in which directions?', a: 'About 210 m predicted; lift from spin outweighs drag', s: ['R = v₀² sin 2θ / g = 75² × sin 22° / 9.81 ≈ 215 m (210 m at 74.6 m/s, 10.9°).', 'Air drag alone would make the real carry shorter than this.', 'Backspin makes the ball deflect air downwards, giving an upward Magnus lift that keeps it airborne longer.', 'Here lift wins, so the real carry is about 20% longer: the vacuum parabola fails because it assumes gravity is the only force.'] }
      ]
    },

    'al-circular': {
      big: 'An object moving round a circle at constant speed is still accelerating, because its direction keeps changing. That acceleration always points to the centre and has size v²/r, and something real (tension, friction, gravity, a normal force) must supply the force that causes it.',
      sec: [
        { h: 'Angles in radians and angular speed', p: ['In circular motion angles are measured in radians: the angle subtended by an arc equal to the radius. A full turn is 2π rad. Angular speed ω is the angle swept per second, so ω = 2π/T = 2πf. The speed along the circle is v = rω, so for the same ω, points further out move faster.'], eq: R`\omega = \frac{\Delta\theta}{\Delta t} = \frac{2\pi}{T},\qquad v = r\omega` },
        { h: 'Why the acceleration points inwards', p: ['Take the velocity at two moments a short time apart. Both have length v, but the second has turned through a small angle Δθ. The change Δv is the short side of a thin isosceles triangle, of length about vΔθ, and as Δt → 0 it points towards the centre. Dividing by Δt gives a = vω = v²/r.'], eq: R`a = \frac{v^2}{r} = \omega^2 r\quad\text{(towards the centre)}` },
        { h: 'Centripetal force is a job, not a force', p: ['Newton’s second law says a net force mv²/r towards the centre is needed. It is not an extra force to add to your diagram; it is the name of the job some real force (or combination) is doing. For a car on a bend it is friction; for the Moon, gravity; for a conker on a string, tension; for a plane banking, the horizontal part of the lift.'], box: '**There is no outward “centrifugal force” in an inertial frame.** You feel pushed outwards in a turning car because your body tries to carry on in a straight line while the car turns under you. The only horizontal force on you is the seat or door pushing you inwards.' },
        { h: 'Flat bends, banked tracks and loops', list: ['Flat bend: friction provides mv²/r ≤ μmg, so the top speed is √(μgr), independent of mass.', 'Banked track: with no friction at all, the normal force alone provides the centripetal force when tan θ = v²/(rg).', 'Vertical loop: at the top, weight plus the track’s push provide mv²/r, so the speed there must be at least √(gr) or the car falls away.', 'Conical pendulum: the horizontal part of the tension provides the centripetal force; the period is 2π√(L cos θ/g).'] },
        { h: 'Apparent weight', p: ['What scales (or your body) feel is the normal force. At the bottom of a loop it must hold you up and also provide the centripetal force, so N = mg + mv²/r and you feel heavier. At the top it can fall to zero: weightlessness, the same free fall that astronauts feel in orbit.'], warn: '**Hidden assumptions.** v²/r assumes uniform motion on a perfect circle. In a vertical loop the speed changes all the way round, so only the radial part of the acceleration is v²/r; there is also a tangential acceleration. In rotating space habitats, the floor rotates faster than your head: in a 100 m radius station turning in 20 s, your head feels 1.8% less “gravity” than your feet, and turning your head at 3 rpm brings on motion sickness for many people.' }
      ],
      eqs: [[R`\omega = 2\pi f = \frac{2\pi}{T}`, 'angular speed in rad/s'], [R`v = r\omega`, 'linear speed'], [R`a = \frac{v^2}{r} = r\omega^2`, 'centripetal acceleration, towards the centre'], [R`F = \frac{mv^2}{r} = mr\omega^2`, 'resultant force needed'], [R`v_{\max} = \sqrt{\mu g r}`, 'flat bend with friction coefficient μ'], [R`\tan\theta = \frac{v^2}{rg}`, 'ideal banking angle']],
      how: ['Identify the centre of the circle and the radius r.', 'Draw every real force; resolve them towards the centre.', 'Set the net inward force equal to mv²/r (or mrω²).', 'Use energy conservation if the speed changes round the circle (vertical loops).', 'Check limits: at the top of a loop the normal force cannot be negative.'],
      sum: ['Constant speed in a circle still means acceleration v²/r towards the centre.', 'A real force (tension, friction, gravity, normal force) provides the centripetal force.', 'No centrifugal force in an inertial frame: you just tend to go straight on.', 'Flat bend: v_{max} = √(μgr). Banked: tan θ = v²/rg. Top of a loop: v ≥ √(gr).', 'Apparent weight = normal force; largest at the bottom of a loop.'],
      probs: [
        { l: 1, q: 'A record turns at 33⅓ revolutions per minute. What is its angular speed in rad/s?', a: '3.49 rad/s', s: ['33.33 rev/min = 0.5556 rev/s.', 'ω = 2π × 0.5556 = 3.49 rad/s.'] },
        { l: 1, q: 'A car travels at 15 m/s round a bend of radius 50 m. What is its centripetal acceleration?', a: '4.5 m/s²', s: ['a = v²/r = 225/50 = 4.5 m/s².'] },
        { l: 1, q: 'What provides the centripetal force that keeps the Moon in orbit?', a: 'Earth’s gravitational pull', s: ['The only significant force on the Moon towards Earth is gravity; it does the centripetal job.'] },
        { l: 2, q: 'A 0.20 kg mass on a 0.80 m string is whirled in a horizontal circle at 3.0 revolutions per second. Ignoring gravity, find the tension.', a: '57 N', s: ['ω = 2π × 3.0 = 18.85 rad/s.', 'T = mω²r = 0.20 × 18.85² × 0.80 = 56.8 N.'] },
        { l: 2, q: 'What is the greatest speed at which a car can take a flat bend of radius 40 m if the coefficient of friction is 0.70?', a: '16.6 m/s (about 60 km/h)', s: ['Friction provides the centripetal force: mv²/r ≤ μmg.', 'v_{max} = √(μgr) = √(0.70 × 9.81 × 40) = 16.6 m/s. The mass cancels.'] },
        { l: 2, q: 'At what angle should a curve of radius 150 m be banked so that cars at 25 m/s need no friction?', a: '23°', s: ['tan θ = v²/(rg) = 625/(150 × 9.81) = 0.425.', 'θ = 23.0°.'] },
        { l: 2, q: 'A roller-coaster loop has radius 5.0 m. What is the minimum speed at the top, and the corresponding speed at the bottom (no friction)?', a: '7.0 m/s at the top; 15.7 m/s at the bottom', s: ['At the top, gravity alone just provides the centripetal force: mg = mv²/r, so v = √(gr) = √(9.81 × 5.0) = 7.0 m/s.', 'Energy: ½v_b² = ½v_t² + g(2r), so v_b² = gr + 4gr = 5gr.', 'v_b = √(5 × 9.81 × 5.0) = 15.7 m/s.'] },
        { l: 2, q: 'For the loop in the previous question, find the normal force on a 60 kg rider at the bottom. How many times their weight is it?', a: '3530 N, six times their weight', s: ['N − mg = mv_b²/r = m × 5g, so N = 6mg.', 'N = 6 × 60 × 9.81 = 3530 N: riders feel “6 g” at the bottom of a minimum-speed loop, which is why real loops are not circles.'] },
        { l: 3, q: 'A conical pendulum has a 1.0 m string making 30° with the vertical. Find its period.', a: '1.87 s', s: ['Vertical: T cos θ = mg. Horizontal: T sin θ = mω²r with r = L sin θ.', 'Dividing: tan θ = ω²L sin θ / g, so ω² = g/(L cos θ).', 'Period = 2π√(L cos θ / g) = 2π√(0.866/9.81) = 1.87 s.'] },
        { l: 3, q: 'A space station of radius 100 m rotates to give 1 g at its rim. Find its rotation period and rate in rpm. How much weaker is the effective gravity at the head of a 1.8 m astronaut, and why might the rotation rate be a problem?', a: 'About 20 s, 3.0 rpm; 1.8% weaker at the head', s: ['ω = √(g/r) = √(9.81/100) = 0.313 rad/s; T = 2π/ω = 20.1 s ≈ 3.0 rpm.', 'At the head r = 98.2 m, so g_{eff} = ω²r is 98.2/100 = 0.982 of the floor value.', 'Many people feel motion sickness when they move their heads in a frame rotating faster than about 2 rpm, because the inner ear senses Coriolis effects. So real designs would need a larger radius and slower spin.'] }
      ]
    },

    'al-shm': {
      big: 'Whenever something is pulled back towards a resting position with a force proportional to how far it has been moved, it oscillates in exactly the same way: simple harmonic motion. Springs, pendulums, guitar strings, atoms in a crystal and the electric field in a radio circuit all follow the same equation, a = −ω²x.',
      sec: [
        { h: 'The defining equation', p: ['A mass on a spring feels F = −kx: the further you pull it, the harder it pulls back, always towards equilibrium. Newton’s second law then gives an acceleration proportional to displacement and opposite in direction. That is the definition of SHM.'], eq: R`a = \ddot x = -\omega^2 x,\qquad \omega^2 = \frac{k}{m}` },
        { h: 'The solution: a shadow of circular motion', p: ['A point going round a circle of radius A at angular speed ω casts a shadow that moves back and forth along a line. The shadow’s position is A cos(ωt + φ) and its acceleration is exactly −ω² times its position. So SHM is circular motion seen edge-on, and its period is the time for one lap: T = 2π/ω.', 'Differentiating gives the velocity, a quarter of a cycle ahead of the displacement; the acceleration is half a cycle ahead (opposite in sign).'], eq: R`x = A\cos(\omega t + \phi),\quad v = -A\omega\sin(\omega t+\phi),\quad v = \pm\omega\sqrt{A^2 - x^2}` },
        { h: 'Period does not depend on amplitude', p: ['For a mass on a spring, T = 2π√(m/k), whatever the amplitude. A bigger swing has further to go but is pulled harder and moves faster, and the two effects cancel exactly. This isochronism is why pendulums made good clocks.', 'A simple pendulum is SHM only for small angles, where sin θ ≈ θ: then T = 2π√(L/g), independent of the mass.'], eq: R`T_{\text{spring}} = 2\pi\sqrt{\frac{m}{k}},\qquad T_{\text{pendulum}} = 2\pi\sqrt{\frac{L}{g}}` },
        { h: 'Energy', p: ['The total energy is fixed: ½kA² = ½mω²A². At the extremes it is all potential (the mass is momentarily at rest); at the centre it is all kinetic (maximum speed ωA). In between, KE = ½mω²(A² − x²) and PE = ½mω²x².'] },
        { h: 'Damping and resonance', p: ['Real oscillators lose energy. Light damping makes the amplitude decay gradually; critical damping returns the system to rest in the shortest time without overshooting (car suspension, door closers); heavy damping returns it slowly.', 'Driven at a frequency close to its natural frequency, an oscillator absorbs energy efficiently and its amplitude grows large: resonance. The lighter the damping, the taller and sharper the resonance peak.'], warn: '**Two famous stories, checked.** London’s Millennium Bridge (2000) swayed sideways because walkers fell into step with its motion, a feedback resonance that was cured by adding dampers. The 1940 Tacoma Narrows collapse is often blamed on simple resonance with the wind, but the wind was steady, not periodic: the cause was aeroelastic flutter, a self-excited instability. And the pendulum formula itself assumes small angles: at a 30° amplitude the true period is 1.7% longer.' }
      ],
      eqs: [[R`a = -\omega^2 x`, 'defining condition for SHM'], [R`x = A\cos(\omega t + \phi)`, 'displacement; A amplitude, φ phase'], [R`v_{\max} = \omega A,\quad a_{\max} = \omega^2 A`, 'peak speed (at x = 0) and acceleration (at x = ±A)'], [R`T = 2\pi\sqrt{m/k}`, 'mass on a spring'], [R`T = 2\pi\sqrt{L/g}`, 'simple pendulum, small angles'], [R`E = \tfrac12 m\omega^2A^2`, 'total energy']],
      how: ['Check the motion really is SHM: is the restoring force proportional to displacement?', 'Find ω from the system (√(k/m), √(g/L)) or from the period (2π/T).', 'Use v = ω√(A² − x²) for speeds at a given position, and a = −ω²x for accelerations.', 'Use the energy ½mω²A² when the question involves speeds and amplitudes together.'],
      sum: ['SHM: a = −ω²x; the motion is A cos(ωt + φ).', 'Period is independent of amplitude: 2π√(m/k) or 2π√(L/g).', 'Max speed ωA at the centre; max acceleration ω²A at the ends.', 'Energy ½mω²A² swaps between kinetic and potential.', 'Damping removes energy; driving near the natural frequency causes resonance.'],
      probs: [
        { l: 1, q: 'A 0.50 kg mass hangs on a spring with k = 200 N/m. What is its period of oscillation?', a: '0.314 s', s: ['T = 2π√(m/k) = 2π√(0.50/200) = 2π × 0.05 = 0.314 s.'] },
        { l: 1, q: 'How long must a simple pendulum be for a period of exactly 2.00 s? (g = 9.81 m/s²)', a: '0.994 m', s: ['L = gT²/(4π²) = 9.81 × 4.00 / 39.48 = 0.994 m: the “seconds pendulum” of old clocks.'] },
        { l: 1, q: 'Where in SHM is the speed greatest, and where is the acceleration greatest?', a: 'Speed at the centre; acceleration at the extremes', s: ['At x = 0 all the energy is kinetic, so speed is greatest.', 'a = −ω²x is largest where |x| is largest: at x = ±A.'] },
        { l: 2, q: 'An oscillator has amplitude 0.050 m and frequency 2.0 Hz. Find its maximum speed and maximum acceleration.', a: '0.63 m/s; 7.9 m/s²', s: ['ω = 2πf = 12.57 rad/s.', 'v_{max} = ωA = 0.628 m/s; a_{max} = ω²A = 7.90 m/s².'] },
        { l: 2, q: 'For the same oscillator, find the speed when the displacement is 0.030 m.', a: '0.50 m/s', s: ['v = ω√(A² − x²) = 12.57 × √(0.0025 − 0.0009) = 12.57 × 0.040 = 0.50 m/s.'] },
        { l: 2, q: 'A 0.20 kg mass on a spring with k = 80 N/m oscillates with amplitude 0.10 m. Find its total energy and maximum speed.', a: '0.40 J; 2.0 m/s', s: ['E = ½kA² = ½ × 80 × 0.01 = 0.40 J.', 'At the centre E = ½mv², so v_{max} = √(2 × 0.40/0.20) = 2.0 m/s.'] },
        { l: 2, q: 'A mass on a spring has a period of 1.20 s. The mass is doubled. What is the new period?', a: '1.70 s', s: ['T ∝ √m, so T = 1.20 × √2 = 1.70 s.'] },
        { l: 2, q: 'The displacement of an oscillator is x = 0.08 cos(5πt) in metres. State the amplitude and frequency, and find x at t = 0.10 s.', a: '0.08 m; 2.5 Hz; 0', s: ['A = 0.08 m and ω = 5π rad/s, so f = ω/2π = 2.5 Hz.', 'x(0.10) = 0.08 cos(0.5π) = 0: it is passing through equilibrium.'] },
        { l: 3, q: 'Find the period of a 1.0 m pendulum on the Moon (g = 1.62 m/s²) and compare it with Earth (9.81 m/s²).', a: '4.94 s on the Moon against 2.01 s on Earth (2.46 times longer)', s: ['Moon: T = 2π√(1.0/1.62) = 4.94 s.', 'Earth: T = 2π√(1.0/9.81) = 2.01 s.', 'Ratio √(9.81/1.62) = 2.46: a pendulum clock taken to the Moon runs about 2.5 times slow.'] },
        { l: 3, q: 'A spring of mass 30 g and k = 50 N/m holds a 200 g mass. Predict the period ignoring the spring’s mass, then using the effective mass m + m_s/3. Why is a third of the spring’s mass included?', a: '0.397 s and 0.407 s', s: ['Ignoring the spring: T = 2π√(0.200/50) = 0.397 s.', 'With m_{eff} = 0.200 + 0.010 = 0.210 kg: T = 2π√(0.210/50) = 0.407 s, 2.5% longer.', 'Each bit of spring moves at a speed proportional to its distance from the fixed end; adding up their kinetic energies gives ½(m_s/3)v². Careful experiments agree with the corrected value.'] }
      ]
    },

    'al-capacitors': {
      big: 'A capacitor stores charge, and therefore energy, on two conductors separated by an insulator. Let it discharge through a resistor and the current falls exponentially, because the less charge is left, the smaller the voltage pushing it out. One number, the time constant RC, sets the pace.',
      sec: [
        { h: 'Capacitance', p: ['Charge flows onto one plate and an equal charge leaves the other, until the voltage across the plates matches the supply. The charge stored is proportional to the voltage; the constant is the capacitance, in farads. A farad is huge: practical capacitors range from picofarads to millifarads, and supercapacitors reach thousands of farads.', 'For parallel plates of area A, separation d and a dielectric of relative permittivity ε_r, the capacitance grows with area and shrinks with separation.'], eq: R`C = \frac{Q}{V},\qquad C = \frac{\varepsilon_0\varepsilon_r A}{d}` },
        { h: 'Energy stored', p: ['Charging takes work, because each extra bit of charge is pushed against the voltage already built up. On a graph of V against Q the energy is the area under the straight line: half of QV, not QV.'], eq: R`W = \tfrac12 QV = \tfrac12 CV^2 = \frac{Q^2}{2C}` },
        { h: 'Discharge: exponential decay', p: ['Through a resistor, the current is I = V/R = Q/(RC), and that current is the rate at which charge leaves. So dQ/dt = −Q/(RC): the rate of loss is proportional to what is left. The solution is an exponential, and the same shape describes V and I.', 'After one time constant τ = RC the charge has fallen to 1/e ≈ 37% of its starting value; after 5τ it is below 1%. The time to halve is RC ln 2 ≈ 0.69 RC.'], eq: R`Q = Q_0e^{-t/RC},\quad V = V_0e^{-t/RC},\quad I = I_0e^{-t/RC},\qquad t_{1/2} = RC\ln 2` },
        { h: 'Charging', p: ['Charging from a supply V₀ through R, the capacitor voltage rises towards V₀ along 1 − e^{−t/RC} while the current falls exponentially from V₀/R to zero.'], eq: R`V_C = V_0\left(1 - e^{-t/RC}\right),\qquad I = \frac{V_0}{R}e^{-t/RC}` },
        { h: 'Combining capacitors', p: ['In parallel, capacitances add (more plate area). In series, reciprocals add (each capacitor carries the same charge and the voltages add). Note the pattern is the opposite of resistors.'], eq: R`C_{\parallel} = C_1 + C_2,\qquad \frac{1}{C_{\text{series}}} = \frac{1}{C_1} + \frac{1}{C_2}` },
        { h: 'Uses', list: ['Camera flashes and defibrillators: store energy slowly, release it in milliseconds.', 'Smoothing the output of rectifiers in power supplies.', 'Timing circuits: the RC time constant sets delays and oscillator frequencies.', 'Memory: each bit of a DRAM chip is a tiny capacitor that leaks, so it is refreshed every 64 ms or so.'], warn: '**Hidden assumptions: an ideal, leak-free capacitor and a fixed R.** Real dielectrics leak, so a charged capacitor slowly discharges on its own (electrolytic capacitors noticeably, in minutes to days). And when you charge a capacitor from a battery through any resistor, exactly half the energy drawn from the battery is lost as heat, however small R is: an ideal-circuit puzzle that shows the model breaks down at R → 0.' }
      ],
      eqs: [[R`Q = CV`, 'charge in C; capacitance in F; voltage in V'], [R`C = \varepsilon_0\varepsilon_r A/d`, 'parallel-plate capacitor; ε₀ = 8.85 × 10⁻¹² F/m'], [R`W = \tfrac12 CV^2`, 'energy stored'], [R`\tau = RC`, 'time constant in s'], [R`x = x_0e^{-t/RC}`, 'Q, V or I during discharge'], [R`t_{1/2} = RC\ln2`, 'time to halve']],
      how: ['Write down τ = RC first; it sets every time in the problem.', 'For discharge use x = x₀e^{−t/RC}; take ln of both sides to solve for t.', 'For energy use ½CV², and remember energy ∝ V².', 'For combinations, parallel capacitances add, series reciprocals add.'],
      sum: ['Q = CV; parallel plates C = ε₀ε_rA/d.', 'Energy ½CV², the area under the V–Q graph.', 'Discharge is exponential with time constant RC; 37% left after one τ.', 'Charging: V rises as 1 − e^{−t/RC}; current falls exponentially.', 'Real capacitors leak; half the battery’s energy is always dissipated while charging.'],
      probs: [
        { l: 1, q: 'A 470 μF capacitor is charged to 12 V. How much charge does it store?', a: '5.6 mC', s: ['Q = CV = 470 × 10⁻⁶ × 12 = 5.64 × 10⁻³ C.'] },
        { l: 1, q: 'How much energy does that capacitor store?', a: '34 mJ', s: ['W = ½CV² = ½ × 470 × 10⁻⁶ × 144 = 0.0338 J.'] },
        { l: 1, q: 'What is the time constant of a 100 μF capacitor discharging through 10 kΩ?', a: '1.0 s', s: ['τ = RC = 10 000 × 100 × 10⁻⁶ = 1.0 s.'] },
        { l: 2, q: 'A 1000 μF capacitor charged to 9.0 V discharges through 2.2 kΩ. What is its voltage after 3.0 s?', a: '2.3 V', s: ['τ = 2200 × 1000 × 10⁻⁶ = 2.2 s.', 'V = 9.0 e^{−3.0/2.2} = 9.0 × 0.256 = 2.3 V.'] },
        { l: 2, q: 'For the same circuit, how long does the voltage take to fall to 1.0 V?', a: '4.8 s', s: ['1.0 = 9.0 e^{−t/2.2}, so t = 2.2 ln 9 = 4.83 s.'] },
        { l: 2, q: 'How long does that circuit take to lose half its voltage? Half its stored energy?', a: '1.52 s for half the voltage; 0.76 s for half the energy', s: ['Voltage halves in RC ln 2 = 2.2 × 0.693 = 1.52 s.', 'Energy ∝ V², so it decays with time constant RC/2: half the energy is gone after (RC/2) ln 2 = 0.76 s.'] },
        { l: 2, q: 'Find the combined capacitance of 2.0 μF and 3.0 μF connected (a) in parallel, (b) in series.', a: '(a) 5.0 μF (b) 1.2 μF', s: ['Parallel: 2.0 + 3.0 = 5.0 μF.', 'Series: 1/C = 1/2 + 1/3 = 5/6, so C = 1.2 μF, less than either.'] },
        { l: 2, q: 'Find the capacitance of two parallel plates of area 0.010 m² separated by 1.0 mm of air.', a: '89 pF', s: ['C = ε₀A/d = 8.85 × 10⁻¹² × 0.010 / 0.0010 = 8.9 × 10⁻¹¹ F.', 'That tiny value is why practical capacitors roll up long thin plates with a thin dielectric between them.'] },
        { l: 3, q: 'A defibrillator charges a 32 μF capacitor to 5.0 kV and discharges it through a patient’s chest (about 50 Ω). Find the energy stored, the time constant and the initial current.', a: '400 J; 1.6 ms; 100 A', s: ['W = ½CV² = ½ × 32 × 10⁻⁶ × (5000)² = 400 J.', 'τ = RC = 50 × 32 × 10⁻⁶ = 1.6 ms.', 'I₀ = V/R = 5000/50 = 100 A, falling to 37 A after 1.6 ms.'] },
        { l: 3, q: 'Show that when an uncharged capacitor C is charged to V through a resistor R from a battery of e.m.f. V, the heat produced in R equals the energy finally stored, whatever the value of R.', a: 'Both equal ½CV²', s: ['The battery moves charge Q = CV through its e.m.f. V, doing work QV = CV².', 'The capacitor ends up with ½CV².', 'The rest, ½CV², must be dissipated: ∫I²R dt = ∫(V/R)²e^{−2t/RC}R dt = (V²/R)(RC/2) = ½CV², independent of R.', 'Even as R → 0 the loss stays the same (the current becomes enormous and brief), showing the ideal-component model is incomplete there.'] }
      ]
    },

    'al-photoelectric': {
      big: 'Shine light on a clean metal and electrons can fly out, but only if the light’s frequency is high enough, however bright it is. Wave theory could not explain that; Einstein’s idea that light delivers energy in packets of hf could, and it gave the first precise measurement of Planck’s constant.',
      sec: [
        { h: 'What experiments show', list: ['Below a threshold frequency f₀ no electrons are emitted, however intense the light.', 'Above f₀ emission starts at once, with no measurable delay, even in very dim light.', 'The maximum kinetic energy of the electrons rises linearly with frequency and does not depend on intensity.', 'The number of electrons per second (the photocurrent) is proportional to the intensity.'] },
        { h: 'Why the wave picture fails', p: ['In a classical wave, energy arrives continuously and is spread over the wavefront. Brighter light should eject faster electrons, any frequency should work if you wait long enough, and dim light should take seconds before an electron has gathered enough energy. All three predictions are wrong.'] },
        { h: 'Einstein’s photon explanation (1905)', p: ['Light energy is delivered in quanta of size hf. One photon gives all its energy to one electron. Leaving the metal costs at least the work function φ, so the fastest electrons have hf − φ left. Below f₀ = φ/h no single photon has enough energy, and doubling the intensity only doubles the number of photons, not their energy.'], eq: R`E = hf,\qquad hf = \phi + \tfrac12 m v_{\max}^2` },
        { h: 'Stopping potential: measuring h', p: ['Make the collecting electrode negative. The current stops when eV_s equals the largest kinetic energy. A graph of V_s against f is a straight line with gradient h/e and intercept −φ/e. Millikan, who expected to disprove Einstein, measured h this way in 1916 to within about 1% of today’s value.'], eq: R`eV_s = hf - \phi\;\Longrightarrow\; V_s = \frac{h}{e}f - \frac{\phi}{e}` },
        { h: 'The electronvolt', p: ['1 eV is the energy an electron gains crossing 1 V: 1.60 × 10⁻¹⁹ J. Work functions are a few eV (caesium 2.1 eV, zinc 4.3 eV, platinum 5.6 eV); visible photons carry 1.8–3.1 eV, so visible light frees electrons from caesium but not from zinc.'], warn: '**What the experiment does and does not prove.** It proves that light and electrons exchange energy in lumps of hf. It does not by itself prove that light consists of particles: treating the light as a classical wave and only the electrons quantum-mechanically also predicts a threshold and prompt emission (Lamb and Scully, 1969). The decisive evidence for photons came later, from experiments such as antibunching (1977), where a classical wave gives the wrong statistics.' }
      ],
      eqs: [[R`E = hf = \frac{hc}{\lambda}`, 'photon energy; h = 6.63 × 10⁻³⁴ J s'], [R`hf = \phi + KE_{\max}`, 'Einstein’s photoelectric equation'], [R`f_0 = \phi/h`, 'threshold frequency'], [R`eV_s = KE_{\max}`, 'stopping potential'], [R`1\ \text{eV} = 1.60\times10^{-19}\ \text{J}`, 'electronvolt']],
      how: ['Work in electronvolts where possible: E (eV) ≈ 1240 / λ (nm).', 'Compare photon energy with the work function first: no emission if hf < φ.', 'KE_max = hf − φ; stopping potential V_s = KE_max/e.', 'For graphs of V_s against f, gradient = h/e and the f-intercept is the threshold frequency.'],
      sum: ['Light energy arrives in photons of hf; one photon frees at most one electron.', 'Threshold frequency f₀ = φ/h; brightness cannot make up for low frequency.', 'KE_max = hf − φ depends on frequency, not intensity; intensity sets the number of electrons.', 'Stopping-potential graphs measure h/e and φ.', 'The effect is strong evidence for quanta, though not on its own proof of photons.'],
      probs: [
        { l: 1, q: 'Find the energy of a 500 nm photon in joules and in electronvolts.', a: '3.97 × 10⁻¹⁹ J = 2.48 eV', s: ['E = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ / 500 × 10⁻⁹ = 3.97 × 10⁻¹⁹ J.', 'Divide by 1.60 × 10⁻¹⁹: 2.48 eV.'] },
        { l: 1, q: 'A metal has a work function of 2.3 eV. What is its threshold frequency?', a: '5.6 × 10^{14} Hz', s: ['f₀ = φ/h = 2.3 × 1.60 × 10⁻¹⁹ / 6.63 × 10⁻³⁴ = 5.6 × 10^{14} Hz (green light).'] },
        { l: 1, q: 'Why does very bright red light (photon energy 1.9 eV) eject no electrons from zinc (φ = 4.3 eV)?', a: 'Each photon has too little energy', s: ['Each electron absorbs one photon at a time.', '1.9 eV is less than 4.3 eV, so no electron can escape, however many photons arrive.'] },
        { l: 2, q: 'Ultraviolet light of wavelength 200 nm falls on zinc (φ = 4.3 eV). Find the maximum kinetic energy of the electrons and the stopping potential.', a: '1.9 eV; 1.9 V', s: ['Photon energy = 1240/200 = 6.2 eV.', 'KE_max = 6.2 − 4.3 = 1.9 eV, so V_s = 1.9 V.'] },
        { l: 2, q: 'Find the maximum speed of those electrons.', a: '8.2 × 10⁵ m/s', s: ['KE = 1.9 × 1.60 × 10⁻¹⁹ = 3.04 × 10⁻¹⁹ J.', 'v = √(2KE/m) = √(2 × 3.04 × 10⁻¹⁹ / 9.11 × 10⁻³¹) = 8.2 × 10⁵ m/s.'] },
        { l: 2, q: 'A graph of stopping potential against frequency has gradient 4.1 × 10⁻¹⁵ V s and meets the V axis at −2.0 V. Find h and the work function.', a: 'h = 6.6 × 10⁻³⁴ J s; φ = 2.0 eV', s: ['Gradient = h/e, so h = 4.1 × 10⁻¹⁵ × 1.60 × 10⁻¹⁹ = 6.6 × 10⁻³⁴ J s.', 'Intercept = −φ/e, so φ = 2.0 eV.'] },
        { l: 2, q: 'How many photons per second does a 1.0 mW, 650 nm laser pointer emit?', a: '3.3 × 10^{15} per second', s: ['Photon energy = hc/λ = 3.06 × 10⁻¹⁹ J.', 'N = 1.0 × 10⁻³ / 3.06 × 10⁻¹⁹ = 3.3 × 10^{15} s⁻¹.'] },
        { l: 2, q: 'The intensity of light on a photocell is doubled at constant frequency. What happens to the photocurrent and to the stopping potential?', a: 'Current doubles; stopping potential unchanged', s: ['Twice as many photons per second free twice as many electrons.', 'Each photon still has the same energy, so KE_max and V_s do not change.'] },
        { l: 3, q: 'In a wave model, light of intensity 1.0 W/m² falls on sodium (φ = 2.3 eV), and each atom collects energy over an area of about 1 × 10⁻¹⁹ m² (its size). Estimate how long an electron would take to gather enough energy to escape. Compare with experiment.', a: 'About 4 s, yet emission is observed within nanoseconds', s: ['Energy needed: 2.3 × 1.60 × 10⁻¹⁹ = 3.7 × 10⁻¹⁹ J.', 'Power collected: 1.0 × 1 × 10⁻¹⁹ = 1 × 10⁻¹⁹ W.', 'Time ≈ 3.7 s.', 'Experiments find no delay longer than about 10⁻⁹ s, a contradiction of nine orders of magnitude for the classical picture.'] },
        { l: 3, q: 'Does the photoelectric effect on its own prove that light is made of photons? Explain.', a: 'No: a semiclassical model also explains it; photons are proved by other experiments', s: ['If the electrons in the metal have quantised energy levels but the light is treated as a classical wave, quantum mechanics still predicts a threshold, KE_max = hf − φ and prompt emission (Lamb and Scully, 1969).', 'So the effect proves energy exchange in quanta, not that the field itself is quantised.', 'Stronger evidence comes from experiments a classical wave cannot fake, such as photon antibunching (Kimble, Dagenais and Mandel, 1977) and single photons that never trigger both outputs of a beam splitter (Grangier, Roger and Aspect, 1986).'] }
      ]
    },

    'al-gravfields': {
      big: 'Newton showed that the force making apples fall also holds the Moon and the planets, weakening as the square of distance. From that single law come orbital speeds, Kepler’s rule that T² ∝ r³, geostationary satellites, escape velocity and a way to weigh planets and stars.',
      sec: [
        { h: 'Newton’s law of gravitation', p: ['Every pair of masses attracts with a force proportional to both masses and inversely proportional to the square of the distance between their centres. G = 6.67 × 10⁻¹¹ N m²/kg² is tiny, which is why gravity between everyday objects is undetectable without delicate apparatus (Cavendish, 1798).', 'Outside a spherical body, its gravity acts as if all its mass were at the centre.'], eq: R`F = \frac{GMm}{r^2}` },
        { h: 'Field strength and potential', p: ['The gravitational field strength g is the force per kilogram: GM/r², pointing towards the mass. The potential φ is the work done per kilogram bringing a mass from infinity to that point. It is negative, because gravity pulls the mass in, and it rises towards zero far away. Field strength is minus the gradient of potential.'], eq: R`g = \frac{GM}{r^2},\qquad \phi = -\frac{GM}{r},\qquad g = -\frac{d\phi}{dr}` },
        { h: 'Circular orbits and Kepler’s third law', p: ['For a circular orbit gravity provides the centripetal force. The orbiting mass cancels, so every satellite at the same radius moves at the same speed. Writing ω = 2π/T gives Kepler’s third law: the square of the period is proportional to the cube of the radius.'], eq: R`\frac{GMm}{r^2} = \frac{mv^2}{r}\;\Rightarrow\; v = \sqrt{\frac{GM}{r}},\qquad T^2 = \frac{4\pi^2}{GM}\,r^3` },
        { h: 'Geostationary orbits', p: ['A satellite above the equator with a period of one sidereal day (86 164 s) stays over the same point of Earth. Kepler’s law fixes its radius: about 42 200 km from Earth’s centre, 35 800 km above the surface. Communications and weather satellites sit there.'] },
        { h: 'Energy and escape', p: ['The gravitational potential energy of m at r is −GMm/r. To escape completely, its kinetic energy must at least cancel that, giving the escape speed √(2GM/r): 11.2 km/s from Earth’s surface, 2.4 km/s from the Moon. Escape speed is √2 times the circular orbital speed at the same radius.'], eq: R`v_{\text{esc}} = \sqrt{\frac{2GM}{r}}` },
        { h: 'Weighing the heavens', p: ['Measure a moon’s or planet’s orbital radius and period and Kepler’s law gives the central mass: M = 4π²r³/(GT²). Earth’s orbit gives the Sun’s mass, 2.0 × 10³⁰ kg; Io’s orbit gives Jupiter’s.'], warn: '**Where Newton’s gravity fails.** Mercury’s orbit slowly rotates by 43 arcseconds per century more than Newtonian gravity predicts from the other planets; general relativity accounts for it exactly. GPS satellite clocks run 38 μs per day fast relative to the ground and must be corrected using relativity. And stars in the outer parts of galaxies orbit far too fast for the visible mass: either most of the mass is invisible (dark matter) or the law of gravity changes at low accelerations.' }
      ],
      eqs: [[R`F = \frac{GMm}{r^2}`, 'G = 6.67 × 10⁻¹¹ N m² kg⁻²'], [R`g = \frac{GM}{r^2}`, 'field strength in N/kg'], [R`\phi = -\frac{GM}{r}`, 'potential in J/kg; zero at infinity'], [R`v = \sqrt{GM/r}`, 'circular orbital speed'], [R`T^2 = \frac{4\pi^2 r^3}{GM}`, 'Kepler’s third law'], [R`v_{\text{esc}} = \sqrt{2GM/r}`, 'escape speed']],
      how: ['Measure r from the centre of the attracting body, not from its surface.', 'For orbits, set GMm/r² = mv²/r (or mω²r); the orbiting mass cancels.', 'For energy changes, use −GMm/r, not mgh, when the height change is comparable with the radius.', 'Keep times in seconds (a day is 86 400 s; a sidereal day 86 164 s).'],
      sum: ['F = GMm/r²; g = GM/r²; φ = −GM/r.', 'Circular orbit: v = √(GM/r); T² ∝ r³ (Kepler 3).', 'Geostationary radius ≈ 42 200 km.', 'Escape speed √(2GM/r), 11.2 km/s for Earth.', 'Newtonian gravity fails for Mercury’s perihelion, GPS clocks and galaxy rotation.'],
      probs: [
        { l: 1, q: 'Calculate g at Earth’s surface from G = 6.67 × 10⁻¹¹ N m²/kg², M = 5.97 × 10²⁴ kg and R = 6.37 × 10⁶ m.', a: '9.82 N/kg', s: ['g = GM/R² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ / (6.37 × 10⁶)² = 9.82 N/kg.'] },
        { l: 1, q: 'Find the gravitational force between Earth and the Moon (M_{Moon} = 7.35 × 10²² kg, distance 3.84 × 10⁸ m).', a: '2.0 × 10²⁰ N', s: ['F = GMm/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 7.35 × 10²² / (3.84 × 10⁸)² = 1.99 × 10²⁰ N.'] },
        { l: 1, q: 'By what factor does g change if you move from Earth’s surface to twice Earth’s radius from its centre?', a: 'It falls to a quarter', s: ['g ∝ 1/r², and (1/2)² = 1/4.'] },
        { l: 2, q: 'Find the radius of a geostationary orbit (period 86 164 s).', a: '4.22 × 10⁷ m (35 800 km above the surface)', s: ['r³ = GMT²/(4π²) = 3.98 × 10¹⁴ × (86 164)² / 39.48.', 'r = 4.22 × 10⁷ m; subtracting Earth’s radius gives an altitude of 35 800 km.'] },
        { l: 2, q: 'Find the orbital speed and period of the ISS, which orbits 400 km above the surface.', a: '7.67 km/s; 92 min', s: ['r = 6.37 × 10⁶ + 4.0 × 10⁵ = 6.77 × 10⁶ m.', 'v = √(GM/r) = 7.67 × 10³ m/s.', 'T = 2πr/v = 5545 s = 92.4 min (measured: about 92.7 min).'] },
        { l: 2, q: 'Find the escape speeds from Earth’s surface and from the Moon’s surface (Moon: M = 7.35 × 10²² kg, R = 1.74 × 10⁶ m).', a: '11.2 km/s and 2.4 km/s', s: ['Earth: √(2GM/R) = √(2 × 3.98 × 10¹⁴ / 6.37 × 10⁶) = 11.2 km/s.', 'Moon: √(2 × 6.67 × 10⁻¹¹ × 7.35 × 10²² / 1.74 × 10⁶) = 2.38 km/s, which is why the Moon has lost any atmosphere.'] },
        { l: 2, q: 'Earth orbits the Sun at 1.496 × 10¹¹ m in 3.156 × 10⁷ s. Find the mass of the Sun.', a: '1.99 × 10³⁰ kg', s: ['M = 4π²r³/(GT²) = 39.48 × (1.496 × 10¹¹)³ / (6.67 × 10⁻¹¹ × (3.156 × 10⁷)²) = 1.99 × 10³⁰ kg.'] },
        { l: 2, q: 'How much energy does it take to lift a 1000 kg satellite from Earth’s surface into a circular orbit 400 km up? (Ignore Earth’s rotation.)', a: 'About 33 GJ', s: ['Total energy in orbit: −GMm/(2r). At the surface: −GMm/R.', 'Energy needed = GMm(1/R − 1/(2r)) = 3.98 × 10¹⁷ × (1/6.37 × 10⁶ − 1/1.354 × 10⁷).', '= 3.98 × 10¹⁷ × 8.31 × 10⁻⁸ = 3.3 × 10^{10} J. Only about 11% of it is potential energy; the rest is the orbital kinetic energy.'] },
        { l: 3, q: 'Jupiter’s moon Io orbits at 4.22 × 10⁸ m with a period of 1.769 days. Find the mass of Jupiter.', a: '1.90 × 10²⁷ kg', s: ['T = 1.769 × 86 400 = 1.528 × 10⁵ s.', 'M = 4π²r³/(GT²) = 39.48 × (4.22 × 10⁸)³ / (6.67 × 10⁻¹¹ × (1.528 × 10⁵)²) = 1.90 × 10²⁷ kg, about 318 Earth masses.'] },
        { l: 3, q: 'The Sun orbits the Milky Way’s centre at 230 km/s at 8 kpc (1 kpc = 3.09 × 10¹⁹ m). Estimate the mass inside its orbit. If that mass were all the galaxy’s mass, what speed would stars at 16 kpc have? Observed speeds there are still about 220–230 km/s. What does that imply?', a: 'About 2 × 10⁴¹ kg (10¹¹ Suns); 163 km/s predicted', s: ['M = v²r/G = (2.3 × 10⁵)² × 8 × 3.09 × 10¹⁹ / 6.67 × 10⁻¹¹ = 1.96 × 10⁴¹ kg ≈ 1 × 10¹¹ solar masses.', 'With no extra mass outside, v ∝ 1/√r, so v(16 kpc) = 230/√2 = 163 km/s.', 'The rotation curve stays flat instead, so the enclosed mass keeps growing roughly in proportion to r, far beyond the visible stars and gas.', 'Either an unseen dark-matter halo surrounds the galaxy or Newtonian gravity changes at very small accelerations; galaxy dynamics alone cannot yet decide.'] }
      ]
    }
  });
})();
/* ---- notes-al2.js ---- */
/* Geodesic: study notes and ten-problem practice sets, A Level part 2 (Cambridge 9702 standard). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'al-interference': {
      big: 'When two waves overlap, their displacements simply add. If the sources keep in step, the result is a fixed pattern of strong and cancelled waves, interference fringes. Young used it in 1801 to show light is a wave, and its spacing still measures wavelengths with ease, of light, of sound and even of electrons.',
      sec: [
        { h: 'Superposition', p: ['Where two waves meet, the total displacement is the sum of the two displacements at that point and moment. Two crests make a bigger crest (constructive interference); a crest and a trough of equal size cancel (destructive interference). The waves pass through each other unchanged afterwards.'] },
        { h: 'Coherence', p: ['A stable pattern needs coherent sources: the same frequency and a constant phase difference. Two separate light bulbs are not coherent, because each atom emits short random bursts, so their pattern changes billions of times a second and averages out. Young solved this by splitting light from one source with two slits; lasers are naturally highly coherent.'] },
        { h: 'Path difference and phase difference', p: ['At a point P the two waves have travelled different distances r₁ and r₂. A path difference of one whole wavelength shifts one wave by a full cycle, so they arrive in step. A path difference of half a wavelength puts them exactly out of step.'], eq: R`\Delta = r_2 - r_1:\qquad \Delta = n\lambda\ \text{(bright)},\qquad \Delta = \left(n + \tfrac12\right)\lambda\ \text{(dark)},\qquad \phi = \frac{2\pi\Delta}{\lambda}` },
        { h: 'Young’s double slit', p: ['With the screen far away (D ≫ d), the two rays to a point are almost parallel and the path difference is d sin θ. Bright fringes appear where d sin θ = nλ. For small angles sin θ ≈ y/D, so the fringes are evenly spaced.', 'Larger wavelengths and more distant screens spread the fringes out; wider slit separations squeeze them together. Measure w, d and D and you have λ.'], eq: R`w = \frac{\lambda D}{d}` },
        { h: 'Diffraction gratings', p: ['A grating has hundreds of slits per millimetre. The condition for a bright line is the same as for two slits, but with many slits the maxima are extremely sharp and bright, while everything in between cancels. The highest order you can see is limited by sin θ ≤ 1: n ≤ d/λ.', 'Each wavelength appears at its own angle, so gratings split light into precise spectra. They are how astronomers read the composition and red-shift of stars.'], eq: R`d\sin\theta = n\lambda,\qquad n_{\max} = \left\lfloor\frac{d}{\lambda}\right\rfloor` },
        { h: 'Waves of matter, one at a time', p: ['Dim the light until only one photon at a time passes through, and the fringe pattern still builds up, dot by dot (G. I. Taylor, 1909). Electrons do the same (Tonomura, 1989). Each particle somehow goes through the arrangement as a wave, but lands at one point.'], warn: '**Hidden assumptions.** w = λD/d needs D ≫ d and small angles; near the edges of a wide pattern use d sin θ = nλ directly. Real slits have width, so the fringes are modulated by a single-slit diffraction envelope, and some orders can go missing entirely. And any measurement that reveals which slit each photon went through destroys the fringes, an effect that is about information, not about clumsy apparatus.' }
      ],
      eqs: [[R`\Delta = n\lambda`, 'constructive interference (bright)'], [R`\Delta = (n+\tfrac12)\lambda`, 'destructive interference (dark)'], [R`\phi = 2\pi\Delta/\lambda`, 'phase difference in radians'], [R`w = \frac{\lambda D}{d}`, 'double-slit fringe spacing (D ≫ d)'], [R`d\sin\theta = n\lambda`, 'diffraction grating; d = 1/(lines per metre)']],
      how: ['Find the path difference, or use the formulas that already contain it.', 'For fringe spacing measure across many fringes and divide, to cut the percentage error.', 'For gratings convert “lines per mm” to slit spacing d in metres first.', 'For the highest order, round d/λ down to a whole number.'],
      sum: ['Overlapping waves add: superposition.', 'A stable pattern needs coherent sources.', 'Bright where path difference = nλ, dark where it is (n + ½)λ.', 'Young’s slits: w = λD/d.', 'Gratings: d sin θ = nλ with sharp, bright maxima.'],
      probs: [
        { l: 1, q: 'Two coherent waves arrive at a point with a path difference of 1.5λ. What do you observe there?', a: 'Destructive interference (darkness or quiet)', s: ['1.5λ = (1 + ½)λ, an odd number of half wavelengths, so the waves arrive in antiphase.'] },
        { l: 1, q: 'A laser of wavelength 633 nm illuminates two slits 0.50 mm apart. The screen is 2.0 m away. What is the fringe spacing?', a: '2.5 mm', s: ['w = λD/d = 633 × 10⁻⁹ × 2.0 / 0.50 × 10⁻³ = 2.53 × 10⁻³ m.'] },
        { l: 1, q: 'What does it mean for two sources to be coherent?', a: 'Same frequency and a constant phase difference', s: ['Only then does the pattern of reinforcement and cancellation stay fixed long enough to be seen.'] },
        { l: 2, q: 'Sodium light (589 nm) falls on a grating with 300 lines per mm. Find the angle of the first-order maximum and the highest order visible.', a: '10.2°; 5th order', s: ['d = 1/300 mm = 3.33 × 10⁻⁶ m.', 'sin θ₁ = λ/d = 0.177, θ₁ = 10.2°.', 'd/λ = 5.66, so the highest order is 5.'] },
        { l: 2, q: 'Ten fringe spacings measure 32 mm on a screen 1.8 m from slits 0.40 mm apart. Find the wavelength.', a: '711 nm', s: ['w = 32/10 = 3.2 mm.', 'λ = wd/D = 3.2 × 10⁻³ × 0.40 × 10⁻³ / 1.8 = 7.1 × 10⁻⁷ m (deep red).'] },
        { l: 2, q: 'Two loudspeakers 1.5 m apart emit the same 680 Hz note in phase (λ = 0.50 m). A listener walks along a line 10 m away. How far from the central line is the first quiet spot?', a: 'About 1.7 m', s: ['First minimum: d sin θ = λ/2, so sin θ = 0.25/1.5 = 0.167, θ = 9.6°.', 'y = 10 tan 9.6° = 1.69 m (the small-angle formula gives 1.67 m).'] },
        { l: 2, q: 'White light passes through a grating. In each order, which colour is nearest the central white maximum, and why?', a: 'Violet', s: ['sin θ = nλ/d, so shorter wavelengths diffract through smaller angles.', 'Violet (about 400 nm) is nearest the centre and red (about 700 nm) furthest.'] },
        { l: 2, q: 'What phase difference corresponds to a path difference of a quarter of a wavelength?', a: 'π/2 rad (90°)', s: ['φ = 2πΔ/λ = 2π × ¼ = π/2.'] },
        { l: 3, q: 'Electrons accelerated through 50 V pass through two slits 1.0 μm apart onto a screen 1.0 m away. Find their wavelength and the fringe spacing.', a: '0.17 nm; 0.17 mm', s: ['p = √(2meV) = √(2 × 9.11 × 10⁻³¹ × 1.60 × 10⁻¹⁹ × 50) = 3.82 × 10⁻²⁴ kg m/s.', 'λ = h/p = 6.63 × 10⁻³⁴ / 3.82 × 10⁻²⁴ = 1.73 × 10⁻¹⁰ m.', 'w = λD/d = 1.73 × 10⁻¹⁰ × 1.0 / 1.0 × 10⁻⁶ = 1.7 × 10⁻⁴ m.'] },
        { l: 3, q: 'You try to see which slit each photon goes through by bouncing light off it. Explain, using the fringe formula, why this must wash out the fringes.', a: 'Telling the slits apart needs light of wavelength below d, whose momentum kick scrambles the phase', s: ['To resolve two slits a distance d apart, the probe light needs wavelength λ′ ≲ d.', 'Each probe photon carries momentum h/λ′ ≳ h/d, and scattering it gives the particle a sideways momentum uncertainty of about h/d.', 'That changes its direction by about Δθ ~ (h/d)/p = λ/d, which is the angular spacing of the fringes themselves.', 'So the pattern is smeared out exactly enough to erase it: the act of gaining which-path information destroys the interference.'] }
      ]
    },

    'al-efields': {
      big: 'Electric charges push and pull with a force that falls off as the square of distance, just like gravity but about 10³⁶ times stronger between two protons. Field strength tells you the force per coulomb at each point; potential tells you the energy per coulomb, and turns force problems into simple energy bookkeeping.',
      sec: [
        { h: 'Coulomb’s law', p: ['Two point charges Q and q a distance r apart attract (opposite signs) or repel (like signs) with a force proportional to Qq/r². In a vacuum the constant is k = 1/(4πε₀) = 8.99 × 10⁹ N m²/C². A spherical charged conductor acts, from outside, like a point charge at its centre.'], eq: R`F = \frac{1}{4\pi\varepsilon_0}\frac{Qq}{r^2}` },
        { h: 'Electric field strength', p: ['The field strength E at a point is the force per unit positive charge placed there, in N/C (equivalently V/m). Field lines show its direction: away from positive charges, towards negative ones, never crossing, and closer together where the field is stronger.'], eq: R`E = \frac{F}{q} = \frac{Q}{4\pi\varepsilon_0 r^2}` },
        { h: 'Uniform fields between plates', p: ['Between two parallel plates with potential difference V and separation d, the field is uniform (apart from the edges) and E = V/d. A charged particle there feels a constant force, so its path is a parabola, exactly like a projectile under gravity. This is how old CRT screens steered electron beams.'], eq: R`E = \frac{V}{d}` },
        { h: 'Potential and potential energy', p: ['The electric potential V at a point is the work done per unit positive charge in bringing it from infinity. Around a point charge V = Q/(4πε₀r): positive near positive charges, negative near negative ones. A charge q there has potential energy qV.', 'Field and potential are two views of the same thing: the field is minus the gradient of the potential, so field lines run downhill in potential and always cross equipotential surfaces at right angles.'], eq: R`V = \frac{Q}{4\pi\varepsilon_0 r},\qquad E = -\frac{dV}{dr},\qquad \Delta E_k = q\,\Delta V` },
        { h: 'Several charges', p: ['Potentials add as ordinary numbers; fields add as vectors. That makes potential much easier: find V from each charge and add, then (if needed) get E from the slope.'] },
        { h: 'Electric and gravitational fields compared', p: ['Both are inverse-square, both have potentials that go as 1/r. But gravity only attracts and acts on mass; electric forces attract or repel and act on charge. Between two protons the electric repulsion is 1.2 × 10³⁶ times their gravitational attraction, which is why gravity matters only when charges cancel out on large scales.'], warn: '**How sure are we of the 1/r²?** If Coulomb’s law were 1/r^{2+q}, a charged conducting shell would have a field inside it. Experiments find none: q is consistent with zero to within about 3 × 10⁻¹⁶ (Williams, Faller and Hill, 1971). The law does need correcting at tiny distances: quantum electrodynamics makes the effective charge grow slightly at distances below about 4 × 10⁻¹³ m (the electron’s Compton wavelength), an effect measured precisely in hydrogen’s energy levels.' }
      ],
      eqs: [[R`F = \frac{kQq}{r^2}`, 'k = 1/(4πε₀) = 8.99 × 10⁹ N m² C⁻²'], [R`E = \frac{kQ}{r^2}`, 'field of a point charge, in N/C'], [R`E = \frac{V}{d}`, 'uniform field between plates, in V/m'], [R`V = \frac{kQ}{r}`, 'potential of a point charge'], [R`W = q\Delta V`, 'work done moving charge q through ΔV'], [R`\tfrac12 mv^2 = qV`, 'speed after acceleration from rest through V']],
      how: ['Decide whether the question is about forces (use E, add as vectors) or energy (use V, add as numbers).', 'For a particle accelerated through a potential difference, use qV = ½mv².', 'Between plates, use E = V/d and treat the motion like a projectile.', 'For zero-field points, set the two field magnitudes equal and check the directions really oppose.'],
      sum: ['Coulomb: F = kQq/r², k = 8.99 × 10⁹ N m²/C².', 'E = F/q; point charge E = kQ/r²; plates E = V/d.', 'V = kQ/r; E = −dV/dr; field lines cross equipotentials at 90°.', 'Potentials add as scalars; fields add as vectors.', 'Electric forces dwarf gravity; the 1/r² law is tested to 3 parts in 10¹⁶.'],
      probs: [
        { l: 1, q: 'Find the force between two 1.0 μC charges 0.10 m apart.', a: '0.90 N (repulsive)', s: ['F = kQq/r² = 8.99 × 10⁹ × (1.0 × 10⁻⁶)² / 0.010 = 0.90 N.'] },
        { l: 1, q: 'Find the electric field strength 0.20 m from a +5.0 nC point charge.', a: '1.1 × 10³ N/C, pointing away from the charge', s: ['E = kQ/r² = 8.99 × 10⁹ × 5.0 × 10⁻⁹ / 0.040 = 1120 N/C.'] },
        { l: 1, q: 'Find the potential at the same point.', a: '225 V', s: ['V = kQ/r = 8.99 × 10⁹ × 5.0 × 10⁻⁹ / 0.20 = 225 V.'] },
        { l: 2, q: 'Two parallel plates 2.0 cm apart have a potential difference of 500 V. Find the field strength and the force and acceleration of an electron between them.', a: '2.5 × 10⁴ V/m; 4.0 × 10⁻¹⁵ N; 4.4 × 10¹⁵ m/s²', s: ['E = V/d = 500/0.020 = 25 000 V/m.', 'F = eE = 1.60 × 10⁻¹⁹ × 25 000 = 4.0 × 10⁻¹⁵ N.', 'a = F/m = 4.0 × 10⁻¹⁵ / 9.11 × 10⁻³¹ = 4.4 × 10¹⁵ m/s².'] },
        { l: 2, q: 'An electron is accelerated from rest through 2000 V. Find its speed (non-relativistic).', a: '2.65 × 10⁷ m/s', s: ['½mv² = eV, so v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 2000 / 9.11 × 10⁻³¹) = 2.65 × 10⁷ m/s, about 9% of c, so the classical formula is still adequate.'] },
        { l: 2, q: 'Charges of +4.0 μC and +1.0 μC are 0.30 m apart. Where between them is the electric field zero?', a: '0.20 m from the 4.0 μC charge', s: ['At distance x from the 4.0 μC charge: 4.0/x² = 1.0/(0.30 − x)².', 'Taking square roots: 2(0.30 − x) = x, so x = 0.20 m.', 'The fields point in opposite directions between two like charges, so they can cancel there.'] },
        { l: 2, q: 'How much work is needed to bring a +2.0 μC charge from far away to 0.050 m from a fixed +3.0 μC charge?', a: '1.08 J', s: ['W = qV = kQq/r = 8.99 × 10⁹ × 3.0 × 10⁻⁶ × 2.0 × 10⁻⁶ / 0.050 = 1.08 J.'] },
        { l: 2, q: 'An electron enters the field between two plates horizontally at 3.0 × 10⁷ m/s. The plates are 5.0 cm long and the field is 2.0 × 10⁴ V/m. How far is it deflected by the time it leaves?', a: '4.9 mm', s: ['Time between the plates: 0.050 / 3.0 × 10⁷ = 1.67 × 10⁻⁹ s.', 'Acceleration: eE/m = 3.51 × 10¹⁵ m/s².', 'Deflection: ½at² = ½ × 3.51 × 10¹⁵ × (1.67 × 10⁻⁹)² = 4.9 × 10⁻³ m.'] },
        { l: 3, q: 'Compare the electric repulsion and the gravitational attraction between two protons. Does the distance matter?', a: 'Ratio 1.2 × 10³⁶, the same at every distance', s: ['Both forces go as 1/r², so the ratio does not depend on r.', 'Ratio = ke²/(Gm_p²) = 8.99 × 10⁹ × (1.60 × 10⁻¹⁹)² / (6.67 × 10⁻¹¹ × (1.67 × 10⁻²⁷)²) = 1.2 × 10³⁶.'] },
        { l: 3, q: 'In a Millikan experiment an oil drop of mass 3.2 × 10⁻¹⁵ kg is held stationary between plates 1.5 cm apart with 1470 V across them. Find its charge and the number of excess electrons.', a: '3.2 × 10⁻¹⁹ C, two electrons', s: ['E = V/d = 1470/0.015 = 9.8 × 10⁴ V/m.', 'Balance: qE = mg, so q = 3.2 × 10⁻¹⁵ × 9.81 / 9.8 × 10⁴ = 3.2 × 10⁻¹⁹ C.', 'That is 2.0 times e: every drop Millikan measured carried a whole-number multiple of e.'] }
      ]
    },

    'al-induction': {
      big: 'A changing magnetic field through a coil drives an e.m.f. around it. That single discovery of Faraday’s (1831) gives us generators, transformers, induction hobs, metal detectors and wireless chargers, and Lenz’s law, which fixes the direction, is energy conservation in disguise.',
      sec: [
        { h: 'Magnetic flux and flux linkage', p: ['Magnetic flux Φ measures how much field passes through an area: the field strength times the area perpendicular to it, in webers (Wb = T m²). For a coil of N turns the flux linkage is NΦ.'], eq: R`\Phi = BA\cos\theta,\qquad \text{flux linkage} = N\Phi` },
        { h: 'Faraday’s law', p: ['The induced e.m.f. equals the rate of change of flux linkage. It does not matter how the flux changes: moving a magnet, moving the coil, changing the current in a nearby coil, or rotating the coil all work. No change, no e.m.f., however strong the field.'], eq: R`\varepsilon = -N\frac{d\Phi}{dt}` },
        { h: 'Lenz’s law: the minus sign', p: ['The induced current always flows so as to oppose the change that produces it. Push a magnet’s north pole into a coil and the coil’s near end becomes a north pole, repelling it. If it did the opposite, the induced current would pull the magnet in faster, producing more current: energy from nothing. So Lenz’s law is conservation of energy.'] },
        { h: 'Moving conductors', p: ['A rod of length L moving at speed v across a field B sweeps out area at a rate Lv, so the e.m.f. is BLv. If a current flows, the field pushes back on it with a force BIL, and you must do work to keep the rod moving: that work is exactly the electrical energy produced.'], eq: R`\varepsilon = BLv` },
        { h: 'Generators', p: ['A coil of area A and N turns rotating at angular speed ω has flux linkage NBA cos ωt, so its e.m.f. is NBAω sin ωt: alternating current. The e.m.f. is largest when the coil’s plane is parallel to the field, where the flux is zero but changing fastest.'], eq: R`\varepsilon = NBA\omega\sin\omega t,\qquad \varepsilon_0 = NBA\omega` },
        { h: 'Transformers and power transmission', p: ['An alternating current in the primary coil makes a changing flux in an iron core that links the secondary coil. The voltages are in the ratio of the turns. An ideal transformer wastes no power, so stepping the voltage up steps the current down.', 'Power lines lose I²R as heat. Transmitting at hundreds of kilovolts keeps the current, and so the losses, small; transformers then step it down for safe use.'], eq: R`\frac{V_s}{V_p} = \frac{N_s}{N_p},\qquad V_pI_p = V_sI_s\ (\text{ideal})`, warn: '**Hidden assumptions.** Real transformers lose energy to eddy currents in the core (reduced by laminating it), to repeatedly magnetising the iron (hysteresis) and to the resistance of the windings; large ones still reach 98–99% efficiency. And the “flux rule” ε = −dΦ/dt has famous exceptions: in a Faraday disc the flux through any obvious circuit does not change, yet an e.m.f. appears. The underlying law is the force qv × B on moving charges plus the induced electric field of a changing B; the flux rule is a convenient summary that usually, but not always, agrees.' }
      ],
      eqs: [[R`\Phi = BA\cos\theta`, 'flux in Wb; θ between B and the normal to the area'], [R`\varepsilon = -N\frac{\Delta\Phi}{\Delta t}`, 'Faraday’s and Lenz’s laws'], [R`\varepsilon = BLv`, 'rod moving across a field'], [R`\varepsilon = NBA\omega\sin\omega t`, 'rotating coil (generator)'], [R`\frac{V_s}{V_p} = \frac{N_s}{N_p}`, 'ideal transformer'], [R`P_{\text{loss}} = I^2R`, 'heating in transmission lines']],
      how: ['Find how the flux linkage changes: B, A or the angle.', 'Divide the change by the time taken (or differentiate) to get the e.m.f.', 'Use Lenz’s law separately to get the direction: the effect opposes the cause.', 'For transformers assume ideal (power in = power out) unless told otherwise.'],
      sum: ['Flux Φ = BA cos θ; e.m.f. = rate of change of flux linkage.', 'Lenz: the induced current opposes the change, which is energy conservation.', 'Moving rod: ε = BLv. Rotating coil: ε = NBAω sin ωt.', 'Transformers: V_s/V_p = N_s/N_p; high-voltage transmission cuts I²R losses.', 'Eddy currents brake moving conductors and heat transformer cores.'],
      probs: [
        { l: 1, q: 'A coil of area 0.020 m² sits at right angles to a 0.50 T field. What is the flux through it?', a: '0.010 Wb', s: ['Φ = BA = 0.50 × 0.020 = 0.010 Wb.'] },
        { l: 1, q: 'A 200-turn coil sees its flux fall steadily from 0.010 Wb to zero in 0.050 s. What is the average e.m.f.?', a: '40 V', s: ['ε = NΔΦ/Δt = 200 × 0.010 / 0.050 = 40 V.'] },
        { l: 1, q: 'A 0.30 m rod moves at 4.0 m/s at right angles to a 0.20 T field. What e.m.f. is induced between its ends?', a: '0.24 V', s: ['ε = BLv = 0.20 × 0.30 × 4.0 = 0.24 V.'] },
        { l: 2, q: 'A generator coil has 100 turns of area 0.010 m² and rotates at 50 Hz in a 0.40 T field. Find the peak and r.m.s. e.m.f.', a: '126 V peak; 89 V r.m.s.', s: ['ω = 2π × 50 = 314 rad/s.', 'ε₀ = NBAω = 100 × 0.40 × 0.010 × 314 = 126 V.', 'r.m.s. = ε₀/√2 = 89 V.'] },
        { l: 2, q: 'A transformer steps 230 V down to 12 V and its primary has 1150 turns. How many turns does the secondary need? If the secondary supplies 2.0 A, what current does the primary draw (ideal transformer)?', a: '60 turns; 0.10 A', s: ['N_s = N_p × V_s/V_p = 1150 × 12/230 = 60.', 'Power in = power out: I_p = 12 × 2.0 / 230 = 0.104 A.'] },
        { l: 2, q: 'The north pole of a magnet is pushed into one end of a coil. Which magnetic pole forms at that end of the coil, and why?', a: 'A north pole', s: ['The induced current opposes the approach of the magnet.', 'A north pole at the near end repels the incoming north pole, so you must do work, which becomes electrical energy.'] },
        { l: 2, q: 'A strong magnet dropped down a vertical copper pipe falls very slowly. Explain, and say where its gravitational potential energy goes.', a: 'Eddy currents in the pipe oppose its motion; the energy heats the copper', s: ['As the magnet falls, the flux through each ring of the pipe changes, inducing circulating eddy currents.', 'By Lenz’s law their fields oppose the motion, so a drag force quickly balances the weight and the magnet falls at a low steady speed.', 'The lost potential energy is dissipated as heat in the copper’s resistance.'] },
        { l: 2, q: 'A rod of length 0.40 m slides at 3.0 m/s along rails in a 0.50 T field; the circuit resistance is 2.0 Ω. Find the e.m.f., the current, the force needed to keep it moving and the power delivered.', a: '0.60 V; 0.30 A; 0.060 N; 0.18 W', s: ['ε = BLv = 0.50 × 0.40 × 3.0 = 0.60 V; I = 0.60/2.0 = 0.30 A.', 'Opposing force BIL = 0.50 × 0.30 × 0.40 = 0.060 N, so you must push with 0.060 N.', 'Mechanical power = Fv = 0.18 W = I²R = 0.09 × 2.0: every joule of work becomes heat.'] },
        { l: 3, q: 'A power station sends 100 MW through lines of total resistance 5.0 Ω. Find the power lost if it transmits at 400 kV, and at 25 kV.', a: '0.31 MW (0.3%) at 400 kV; 80 MW (80%) at 25 kV', s: ['At 400 kV: I = P/V = 250 A; loss = I²R = 250² × 5.0 = 0.31 MW.', 'At 25 kV: I = 4000 A; loss = 4000² × 5.0 = 80 MW.', 'Sixteen times the voltage means a sixteenth of the current and 1/256 of the loss: the reason for the National Grid’s high voltages.'] },
        { l: 3, q: 'Show that a rotating coil’s e.m.f. is greatest when the plane of the coil is parallel to the field, even though the flux through it is then zero.', a: 'ε ∝ sin ωt is maximum where Φ ∝ cos ωt passes through zero', s: ['Φ = BA cos ωt, so ε = −N dΦ/dt = NBAω sin ωt.', 'When the coil’s plane is parallel to B, ωt = 90° and Φ = 0, but sin ωt = 1 and the flux is changing at its fastest rate.', 'E.m.f. depends on how fast the flux changes, not on how much flux there is.'] }
      ]
    },

    'al-ideal-gas': {
      big: 'Pressure is the drumming of countless molecules on a wall, and temperature measures how fast they move. Kinetic theory turns that picture into numbers: it derives pV = NkT from Newton’s laws and shows that the average kinetic energy of a molecule is (3/2)kT.',
      sec: [
        { h: 'The gas laws and absolute zero', p: ['For a fixed mass of gas, pV is constant at fixed temperature (Boyle), V ∝ T at fixed pressure (Charles), and p ∝ T at fixed volume. Extrapolated, all three point to the same temperature at which the pressure or volume would vanish: −273.15 °C, absolute zero, 0 K.', 'Combined, they give the ideal gas equation, written per mole (R = 8.31 J/(mol K)) or per molecule (Boltzmann constant k = R/N_A = 1.38 × 10⁻²³ J/K).'], eq: R`pV = nRT = NkT,\qquad T/\text{K} = \theta/^{\circ}\text{C} + 273.15` },
        { h: 'Pressure from molecular impacts', p: ['A molecule bouncing elastically off a wall reverses its momentum, giving the wall 2mc_x each hit; it returns every 2L/c_x seconds. Summing over all N molecules and using ⟨c_x²⟩ = ⟨c²⟩/3 (no direction is special) gives the pressure.'], eq: R`pV = \tfrac13 Nm\langle c^2\rangle` },
        { h: 'What temperature means', p: ['Comparing with pV = NkT shows that the average translational kinetic energy of a molecule depends only on temperature. Different gases at the same temperature have the same average kinetic energy, so lighter molecules move faster.'], eq: R`\tfrac12 m\langle c^2\rangle = \tfrac32 kT,\qquad c_{\text{rms}} = \sqrt{\frac{3kT}{m}}` },
        { h: 'Internal energy', p: ['In an ideal monatomic gas there are no forces between molecules, so the internal energy is just the total kinetic energy: U = (3/2)NkT = (3/2)nRT. It depends only on temperature.'] },
        { h: 'The assumptions', list: ['Molecules are points: their volume is negligible compared with the container.', 'Collisions are perfectly elastic and take negligible time.', 'There are no forces between molecules except during collisions.', 'There are very many molecules moving randomly, so averages are meaningful.'], warn: '**Where the ideal gas fails.** At high pressure or low temperature, molecular size and attraction matter. One mole of CO₂ at 300 K and 5 atm occupies about 2% less than the ideal 4.92 L, and near its critical point it differs hugely; real gases liquefy, which an ideal gas never does. And the heat capacity of nitrogen at room temperature is (5/2)R, not the (7/2)R classical physics predicts once vibrations are counted: the vibrations are “frozen out”, one of the first clues that classical physics fails and energy is quantised.' }
      ],
      eqs: [[R`pV = nRT`, 'n in mol; R = 8.31 J mol⁻¹ K⁻¹; T in K'], [R`pV = NkT`, 'N molecules; k = 1.38 × 10⁻²³ J K⁻¹'], [R`pV = \tfrac13 Nm\langle c^2\rangle`, 'kinetic theory'], [R`\tfrac12 m\langle c^2\rangle = \tfrac32 kT`, 'mean translational KE per molecule'], [R`c_{\text{rms}} = \sqrt{3kT/m}`, 'root-mean-square speed'], [R`U = \tfrac32 nRT`, 'internal energy of a monatomic ideal gas']],
      how: ['Convert temperatures to kelvin before doing anything else.', 'For changes of state of a fixed gas, use p₁V₁/T₁ = p₂V₂/T₂.', 'For molecular speeds, use the mass of one molecule (molar mass ÷ N_A).', 'Keep pressure in Pa and volume in m³ when using R or k.'],
      sum: ['pV = nRT = NkT, with T in kelvin.', 'Pressure comes from molecular momentum changes at the walls: pV = ⅓Nm⟨c²⟩.', 'Mean KE per molecule = (3/2)kT: temperature measures molecular motion.', 'c_{rms} = √(3kT/m): lighter molecules are faster.', 'Real gases deviate at high pressure and low temperature; heat capacities reveal quantum effects.'],
      probs: [
        { l: 1, q: 'Convert 27 °C to kelvin.', a: '300 K', s: ['T = 27 + 273 = 300 K.'] },
        { l: 1, q: 'How many moles of gas are in 2.0 m³ at 100 kPa and 300 K?', a: '80 mol', s: ['n = pV/(RT) = 100 000 × 2.0 / (8.31 × 300) = 80 mol.'] },
        { l: 1, q: 'What is the mean translational kinetic energy of a gas molecule at 300 K?', a: '6.2 × 10⁻²¹ J', s: ['⟨KE⟩ = (3/2)kT = 1.5 × 1.38 × 10⁻²³ × 300 = 6.2 × 10⁻²¹ J (about 0.04 eV).'] },
        { l: 2, q: 'A sealed rigid can of gas at 20 °C and 100 kPa is heated to 300 °C. What is the new pressure?', a: '196 kPa', s: ['At constant volume p ∝ T (in kelvin).', 'p = 100 × 573/293 = 196 kPa: nearly double, which is why aerosol cans must not be heated.'] },
        { l: 2, q: 'A weather balloon holds 5.0 L of gas at 100 kPa and 290 K. It rises to where the pressure is 50 kPa and the temperature is 250 K. What is its new volume?', a: '8.6 L', s: ['V₂ = V₁ × (p₁/p₂) × (T₂/T₁) = 5.0 × 2 × 250/290 = 8.6 L.'] },
        { l: 2, q: 'Find the r.m.s. speed of nitrogen molecules (molar mass 28 g/mol) at 300 K.', a: '517 m/s', s: ['m = 0.028/6.02 × 10²³ = 4.65 × 10⁻²⁶ kg.', 'c_{rms} = √(3kT/m) = √(3 × 1.38 × 10⁻²³ × 300 / 4.65 × 10⁻²⁶) = 517 m/s, faster than sound in air.'] },
        { l: 2, q: 'At the same temperature, how does the r.m.s. speed of hydrogen (H₂) compare with that of oxygen (O₂)?', a: 'Four times faster', s: ['Equal mean KE means c_{rms} ∝ 1/√m.', '√(32/2) = 4.'] },
        { l: 2, q: 'How many molecules are in 1.0 cm³ of air at 273 K and 101.3 kPa?', a: '2.7 × 10^{19}', s: ['N = pV/(kT) = 101 300 × 1.0 × 10⁻⁶ / (1.38 × 10⁻²³ × 273) = 2.7 × 10^{19} (the Loschmidt number).'] },
        { l: 3, q: 'Find the internal energy of 1.0 mol of helium at 300 K and the energy needed to warm it by 10 K at constant volume. Nitrogen needs (5/2)R per mole per kelvin, not (3/2)R. Why, and why not the (7/2)R classical physics predicts?', a: '3.7 kJ; 125 J', s: ['U = (3/2)nRT = 1.5 × 8.31 × 300 = 3740 J; ΔU = 1.5 × 8.31 × 10 = 125 J.', 'N₂ molecules can also rotate about two axes, each storing ½kT: (5/2)R in total.', 'Classically, vibration should add two more half-kT terms, giving (7/2)R. It does not at room temperature because vibrational energy is quantised in steps far larger than kT, so vibrations are almost never excited.'] },
        { l: 3, q: 'Treat 1.0 mol of CO₂ at 300 K and 5.0 atm (5.07 × 10⁵ Pa) as an ideal gas and find its volume. The van der Waals equation, with a = 0.364 Pa m⁶ mol⁻² and b = 4.27 × 10⁻⁵ m³ mol⁻¹, gives 4.82 L. Explain the difference.', a: 'Ideal 4.92 L; the real gas occupies about 2% less', s: ['V = nRT/p = 8.31 × 300 / 5.07 × 10⁵ = 4.92 × 10⁻³ m³.', 'Attractions between molecules pull them inwards, lowering the pressure they exert, so at a given pressure the gas is more compressed (the a term).', 'The molecules’ own volume works the other way (the b term), but at this pressure attraction wins.', 'The ideal gas law ignores both effects, which grow as the gas approaches liquefaction.'] }
      ]
    },

    'al-nuclear': {
      big: 'A nucleus weighs less than the protons and neutrons it is made of. The missing mass, times c², is the binding energy that holds it together. Plotting binding energy per nucleon shows why both splitting heavy nuclei and fusing light ones release energy, and why stars stop making energy at iron and nickel.',
      sec: [
        { h: 'Mass defect', p: ['Measure the mass of a helium-4 nucleus and it is 0.0304 u less than two free protons plus two free neutrons. That mass defect is not an error: when nucleons bind, energy is released, and energy has mass.'], eq: R`\Delta m = Zm_p + Nm_n - M_{\text{nucleus}}` },
        { h: 'Binding energy and E = mc²', p: ['The binding energy is the energy needed to pull the nucleus completely apart, equal to the mass defect times c². In nuclear units, 1 u corresponds to 931.5 MeV. For helium-4, 0.0304 u is 28.3 MeV, about 7 MeV per nucleon, millions of times the few eV that bind atoms in molecules.'], eq: R`B = \Delta m\,c^2,\qquad 1\ \text{u} \leftrightarrow 931.5\ \text{MeV}` },
        { h: 'The binding-energy curve', p: ['Binding energy per nucleon rises steeply for light nuclei, peaks around iron and nickel at about 8.8 MeV, and falls slowly to about 7.6 MeV for uranium. Any reaction that moves nuclei towards the peak releases energy equal to the increase in total binding energy.'], eq: R`Q = \sum B_{\text{after}} - \sum B_{\text{before}}` },
        { h: 'Fission and fusion', p: ['Fission: a heavy nucleus such as uranium-235 absorbs a neutron and splits into two medium nuclei plus two or three neutrons, releasing about 200 MeV. Those neutrons can cause further fissions, a chain reaction that reactors control with absorbers and moderators.', 'Fusion: light nuclei join. Deuterium and tritium fuse into helium-4 and a neutron, releasing 17.6 MeV. Fusion needs very high temperatures so the nuclei can approach closely despite their electric repulsion; it powers the Sun.'] },
        { h: 'Why the curve has its shape', p: ['The liquid-drop model treats the nucleus as a drop: each nucleon is bound to its neighbours (a volume term), nucleons at the surface have fewer neighbours (a surface term), protons repel each other (a Coulomb term), and nuclei prefer equal numbers of protons and neutrons (an asymmetry term). Surface effects hurt small nuclei; Coulomb repulsion hurts large ones; the best compromise is near A ≈ 60.'], eq: R`B = a_V A - a_S A^{2/3} - a_C\frac{Z(Z-1)}{A^{1/3}} - a_A\frac{(A-2Z)^2}{A} \pm \delta`, warn: '**Two standard claims, corrected.** The most tightly bound nucleus per nucleon is nickel-62 (8.795 MeV), not iron-56 (8.790 MeV); iron-56 is the one with the lowest mass per nucleon, because it has relatively more of the lighter protons. And the smooth liquid-drop formula misses extra binding at the magic numbers 2, 8, 20, 28, 50, 82 and 126, which come from nuclear shell structure.' }
      ],
      eqs: [[R`\Delta m = Zm_p + Nm_n - M`, 'mass defect in u or kg'], [R`E = mc^2`, 'mass–energy equivalence'], [R`1\ \text{u} = 931.5\ \text{MeV}/c^2`, '1 u = 1.661 × 10⁻²⁷ kg'], [R`B/A`, 'binding energy per nucleon: a measure of stability'], [R`Q = \sum B_{\text{products}} - \sum B_{\text{reactants}}`, 'energy released by a reaction']],
      how: ['Use nuclear masses, or atomic masses with electrons balanced on both sides.', 'Mass defect in u × 931.5 gives MeV directly.', 'For reaction energies, compare total binding energies (or total masses) before and after.', 'Convert MeV to J with 1 MeV = 1.60 × 10⁻¹³ J when you need energy per kilogram.'],
      sum: ['Nuclei are lighter than their parts: the mass defect.', 'Binding energy B = Δm c²; 1 u = 931.5 MeV.', 'B/A peaks near nickel-62 and iron-56 at about 8.8 MeV.', 'Fission of heavy and fusion of light nuclei both move towards the peak and release energy.', 'The liquid-drop model explains the curve’s shape; shell effects add structure.'],
      probs: [
        { l: 1, q: 'Convert a mass defect of 0.0304 u into MeV.', a: '28.3 MeV', s: ['0.0304 × 931.5 = 28.3 MeV.'] },
        { l: 1, q: 'How much energy is equivalent to 1.0 g of mass?', a: '9.0 × 10¹³ J', s: ['E = mc² = 1.0 × 10⁻³ × (3.0 × 10⁸)² = 9.0 × 10¹³ J, roughly a day’s output of a large power station.'] },
        { l: 1, q: 'Why do both the fission of uranium and the fusion of hydrogen release energy?', a: 'Both move the nuclei towards higher binding energy per nucleon', s: ['Uranium is to the right of the peak; splitting it makes medium nuclei with more binding per nucleon.', 'Hydrogen is far to the left; fusing it makes helium, with much more binding per nucleon.'] },
        { l: 2, q: 'Find the binding energy of a deuteron (m_p = 1.007276 u, m_n = 1.008665 u, m_d = 2.013553 u).', a: '2.22 MeV (1.11 MeV per nucleon)', s: ['Δm = 1.007276 + 1.008665 − 2.013553 = 0.002388 u.', 'B = 0.002388 × 931.5 = 2.22 MeV: the deuteron is only loosely bound.'] },
        { l: 2, q: 'Find the binding energy per nucleon of carbon-12 (nuclear mass 11.996709 u).', a: '7.68 MeV', s: ['Δm = 6 × 1.007276 + 6 × 1.008665 − 11.996709 = 0.098937 u.', 'B = 0.098937 × 931.5 = 92.2 MeV; per nucleon 92.2/12 = 7.68 MeV.'] },
        { l: 2, q: 'Binding energies: deuterium 2.22 MeV, tritium 8.48 MeV, helium-4 28.30 MeV. Find the energy released by D + T → ⁴He + n.', a: '17.6 MeV', s: ['The free neutron has no binding energy.', 'Q = 28.30 − (2.22 + 8.48) = 17.6 MeV, carried mostly by the neutron (about 14.1 MeV).'] },
        { l: 2, q: 'Each fission of uranium-235 releases about 200 MeV. How much energy is released by fissioning 1.0 kg? Compare with burning 1.0 kg of coal (3 × 10⁷ J).', a: '8.2 × 10¹³ J, about 3 million times more', s: ['Nuclei per kg = 6.02 × 10²³ / 0.235 = 2.56 × 10²⁴.', 'E = 2.56 × 10²⁴ × 200 × 1.60 × 10⁻¹³ J = 8.2 × 10¹³ J.', 'Ratio to coal ≈ 2.7 × 10⁶.'] },
        { l: 2, q: 'The Sun radiates 3.83 × 10²⁶ W. How much mass does it lose each second?', a: '4.3 × 10⁹ kg per second', s: ['m = P/c² = 3.83 × 10²⁶ / (3.0 × 10⁸)² = 4.3 × 10⁹ kg, over four million tonnes a second, yet a negligible fraction of its 2 × 10³⁰ kg.'] },
        { l: 3, q: 'Use the liquid-drop formula with a_V = 15.8, a_S = 18.3, a_C = 0.714, a_A = 23.2 MeV and a pairing term +12/√A MeV to estimate the binding energy of iron-56 (Z = 26). Compare with the measured 492.3 MeV.', a: 'About 490.6 MeV, within 0.3%', s: ['Volume: 15.8 × 56 = 884.8. Surface: 18.3 × 56^{2/3} = 267.9.', 'Coulomb: 0.714 × 26 × 25 / 56^{1/3} = 121.3. Asymmetry: 23.2 × 4² / 56 = 6.6. Pairing: 12/√56 = 1.6.', 'B = 884.8 − 267.9 − 121.3 − 6.6 + 1.6 = 490.6 MeV.', 'Five fitted constants reproduce the binding of hundreds of nuclei this well, which is strong evidence for the liquid-drop picture.'] },
        { l: 3, q: 'Why can neither the fusion nor the fission of iron-56 release energy? And is iron-56 really the most tightly bound nucleus?', a: 'It sits at the top of the curve; the true maximum of B/A is nickel-62', s: ['Near the peak, moving in either direction lowers the binding energy per nucleon, so both reactions absorb energy.', 'That is why a massive star’s core stops producing energy once it has made iron-group nuclei, and collapses.', 'Careful measurements put nickel-62 (8.795 MeV per nucleon) slightly above iron-56 (8.790 MeV). Iron-56 is special for a different reason: the lowest mass per nucleon, because it has relatively more protons, which are lighter than neutrons.'] }
      ]
    }
  });
})();
/* ---- notes-gcse2.js ---- */
/* Geodesic: notes and ten-problem sets for GCSE outline topics, part 1 (IGCSE 0625 sections 1.1–1.8). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'gcse-measurement': {
      big: 'Every result in physics is a measurement, and every measurement has an uncertainty. Good technique (reading at eye level, timing many swings, measuring a stack instead of one sheet) shrinks that uncertainty. Quantities also come in two kinds: scalars, which have only a size, and vectors, which also have a direction and must be added with geometry, not arithmetic.',
      sec: [
        { h: 'Length and volume', p: ['A metre rule reads to the nearest millimetre. Put your eye level with the mark you are reading; looking from an angle shifts the reading (parallax error). Measure from a clear mark, not the worn end of the rule.', 'A measuring cylinder measures the volume of a liquid. Water curves up at the walls, forming a meniscus: read the bottom of the meniscus, at eye level. The volume of an irregular solid is the rise in level when it is lowered in (displacement).'], box: '**1 cm³ = 1 mL** and **1 m³ = 1 000 000 cm³**. Converting volumes means cubing the length conversion: 1 m = 100 cm, so 1 m³ = 100³ cm³.' },
        { h: 'Time, and measuring multiples', p: ['Your reaction time when starting and stopping a stopwatch is about 0.2–0.3 s, far larger than the stopwatch’s 0.01 s resolution. That error is the same whether you time one swing of a pendulum or twenty. So time twenty swings and divide by twenty: the error in one period drops twenty-fold.', 'The same trick measures tiny lengths: the thickness of one sheet of paper from a stack of 200 sheets, or the diameter of a thin wire from 30 tightly wound turns.'], eq: R`\text{period} = \frac{\text{time for } N \text{ oscillations}}{N},\qquad \text{thickness} = \frac{\text{height of stack}}{\text{number of sheets}}` },
        { h: 'Scalars and vectors', p: ['A scalar has a size (magnitude) only: distance, speed, time, mass, energy, temperature. A vector has a magnitude and a direction: displacement, velocity, acceleration, force, weight, momentum, and electric and gravitational field strength.', 'Walking 3 km east then 4 km north, you cover a distance of 7 km (scalar) but your displacement is only 5 km, north-east-ish (vector). Speed is distance per time; velocity is displacement per time.'] },
        { h: 'Adding two perpendicular vectors', p: ['Two vectors at right angles add like the sides of a right-angled triangle: draw them nose to tail, and the resultant runs from the start of the first to the end of the second. Its size comes from Pythagoras and its direction from the tangent.', 'You can also use a scale drawing: choose a scale (say 1 cm for 1 N), draw both arrows nose to tail, then measure the resultant with a ruler and its angle with a protractor.'], eq: R`R = \sqrt{F_1^2 + F_2^2},\qquad \tan\theta = \frac{F_2}{F_1}` },
        { h: 'Random and systematic errors', p: ['Random errors scatter readings both ways (reaction time, judging a meniscus); averaging repeats and timing multiples reduce them. Systematic errors push every reading the same way (a worn ruler end, a stopwatch that runs fast, a balance that reads 0.3 g with nothing on it). Repeats do not remove them; you must find and correct the cause.'], warn: '**Hidden assumption in “time twenty swings”.** It assumes all twenty swings are identical. A real pendulum’s swings slowly shrink because of air resistance, and its period depends slightly on the size of the swing (by about 0.2% for a 10° amplitude). Timing multiples beats reaction time, but it cannot beat a change in the thing being measured.' }
      ],
      eqs: [[R`T = t_N / N`, 'period from the time for N oscillations'], [R`V = V_{\text{after}} - V_{\text{before}}`, 'volume of an irregular solid by displacement'], [R`R = \sqrt{F_1^2 + F_2^2}`, 'size of the resultant of two perpendicular vectors'], [R`\tan\theta = F_2/F_1`, 'direction of the resultant, measured from F₁']],
      how: ['Read scales at eye level; read the bottom of a meniscus.', 'Measure many and divide when the thing is too small or too fast to measure once.', 'Decide whether each quantity is a scalar or a vector before adding.', 'For perpendicular vectors, sketch nose to tail, then use Pythagoras and tan.', 'Check for zero errors and other systematic errors that repeats cannot fix.'],
      sum: ['Rulers to 1 mm, cylinders to the meniscus, timers limited by reaction time.', 'Timing N oscillations divides the timing error by N.', 'Scalars: magnitude only. Vectors: magnitude and direction.', 'Perpendicular vectors: R = √(F₁² + F₂²), tan θ = F₂/F₁.', 'Random errors average out; systematic errors do not.'],
      probs: [
        { l: 1, q: 'A stack of 250 identical sheets of paper is 2.5 cm thick. How thick is one sheet?', a: '0.10 mm', s: ['2.5 cm ÷ 250 = 0.010 cm = 0.10 mm.'] },
        { l: 1, q: 'The water in a measuring cylinder rises from 40 cm³ to 52 cm³ when a stone is lowered in. What is the stone’s volume?', a: '12 cm³', s: ['Volume = 52 − 40 = 12 cm³ (the stone must be fully under water).'] },
        { l: 1, q: 'Sort into scalars and vectors: speed, velocity, mass, weight, energy, acceleration, time, force.', a: 'Scalars: speed, mass, energy, time. Vectors: velocity, weight, acceleration, force.', s: ['Ask “does it need a direction to be complete?” Weight does (downwards); mass does not.'] },
        { l: 2, q: 'A pendulum makes 20 oscillations in 36.4 s. Your starting and stopping together may be out by 0.3 s. Find the period and its uncertainty, and compare with timing just one swing.', a: 'T = 1.82 s ± 0.015 s; timing one swing gives ± 0.3 s', s: ['T = 36.4 ÷ 20 = 1.82 s.', 'The 0.3 s error is shared over 20 swings: 0.3 ÷ 20 = 0.015 s.', 'Timing one swing, the same 0.3 s error would be 16% of the period.'] },
        { l: 2, q: 'Forces of 6.0 N east and 8.0 N north act on an object. Find the resultant.', a: '10 N at 53° north of east', s: ['R = √(6.0² + 8.0²) = √100 = 10 N.', 'tan θ = 8.0 ÷ 6.0, so θ = 53° north of east.'] },
        { l: 2, q: 'A plane flies north at 120 m/s through air while a wind blows east at 35 m/s. Find its velocity relative to the ground.', a: '125 m/s, 16° east of north', s: ['R = √(120² + 35²) = √15 625 = 125 m/s.', 'tan θ = 35 ÷ 120, θ = 16° east of north.'] },
        { l: 2, q: 'A swimmer aims straight across a 40 m wide river at 1.0 m/s relative to the water. The current flows at 0.60 m/s. How long does the crossing take, and how far downstream does she land?', a: '40 s; 24 m downstream', s: ['Across-river motion is unaffected by the current: t = 40 ÷ 1.0 = 40 s.', 'Drift = 0.60 × 40 = 24 m.', 'Her speed over the ground is √(1.0² + 0.60²) = 1.17 m/s.'] },
        { l: 2, q: 'A ruler has a worn end, so its zero is 0.2 cm in from the edge. An object measured from the edge reads 5.6 cm. What is its true length, and is this a random or a systematic error?', a: '5.4 cm; systematic', s: ['Every reading from the edge is 0.2 cm too big: 5.6 − 0.2 = 5.4 cm.', 'It is systematic (a zero error): repeating the measurement gives the same wrong answer.'] },
        { l: 3, q: 'You walk 300 m east and then 400 m north in 10 minutes. Find the distance, the displacement, the average speed and the average velocity.', a: '700 m; 500 m at 53° north of east; 1.17 m/s; 0.83 m/s', s: ['Distance = 300 + 400 = 700 m.', 'Displacement = √(300² + 400²) = 500 m, at tan⁻¹(400/300) = 53° north of east.', 'Average speed = 700 ÷ 600 s = 1.17 m/s; average velocity = 500 ÷ 600 = 0.83 m/s in that direction.'] },
        { l: 3, q: 'Thirty turns of a thin wire wound tightly round a pencil span 1.8 cm. Find the diameter of the wire and its cross-sectional area in m².', a: '0.60 mm; 2.8 × 10⁻⁷ m²', s: ['d = 1.8 cm ÷ 30 = 0.060 cm = 0.60 mm.', 'A = πr² = π × (0.30 × 10⁻³ m)² = 2.8 × 10⁻⁷ m².', 'Gaps between turns would make d too big: a systematic error, so wind tightly.'] }
      ]
    },

    'gcse-mass-weight': {
      big: 'Mass measures how much matter something has and how hard it is to accelerate; it is the same everywhere. Weight is the force of gravity on that mass, so it changes from planet to planet. Density, mass per unit volume, decides what floats and what sinks.',
      sec: [
        { h: 'Mass and weight', p: ['Mass is measured in kilograms. Weight is a force, measured in newtons, and points towards the centre of the planet. They are linked by the gravitational field strength g, the force on each kilogram.', 'On Earth g = 9.8 N/kg, on the Moon about 1.6 N/kg and on Jupiter about 25 N/kg. An astronaut’s mass is the same on all three; her weight is not.'], eq: R`W = m\,g` },
        { h: 'Two meanings of g', p: ['g is the gravitational field strength (N/kg) and also the acceleration of free fall (m/s²). The two are the same number because F = ma: a falling object has only its weight acting, so a = W/m = g. Every object, heavy or light, falls with the same acceleration when air resistance is negligible.'], box: '**Weight is a field effect.** A mass in a gravitational field feels a force because of the field; take the mass far from all planets and its weight goes to zero while its mass stays the same.' },
        { h: 'Balances', p: ['A beam balance compares an unknown mass with standard masses: both sides are pulled by the same g, so it gives the right mass on the Moon too. A spring balance (newton-meter) measures the force stretching its spring, so it measures weight. One marked in kilograms only reads correctly where g = 9.8 N/kg.'] },
        { h: 'Density', p: ['Density is mass per unit volume, in kg/m³ or g/cm³ (1 g/cm³ = 1000 kg/m³). Water is 1000 kg/m³, aluminium 2700, iron 7900, gold 19 300, air about 1.2.', 'To measure it: for a regular block, measure its sides to get V and weigh it; for an irregular solid, find V by displacement; for a liquid, weigh an empty measuring cylinder, then the cylinder with a known volume of liquid.'], eq: R`\rho = \frac{m}{V}` },
        { h: 'Floating and layering', p: ['An object floats in a liquid if its average density is less than the liquid’s, and sinks if it is greater. Liquids that do not mix (oil and water) settle in layers, the least dense on top.', 'A steel ship floats because the hull encloses a lot of air, so its average density (steel plus air) is less than water’s.'], warn: '**Density is not a fixed label.** It changes with temperature (water is densest at 4 °C, which is why lakes freeze from the top) and, for gases, with pressure. And “equal g for every mass” is an experimental fact, not a definition: torsion balances and the MICROSCOPE satellite (2022) show that all materials fall alike to about 1 part in 10¹⁵.' }
      ],
      eqs: [[R`W = mg`, 'weight W in N, mass m in kg, g in N/kg'], [R`g_{\text{Earth}} = 9.8\ \text{N/kg}`, 'also the free-fall acceleration in m/s²'], [R`\rho = m/V`, 'density in kg/m³ (or g/cm³)'], [R`1\ \text{g/cm}^3 = 1000\ \text{kg/m}^3`, 'unit conversion']],
      how: ['Decide whether the question wants mass (kg) or weight (N).', 'For density, get m and V in matching units first (g with cm³, or kg with m³).', 'For irregular solids, V is the rise in liquid level.', 'For floating, compare densities: less dense floats.'],
      sum: ['Mass in kg is the same everywhere; weight W = mg in N depends on g.', 'g = 9.8 N/kg = 9.8 m/s² on Earth.', 'Beam balances compare masses; spring balances measure weight.', 'ρ = m/V; measure V by dimensions or displacement.', 'Less dense objects float; immiscible liquids form layers.'],
      probs: [
        { l: 1, q: 'Find the weight of a 65 kg person on Earth (g = 9.8 N/kg) and on the Moon (g = 1.6 N/kg).', a: '640 N on Earth; 104 N on the Moon', s: ['Earth: 65 × 9.8 = 637 N ≈ 640 N.', 'Moon: 65 × 1.6 = 104 N. The mass is 65 kg in both places.'] },
        { l: 1, q: 'A block measures 2.0 cm × 3.0 cm × 5.0 cm and has a mass of 81 g. What is its density?', a: '2.7 g/cm³ = 2700 kg/m³ (aluminium)', s: ['V = 2.0 × 3.0 × 5.0 = 30 cm³.', 'ρ = 81 ÷ 30 = 2.7 g/cm³.'] },
        { l: 1, q: 'Which of these float in water (1000 kg/m³): pine wood (650 kg/m³), ice (917 kg/m³), steel (7800 kg/m³)?', a: 'Pine and ice float; solid steel sinks', s: ['Compare each density with 1000 kg/m³.'] },
        { l: 2, q: 'A stone of mass 156 g raises the water in a measuring cylinder from 50.0 cm³ to 110.0 cm³. Find its density.', a: '2.6 g/cm³', s: ['V = 110.0 − 50.0 = 60.0 cm³.', 'ρ = 156 ÷ 60.0 = 2.6 g/cm³.'] },
        { l: 2, q: 'An empty measuring cylinder has a mass of 120 g. With 50.0 cm³ of a liquid in it, the mass is 160 g. Find the liquid’s density.', a: '0.80 g/cm³', s: ['Mass of liquid = 160 − 120 = 40 g.', 'ρ = 40 ÷ 50.0 = 0.80 g/cm³ (close to alcohol, 0.79 g/cm³).'] },
        { l: 2, q: 'An 80 kg astronaut stands on Mars, where g = 3.7 N/kg. What are her mass and weight there?', a: '80 kg; 296 N', s: ['Mass does not change: 80 kg.', 'W = 80 × 3.7 = 296 N, about 38% of her Earth weight.'] },
        { l: 2, q: 'Gold has a density of 19 300 kg/m³. Find the mass of a 1.0 cm³ cube and the volume of 1.0 kg of gold.', a: '19.3 g; 51.8 cm³', s: ['19 300 kg/m³ = 19.3 g/cm³, so 1.0 cm³ has mass 19.3 g.', 'V = 1000 g ÷ 19.3 g/cm³ = 51.8 cm³, smaller than a matchbox.'] },
        { l: 2, q: 'A spring balance marked in kilograms was calibrated on Earth. On the Moon (g = 1.6 N/kg) it reads 6.0 kg with an object hanging from it. What is the object’s real mass?', a: 'About 37 kg', s: ['The spring measures force. A reading of 6.0 kg means a force of 6.0 × 9.8 = 58.8 N.', 'On the Moon that force is the weight: m = 58.8 ÷ 1.6 = 36.8 kg.', 'A beam balance would have read the true mass directly.'] },
        { l: 3, q: 'Ice (917 kg/m³) floats in seawater (1025 kg/m³). What fraction of an iceberg is below the surface? (A floating object displaces its own weight of liquid.)', a: 'About 89%', s: ['Weight of iceberg = ρ_{ice} V g; weight of displaced water = ρ_{sea} V_{sub} g.', 'Setting them equal: V_{sub}/V = 917 ÷ 1025 = 0.895.', 'So about 89% is hidden below the surface.'] },
        { l: 3, q: 'A closed hollow steel box measures 2.0 m × 2.0 m × 1.0 m on the outside, and its walls contain 0.30 m³ of steel (7800 kg/m³). Does it float in fresh water, and if so, how deep does it sit?', a: 'It floats, 0.59 m deep', s: ['Mass = 0.30 × 7800 = 2340 kg; average density = 2340 ÷ 4.0 m³ = 585 kg/m³ < 1000, so it floats.', 'It sinks until it displaces 2340 kg of water: 2.34 m³.', 'Depth = 2.34 ÷ (2.0 × 2.0) = 0.585 m.'] }
      ]
    },

    'gcse-forces': {
      big: 'A force can change an object’s speed, its direction or its shape. Springs show the shape change most simply: up to a limit, the extension is proportional to the load. For motion, only the resultant force matters, and F = ma tells you the acceleration it causes. A force at right angles to the motion changes only the direction: that is circular motion.',
      sec: [
        { h: 'Springs and Hooke’s law', p: ['Hang loads on a spring and measure the extension (the increase in length, not the total length). A graph of load against extension is a straight line through the origin, up to the limit of proportionality. Beyond it the line curves, and past the elastic limit the spring no longer returns to its original length.', 'The gradient of the straight part is the spring constant k: the force per unit extension. A stiff spring has a large k.'], eq: R`F = k\,x\qquad(\text{up to the limit of proportionality})` },
        { h: 'Resultant force', p: ['Forces along the same line add with signs: 12 N to the right and 5 N to the left give a resultant of 7 N to the right. If the resultant is zero the forces are balanced, and the object either stays at rest or keeps moving at constant velocity (Newton’s first law).'] },
        { h: 'Force, mass and acceleration', p: ['An unbalanced resultant force makes the object accelerate in the direction of the force. The acceleration is proportional to the resultant force and inversely proportional to the mass.'], eq: R`F = m\,a`, after: ['One newton is the resultant force that gives a 1 kg mass an acceleration of 1 m/s².'] },
        { h: 'Friction and drag', p: ['Friction between surfaces opposes motion (or attempted motion) and heats the surfaces. Drag (air resistance or water resistance) opposes motion through a fluid and grows with speed.', 'A falling skydiver speeds up until the drag equals her weight; then the resultant force is zero and she falls at a steady terminal velocity. Opening the parachute increases the drag, she slows, and she reaches a new, lower terminal velocity.'] },
        { h: 'Circular motion', p: ['An object moving in a circle at constant speed is still accelerating, because its direction keeps changing. It needs a resultant force towards the centre, at right angles to its velocity. That force changes the direction, never the speed.', 'The force needed is larger for a larger mass, a higher speed and a tighter circle (smaller radius). Remove it, as when a car hits ice on a bend, and the object carries on in a straight line along the tangent.'], warn: '**Hidden assumptions.** Hooke’s law is an approximation for small stretches: rubber bands never obey it, and every spring fails it eventually. F = ma assumes a constant mass and speeds far below light’s; a rocket losing fuel needs F = Δ(mv)/Δt. Drag that grows with speed means the acceleration of a falling object is not constant, so the suvat equations do not apply to a skydiver.' }
      ],
      eqs: [[R`F = kx`, 'Hooke’s law: k in N/m, extension x in m'], [R`F_{\text{res}} = ma`, 'resultant force in N, mass in kg, acceleration in m/s²'], [R`W = mg`, 'weight, often one of the forces'], [R`F \propto \frac{mv^2}{r}`, 'force needed for circular motion (the exact form comes at A level)']],
      how: ['Draw a free-body diagram: every force on the object, as an arrow.', 'Find the resultant along the direction of motion, with signs.', 'Use F = ma with the resultant, never with one force alone.', 'For springs, use extension, and check you are below the limit of proportionality.', 'For circles, ask what supplies the inward force (tension, friction, gravity).'],
      sum: ['Forces change speed, direction or shape.', 'F = kx up to the limit of proportionality.', 'Balanced forces: constant velocity. Unbalanced: F = ma.', 'Friction and drag oppose motion; drag grows with speed, giving terminal velocity.', 'Circular motion needs an inward force; it changes direction, not speed.'],
      probs: [
        { l: 1, q: 'A spring stretches 4.0 cm when a 2.0 N load hangs from it. Find k, and the extension for a 3.0 N load (assume it is below the limit of proportionality).', a: 'k = 50 N/m; 6.0 cm', s: ['k = F/x = 2.0 ÷ 0.040 = 50 N/m.', 'x = 3.0 ÷ 50 = 0.060 m = 6.0 cm.'] },
        { l: 1, q: 'Forces of 12 N to the right and 5.0 N to the left act on a box. What is the resultant?', a: '7.0 N to the right', s: ['12 − 5.0 = 7.0 N, in the direction of the larger force.'] },
        { l: 1, q: 'A resultant force of 3000 N acts on a 1200 kg car. What is its acceleration?', a: '2.5 m/s²', s: ['a = F/m = 3000 ÷ 1200 = 2.5 m/s².'] },
        { l: 2, q: 'A 70 kg skydiver falls with 400 N of air resistance acting on her. Find her acceleration (g = 9.8 N/kg). What will the air resistance be when she reaches terminal velocity?', a: '4.1 m/s²; 686 N', s: ['Weight = 70 × 9.8 = 686 N.', 'Resultant = 686 − 400 = 286 N downwards; a = 286 ÷ 70 = 4.1 m/s².', 'At terminal velocity the resultant is zero, so drag = weight = 686 N.'] },
        { l: 2, q: 'A spring gives these extensions for loads of 0, 1, 2, 3, 4 and 5 N: 0, 2.0, 4.0, 6.0, 8.2 and 11.0 cm. Where is the limit of proportionality, and what is k?', a: 'Between 3 N and 4 N; k = 50 N/m', s: ['Up to 3 N each newton adds 2.0 cm: proportional.', 'At 4 N the extension is 8.2 cm instead of 8.0 cm, so the limit is passed between 3 N and 4 N.', 'k = 1 N ÷ 0.020 m = 50 N/m.'] },
        { l: 2, q: 'A car of mass 1000 kg has a driving force of 2500 N, while friction and drag total 1700 N. Find its acceleration.', a: '0.80 m/s²', s: ['Resultant = 2500 − 1700 = 800 N.', 'a = 800 ÷ 1000 = 0.80 m/s².'] },
        { l: 2, q: 'Two identical springs (k = 40 N/m) carry a 2.0 N load. Find the total extension when they hang one below the other, and when they hang side by side sharing the load equally.', a: '10 cm in series; 2.5 cm side by side', s: ['One below the other: each carries the full 2.0 N and stretches 2.0 ÷ 40 = 5.0 cm, total 10 cm.', 'Side by side: each carries 1.0 N and stretches 2.5 cm.'] },
        { l: 2, q: 'A car goes round a bend at constant speed. What provides the force towards the centre? What happens on an icy road, and how does the force needed change if the car goes faster?', a: 'Friction on the tyres; it slides along a tangent; it needs more', s: ['Sideways friction between the tyres and the road points towards the centre of the bend.', 'Ice cannot supply enough friction, so the car carries on in a straight line, along a tangent.', 'More speed needs more force (in fact, double the speed needs four times the force).'] },
        { l: 3, q: 'A lift of mass 800 kg accelerates upwards at 1.5 m/s². What is the tension in its cable?', a: '9000 N (9040 N)', s: ['Forces: tension T up, weight 800 × 9.8 = 7840 N down.', 'T − 7840 = 800 × 1.5 = 1200.', 'T = 9040 N, more than the weight, which is why you feel heavier as the lift starts up.'] },
        { l: 3, q: 'A 2.0 kg box is pulled along a floor by a 15 N force against 9.0 N of friction, from rest, for 4.0 s. Then the pull stops. How fast is it moving at 4.0 s, and how far does it slide after the pull stops?', a: '12 m/s; 16 m', s: ['a = (15 − 9.0) ÷ 2.0 = 3.0 m/s², so v = 3.0 × 4.0 = 12 m/s.', 'Without the pull, only friction acts: deceleration = 9.0 ÷ 2.0 = 4.5 m/s².', 'Sliding distance = v²/(2a) = 144 ÷ 9.0 = 16 m.'] }
      ]
    },

    'gcse-moments': {
      big: 'A force can turn things as well as push them. Its turning effect, the moment, is the force times its perpendicular distance from the pivot. When an object is balanced, the clockwise moments equal the anticlockwise moments, and the forces balance too. Where the weight acts, the centre of gravity, decides whether it stays upright or topples.',
      sec: [
        { h: 'The moment of a force', p: ['The moment of a force about a pivot is the force multiplied by the perpendicular distance from the pivot to the line of the force. It is measured in newton metres (N m).', 'This is why door handles are placed far from the hinges, and why a long spanner loosens a tight nut more easily: the same moment needs a smaller force when the distance is bigger.'], eq: R`\text{moment} = F \times d_{\perp}` },
        { h: 'The principle of moments', p: ['An object is in equilibrium when there is no resultant force and no resultant moment. Taking moments about any point, the total clockwise moment then equals the total anticlockwise moment.', 'On a seesaw, a 300 N child 2.0 m from the pivot balances a 400 N child 1.5 m from the pivot: 600 N m each way. The pivot pushes up with 700 N, so the forces balance as well.'], eq: R`\sum \text{clockwise moments} = \sum \text{anticlockwise moments}` },
        { h: 'Several forces and the weight of the beam', p: ['With several forces, add all the clockwise moments and all the anticlockwise ones. A beam that is not “light” has its own weight, which acts at its centre of gravity (the middle, for a uniform beam), and that weight has a moment too.', 'Choosing the pivot (or an unknown support) as the point you take moments about removes that force from the equation, because its distance is zero.'] },
        { h: 'Centre of gravity', p: ['The centre of gravity is the point where the whole weight of an object can be taken to act. For a uniform, symmetrical object it is at the geometric centre.', 'For a flat irregular shape (a lamina), hang it from a pin so it swings freely, and draw a vertical line along a plumb line from the pin. Repeat from another hole. The centre of gravity is where the lines cross, because a freely hanging object always comes to rest with its centre of gravity directly below the pivot.'] },
        { h: 'Stability', p: ['An object tips over when the vertical line through its centre of gravity passes outside its base: the weight then has a moment that turns it further. A low centre of gravity and a wide base make an object stable: racing cars, Bunsen burners and wine glasses with heavy bases.'], warn: '**Hidden assumptions.** “The weight acts at one point” assumes a uniform gravitational field; across the Moon, Earth’s pull differs from near side to far side, and that difference raises tides. And the distance in a moment must be perpendicular: for a force at an angle, use the perpendicular distance (or the perpendicular part of the force), not the length of the lever.' }
      ],
      eqs: [[R`M = F d_{\perp}`, 'moment in N m'], [R`\sum M_{\text{cw}} = \sum M_{\text{acw}}`, 'principle of moments (equilibrium)'], [R`\sum F_{\text{up}} = \sum F_{\text{down}}`, 'no resultant force (equilibrium)']],
      how: ['Draw the beam with every force, including its own weight at its centre.', 'Choose the point to take moments about, preferably where an unknown force acts.', 'Write clockwise moments = anticlockwise moments, using perpendicular distances.', 'Use the force balance to find any remaining support force.'],
      sum: ['Moment = force × perpendicular distance from the pivot.', 'Equilibrium: no resultant force and no resultant moment.', 'A uniform beam’s weight acts at its middle.', 'Centre of gravity of a lamina: where plumb lines from two pivots cross.', 'Stable: low centre of gravity, wide base.'],
      probs: [
        { l: 1, q: 'A force of 40 N is applied at right angles to a spanner, 0.25 m from the nut. What is its moment?', a: '10 N m', s: ['M = 40 × 0.25 = 10 N m.'] },
        { l: 1, q: 'A 300 N child sits 2.0 m from the pivot of a seesaw. Where must a 400 N child sit on the other side to balance?', a: '1.5 m from the pivot', s: ['300 × 2.0 = 400 × d, so d = 1.5 m.'] },
        { l: 1, q: 'Why is a door handle placed on the edge furthest from the hinges?', a: 'A bigger distance needs a smaller force', s: ['For the moment needed to open the door, a larger perpendicular distance means a smaller force.'] },
        { l: 2, q: 'A light metre rule is pivoted at the 50 cm mark. A 2.0 N weight hangs at the 10 cm mark. Where must a 5.0 N weight hang to balance it?', a: 'At the 66 cm mark', s: ['Anticlockwise moment = 2.0 × 0.40 = 0.80 N m.', '5.0 × d = 0.80, so d = 0.16 m to the right of the pivot: the 66 cm mark.'] },
        { l: 2, q: 'A uniform metre rule weighing 1.5 N is pivoted at the 30 cm mark. What weight hung at the 0 cm mark balances it?', a: '1.0 N', s: ['The rule’s weight acts at 50 cm, 0.20 m from the pivot: 1.5 × 0.20 = 0.30 N m.', 'W × 0.30 = 0.30, so W = 1.0 N.'] },
        { l: 2, q: 'A uniform 4.0 m plank weighing 200 N rests on supports at each end. A 600 N person stands 1.5 m from the left end. Find the force from each support.', a: '475 N (left) and 325 N (right)', s: ['Moments about the left end: R × 4.0 = 600 × 1.5 + 200 × 2.0 = 1300, so R = 325 N.', 'Forces: left support = 800 − 325 = 475 N. The support nearer the person carries more.'] },
        { l: 2, q: 'A wheelbarrow carries a 400 N load 0.40 m from the wheel’s axle. The handles are 1.2 m from the axle. What upward force at the handles lifts the load? (Ignore the barrow’s weight.)', a: '133 N', s: ['Moments about the axle: F × 1.2 = 400 × 0.40.', 'F = 133 N: the barrow is a force multiplier.'] },
        { l: 2, q: 'A 20 N force pulls on the end of a 0.30 m spanner at 60° to the handle. What is its moment?', a: '5.2 N m', s: ['Only the part of the force perpendicular to the spanner turns it: 20 × sin 60° = 17.3 N.', 'M = 17.3 × 0.30 = 5.2 N m (less than 6.0 N m for a perpendicular pull).'] },
        { l: 3, q: 'Explain why hanging a cardboard shape from two different holes, with a plumb line, finds its centre of gravity.', a: 'Each time it hangs with the centre of gravity directly below the pin', s: ['If the centre of gravity were not below the pin, the weight would have a moment about the pin and the shape would swing.', 'So at rest the centre of gravity lies on the vertical line through the pin.', 'Two such lines can only both pass through the centre of gravity where they cross.'] },
        { l: 3, q: 'A double-decker bus has its centre of gravity 1.2 m above the road, and its wheels are 2.0 m apart. How far can it be tilted sideways before it topples? (UK rules require it to stay upright at 28°.)', a: 'About 40°', s: ['It topples when the vertical through the centre of gravity passes the lower wheels, 1.0 m out from the centre line.', 'tan θ = 1.0 ÷ 1.2, so θ = 40°.', 'Passengers upstairs raise the centre of gravity and lower this angle, which is why the test is done with the top deck loaded.'] }
      ]
    },

    'gcse-work-power': {
      big: 'When a force moves something, it does work, and the work done is exactly the energy transferred. Power is how fast the energy is transferred. Efficiency is the share of it that ends up doing something useful; the rest is wasted, usually heating the surroundings.',
      sec: [
        { h: 'Work done', p: ['Work done equals the force times the distance moved in the direction of the force. One joule is the work done when a force of one newton moves its point of application one metre.', 'No movement, no work: holding a heavy bag still does no work on it (your muscles tire for biological reasons). Carrying it along a level path at constant speed does no work on it either, because your upward force is at right angles to the motion.'], eq: R`W = F\,d = \Delta E` },
        { h: 'Work and energy stores', p: ['Lifting something at steady speed: the force equals its weight, so the work done is mgh, which goes into the gravitational store. Pushing a box at steady speed against friction: the work done ends up in the thermal store of the box and floor.'] },
        { h: 'Power', p: ['Power is the rate of doing work or transferring energy. One watt is one joule per second. A 2 kW kettle transfers 2000 J every second.', 'For a vehicle moving at steady speed v against a resistive force F, the power needed is P = Fv, because each second it moves v metres against the force.'], eq: R`P = \frac{W}{t} = \frac{\Delta E}{t}` },
        { h: 'Efficiency and Sankey diagrams', p: ['Efficiency is the useful energy output divided by the total energy input (or the same with powers). It is always less than 1 (100%) for real machines.', 'A Sankey diagram draws energy flows as arrows whose widths are proportional to the energy: one wide input arrow splits into a useful arrow and wasted arrows bending away.'], eq: R`\text{efficiency} = \frac{\text{useful energy output}}{\text{total energy input}} \times 100\%`, warn: '**Limits that are not engineering failures.** Any engine that turns heat into work must dump some heat to a colder place; thermodynamics caps the efficiency below 100% even for a perfect machine. That is why the best steam-turbine power stations reach about 45% and car engines 25–35%, while electric motors can exceed 90%. And “useful” is a choice: the heat from a filament lamp is waste in summer and welcome in a cold room.' }
      ],
      eqs: [[R`W = Fd`, 'work in J, force in N, distance in m'], [R`W = \Delta E`, 'work done = energy transferred'], [R`P = W/t = \Delta E/t`, 'power in W (J/s)'], [R`P = Fv`, 'power to move at speed v against force F'], [R`\text{eff} = \frac{\text{useful out}}{\text{total in}}`, 'efficiency (×100 for a percentage)']],
      how: ['Check the force and the distance are along the same line.', 'Convert minutes to seconds and kW to W before using P = E/t.', 'For lifting at steady speed, the force is the weight mg.', 'For efficiency, identify the useful output first; the rest is waste.'],
      sum: ['Work done W = Fd = energy transferred.', 'No distance moved along the force means no work.', 'Power P = W/t; 1 W = 1 J/s.', 'Efficiency = useful output ÷ total input, always below 100%.', 'Sankey arrows have widths proportional to energy.'],
      probs: [
        { l: 1, q: 'You push a trolley with a 50 N force for 12 m. How much work do you do?', a: '600 J', s: ['W = Fd = 50 × 12 = 600 J.'] },
        { l: 1, q: 'How much energy does a 60 W lamp transfer in 5.0 minutes?', a: '18 000 J', s: ['E = Pt = 60 × 300 = 18 000 J.'] },
        { l: 1, q: 'A motor takes in 200 J of electrical energy and gives out 150 J of useful kinetic energy. What is its efficiency?', a: '75%', s: ['150 ÷ 200 = 0.75 = 75%. The other 50 J heats the motor and surroundings.'] },
        { l: 2, q: 'A crane lifts a 500 kg load 20 m in 25 s. Find the work done on the load and the useful power.', a: '98 kJ; 3.9 kW', s: ['W = mgh = 500 × 9.8 × 20 = 98 000 J.', 'P = 98 000 ÷ 25 = 3920 W ≈ 3.9 kW.'] },
        { l: 2, q: 'A 55 kg student runs up stairs with a vertical height of 3.6 m in 4.5 s. What power does she develop in lifting herself?', a: 'About 430 W', s: ['Work = 55 × 9.8 × 3.6 = 1940 J.', 'P = 1940 ÷ 4.5 = 431 W.'] },
        { l: 2, q: 'A 2.0 kW kettle is 85% efficient. How much energy goes into the water in 3.0 minutes?', a: '306 kJ', s: ['Input = 2000 × 180 = 360 000 J.', 'Useful = 0.85 × 360 000 = 306 000 J.'] },
        { l: 2, q: 'A car engine uses 100 kJ of fuel energy. 25 kJ becomes kinetic energy, 65 kJ heats the exhaust and cooling system, and the rest is sound and friction. Find the efficiency and the energy in sound and friction.', a: '25%; 10 kJ', s: ['Efficiency = 25 ÷ 100 = 25%.', 'Remaining = 100 − 25 − 65 = 10 kJ. On a Sankey diagram, the 65 kJ arrow is by far the widest waste arrow.'] },
        { l: 2, q: 'A cyclist does 18 kJ of work in one minute. What is her power, and how many such cyclists match a 60 kW car engine?', a: '300 W; 200 cyclists', s: ['P = 18 000 ÷ 60 = 300 W.', '60 000 ÷ 300 = 200.'] },
        { l: 3, q: 'A motor with an efficiency of 40% lifts a 30 kg load through 12 m in 20 s. Find the useful power, the electrical input power and the power wasted.', a: '176 W; 441 W; 265 W', s: ['Useful power = 30 × 9.8 × 12 ÷ 20 = 176 W.', 'Input = 176 ÷ 0.40 = 441 W.', 'Wasted = 441 − 176 = 265 W, mostly heating the motor.'] },
        { l: 3, q: 'A car cruises at a steady 25 m/s against resistive forces totalling 600 N. Show that the power needed is P = Fv and find it. If the engine is 30% efficient and petrol releases 34 MJ per litre, how many litres does it use per 100 km?', a: '15 kW; about 5.9 L per 100 km', s: ['In one second the car moves 25 m against 600 N: work per second = 600 × 25, so P = Fv = 15 000 W.', 'Fuel power = 15 000 ÷ 0.30 = 50 kW.', '100 km at 25 m/s takes 4000 s, using 50 kW × 4000 s = 200 MJ of fuel energy.', '200 ÷ 34 = 5.9 litres, close to real figures for a small car.'] }
      ]
    },

    'gcse-resources': {
      big: 'Almost all electricity comes from spinning a generator. Burning fuel, splitting uranium or tapping hot rocks boils water to drive a steam turbine; wind, falling water, tides and waves push turbines directly; only solar cells skip the turbine. Each resource trades off cost, reliability, pollution and whether it will run out, and nearly all of them are the Sun’s energy in disguise.',
      sec: [
        { h: 'Heat, steam, turbine, generator', p: ['In coal, oil, gas, biomass and nuclear power stations, energy from the fuel heats water into high-pressure steam. The steam spins a turbine, which turns a generator that induces an electric current. Geothermal stations do the same with steam from hot underground rocks.', 'Fossil fuels release chemical energy and carbon dioxide; nuclear fission releases nuclear energy with no CO₂ while running, but leaves radioactive waste that must be stored for thousands of years.'] },
        { h: 'Moving air and water', p: ['Wind turbines are pushed round by moving air. Hydroelectric dams let water stored high up fall through turbines (gravitational potential energy to kinetic energy). Tidal barrages trap water at high tide and release it through turbines; wave machines use the up-and-down motion of the sea.', 'Hydroelectric and tidal power are predictable; wind and waves depend on the weather.'] },
        { h: 'Solar energy', p: ['Solar cells (photovoltaic cells) turn light directly into electricity, with no moving parts; typical panels convert about 20% of the light. Solar thermal panels absorb sunlight to heat water instead.'] },
        { h: 'Comparing resources', list: ['Renewable (will not run out on human timescales): wind, hydroelectric, tidal, waves, solar, geothermal, biomass. Non-renewable: coal, oil, gas, uranium.', 'Reliability: fossil, nuclear, geothermal and hydro run on demand; wind, waves and solar vary and need storage or backup.', 'Environment: fossil fuels emit CO₂ (climate change) and pollutants; hydro floods valleys; tidal barrages change estuary habitats; wind farms take space and change landscapes.', 'Cost: some are cheap to run but expensive to build (nuclear, hydro, tidal); fuel costs dominate for gas.'] },
        { h: 'Where the energy really comes from', p: ['The Sun is powered by nuclear fusion: hydrogen nuclei join to make helium, releasing energy. Its light drives the weather (wind, waves, and rain that fills hydroelectric dams) and photosynthesis, which made biomass and, over millions of years, fossil fuels.', 'Three resources do not come from the Sun: nuclear fission (uranium made in ancient stellar explosions), geothermal (heat from radioactive decay inside Earth) and tidal power (the Moon’s gravity and Earth’s spin).', 'Fusion power stations on Earth are being researched; they would need temperatures of over 100 million kelvin and have not yet produced net electricity.'], warn: '**Ratings are not outputs.** A 3 MW wind turbine averages far less than 3 MW because the wind varies: onshore wind in the UK produces about 25–35% of its rated output over a year, UK solar about 10%, nuclear about 80–90%. Comparing resources by rated power alone overstates the variable ones.' }
      ],
      eqs: [[R`P = \frac{mgh}{t} = \rho Q g h`, 'power available from falling water (Q = volume flow per second)'], [R`\text{eff} = \frac{P_{\text{electrical}}}{P_{\text{input}}}`, 'efficiency of a power station'], [R`E = P\,t`, 'energy from power and time (1 kWh = 3.6 MJ)']],
      how: ['Trace the chain of energy transfers from the source to the generator.', 'Classify the source: renewable or not, from the Sun or not.', 'For numbers, convert to watts and seconds (or kW and hours) first.', 'When comparing, consider cost, reliability, pollution and scale, not one alone.'],
      sum: ['Most stations: heat → steam → turbine → generator.', 'Wind, hydro, tidal and waves turn turbines directly; solar cells need no turbine.', 'Renewable: wind, hydro, tidal, waves, solar, geothermal, biomass.', 'The Sun (fusion) is the source of most resources; not of nuclear, geothermal or tidal.', 'Variable sources need storage or backup.'],
      probs: [
        { l: 1, q: 'Which of these are renewable: coal, wind, uranium, tides, natural gas, biomass, geothermal?', a: 'Wind, tides, biomass, geothermal', s: ['Coal, gas and uranium are used up far faster than they form.'] },
        { l: 1, q: 'Describe the energy transfers in a hydroelectric power station.', a: 'Gravitational potential → kinetic → electrical', s: ['Water stored high up falls, gaining kinetic energy, which spins the turbine and generator.'] },
        { l: 1, q: 'Which energy resources do not get their energy from the Sun?', a: 'Nuclear fission, geothermal and tidal', s: ['Uranium was made in ancient stars, geothermal heat comes from radioactive decay in Earth, and tides from the Moon’s gravity and Earth’s rotation.'] },
        { l: 2, q: 'Water flows through a hydroelectric station at 50 m³ per second, falling 120 m. How much power does the water deliver, and how much electricity at 90% efficiency? (Water: 1000 kg/m³.)', a: '59 MW; 53 MW', s: ['Mass per second = 50 000 kg.', 'P = mgh per second = 50 000 × 9.8 × 120 = 5.9 × 10⁷ W.', 'Electrical output = 0.90 × 59 MW = 53 MW.'] },
        { l: 2, q: 'A gas power station takes in 1500 MW of fuel energy and produces 600 MW of electricity. Find its efficiency and say where the rest goes.', a: '40%; 900 MW of heat, mostly into cooling water and the air', s: ['600 ÷ 1500 = 40%.', 'The other 900 MW leaves as heat in cooling water, cooling towers and exhaust gases.'] },
        { l: 2, q: 'A 1.6 m² solar panel in 800 W/m² sunlight is 20% efficient. Find its output power and the energy it produces in 5.0 hours.', a: '256 W; 1.28 kWh (4.6 MJ)', s: ['Light power = 800 × 1.6 = 1280 W; output = 0.20 × 1280 = 256 W.', 'Energy = 0.256 kW × 5.0 h = 1.28 kWh = 4.6 MJ.'] },
        { l: 2, q: 'A 3.0 MW wind turbine runs at an average of 30% of its rating. How much energy does it produce in a year, and how many homes using 3.0 MWh a year could it supply?', a: 'About 7.9 GWh; about 2600 homes', s: ['Average power = 0.30 × 3.0 = 0.90 MW.', 'Energy = 0.90 MW × 8760 h = 7900 MWh.', '7900 ÷ 3.0 ≈ 2600 homes on average (but not on still days).'] },
        { l: 2, q: 'Explain why a grid that relies on wind and solar power needs storage or backup.', a: 'Their output varies with the weather, not with demand', s: ['Solar gives nothing at night and little in winter; wind can drop for days.', 'Demand peaks in the evening. Storage (batteries, pumped hydroelectric) or reliable backup (gas, hydro, nuclear, imports) fills the gaps.'] },
        { l: 3, q: 'The power in the wind passing through a turbine’s blades is ½ρAv³. For blades 50 m long in a 10 m/s wind (air: 1.2 kg/m³), find this power. No turbine can extract more than 59% of it (the Betz limit). What happens to the available power if the wind speed halves?', a: '4.7 MW, at most 2.8 MW extracted; it falls to one eighth', s: ['A = π × 50² = 7850 m².', 'P = ½ × 1.2 × 7850 × 10³ = 4.7 × 10⁶ W; 59% of it is 2.8 MW.', 'P ∝ v³, so halving v gives (½)³ = ⅛ of the power: why wind output swings so much.'] },
        { l: 3, q: 'Burning 1 kg of carbon releases about 33 MJ and makes 3.7 kg of CO₂. Estimate the CO₂ emitted per kWh of electricity from a 38%-efficient coal power station.', a: 'About 1 kg of CO₂ per kWh', s: ['1 kWh of electricity = 3.6 MJ; fuel energy needed = 3.6 ÷ 0.38 = 9.5 MJ.', 'Carbon burned = 9.5 ÷ 33 = 0.29 kg, giving 0.29 × 3.7 = 1.05 kg of CO₂.', 'Real coal stations emit 0.9–1.0 kg/kWh, about twice a gas station and roughly fifty times the lifetime figure for wind.'] }
      ]
    },

    'gcse-pressure': {
      big: 'Pressure is force spread over an area: the same force pressing on a smaller area gives a bigger pressure. In a liquid, pressure comes from the weight of liquid above, so it grows with depth and with the liquid’s density, and it pushes equally in all directions.',
      sec: [
        { h: 'Pressure on solids', p: ['Pressure is the force acting at right angles to a surface divided by the area it acts on. The unit is the pascal: 1 Pa = 1 N/m².', 'A sharp knife has a tiny cutting area, so a modest force gives an enormous pressure. Snowshoes and tractor tyres spread the weight over a large area, so the pressure is small and they do not sink in.'], eq: R`p = \frac{F}{A}` },
        { h: 'Pressure in liquids', p: ['A liquid pushes on everything in it and on the walls of its container. The pressure increases with depth, because there is more liquid above pushing down, and is larger in a denser liquid. At a given depth it acts equally in all directions.', 'That is why dams are much thicker at the bottom, and why water spurts furthest from the lowest hole in a can.'] },
        { h: 'Δp = ρgΔh', p: ['Picture a column of liquid of height Δh standing on an area A. Its volume is AΔh, its mass ρAΔh and its weight ρAΔh g. That weight presses on area A, so the extra pressure is ρgΔh. The area cancels: the shape of the container does not matter.'], eq: R`\Delta p = \rho\,g\,\Delta h` },
        { h: 'Atmospheric pressure', p: ['The air above us also has weight. At sea level it presses with about 101 000 Pa (101 kPa), the weight of roughly 10 tonnes on every square metre. We do not notice because the pressure inside our bodies pushes back equally.', 'Under water the total pressure is atmospheric pressure plus ρgh. Every 10 m of water adds about one more atmosphere.'], eq: R`p_{\text{total}} = p_{\text{atm}} + \rho g h` },
        { h: 'Using pressure: hydraulics', p: ['A liquid passes on any pressure applied to it. In a hydraulic jack or car brakes, a small force on a small piston creates a pressure that acts on a large piston, giving a large force: F₂ = F₁ × A₂/A₁. The large piston moves a smaller distance, so the work done is not multiplied.'], warn: '**Where Δp = ρgΔh fails.** It assumes the density is the same at every depth (true for liquids, which are almost incompressible) and that g is constant. It is badly wrong for the atmosphere over large heights, because air is compressible: the pressure roughly halves for every 5.5 km you climb, falling off exponentially rather than in a straight line.' }
      ],
      eqs: [[R`p = F/A`, 'pressure in Pa (N/m²)'], [R`\Delta p = \rho g \Delta h`, 'pressure change with depth in a liquid'], [R`p_{\text{atm}} \approx 1.01 \times 10^5\ \text{Pa}`, 'atmospheric pressure at sea level'], [R`F_2 = F_1\frac{A_2}{A_1}`, 'hydraulic force multiplier']],
      how: ['Convert areas to m² (1 cm² = 10⁻⁴ m²) before using p = F/A.', 'For liquids, use the vertical depth below the surface, not the distance along a slope.', 'Decide whether the question wants the pressure due to the liquid or the total including the atmosphere.', 'For hydraulics, the pressure is the same on both pistons.'],
      sum: ['p = F/A, measured in pascals.', 'Liquid pressure increases with depth and density, and acts in all directions.', 'Δp = ρgΔh; the container’s shape does not matter.', 'Atmospheric pressure is about 101 kPa; 10 m of water adds about the same again.', 'Hydraulics multiply force, not energy.'],
      probs: [
        { l: 1, q: 'A 600 N person stands on two feet with a total contact area of 0.040 m². What pressure do they exert on the floor?', a: '15 000 Pa', s: ['p = F/A = 600 ÷ 0.040 = 15 000 Pa.'] },
        { l: 1, q: 'Why does a sharp knife cut better than a blunt one?', a: 'Smaller area, larger pressure', s: ['The same force acts on a much smaller area, so the pressure on the food is much larger.'] },
        { l: 1, q: 'What is the pressure due to the water 25 m below the surface of a lake? (ρ = 1000 kg/m³, g = 9.8 N/kg)', a: '245 kPa', s: ['Δp = ρgh = 1000 × 9.8 × 25 = 245 000 Pa.'] },
        { l: 2, q: 'Atmospheric pressure is 101 kPa. What is the total pressure on a diver 25 m below the lake surface?', a: '346 kPa', s: ['p = 101 + 245 = 346 kPa, about 3.4 times the pressure at the surface.'] },
        { l: 2, q: 'A 50 000 N elephant stands on four feet, each 0.10 m². A 500 N person balances on one stiletto heel of area 1.0 cm². Compare the pressures.', a: '125 kPa against 5.0 MPa: the heel is 40 times worse', s: ['Elephant: 50 000 ÷ 0.40 = 125 000 Pa.', 'Heel: 500 ÷ (1.0 × 10⁻⁴) = 5.0 × 10⁶ Pa.', 'Ratio 40: why some floors ban stiletto heels.'] },
        { l: 2, q: 'In a mercury barometer, atmospheric pressure holds up a column of mercury (13 600 kg/m³). How tall is the column when the pressure is 101 kPa?', a: '0.76 m (760 mm)', s: ['h = p/(ρg) = 101 000 ÷ (13 600 × 9.8) = 0.758 m.'] },
        { l: 2, q: 'Seawater has a density of 1030 kg/m³. How much greater is the pressure on a diver at 12 m than at the surface?', a: '121 kPa', s: ['Δp = 1030 × 9.8 × 12 = 121 000 Pa: more than one extra atmosphere.'] },
        { l: 2, q: 'In a hydraulic jack, a 150 N force pushes a 2.0 cm² piston. The large piston has an area of 100 cm². What force does it exert, and how far does it rise when the small piston moves 10 cm?', a: '7500 N; 0.20 cm', s: ['p = 150 ÷ 2.0 cm² = 75 N/cm²; F = 75 × 100 = 7500 N.', 'The volume of liquid moved is the same: 2.0 × 10 = 100 × d, so d = 0.20 cm.', 'Work in = 150 × 0.10 = 15 J; work out = 7500 × 0.0020 = 15 J.'] },
        { l: 3, q: 'A dam holds back water 40 m deep. Find the average pressure on the wall and the force on a 1.0 m wide vertical strip of it. Why is the dam thicker at the bottom?', a: '196 kPa; 7.8 MN', s: ['Pressure rises steadily from 0 at the top to ρgh = 392 kPa at the bottom, so the average is 196 kPa.', 'Area of the strip = 40 m²: force = 196 000 × 40 = 7.8 × 10⁶ N.', 'The pressure is greatest at the bottom, so the wall must be strongest there.'] },
        { l: 3, q: 'Suction pumps at the top of a mine shaft could never lift water more than about 10 m. Explain why, and calculate the limit.', a: '10.3 m: the atmosphere can only push water that high', s: ['A suction pump only removes air above the water; the atmosphere outside pushes the water up the pipe.', 'Even with a perfect vacuum, the column stops when ρgh equals atmospheric pressure: h = 101 000 ÷ (1000 × 9.8) = 10.3 m.', 'This puzzle led Torricelli in 1643 to the mercury barometer and the idea that air has weight.'] }
      ]
    }
  });
})();
/* ---- notes-gcse3.js ---- */
/* Geodesic: notes and ten-problem sets for GCSE outline topics, part 2 (IGCSE 0625 sections 2 and 3). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'gcse-particles': {
      big: 'Everything is made of particles in constant motion. How closely they are packed and how strongly they attract each other decide whether a substance is a solid, a liquid or a gas. Temperature measures how fast they move, and gas pressure is nothing more than particles hammering on the walls.',
      sec: [
        { h: 'Solids, liquids and gases', list: ['Solid: particles closely packed in a regular pattern, vibrating about fixed positions; strong forces between them. Fixed shape and volume.', 'Liquid: particles close together but irregular, sliding past one another; forces still significant. Fixed volume, takes the container’s shape.', 'Gas: particles far apart, moving fast and randomly in straight lines between collisions; forces negligible except in collisions. Fills any container; easily compressed.'], p: ['The three states differ in how the particles are arranged, how far apart they are, how they move and how strongly they attract. Melting, boiling, freezing and condensing change the arrangement, not the particles themselves; pure water melts at 0 °C and boils at 100 °C at normal atmospheric pressure.'] },
        { h: 'Temperature and absolute zero', p: ['The hotter a substance, the faster its particles move on average: temperature measures their average kinetic energy. Cool anything enough and the motion approaches its minimum. That temperature, −273 °C, is absolute zero, the bottom of the Kelvin scale.', 'A temperature change of 1 K is the same size as a change of 1 °C; only the starting point differs.'], eq: R`T\,(\text{K}) = \theta\,(^\circ\text{C}) + 273` },
        { h: 'Brownian motion: seeing molecules indirectly', p: ['Under a microscope, smoke specks in air jiggle about at random. Air molecules are far too small to see, but they move fast and hit each speck unevenly from different sides, so it is shoved first one way, then another.', 'Light, fast molecules can move a much more massive speck because there are so many collisions. Einstein explained this in 1905 and Perrin’s measurements of it (1908) convinced the last doubters that atoms are real.'] },
        { h: 'Gas pressure', p: ['Gas particles constantly collide with the walls of their container. Each collision exerts a small force; the total force per unit area is the gas pressure.', 'Heat a gas in a fixed volume: the particles move faster, hitting the walls harder and more often, so the pressure rises. Squash a gas into a smaller volume at constant temperature: the particles hit each part of the wall more often, so again the pressure rises.'] },
        { h: 'Boyle’s law: pV = constant', p: ['For a fixed mass of gas at constant temperature, halving the volume doubles the pressure: the same particles, moving at the same speeds, hit twice as often per unit area.'], eq: R`p_1V_1 = p_2V_2`, warn: '**Hidden assumptions.** pV = constant needs a fixed amount of gas, a constant temperature and an “ideal” gas: particles that are tiny compared with their spacing and do not attract each other. Squash a gas quickly (a bicycle pump) and it heats up, so the pressure rises more than Boyle predicts. Near condensation the attractions matter and the law fails. Absolute zero itself can be approached but never reached: laboratories have cooled atoms to below a billionth of a kelvin.' }
      ],
      eqs: [[R`T = \theta + 273`, 'kelvin from degrees Celsius'], [R`p = F/A`, 'pressure from the force of collisions on the walls'], [R`p_1V_1 = p_2V_2`, 'fixed mass of gas at constant temperature'], [R`0\ \text{K} = -273\ ^\circ\text{C}`, 'absolute zero']],
      how: ['Describe states by arrangement, separation, motion and forces.', 'Convert to kelvin for any gas calculation involving temperature.', 'For Boyle’s law, check the temperature and amount of gas stay fixed, and keep pressures in the same units.', 'Explain pressure changes with collisions: how hard and how often.'],
      sum: ['Solids vibrate in place; liquids slide; gases fly freely.', 'Temperature measures average particle kinetic energy; absolute zero is −273 °C = 0 K.', 'Brownian motion is evidence for moving molecules.', 'Gas pressure comes from collisions with the walls.', 'At constant temperature, pV = constant.'],
      probs: [
        { l: 1, q: 'Convert 27 °C to kelvin and 100 K to degrees Celsius.', a: '300 K; −173 °C', s: ['27 + 273 = 300 K.', '100 − 273 = −173 °C.'] },
        { l: 1, q: 'Describe the arrangement and motion of particles in a liquid.', a: 'Close together, irregular, moving past each other', s: ['They touch their neighbours (so liquids hardly compress) but are not in fixed places, so the liquid flows.'] },
        { l: 1, q: 'Why does a gas exert a pressure on the walls of its container?', a: 'Its particles collide with the walls', s: ['Each collision pushes on the wall; the total force on each square metre is the pressure.'] },
        { l: 2, q: '200 cm³ of air at 100 kPa is slowly compressed to 50 cm³ at constant temperature. What is its new pressure?', a: '400 kPa', s: ['p₂ = p₁V₁/V₂ = 100 × 200 ÷ 50 = 400 kPa.'] },
        { l: 2, q: 'A diver releases a 2.0 cm³ bubble where the pressure is 3.0 × 10⁵ Pa. What is its volume at the surface, where the pressure is 1.0 × 10⁵ Pa? (Assume the temperature stays the same.)', a: '6.0 cm³', s: ['V₂ = p₁V₁/p₂ = 3.0 × 2.0 ÷ 1.0 = 6.0 cm³.', 'The same effect in a diver’s lungs is why divers must never hold their breath while rising.'] },
        { l: 2, q: 'Explain why smoke particles in air move about randomly when seen under a microscope.', a: 'Uneven bombardment by fast, invisible air molecules', s: ['Air molecules move fast in random directions.', 'At any instant more hit one side of a speck than the other, so it is pushed in a random direction, and the imbalance keeps changing.'] },
        { l: 2, q: 'Why is a car tyre’s pressure higher after a long, fast drive?', a: 'The air in it is hotter', s: ['Flexing tyres warm the air inside; its particles move faster.', 'They hit the walls harder and more often, so the pressure rises (the volume barely changes).'] },
        { l: 2, q: 'Using particles, explain why the pressure of a gas rises when it is squashed into a smaller volume at constant temperature.', a: 'More collisions per second on each area of wall', s: ['The particles move at the same average speed (same temperature).', 'In a smaller space they reach the walls more often, so more collisions per second hit each square metre: a larger force per area.'] },
        { l: 3, q: 'A sealed syringe holds 60 cm³ of air at 100 kPa. The plunger (area 4.0 cm²) is pushed in until the volume is 20 cm³, slowly so the temperature stays the same. Find the new pressure and the extra force needed on the plunger, beyond atmospheric pressure.', a: '300 kPa; 80 N', s: ['p₂ = 100 × 60 ÷ 20 = 300 kPa.', 'The air outside pushes with 100 kPa, so the net pressure to overcome is 200 kPa.', 'F = 200 000 × 4.0 × 10⁻⁴ = 80 N.'] },
        { l: 3, q: 'At constant volume, a gas’s pressure is proportional to its kelvin temperature. A sealed rigid can at 20 °C and 100 kPa is thrown on a fire and reaches 400 °C. Estimate the pressure inside. Why must the temperature be in kelvin?', a: 'About 230 kPa', s: ['T₁ = 293 K, T₂ = 673 K.', 'p₂ = 100 × 673 ÷ 293 = 230 kPa, which can burst the can: hence the warnings on aerosol cans.', 'Pressure is proportional to the average particle energy, which is zero at 0 K, not at 0 °C; using Celsius would wrongly give a 20-fold rise.'] }
      ]
    },

    'gcse-expansion': {
      big: 'Most things get bigger when they are heated. Gases expand far more than liquids, and liquids more than solids. The expansion is small for solids, but it is strong enough to buckle railway lines and crack glass, so engineers design around it, and thermometers and thermostats put it to work.',
      sec: [
        { h: 'How much things expand', p: ['For the same temperature rise, gases expand the most, liquids much less and solids least of all. A steel rail 10 m long grows by only about 1 mm for every 10 °C rise, but the force needed to stop it growing is enormous.'], box: '**Extension (A level preview):** the change in length is ΔL = αL₀ΔT, where α is the expansivity: about 12 × 10⁻⁶ per K for steel, 23 × 10⁻⁶ per K for aluminium and 9 × 10⁻⁶ per K for ordinary glass.' },
        { h: 'The particle explanation', p: ['In a solid, heating makes the particles vibrate with larger amplitude, so on average they sit slightly further apart and the whole solid grows. The particles themselves do not get bigger.', 'In a liquid the same happens, more strongly because the forces between particles are weaker. In a gas at constant pressure, faster particles push the walls back further: gases expand most because almost nothing holds their particles together.'] },
        { h: 'Designing for expansion', list: ['Bridges and railway lines have expansion gaps or sliding joints so they do not buckle on hot days.', 'Overhead power cables are hung with slack, so they do not snap when they contract in winter; they sag lower in summer.', 'Metal lids stuck on glass jars loosen under hot water because metal expands more than glass.', 'Hot rivets and shrink-fitted metal rings tighten as they cool and contract.', 'Thick glass can crack if heated unevenly, because one part expands before another; ovenware uses low-expansion glass.'] },
        { h: 'Putting expansion to work', p: ['A liquid-in-glass thermometer uses the expansion of mercury or coloured alcohol: a narrow tube turns a tiny change in volume into a long movement of the thread.', 'A bimetallic strip is two metals bonded together. When heated, the one that expands more (for example brass) ends up on the outside of the curve, so the strip bends. It switches heaters and kettles on and off in thermostats.'] },
        { h: 'Water is strange', p: ['Water contracts as it warms from 0 °C to 4 °C, and only expands above 4 °C, so it is densest at 4 °C. Ponds therefore freeze from the top down: the densest (4 °C) water sinks to the bottom and the ice floats on top, insulating the water below so fish survive.'], warn: '**Hidden assumptions.** A thermometer scale assumes its liquid expands by the same amount for each degree. Mercury comes close; water would be useless near 4 °C. And “a gas expands in proportion to its kelvin temperature” is true only while it stays a gas: cool air towards 90 K and its oxygen starts to liquefy, so a balloon shrinks far more than the gas law predicts.' }
      ],
      eqs: [[R`\text{gases} \gg \text{liquids} > \text{solids}`, 'order of expansion for the same temperature rise'], [R`\Delta L = \alpha L_0 \Delta T`, 'extension: linear expansion of a solid (α in K⁻¹)'], [R`V \propto T\ (\text{K})`, 'extension: gas at constant pressure']],
      how: ['Decide which material expands more; that decides which way things bend, loosen or tighten.', 'Explain with particles vibrating (solids, liquids) or moving faster (gases) and moving further apart.', 'For calculations, use temperature differences (equal in K and °C) for solids; use kelvin for gases.'],
      sum: ['Heating makes solids, liquids and gases expand; gases most, solids least.', 'Particles move further apart; they do not grow.', 'Expansion gaps, slack cables and bimetallic thermostats all follow from it.', 'Liquid-in-glass thermometers use a liquid’s expansion.', 'Water is densest at 4 °C, so ponds freeze from the top.'],
      probs: [
        { l: 1, q: 'Why are small gaps left between sections of railway track or bridge decks?', a: 'So they can expand on hot days without buckling', s: ['Steel expands as it warms; without room to grow, the huge forces would bend the rails.'] },
        { l: 1, q: 'Put solids, liquids and gases in order of how much they expand for the same temperature rise.', a: 'Gases > liquids > solids', s: ['The weaker the forces between particles, the more easily they move apart.'] },
        { l: 1, q: 'Explain, in terms of particles, why a metal bar gets longer when heated.', a: 'Its particles vibrate more and sit further apart', s: ['The particles do not get bigger; their larger vibrations push their average spacing up.'] },
        { l: 2, q: 'A 500 m steel bridge experiences temperatures from −10 °C to 40 °C. Using ΔL = αL₀ΔT with α = 12 × 10⁻⁶ K⁻¹, how much does its length change?', a: '0.30 m', s: ['ΔT = 50 K.', 'ΔL = 12 × 10⁻⁶ × 500 × 50 = 0.30 m: the expansion joints must allow 30 cm of movement.'] },
        { l: 2, q: 'A bimetallic strip is made of brass (expands more) and steel. Which way does it bend when heated?', a: 'Towards the steel side, with brass on the outside of the curve', s: ['The brass grows longer than the steel; the longer strip must be on the outside of the curve.'] },
        { l: 2, q: 'A metal lid is stuck on a glass jar. Why does running hot water over the lid help?', a: 'The metal lid expands more than the glass', s: ['Both warm up, but metal has a larger expansivity (and warms faster), so the lid’s diameter grows more than the jar’s neck.'] },
        { l: 2, q: 'Why do overhead power cables sag more in summer than in winter, and why are they not pulled tight when installed?', a: 'They expand when warm; tight cables could snap on contracting in winter', s: ['Longer cable between the same pylons hangs lower.', 'A cable strung tight in summer would contract in winter and could break or pull on the pylons.'] },
        { l: 2, q: 'Why does a liquid-in-glass thermometer have a very narrow tube and a large bulb?', a: 'To turn a small volume change into a long movement', s: ['The bulb holds a lot of liquid, so the total volume change per degree is as large as possible.', 'Forced into a narrow tube, that small volume makes a long thread movement: a sensitive thermometer.'] },
        { l: 3, q: 'An aluminium rod and a steel rod are each 2.000 m long at 20 °C. Both are heated to 120 °C. How much longer is the aluminium rod then? (α: aluminium 23 × 10⁻⁶ K⁻¹, steel 12 × 10⁻⁶ K⁻¹)', a: '2.2 mm', s: ['Aluminium: ΔL = 23 × 10⁻⁶ × 2.000 × 100 = 4.6 mm.', 'Steel: 12 × 10⁻⁶ × 2.000 × 100 = 2.4 mm.', 'Difference 2.2 mm: bond the two together and the difference forces a bend, which is exactly how a bimetallic strip works.'] },
        { l: 3, q: 'A 2.0 L balloon of air at 27 °C is cooled to 77 K in liquid nitrogen. If the air behaved as an ideal gas at constant pressure (V ∝ T in kelvin), what would its volume become? In practice it shrinks even more. Why?', a: '0.51 L predicted; oxygen liquefies', s: ['V₂ = 2.0 × 77 ÷ 300 = 0.51 L.', 'Oxygen condenses below about 90 K, so part of the gas turns to liquid and takes up almost no space: the ideal-gas assumption has broken down.'] }
      ]
    },

    'gcse-heat-transfer': {
      big: 'Thermal energy flows from hot to cold by three routes. Conduction passes it from particle to particle through a material, convection carries it bodily in moving liquids and gases, and radiation sends it as infrared waves that need no material at all. Insulating a house, designing a saucepan or understanding Earth’s climate all come down to controlling these three.',
      sec: [
        { h: 'Conduction', p: ['Heat one end of a rod and the other end eventually warms. Metals are good thermal conductors; wood, plastic, glass and especially air are poor conductors (insulators).', 'In every solid, hotter particles vibrate more and pass vibrations on to their neighbours through the bonds between them. Metals also have free (delocalised) electrons that move fast through the whole metal and carry energy quickly from hot regions to cold ones. That is why metals conduct heat (and electricity) so well.'] },
        { h: 'Convection', p: ['Convection happens only in fluids (liquids and gases). Heated fluid expands, becomes less dense and rises; cooler, denser fluid sinks to replace it, forming a circulating convection current.', 'A room heater warms the air near it, which rises across the ceiling, cools and sinks on the far side. A freezer compartment sits at the top of a fridge so that cold air sinks through the cabinet. Sea breezes blow onshore on sunny days because land heats faster than sea, and the warm air over it rises.'] },
        { h: 'Thermal radiation', p: ['All objects emit infrared radiation, and hotter objects emit more, and more strongly at shorter wavelengths. Radiation is an electromagnetic wave, so it crosses a vacuum: that is how the Sun’s energy reaches Earth.', 'Dull, matt black surfaces are the best absorbers and emitters of infrared; shiny, light-coloured surfaces are the poorest absorbers and emitters, because they reflect it. A Leslie cube (a hot cube with differently painted faces) and an infrared detector show the matt black face emits most. The rate of emission also increases with surface area.'] },
        { h: 'Energy balance and Earth’s temperature', p: ['An object warms up if it absorbs radiation faster than it emits it, and cools if it emits faster. Its temperature stays constant when the two rates are equal.', 'Earth absorbs sunlight and emits infrared to space. Greenhouse gases (water vapour, carbon dioxide, methane) absorb part of the outgoing infrared and re-emit some back down, so the surface must be warmer before the balance is restored. Adding CO₂ shifts the balance and warms the climate.'] },
        { h: 'Everyday consequences', list: ['Saucepans: metal bases conduct heat to the food; plastic or wooden handles do not burn your hand.', 'Loft insulation and woollen clothes trap air, a poor conductor, in small pockets so it cannot convect.', 'Double glazing: a gap of air or argon between panes cuts conduction; a vacuum would cut convection too.', 'A vacuum flask: the vacuum stops conduction and convection, silvered walls reduce radiation, and the stopper stops convection out of the top.', 'Cooling fins on engines and computer chips are large and thin to radiate and convect energy away quickly.'], warn: '**Colour in visible light is not colour in infrared.** “Black is a good emitter” really means “a good emitter of infrared”, and many surfaces look different there: white paint, skin and snow are almost perfect infrared emitters and absorbers despite looking white. Shiny metal really is poor in both. Judging infrared behaviour by eye is a hidden assumption that often fails.' }
      ],
      eqs: [[R`\text{absorbed rate} = \text{emitted rate}`, 'constant temperature (energy balance)'], [R`P = \varepsilon\sigma A T^4`, 'extension (A level): power radiated by a surface at kelvin temperature T'], [R`\sigma = 5.67\times10^{-8}\ \text{W m}^{-2}\text{K}^{-4}`, 'Stefan–Boltzmann constant']],
      how: ['Name the route: through a solid (conduction), by fluid movement (convection), or as infrared (radiation).', 'For conduction in metals, mention free electrons; for convection, density changes.', 'For radiation, consider the surface (matt/black or shiny/silver), its temperature and its area.', 'For a steady temperature, set the rates of gain and loss equal.'],
      sum: ['Conduction: particle vibrations, plus free electrons in metals.', 'Convection: hot fluid expands, becomes less dense and rises.', 'Radiation: infrared, needs no medium; matt black absorbs and emits best.', 'Steady temperature when energy in = energy out.', 'Insulation traps air; vacuum flasks block all three routes.'],
      probs: [
        { l: 1, q: 'Why are saucepan handles made of plastic or wood?', a: 'They are poor conductors', s: ['Little energy conducts from the hot pan to your hand.'] },
        { l: 1, q: 'Why does warm air rise above a radiator?', a: 'It expands, becomes less dense and floats up', s: ['Cooler, denser air sinks to take its place, setting up a convection current.'] },
        { l: 1, q: 'How does the Sun’s energy reach Earth, and why can’t it be by conduction or convection?', a: 'By radiation; space is a vacuum', s: ['Conduction and convection need particles; electromagnetic waves do not.'] },
        { l: 2, q: 'Explain why metals conduct heat much better than non-metals.', a: 'Free electrons carry energy quickly', s: ['All solids pass on vibrations between neighbouring particles, which is slow.', 'Metals also have free electrons that move rapidly through the metal and transfer energy as they collide.'] },
        { l: 2, q: 'An infrared detector is held the same distance from each face of a Leslie cube full of hot water. The faces are matt black, matt white, shiny black and shiny silver. Which face gives the largest reading and which the smallest?', a: 'Largest: matt black. Smallest: shiny silver.', s: ['All faces are at the same temperature, so differences come from the surfaces.', 'Matt black is the best emitter; shiny silver reflects rather than emits and is the worst.'] },
        { l: 2, q: 'Explain how each feature of a vacuum flask reduces energy transfer: the vacuum, the silvered walls and the stopper.', a: 'Vacuum: no conduction or convection. Silvering: little radiation. Stopper: stops convection and evaporation.', s: ['A vacuum has no particles to conduct or convect.', 'Shiny surfaces are poor emitters and good reflectors of infrared.', 'The stopper stops warm air and vapour from rising out of the top.'] },
        { l: 2, q: 'Why is the freezer compartment of an old-style fridge at the top?', a: 'Cold air sinks and sets up a convection current', s: ['Air cooled by the freezer becomes denser and sinks through the cabinet, cooling the food; warmer air rises to be cooled.'] },
        { l: 2, q: 'Why do loft insulation and double glazing reduce heat loss?', a: 'Trapped air is a poor conductor and cannot convect', s: ['Air conducts heat very poorly.', 'Trapping it in small pockets or a thin gap stops it circulating, so convection is reduced too.'] },
        { l: 3, q: 'Earth receives 1361 W/m² of sunlight and reflects 30% of it. Absorbed sunlight, averaged over the whole spherical surface, is 1361 × 0.70 ÷ 4 = 238 W/m². If Earth radiated as σT⁴ (σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴), what temperature would balance this? Compare with the actual average, 288 K.', a: '255 K, which is 33 K colder than reality', s: ['σT⁴ = 238, so T⁴ = 238 ÷ 5.67 × 10⁻⁸ = 4.20 × 10⁹.', 'T = 255 K (−18 °C).', 'The 33 K difference is the greenhouse effect: the atmosphere absorbs and re-emits part of the outgoing infrared.'] },
        { l: 3, q: 'Two identical cans, one matt black and one shiny silver, are filled with water at 80 °C and left in a cool room. Which cools faster? The cans are then refilled with cold water and put in bright sunlight. Which warms faster, and why does each eventually stop warming?', a: 'Black cools faster and warms faster; each stops when it loses energy as fast as it gains it', s: ['Matt black is the better emitter, so it cools faster.', 'It is also the better absorber, so it warms faster in sunlight.', 'As a can warms it emits more (and convection losses grow) until loss rate = absorbed rate: a steady temperature.'] }
      ]
    },

    'gcse-waves': {
      big: 'A wave carries energy from place to place without carrying matter with it: the water in a ripple only bobs up and down while the ripple travels on. All waves share the same vocabulary (amplitude, wavelength, frequency, speed) and the same behaviours: they reflect, refract and diffract. One equation, v = fλ, links their speed, frequency and wavelength.',
      sec: [
        { h: 'Describing a wave', list: ['Amplitude: the largest displacement from the rest position.', 'Wavelength λ: the distance between two neighbouring crests (or any two matching points), in metres.', 'Frequency f: how many waves pass a point each second, in hertz (Hz).', 'Period T: the time for one complete wave; T = 1/f.', 'Wavefront: a line joining matching points, such as the crests of ripples.'] },
        { h: 'The wave equation', p: ['In one period T the wave moves forward one wavelength λ. So its speed is λ/T, which is fλ. The speed is usually set by the medium; the frequency is set by the source.'], eq: R`v = f\lambda,\qquad T = \frac1f` },
        { h: 'Transverse and longitudinal', p: ['In a transverse wave the oscillations are at right angles to the direction the wave travels: light and all electromagnetic waves, ripples on water, waves on a rope, seismic S-waves.', 'In a longitudinal wave the oscillations are along the direction of travel, making compressions and rarefactions: sound, and seismic P-waves.'] },
        { h: 'Reflection, refraction and diffraction', p: ['A ripple tank shows all three. Waves reflect from a straight barrier at the same angle they arrive. Waves passing into shallower water slow down; their frequency cannot change, so their wavelength shortens, and if they meet the boundary at an angle their direction changes: refraction.', 'Waves spread out after passing through a gap or around an edge: diffraction. The spreading is greatest when the gap is about the same size as the wavelength; through a gap much wider than the wavelength the waves pass almost straight on.'] },
        { h: 'Why gap size matters', p: ['Sound has wavelengths of about a metre, similar to a doorway, so you hear people round corners. Light has wavelengths of about half a millionth of a metre, so it hardly diffracts at a doorway and you cannot see round it. Long-wave radio (wavelengths over a kilometre) bends round hills; FM radio and TV (a few metres or less) need a clearer line of sight.'], warn: '**What a wave model hides.** v = fλ assumes the speed does not depend on frequency. That is true for sound in air and light in a vacuum, but not for light in glass (which is why prisms split colours) or for water waves in deep water (long waves travel faster). And “waves carry no matter” is an average: water particles move in near-circles and drift slightly forward, the Stokes drift.' }
      ],
      eqs: [[R`v = f\lambda`, 'speed in m/s, frequency in Hz, wavelength in m'], [R`T = 1/f`, 'period in s'], [R`c = 3.0\times10^8\ \text{m/s}`, 'speed of all electromagnetic waves in a vacuum']],
      how: ['Read λ from crest to crest on a diagram, or divide a total length by the number of waves in it.', 'Use v = fλ; when a wave enters a new medium, keep f and change v and λ.', 'For diffraction, compare the gap or obstacle with the wavelength.'],
      sum: ['Waves transfer energy, not matter.', 'v = fλ and T = 1/f.', 'Transverse: oscillation ⟂ travel. Longitudinal: oscillation ∥ travel.', 'Refraction: speed change, same frequency, new wavelength and direction.', 'Diffraction is greatest when the gap is about one wavelength.'],
      probs: [
        { l: 1, q: 'A wave has a frequency of 5.0 Hz and a wavelength of 0.40 m. What is its speed?', a: '2.0 m/s', s: ['v = fλ = 5.0 × 0.40 = 2.0 m/s.'] },
        { l: 1, q: 'What is the period of a 50 Hz wave?', a: '0.020 s', s: ['T = 1/f = 1/50 = 0.020 s.'] },
        { l: 1, q: 'Classify as transverse or longitudinal: light, sound, ripples on water, seismic P-waves, seismic S-waves.', a: 'Transverse: light, ripples, S-waves. Longitudinal: sound, P-waves.', s: ['Ask whether the medium moves across or along the direction of travel.'] },
        { l: 2, q: 'A long-wave radio station broadcasts at 198 kHz. What is its wavelength? (c = 3.0 × 10⁸ m/s)', a: 'About 1500 m', s: ['λ = c/f = 3.0 × 10⁸ ÷ 1.98 × 10⁵ = 1520 m.'] },
        { l: 2, q: 'In a ripple tank, 10 wavefronts span 15 cm and the dipper vibrates at 12 Hz. Find the speed. In shallower water the speed falls to 12 cm/s. What is the new wavelength?', a: '18 cm/s; 1.0 cm', s: ['λ = 15 ÷ 10 = 1.5 cm; v = 12 × 1.5 = 18 cm/s.', 'The frequency stays 12 Hz: λ = 12 ÷ 12 = 1.0 cm.'] },
        { l: 2, q: 'Why can you hear someone talking round a corner but not see them?', a: 'Sound’s wavelength is similar to a doorway; light’s is far smaller', s: ['Sound (λ ≈ 1 m) diffracts strongly through a doorway.', 'Light (λ ≈ 5 × 10⁻⁷ m) barely diffracts at all through a gap that wide.'] },
        { l: 2, q: 'A rope is shaken 3 times a second, and 6 complete waves fit along 4.8 m of it. Find the wavelength and the speed.', a: '0.80 m; 2.4 m/s', s: ['λ = 4.8 ÷ 6 = 0.80 m.', 'v = 3 × 0.80 = 2.4 m/s.'] },
        { l: 2, q: 'If the hand shaking the rope moves further, doubling the amplitude but keeping the frequency, what happens to the speed, wavelength and energy carried?', a: 'Speed and wavelength unchanged; energy four times larger', s: ['The speed is set by the rope; the frequency is unchanged, so λ is unchanged.', 'The energy carried is proportional to the amplitude squared: 2² = 4 times.'] },
        { l: 3, q: 'Straight ripples travelling at 20 cm/s meet a boundary with shallower water at 40° (between the wave’s direction and the normal). In the shallow water they travel at 15 cm/s. Using sin r ÷ sin i = v₂ ÷ v₁, find their new direction. Why do they bend?', a: 'About 29° to the normal', s: ['sin r = (15 ÷ 20) × sin 40° = 0.482, so r = 29°.', 'The part of each wavefront that reaches the shallow water first slows first, while the rest keeps going faster, so the wavefront swings round towards the boundary.'] },
        { l: 3, q: 'Explain why long-wave radio (λ ≈ 1500 m) can be received in a deep valley while FM radio (λ ≈ 3 m) often cannot.', a: 'Long waves diffract around hills; short waves do not', s: ['A hill is hundreds of metres across: comparable to the long-wave wavelength, so those waves diffract over and around it.', 'For 3 m waves the hill is hundreds of wavelengths wide, so they hardly bend and leave a “shadow”: FM needs line of sight or a local transmitter.'] }
      ]
    },

    'gcse-reflection-refraction': {
      big: 'Light reflects from a mirror at the same angle it arrives, and bends when it crosses into a material where it travels at a different speed. Going from glass into air, it bends away from the normal, and beyond a critical angle it cannot get out at all: it is totally reflected. That trap is what carries light, and the internet, along optical fibres.',
      sec: [
        { h: 'Reflection', p: ['Angles are measured from the normal, a line at right angles to the surface. The law of reflection: the angle of incidence equals the angle of reflection, and both rays lie in the same plane as the normal.', 'The image in a plane mirror is the same size as the object, upright, as far behind the mirror as the object is in front, and laterally inverted (left and right swapped). It is virtual: the light only seems to come from behind the mirror, so the image cannot be caught on a screen.'] },
        { h: 'Refraction', p: ['Light slows down when it passes from air into glass or water. If it arrives at an angle, it bends towards the normal; leaving the glass it speeds up and bends away from the normal. A ray along the normal goes straight through, though it still changes speed.', 'The refractive index n measures how strongly a material bends light. Glass is about 1.5, water 1.33 and diamond 2.42.'], eq: R`n = \frac{\sin i}{\sin r}\qquad(\text{light passing from air into the material})` },
        { h: 'Critical angle and total internal reflection', p: ['Light going from glass to air bends away from the normal. As the angle inside the glass increases, the refracted ray bends ever closer to the surface; at the critical angle c it skims along the surface. Beyond c no light escapes: all of it reflects back inside. This is total internal reflection.', 'It needs two conditions: light travelling from the denser material (higher n) towards the less dense one, and an angle of incidence greater than the critical angle.'], eq: R`n = \frac{1}{\sin c}` },
        { h: 'Optical fibres', p: ['An optical fibre is a thin glass core surrounded by cladding of slightly lower refractive index. Light entering one end hits the core–cladding boundary above the critical angle every time, so it is trapped and follows the fibre round gentle bends.', 'Fibres carry telephone and internet signals as pulses of infrared light, and doctors use bundles of them in endoscopes to see inside the body. Prisms with 45° angles use total internal reflection in periscopes and binoculars, because 45° is more than glass’s 42° critical angle.'], warn: '**One index, one critical angle? Not quite.** The refractive index depends on colour (wavelength): that is dispersion, which splits white light into a spectrum, and it means each colour has a slightly different critical angle. In fibres, different colours and different zigzag paths arrive at slightly different times, smearing pulses and limiting the data rate. Glass also absorbs a little: the best fibres lose about 4% of the light per kilometre, which is why long links need amplifiers.' }
      ],
      eqs: [[R`i = r`, 'law of reflection, angles from the normal'], [R`n = \frac{\sin i}{\sin r}`, 'refractive index (air into material)'], [R`n = \frac{1}{\sin c}`, 'critical angle'], [R`n = \frac{c}{v}`, 'extension: speed of light in the material']],
      how: ['Draw the normal first; measure every angle from it.', 'Entering a denser material: bend towards the normal. Leaving: away.', 'For total internal reflection, check the direction (dense to less dense) and compare i with c.', 'Use n = sin i/sin r with i in air and r in the material.'],
      sum: ['Reflection: i = r; plane-mirror images are virtual, upright, same size, same distance behind.', 'Refraction: light changes speed and bends at an angled boundary.', 'n = sin i ÷ sin r.', 'Critical angle: n = 1/sin c; beyond it, total internal reflection.', 'Optical fibres and prisms use total internal reflection.'],
      probs: [
        { l: 1, q: 'A ray hits a plane mirror at 35° to the normal. What is the angle of reflection?', a: '35°', s: ['The angle of reflection equals the angle of incidence.'] },
        { l: 1, q: 'Describe the image formed by a plane mirror.', a: 'Virtual, upright, same size, laterally inverted, as far behind as the object is in front', s: ['It cannot be projected on a screen because no light actually reaches the image position.'] },
        { l: 1, q: 'A ray passes at an angle from air into glass. Which way does it bend, and why?', a: 'Towards the normal, because it slows down', s: ['Light travels more slowly in glass than in air.'] },
        { l: 2, q: 'A ray enters a glass block with an angle of incidence of 40° and is refracted at 25°. Find the refractive index.', a: '1.52', s: ['n = sin 40° ÷ sin 25° = 0.643 ÷ 0.423 = 1.52.'] },
        { l: 2, q: 'Find the critical angle for glass of refractive index 1.50.', a: '41.8°', s: ['sin c = 1/1.50 = 0.667, so c = 41.8°.'] },
        { l: 2, q: 'Light in water (n = 1.33) hits the surface at 55° to the normal. Does it escape into the air?', a: 'No: it is totally internally reflected', s: ['sin c = 1/1.33 = 0.752, so c = 48.8°.', '55° > 48.8°, so none of the light refracts out.'] },
        { l: 2, q: 'Using n = c/v, how fast does light travel in glass of refractive index 1.50?', a: '2.0 × 10⁸ m/s', s: ['v = 3.0 × 10⁸ ÷ 1.50 = 2.0 × 10⁸ m/s.'] },
        { l: 2, q: 'You stand 1.5 m in front of a plane mirror. How far are you from your image? You walk 0.5 m towards the mirror; how much closer to you is your image?', a: '3.0 m; 1.0 m closer', s: ['The image is 1.5 m behind the mirror: 3.0 m from you.', 'Now you are 1.0 m from the mirror and the image 1.0 m behind it: 2.0 m apart, 1.0 m closer than before.'] },
        { l: 3, q: 'Light enters a right-angled glass prism (n = 1.50) at right angles to one short face and hits the long face at 45°. What happens there, and where is this used?', a: 'Total internal reflection: periscopes and binoculars', s: ['Entering along the normal, the ray does not bend.', '45° is greater than the critical angle (41.8°), so the light reflects totally and turns through 90°.', 'Unlike a silvered mirror, nothing is absorbed by a metal coating, and the reflecting surface cannot tarnish.'] },
        { l: 3, q: 'An optical fibre has a core of refractive index 1.48 and cladding of 1.46. Find the critical angle at the core–cladding boundary (sin c = n_{cladding} ÷ n_{core}). What is the cladding for, given that bare glass in air would have a smaller critical angle?', a: 'About 81°; it protects the core surface', s: ['sin c = 1.46 ÷ 1.48 = 0.986, so c = 80.6°: light must travel within about 9° of the fibre’s axis.', 'Bare glass would trap more light, but any scratch, dirt or contact on its surface would let light leak out.', 'The cladding keeps the reflecting boundary clean and protected; it also limits the spread of path lengths, which keeps pulses sharp.'] }
      ]
    },

    'gcse-lenses': {
      big: 'A lens bends light by refraction at its curved surfaces. A converging (convex) lens brings parallel rays together at a focus and can project real images onto a screen, as in cameras, projectors and your eye. A diverging (concave) lens spreads rays apart. Three simple rays are enough to find any image.',
      sec: [
        { h: 'Focus and focal length', p: ['Rays parallel to the principal axis (the line through the centre of the lens at right angles to it) pass through a converging lens and meet at one point: the principal focus F. The distance from the centre of the lens to F is the focal length f. A fatter, more curved lens has a shorter focal length: it is more powerful.', 'For a diverging lens, parallel rays spread out as if they had come from a principal focus on the near side of the lens.'] },
        { h: 'Ray diagrams', list: ['A ray parallel to the axis refracts through F on the far side.', 'A ray through the centre of the lens passes straight on.', 'A ray through F on the near side emerges parallel to the axis.'], p: ['Draw rays from the top of the object. Where they cross after the lens, the top of the image forms, and any two of these three rays are enough:'] },
        { h: 'Real and virtual images', p: ['A real image forms where light rays actually meet; it can be caught on a screen and is upside down. A virtual image forms where rays only seem to come from; it cannot be caught on a screen.', 'For a converging lens, an object further away than F gives a real, inverted image. Beyond 2F the image is smaller (camera, eye); at 2F it is the same size; between F and 2F it is bigger and further away (projector).'] },
        { h: 'The magnifying glass', p: ['Put the object closer to a converging lens than its focal length. The rays leave the lens still spreading, and your eye traces them back to a virtual, upright, magnified image on the same side as the object.'], eq: R`\text{magnification} = \frac{\text{image height}}{\text{object height}}` },
        { h: 'Correcting eyesight', p: ['A short-sighted eye focuses distant objects in front of the retina (the eye is too strong for its length). A diverging lens spreads the rays a little first, moving the focus back onto the retina.', 'A long-sighted eye cannot bend light from nearby objects enough, so it would focus behind the retina. A converging lens adds extra bending.'], box: '**Extension (A level preview):** the thin-lens equation 1/f = 1/u + 1/v links object distance u and image distance v for a converging lens; a negative v means a virtual image on the same side as the object. Lens power in dioptres is 1/f with f in metres.', warn: '**What the ray rules assume.** The three rules are exact only for thin lenses and rays close to the axis. Real lenses focus rays near their edges at a slightly different point (spherical aberration) and focus different colours at different points (chromatic aberration), which blurs images and gives coloured fringes. Camera lenses combine several elements to cancel these errors.' }
      ],
      eqs: [[R`m = \frac{h_{\text{image}}}{h_{\text{object}}}`, 'magnification'], [R`\frac1f = \frac1u + \frac1v`, 'extension: thin converging lens (virtual image if v < 0)'], [R`P = \frac{1}{f}`, 'extension: lens power in dioptres (f in m)']],
      how: ['Draw the axis, the lens and F on both sides at the right scale.', 'Draw two of the three standard rays from the top of the object.', 'If the rays meet after the lens, the image is real; if they only seem to meet when traced back, it is virtual.', 'State the image’s nature: real or virtual, upright or inverted, magnified or diminished, and where it is.'],
      sum: ['Converging lenses focus parallel rays at F; diverging lenses spread them.', 'Three rays: parallel → through F; through centre undeviated; through F → parallel.', 'Object beyond F: real, inverted image. Object inside F: virtual, upright, magnified.', 'Short sight: diverging lens. Long sight: converging lens.', 'Real images can be projected; virtual ones cannot.'],
      probs: [
        { l: 1, q: 'Define the principal focus and the focal length of a converging lens.', a: 'The point where parallel rays meet; its distance from the lens centre', s: ['Rays parallel to the principal axis converge to the principal focus F; the focal length is the distance from the centre of the lens to F.'] },
        { l: 1, q: 'Which type of lens corrects short sight?', a: 'A diverging lens', s: ['It spreads the rays slightly so the eye focuses them further back, on the retina.'] },
        { l: 1, q: 'What is the difference between a real image and a virtual image?', a: 'A real image is where rays actually meet and can be put on a screen; a virtual image cannot', s: ['Virtual images are seen only by looking into the lens or mirror.'] },
        { l: 2, q: 'An object stands 20 cm from a converging lens of focal length 10 cm. Describe the image.', a: 'Real, inverted, same size, 20 cm on the other side', s: ['The object is at 2F, so the image is at 2F on the other side, inverted and the same size.'] },
        { l: 2, q: 'The object moves to 15 cm from the same lens (between F and 2F). How does the image change? Name a device that uses this.', a: 'Real, inverted, magnified, beyond 2F: a projector', s: ['Moving the object towards F moves the image further away and makes it larger (here 30 cm away, twice the size).'] },
        { l: 2, q: 'A camera lens forms an image of a distant tree. Describe the image.', a: 'Real, inverted, diminished, just beyond F', s: ['Objects far beyond 2F give small real images close to the focal plane, where the sensor sits.'] },
        { l: 2, q: 'A stamp is held 6.0 cm from a magnifying glass of focal length 10 cm. Using 1/f = 1/u + 1/v, find where the image is and its magnification.', a: 'Virtual, 15 cm from the lens on the stamp’s side; 2.5 times larger', s: ['1/v = 1/10 − 1/6.0 = −1/15, so v = −15 cm (negative: virtual, same side).', 'Magnification = 15 ÷ 6.0 = 2.5, upright.'] },
        { l: 2, q: 'Explain what goes wrong in a long-sighted eye and how a lens corrects it.', a: 'Near objects focus behind the retina; a converging lens adds bending', s: ['The eye’s lens cannot become strong enough (or the eyeball is too short) for nearby objects.', 'A converging spectacle lens starts the rays converging so the eye can finish the job on the retina.'] },
        { l: 3, q: 'An object is 30 cm from a converging lens of focal length 10 cm. Find the image distance and the magnification, and check with a ray diagram.', a: '15 cm; 0.5 (half size, inverted, real)', s: ['1/v = 1/10 − 1/30 = 2/30, so v = 15 cm.', 'm = v/u = 15 ÷ 30 = 0.5.', 'The object is beyond 2F, so the image lies between F and 2F, smaller and inverted: consistent.'] },
        { l: 3, q: 'A short-sighted person can see clearly only up to 2.0 m away. What lens makes very distant objects appear to be 2.0 m away, and what is its power?', a: 'A diverging lens of focal length 2.0 m: −0.5 dioptres', s: ['Parallel rays from a distant object must leave the lens as if from a point 2.0 m in front: the principal focus of a diverging lens.', 'So f = −2.0 m and the power is 1/f = −0.5 D (written −0.50 on a prescription).'] }
      ]
    },

    'gcse-sound': {
      big: 'Sound is a longitudinal wave: a vibrating object pushes and pulls on the particles next to it, sending out a pattern of compressions and rarefactions. It needs a medium, travels about 340 m/s in air and much faster in liquids and solids, and reflects as echoes. Above 20 000 Hz we cannot hear it, but ultrasound lets us map the sea floor and see unborn babies.',
      sec: [
        { h: 'How sound travels', p: ['A loudspeaker cone moving forward squashes the air in front of it (a compression); moving back, it leaves a region of lower pressure (a rarefaction). These pass from particle to particle away from the source. Each air particle only oscillates back and forth along the direction of travel: sound is longitudinal.', 'With no particles there is nothing to pass the vibration on: an electric bell in a jar goes silent as the air is pumped out, though you can still see the hammer moving.'] },
        { h: 'Speed of sound', p: ['In air sound travels at about 330–350 m/s, depending on temperature. It is faster in liquids (about 1500 m/s in water) and faster still in solids (about 5000 m/s in steel), because the particles are linked more stiffly.', 'To measure it in air: stand a long way (say 200 m) from someone who makes a loud bang with a visible action; time from seeing it to hearing it, or use two microphones a measured distance apart and a fast timer. Speed = distance ÷ time.'] },
        { h: 'Pitch, loudness and range', p: ['A higher frequency means a higher pitch. A larger amplitude means a louder sound. Young people hear roughly 20 Hz to 20 000 Hz; the upper limit falls with age.'] },
        { h: 'Echoes', p: ['An echo is reflected sound. The echo travels to the reflector and back, so the distance to it is half of speed × time. Soft furnishings absorb sound and reduce echoes; hard, smooth walls reflect well.'], eq: R`\text{distance} = \frac{v\,t}{2}` },
        { h: 'Ultrasound', p: ['Ultrasound is sound above 20 kHz. Its short wavelength gives fine detail. Ships use it in sonar and echo-sounding to find the depth of the sea and shoals of fish. Doctors use pulses of it to image organs and unborn babies: echoes from each boundary between tissues build up the picture, without the ionising radiation of X-rays. Engineers use it to find hidden cracks in metal.'], warn: '**Hidden assumptions.** The echo formula assumes a constant speed along the whole path. In the sea, sound speed changes with temperature, salt and depth, which bends sonar paths; in the body, tissues range from about 1450 m/s (fat) to over 3000 m/s (bone), and scanners assume 1540 m/s everywhere, so depths are slightly off. The speed of sound in air depends on temperature (about 331 + 0.6θ m/s for θ in °C), not on air pressure.' }
      ],
      eqs: [[R`v = \frac{d}{t}`, 'speed of sound from a measured distance and time'], [R`d = \frac{vt}{2}`, 'distance to a reflector from the echo time'], [R`v = f\lambda`, 'wave equation, as for all waves'], [R`20\ \text{Hz} \text{ to } 20\ \text{kHz}`, 'approximate human hearing range']],
      how: ['Check whether the time is one way or there and back (echoes: halve it).', 'Use the right speed for the medium: about 340 m/s in air, 1500 m/s in water.', 'For pitch questions, think frequency; for loudness, amplitude.', 'For measurements, consider reaction time and make the distance large.'],
      sum: ['Sound is a longitudinal wave of compressions and rarefactions.', 'It needs a medium; it cannot cross a vacuum.', 'Air ~340 m/s, water ~1500 m/s, steel ~5000 m/s.', 'Pitch ↔ frequency; loudness ↔ amplitude; hearing 20 Hz–20 kHz.', 'Echo distance = vt/2; ultrasound (> 20 kHz) for sonar and scanning.'],
      probs: [
        { l: 1, q: 'You hear thunder 3.0 s after seeing the lightning. Roughly how far away was the strike? (Sound: 340 m/s)', a: 'About 1.0 km', s: ['Light arrives almost instantly, so d = 340 × 3.0 = 1020 m.'] },
        { l: 1, q: 'Why can’t sound travel through a vacuum?', a: 'There are no particles to pass on the vibrations', s: ['Sound is a mechanical wave carried by the oscillation of particles.'] },
        { l: 1, q: 'Which has the higher pitch, a 256 Hz note or a 512 Hz note?', a: '512 Hz', s: ['Higher frequency means higher pitch (512 Hz is one octave higher).'] },
        { l: 2, q: 'A shout echoes from a cliff after 1.6 s. How far away is the cliff?', a: '272 m', s: ['The sound travels 340 × 1.6 = 544 m there and back.', 'Distance = 544 ÷ 2 = 272 m.'] },
        { l: 2, q: 'A ship’s echo-sounder pulse returns from the sea bed after 0.80 s. How deep is the sea? (Sound in water: 1500 m/s)', a: '600 m', s: ['d = vt/2 = 1500 × 0.80 ÷ 2 = 600 m.'] },
        { l: 2, q: 'What are the wavelengths in air of the lowest (20 Hz) and highest (20 kHz) sounds humans can hear?', a: '17 m and 1.7 cm', s: ['λ = v/f = 340 ÷ 20 = 17 m.', 'λ = 340 ÷ 20 000 = 0.017 m.'] },
        { l: 2, q: 'Students 200 m apart time a starting pistol from flash to bang and get 0.60 s. What speed does this give, and why is it unreliable? How could they improve it?', a: '333 m/s; reaction time is large compared with 0.60 s', s: ['v = 200 ÷ 0.60 = 333 m/s.', 'A reaction time of about 0.2 s is a third of the measurement.', 'Increase the distance, repeat many times and average, or use two microphones and an electronic timer.'] },
        { l: 2, q: 'An ultrasound pulse reflects from a boundary 6.0 cm deep in the body. How long after the pulse is sent does its echo return? (Use 1540 m/s.)', a: '78 μs', s: ['Path = 2 × 0.060 = 0.12 m.', 't = 0.12 ÷ 1540 = 7.8 × 10⁻⁵ s = 78 μs. Scanners time thousands of such echoes every second.'] },
        { l: 3, q: 'Someone strikes one end of a 1.0 km steel rail. You listen at the other end and hear two bangs. Explain why, and find the time between them. (Steel: 5000 m/s; air: 340 m/s)', a: 'Through the steel first, then through the air: 2.7 s apart', s: ['Through steel: 1000 ÷ 5000 = 0.20 s.', 'Through air: 1000 ÷ 340 = 2.94 s.', 'Gap = 2.74 s.'] },
        { l: 3, q: 'A 680 Hz note travels in air at 340 m/s. Find its wavelength and the distance between a compression and the nearest rarefaction. The sound enters water (1500 m/s): what happens to its frequency and wavelength?', a: '0.50 m; 0.25 m; frequency stays 680 Hz, wavelength becomes 2.2 m', s: ['λ = 340 ÷ 680 = 0.50 m.', 'A compression and the next rarefaction are half a wavelength apart: 0.25 m.', 'The source sets the frequency, so it stays 680 Hz; λ = 1500 ÷ 680 = 2.2 m.'] }
      ]
    }
  });
})();
/* ---- notes-gcse4.js ---- */
/* Geodesic: notes and ten-problem sets for GCSE outline topics, part 3 (IGCSE 0625 sections 4.2–4.5). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'gcse-static': {
      big: 'Rubbing two materials together moves electrons from one to the other, leaving one negatively charged and the other positive. Like charges repel and unlike charges attract. Around every charge is an electric field, the region where other charges feel a force, and its pattern of field lines shows which way a positive charge would be pushed.',
      sec: [
        { h: 'Two kinds of charge', p: ['There are two kinds of electric charge, positive and negative. Like charges repel; unlike charges attract. Atoms contain positive protons in the nucleus and negative electrons around it; normally the numbers are equal and the atom is neutral.', 'Charge is measured in coulombs (C). One electron carries −1.6 × 10⁻¹⁹ C, so a coulomb is a huge amount of static charge: everyday static charges are nanocoulombs to microcoulombs.'] },
        { h: 'Charging by friction', p: ['When two insulators are rubbed together, electrons move from one surface to the other. Only electrons move; the positive charges are locked in the nuclei. A polythene rod rubbed with a cloth gains electrons and becomes negative, while the cloth is left positive. An acetate rod loses electrons to the cloth and becomes positive.', 'Charge is never created, only moved: the rod and cloth end up with equal and opposite charges.'] },
        { h: 'Conductors and insulators', p: ['In metals some electrons are free to move through the material, so charge flows easily: metals are conductors. In insulators such as plastic, rubber and glass the electrons are bound to their atoms, so charge stays where it is put.', 'That is why you can charge a plastic rod by rubbing it but not a metal rod held in your hand: charge on the metal flows away through you to earth. A charged object attracts small uncharged pieces of paper because it pulls opposite charge to the near side of each piece (induction), and the nearer charge is attracted more strongly than the further one is repelled.'] },
        { h: 'Electric fields', p: ['An electric field is a region in which a charge experiences a force. The direction of the field at a point is the direction of the force on a small positive charge placed there. Field lines start on positive charges and end on negative charges; where they are closer together, the field is stronger.', 'Around an isolated point charge the lines are radial: outwards from a positive charge, inwards to a negative one. Between two parallel oppositely charged plates the lines are straight, parallel and evenly spaced: a uniform field (except near the edges).'] },
        { h: 'Static at work and as a danger', list: ['Photocopiers and laser printers use charged drums to pick up toner in the pattern of the image.', 'Electrostatic paint sprays give droplets the same charge so they spread out evenly, and charge the object oppositely so paint wraps round onto its back.', 'Fuel flowing through pipes can charge up a tanker; a spark could ignite the vapour, so tankers are earthed before refuelling.', 'Lightning is a giant discharge between charged clouds and the ground.'], warn: '**Rubbing is not quite the point.** Charging happens on contact; rubbing just makes more contact. Which material gains electrons follows an experimental ranking (the triboelectric series), and results change with humidity and surface dirt: damp air lets charge leak away, which is why static is worse in dry winter weather. Dry air also breaks down and sparks at fields of about 3 million volts per metre, so a 1 cm spark from a door handle means tens of thousands of volts, though very little charge.' }
      ],
      eqs: [[R`e = 1.6\times10^{-19}\ \text{C}`, 'size of the charge on one electron'], [R`Q = n e`, 'charge carried by n electrons'], [R`E = \frac{V}{d}`, 'extension (A level): uniform field between plates a distance d apart']],
      how: ['Explain charging only by movement of electrons.', 'Like charges repel, unlike attract; neutral objects are attracted by induction.', 'Draw field lines from + to −, closer together where the field is stronger.', 'For danger questions, think about sparks igniting fuel and how earthing removes the charge.'],
      sum: ['Like charges repel; unlike charges attract.', 'Friction charging moves electrons only; charges are equal and opposite.', 'Conductors let charge move; insulators hold it in place.', 'Field direction = force on a positive charge; lines from + to −.', 'Radial field round a point charge; uniform field between parallel plates.'],
      probs: [
        { l: 1, q: 'A polythene rod becomes negatively charged when rubbed with a cloth. Explain what happened, and what charge the cloth has.', a: 'Electrons moved from the cloth to the rod; the cloth is positive', s: ['Only electrons move. The rod gained extra electrons; the cloth lost the same number.'] },
        { l: 1, q: 'Two balloons are both negatively charged. What happens when they are brought close together?', a: 'They repel', s: ['Like charges repel.'] },
        { l: 1, q: 'Why can a plastic rod be charged by rubbing, but not a metal rod held in your hand?', a: 'Charge flows away through the metal and your body', s: ['Metals are conductors and you are connected to earth, so any charge leaks away.'] },
        { l: 2, q: 'A sphere carries a charge of −3.2 nC. How many extra electrons does it have?', a: '2.0 × 10¹⁰', s: ['n = Q/e = 3.2 × 10⁻⁹ ÷ 1.6 × 10⁻¹⁹ = 2.0 × 10¹⁰.'] },
        { l: 2, q: 'Describe the electric field pattern around an isolated positive point charge, and between two parallel plates with opposite charges.', a: 'Radial lines pointing outwards; parallel, evenly spaced lines from + to −', s: ['The point-charge field weakens with distance, shown by the lines spreading apart.', 'Between plates the field is uniform: same strength and direction everywhere except near the edges.'] },
        { l: 2, q: 'A balloon charged by rubbing sticks to an uncharged wall. Explain why.', a: 'It induces opposite charge on the wall’s surface, which attracts it', s: ['The negative balloon repels electrons in the wall’s surface slightly away, leaving the nearest region slightly positive.', 'The attraction to that nearby positive charge is stronger than the repulsion from the more distant negative charge.'] },
        { l: 2, q: 'Why must a fuel tanker be connected to earth with a cable before it unloads fuel?', a: 'To stop charge building up and causing a spark that could ignite the fuel', s: ['Fuel rubbing on pipes can charge the tanker.', 'The earth cable lets the charge flow away safely instead of jumping as a spark through flammable vapour.'] },
        { l: 2, q: 'In electrostatic spray painting, the paint droplets are all given the same charge and the car panel is given the opposite charge. Explain both choices.', a: 'Droplets repel into an even spray; the panel attracts them, even onto hidden surfaces', s: ['Like charges repel, so droplets spread out evenly rather than clumping.', 'The opposite charge on the panel pulls droplets onto it, including round edges, so less paint is wasted.'] },
        { l: 3, q: 'Two parallel plates 5.0 mm apart are connected to 1500 V. Using E = V/d, find the field between them and the force on an electron there.', a: '3.0 × 10⁵ V/m; 4.8 × 10⁻¹⁴ N', s: ['E = 1500 ÷ 0.0050 = 3.0 × 10⁵ V/m (equivalently N/C).', 'F = eE = 1.6 × 10⁻¹⁹ × 3.0 × 10⁵ = 4.8 × 10⁻¹⁴ N, towards the positive plate.'] },
        { l: 3, q: 'Dry air breaks down at about 3 × 10⁶ V/m. A 5 mm spark jumps from your finger to a door handle. Roughly what potential difference was there? Why does it hurt but not harm you?', a: 'About 15 000 V; the charge, and so the energy, is tiny', s: ['V ≈ Ed = 3 × 10⁶ × 0.005 = 15 000 V.', 'Only a few microcoulombs flow, for a fraction of a microsecond, so the energy is well under a joule.', 'Danger depends on the current through the body and how long it lasts, not on the voltage alone.'] }
      ]
    },

    'gcse-current-pd': {
      big: 'An electric current is a flow of charge, measured by how many coulombs pass a point each second. A cell or battery gives each coulomb energy, its e.m.f.; components such as lamps take that energy back, and the potential difference across them measures how much each coulomb hands over. Volts are joules per coulomb.',
      sec: [
        { h: 'Current', p: ['Current is the rate of flow of charge. One ampere is one coulomb per second. In metal wires the moving charges are free electrons, drifting from the negative terminal round to the positive. By an old convention, current is drawn flowing the other way, from + to −: conventional current.'], eq: R`I = \frac{Q}{t}` },
        { h: 'Measuring current', p: ['An ammeter measures current. It goes in series, in the loop itself, so that the current flows through it; a good ammeter has a very low resistance so it barely changes the current. Analogue meters have a needle and scale; digital meters show a number.'] },
        { h: 'Direct and alternating current', p: ['Direct current (d.c.) flows one way only, like the current from a cell. Alternating current (a.c.) repeatedly reverses direction; mains electricity in the UK reverses 50 times a second (50 Hz).'] },
        { h: 'e.m.f. and potential difference', p: ['The electromotive force (e.m.f.) of a source is the energy it gives each coulomb of charge that it drives round a complete circuit. A 1.5 V cell gives 1.5 J to every coulomb.', 'The potential difference (p.d.) across a component is the energy each coulomb transfers to it as it passes through. Round a series circuit the p.d.s add up to the e.m.f.: the energy given is all handed over.', 'Both are measured in volts with a voltmeter, connected in parallel across the component (or source). A good voltmeter has a very high resistance so it draws almost no current.'], eq: R`E = \frac{W}{Q},\qquad V = \frac{W}{Q}` },
        { h: 'How fast does electricity travel?', p: ['The electrons themselves drift very slowly, typically a fraction of a millimetre per second in a household wire. Yet a lamp lights the instant you press the switch, because the wire is already full of electrons: the push that sets them moving travels along the wire at a large fraction of the speed of light.'], warn: '**Calling e.m.f. a “force” is a historical slip.** It is energy per unit charge, not a force. And a real battery’s e.m.f. is not all delivered to the circuit: some energy per coulomb is wasted heating the battery itself (internal resistance), so the p.d. across its terminals drops when it supplies a large current. That is why car headlights dim while the starter motor runs.' }
      ],
      eqs: [[R`I = Q/t`, 'current in A, charge in C, time in s'], [R`E = W/Q`, 'e.m.f.: energy given per coulomb (V = J/C)'], [R`V = W/Q`, 'p.d.: energy transferred per coulomb'], [R`Q = ne`, 'charge from a number of electrons, e = 1.6 × 10⁻¹⁹ C']],
      how: ['Turn minutes and hours into seconds before using I = Q/t.', 'Ammeters in series, voltmeters in parallel.', 'Read volts as “joules per coulomb” to set up energy problems.', 'Round a series loop, the p.d.s add up to the e.m.f.'],
      sum: ['Current = charge per second; 1 A = 1 C/s.', 'Electrons flow − to +; conventional current is drawn + to −.', 'd.c. flows one way; a.c. reverses (50 Hz mains).', 'e.m.f. = energy given per coulomb; p.d. = energy transferred per coulomb.', 'Ammeters in series (low resistance), voltmeters in parallel (high resistance).'],
      probs: [
        { l: 1, q: '4.0 C of charge flows past a point in 2.0 s. What is the current?', a: '2.0 A', s: ['I = Q/t = 4.0 ÷ 2.0 = 2.0 A.'] },
        { l: 1, q: 'How are an ammeter and a voltmeter connected to measure the current through, and the p.d. across, a lamp?', a: 'Ammeter in series with the lamp; voltmeter in parallel across it', s: ['The current must flow through the ammeter; the voltmeter compares the two ends of the lamp.'] },
        { l: 1, q: 'What is the difference between a.c. and d.c.? Give one source of each.', a: 'd.c. flows one way (a cell); a.c. reverses repeatedly (the mains)', s: ['UK mains reverses direction 50 times per second.'] },
        { l: 2, q: 'A current of 0.25 A flows for 2.0 minutes. How much charge passes, and how many electrons is that?', a: '30 C; 1.9 × 10²⁰ electrons', s: ['Q = It = 0.25 × 120 = 30 C.', 'n = 30 ÷ 1.6 × 10⁻¹⁹ = 1.9 × 10²⁰.'] },
        { l: 2, q: 'A 12 V battery drives 5.0 C of charge round a circuit. How much energy does it supply?', a: '60 J', s: ['W = EQ = 12 × 5.0 = 60 J.'] },
        { l: 2, q: 'The p.d. across a lamp is 3.0 V and it transfers 120 J of energy. How much charge passed through it?', a: '40 C', s: ['Q = W/V = 120 ÷ 3.0 = 40 C.'] },
        { l: 2, q: 'A battery of e.m.f. 9.0 V drives current through two lamps in series. The p.d. across one lamp is 5.5 V. What is the p.d. across the other (ignoring the battery’s internal resistance)?', a: '3.5 V', s: ['The p.d.s round a series loop add to the e.m.f.: 9.0 − 5.5 = 3.5 V.'] },
        { l: 2, q: 'In which direction do electrons move through a lamp connected to a cell, and in which direction is the conventional current drawn?', a: 'Electrons: from the cell’s negative terminal round to its positive. Conventional current: the reverse.', s: ['The convention (+ to −) was fixed before electrons were discovered; the physics works either way if you are consistent.'] },
        { l: 3, q: 'A battery of e.m.f. 9.0 V gives a terminal p.d. of 8.0 V while supplying 0.50 A. For each second, find the energy the battery’s chemistry supplies, the energy delivered to the circuit, and the energy wasted inside the battery.', a: '4.5 J; 4.0 J; 0.5 J', s: ['Each second 0.50 C flows.', 'Supplied: 9.0 × 0.50 = 4.5 J. Delivered: 8.0 × 0.50 = 4.0 J.', 'The missing 0.5 J heats the battery: each coulomb loses 1.0 J inside it.'] },
        { l: 3, q: 'A phone battery is rated 3.7 V and 4000 mAh (it can deliver 4000 mA for one hour). How much charge does it hold, and how much energy?', a: '14 400 C; about 53 kJ', s: ['Q = It = 4.0 A × 3600 s = 14 400 C.', 'W = EQ = 3.7 × 14 400 = 53 000 J (about 15 watt-hours).'] }
      ]
    },

    'gcse-power-cost': {
      big: 'Electrical power is the rate of transferring energy, and it is simply current times voltage. Multiply by time and you have the energy. Electricity companies bill in kilowatt-hours, the energy a 1 kW appliance uses in one hour, so working out a bill takes one multiplication.',
      sec: [
        { h: 'Power = current × voltage', p: ['Each coulomb passing through a component transfers V joules, and I coulombs pass each second. So the energy transferred per second, the power, is IV watts.'], eq: R`P = IV` },
        { h: 'Energy = power × time', p: ['Over a time t, the energy transferred is the power multiplied by the time.'], eq: R`E = IVt = Pt` },
        { h: 'The kilowatt-hour', p: ['The joule is tiny for household use, so electricity is sold in kilowatt-hours (kWh): the energy transferred by a 1 kW appliance in 1 hour. One kWh is 1000 W × 3600 s = 3 600 000 J.', 'To find the cost, work out the energy in kWh (power in kW × time in hours) and multiply by the price per kWh.'], eq: R`1\ \text{kWh} = 3.6\times10^6\ \text{J},\qquad \text{cost} = \text{energy (kWh)} \times \text{price per kWh}` },
        { h: 'Other forms of the power equation', p: ['Combining P = IV with V = IR gives P = I²R and P = V²/R. P = I²R is the heating in a wire: double the current and the heating goes up four times. That is why power is transmitted at high voltage and low current, and why thick cables are used for high-power appliances.'], eq: R`P = I^2R = \frac{V^2}{R}` },
        { h: 'Reading a power rating', p: ['An appliance marked “230 V, 2.3 kW” draws 10 A when connected to 230 V mains. The rating assumes that voltage: run the same heater on a lower supply and its power falls (as V²/R, if its resistance stays fixed).'], warn: '**Hidden assumptions in P = V²/R.** It assumes the resistance stays the same, but a filament lamp’s resistance rises about tenfold as it heats from room temperature to 2500 °C, so its power at switch-on is far higher than its rating, which is when old bulbs usually failed. For a.c. mains, V and I mean r.m.s. values: 230 V r.m.s. peaks at about 325 V.' }
      ],
      eqs: [[R`P = IV`, 'power in W'], [R`E = IVt = Pt`, 'energy in J (with P in W and t in s)'], [R`E\,(\text{kWh}) = P\,(\text{kW}) \times t\,(\text{h})`, 'energy for billing'], [R`1\ \text{kWh} = 3.6\ \text{MJ}`, 'conversion'], [R`P = I^2R = V^2/R`, 'useful combinations with V = IR']],
      how: ['For joules, use watts and seconds; for kWh, use kilowatts and hours.', 'Find the current an appliance draws with I = P/V.', 'Cost = kWh × price; check the units of the price (pence or pounds).', 'For heating in wires, think P = I²R.'],
      sum: ['P = IV; E = IVt.', '1 kWh = 3.6 MJ: a 1 kW appliance for 1 hour.', 'Cost = kWh used × price per kWh.', 'P = I²R: wire heating grows with the square of the current.', 'Ratings assume the stated voltage.'],
      probs: [
        { l: 1, q: 'A kettle draws 10 A from the 230 V mains. What is its power?', a: '2300 W (2.3 kW)', s: ['P = IV = 10 × 230 = 2300 W.'] },
        { l: 1, q: 'How much energy, in kWh, does a 2.0 kW heater use in 3.0 hours?', a: '6.0 kWh', s: ['E = 2.0 kW × 3.0 h = 6.0 kWh.'] },
        { l: 1, q: 'Electricity costs 30p per kWh. What does the heater in the previous question cost to run for those 3.0 hours?', a: '£1.80', s: ['6.0 × 30p = 180p = £1.80.'] },
        { l: 2, q: 'A 12 V lamp is rated 36 W. What current does it draw, and what is its resistance when lit?', a: '3.0 A; 4.0 Ω', s: ['I = P/V = 36 ÷ 12 = 3.0 A.', 'R = V/I = 12 ÷ 3.0 = 4.0 Ω.'] },
        { l: 2, q: 'A motor draws 0.50 A from a 6.0 V supply for 10 minutes. How much energy does it transfer?', a: '1800 J', s: ['E = IVt = 0.50 × 6.0 × 600 = 1800 J.'] },
        { l: 2, q: 'A television uses 1.0 W on standby. If it is on standby 20 hours a day, how much energy does that use in a year, and what does it cost at 30p per kWh?', a: '7.3 kWh; about £2.20', s: ['E = 0.0010 kW × 20 h × 365 = 7.3 kWh.', 'Cost = 7.3 × 30p = 219p ≈ £2.20.'] },
        { l: 2, q: 'Show that 1 kWh = 3.6 MJ.', a: '1000 W × 3600 s = 3 600 000 J', s: ['1 kW = 1000 J/s and 1 h = 3600 s.', 'E = Pt = 1000 × 3600 = 3.6 × 10⁶ J.'] },
        { l: 2, q: 'A heater draws 8.0 A through a cable of resistance 0.50 Ω. How much power is wasted heating the cable? What would it be at 16 A?', a: '32 W; 128 W', s: ['P = I²R = 64 × 0.50 = 32 W.', 'At 16 A: 256 × 0.50 = 128 W, four times as much for twice the current.'] },
        { l: 3, q: 'An 8 W LED lamp gives the same light as a 60 W filament lamp. Both are used 5 hours a day for a year. How much money does the LED save at 30p per kWh? If it costs £3, how long does it take to pay for itself?', a: 'About £28 a year; about 6 weeks', s: ['Power saved = 52 W = 0.052 kW.', 'Energy saved = 0.052 × 5 × 365 = 94.9 kWh, worth 94.9 × 30p = £28.47 a year.', '£3 ÷ £28.47 per year ≈ 0.105 years, about 5–6 weeks.'] },
        { l: 3, q: 'A 9.5 kW electric shower heats water from 12 °C to 40 °C. Water needs 4200 J to warm 1 kg by 1 °C. What flow rate can it deliver, and what does a 10-minute shower cost at 30p per kWh?', a: 'About 4.8 litres per minute; about 48p', s: ['Each kilogram needs 4200 × 28 = 117 600 J.', 'Mass per second = 9500 ÷ 117 600 = 0.081 kg/s = 4.8 L/min.', 'Energy in 10 min = 9.5 kW × (1/6) h = 1.58 kWh, costing 1.58 × 30p ≈ 48p.'] }
      ]
    },

    'gcse-series-parallel': {
      big: 'Components can be connected one after another (series) or side by side (parallel). In series the same current flows through everything and the voltage is shared; in parallel each branch gets the full voltage and the current is shared. Splitting a voltage with two resistors, a potential divider, is how sensors turn light or temperature into a signal.',
      sec: [
        { h: 'Series circuits', p: ['In a series circuit there is only one path, so the current is the same everywhere. The supply’s e.m.f. is shared between the components: their p.d.s add up to it. Resistances in series add, so adding components makes the total resistance bigger and the current smaller. If one lamp breaks, the circuit is broken and all go out.', 'Cells in series add their e.m.f.s (if they face the same way).'], eq: R`R_{\text{total}} = R_1 + R_2 + \cdots` },
        { h: 'Parallel circuits', p: ['In parallel each branch is connected directly across the supply, so each gets the same p.d. The current splits at junctions: the total current entering a junction equals the total leaving it, because charge cannot pile up.', 'Adding a branch gives the current another path, so the total resistance falls: two resistors in parallel always have less resistance than either one alone. Houses are wired in parallel so each appliance gets the full mains voltage and can be switched on and off independently.'], eq: R`\frac{1}{R_{\text{total}}} = \frac{1}{R_1} + \frac{1}{R_2}` },
        { h: 'Potential dividers', p: ['Two resistors in series across a supply share the voltage in proportion to their resistances: the bigger resistor gets the bigger share. Taking the output across one of them gives a chosen fraction of the input voltage.', 'Replacing one resistor with a variable resistor, a light-dependent resistor (LDR) or a thermistor makes the output change with a knob, with light, or with temperature. An LDR’s resistance falls in bright light; a thermistor’s (NTC type) falls as it gets hotter.'], eq: R`V_{\text{out}} = V_{\text{in}}\frac{R_2}{R_1 + R_2},\qquad \frac{V_1}{V_2} = \frac{R_1}{R_2}` },
        { h: 'Diodes and LEDs', p: ['A diode lets current flow in one direction only and blocks it in the other. A light-emitting diode (LED) is a diode that glows when current flows through it the right way. Diodes are used to turn a.c. into d.c. (rectification) and to protect circuits from batteries put in backwards.'] },
        { h: 'Why parallel resistance is smaller', p: ['Both branches have the same p.d. V. Total current I = I₁ + I₂ = V/R₁ + V/R₂. Dividing by V gives 1/R = 1/R₁ + 1/R₂. More paths means more current for the same push: a smaller total resistance.'], warn: '**Ideal assumptions.** These rules treat wires as resistance-free, meters as perfect (ammeters with zero resistance, voltmeters with infinite resistance) and the supply’s e.m.f. as fully available. A real voltmeter connected across a large resistor in a potential divider draws current and lowers the very voltage it measures, and a real battery’s internal resistance means its terminal p.d. drops as you add parallel branches.' }
      ],
      eqs: [[R`R = R_1 + R_2`, 'series resistance'], [R`1/R = 1/R_1 + 1/R_2`, 'parallel resistance'], [R`I_{\text{in}} = I_{\text{out}}`, 'junction rule (conservation of charge)'], [R`V_{\text{out}} = V_{\text{in}}\,R_2/(R_1+R_2)`, 'potential divider'], [R`V = IR`, 'for each resistor']],
      how: ['Simplify: combine parallel groups first, then add series parts.', 'Find the total current from the supply, then work back to each branch.', 'In parallel, every branch has the full p.d.; in series, the p.d.s add up.', 'For sensors, decide whether the resistance rises or falls, then which resistor gets the bigger share of the voltage.'],
      sum: ['Series: same current; p.d.s add; R = R₁ + R₂.', 'Parallel: same p.d.; currents add; 1/R = 1/R₁ + 1/R₂ (smaller than either).', 'Junction rule: current in = current out.', 'Potential divider: bigger resistor, bigger share of the voltage.', 'LDR: resistance falls with light. Thermistor: falls with temperature. Diode: one way only.'],
      probs: [
        { l: 1, q: 'Resistors of 4.0 Ω and 6.0 Ω are in series with a 12 V supply. Find the total resistance, the current and the p.d. across each.', a: '10 Ω; 1.2 A; 4.8 V and 7.2 V', s: ['R = 4.0 + 6.0 = 10 Ω; I = 12 ÷ 10 = 1.2 A.', 'V₁ = 1.2 × 4.0 = 4.8 V; V₂ = 1.2 × 6.0 = 7.2 V (they add to 12 V).'] },
        { l: 1, q: '0.80 A flows into a junction. One branch carries 0.30 A. What does the other carry?', a: '0.50 A', s: ['Current in = current out: 0.80 − 0.30 = 0.50 A.'] },
        { l: 1, q: 'Give two reasons why the lights in a house are connected in parallel.', a: 'Each gets the full mains voltage, and each can be switched (or fail) independently', s: ['In series the voltage would be shared and one broken lamp would turn them all off.'] },
        { l: 2, q: 'Resistors of 6.0 Ω and 3.0 Ω are connected in parallel to a 6.0 V supply. Find the combined resistance and the current in each branch and from the supply.', a: '2.0 Ω; 1.0 A and 2.0 A; 3.0 A', s: ['1/R = 1/6 + 1/3 = 1/2, so R = 2.0 Ω.', 'Each has 6.0 V across it: 6.0 ÷ 6.0 = 1.0 A and 6.0 ÷ 3.0 = 2.0 A.', 'Total = 3.0 A = 6.0 ÷ 2.0, as it should.'] },
        { l: 2, q: 'A potential divider has R₁ = 2.0 kΩ and R₂ = 1.0 kΩ across 9.0 V. What is the p.d. across R₂?', a: '3.0 V', s: ['V_{out} = 9.0 × 1.0 ÷ (2.0 + 1.0) = 3.0 V.'] },
        { l: 2, q: 'An LDR and a fixed resistor form a potential divider across a supply. The output is taken across the LDR. What happens to the output as it gets dark, and how could this switch on a night light?', a: 'The output rises', s: ['In the dark the LDR’s resistance rises, so it takes a larger share of the supply voltage.', 'A rising output can switch on a transistor or relay that lights a lamp.'] },
        { l: 2, q: 'Three 1.5 V cells are connected in series. What is the total e.m.f.? What is it if one cell is put in backwards?', a: '4.5 V; 1.5 V', s: ['Same direction: 1.5 + 1.5 + 1.5 = 4.5 V.', 'One reversed subtracts: 1.5 + 1.5 − 1.5 = 1.5 V.'] },
        { l: 2, q: 'A 4.0 Ω resistor is in series with a parallel pair of 6.0 Ω and 12 Ω, across a 12 V supply. Find the total resistance, the supply current and the current in the 6.0 Ω resistor.', a: '8.0 Ω; 1.5 A; 1.0 A', s: ['Parallel pair: 1/R = 1/6 + 1/12 = 3/12, so R = 4.0 Ω.', 'Total = 4.0 + 4.0 = 8.0 Ω; I = 12 ÷ 8.0 = 1.5 A.', 'P.d. across the pair = 1.5 × 4.0 = 6.0 V; current in 6.0 Ω = 1.0 A (and 0.5 A in 12 Ω).'] },
        { l: 3, q: 'A thermistor (5.0 kΩ at 20 °C, 1.0 kΩ at 60 °C) is in series with a 2.0 kΩ resistor across 6.0 V. The output is taken across the fixed resistor. Find the output at both temperatures. Could it trigger an alarm that needs more than 3.0 V?', a: '1.7 V at 20 °C; 4.0 V at 60 °C: yes, when hot', s: ['20 °C: V_{out} = 6.0 × 2.0 ÷ (5.0 + 2.0) = 1.7 V.', '60 °C: 6.0 × 2.0 ÷ (1.0 + 2.0) = 4.0 V.', 'So the alarm triggers somewhere between, as the thermistor heats up: a simple fire or overheating alarm.'] },
        { l: 3, q: 'Derive 1/R = 1/R₁ + 1/R₂ for two resistors in parallel, and show that the combined resistance is always smaller than either one.', a: 'From I = I₁ + I₂ with the same V', s: ['Same p.d. V across each: I₁ = V/R₁, I₂ = V/R₂.', 'I = V/R₁ + V/R₂ = V(1/R₁ + 1/R₂), and I = V/R, so 1/R = 1/R₁ + 1/R₂.', '1/R is bigger than 1/R₁ alone (and than 1/R₂ alone), so R is smaller than each.'] }
      ]
    },

    'gcse-safety': {
      big: 'Mains electricity can kill, so plugs, cables and appliances are built with layers of protection. The live wire carries the dangerous voltage, the neutral completes the circuit and the earth wire gives fault currents a safe path. Fuses and circuit breakers cut the supply when the current gets too large, and double insulation keeps the live parts out of reach.',
      sec: [
        { h: 'Hazards', list: ['Damaged insulation: bare wires can be touched, giving a shock, or can short-circuit and start a fire.', 'Overheating cables: too much current for the cable’s thickness, often from overloading sockets and extension leads.', 'Damp conditions: water conducts, so it can carry current from live parts to people.', 'Excess current from a fault, which can melt insulation and cause fires.'] },
        { h: 'Live, neutral and earth', p: ['A UK mains supply is about 230 V a.c. at 50 Hz. The live wire (brown) alternates between large positive and negative voltages; the neutral wire (blue) stays close to 0 V and completes the circuit; the earth wire (green and yellow) is connected to the ground and normally carries no current.', 'Switches and fuses are always fitted in the live wire, so that when they are off or blown the appliance is disconnected from the dangerous voltage.'] },
        { h: 'Fuses and trip switches', p: ['A fuse contains a thin wire that melts if the current exceeds its rating, breaking the circuit. Choose the lowest standard rating (3 A, 5 A or 13 A in UK plugs) that is above the appliance’s normal current, found from I = P/V.', 'A trip switch (circuit breaker) does the same job with an electromagnet or bimetallic strip that opens a switch. It acts faster and can be reset instead of replaced.'] },
        { h: 'Earthing and double insulation', p: ['If a fault connects the live wire to an appliance’s metal case, anyone touching the case would get a shock. With the case earthed, a large current flows straight down the low-resistance earth wire instead, which blows the fuse or trips the breaker and disconnects the live supply.', 'Appliances with plastic outer cases that cannot conduct are double insulated: no live part can touch anything you can reach, so they need no earth wire (the symbol is a square inside a square).'] },
        { h: 'Protecting people, not just wiring', p: ['A residual current device (RCD) compares the currents in the live and neutral wires. They should be equal; if they differ by more than about 30 mA, current must be leaking somewhere (possibly through a person), and the RCD cuts the supply, typically within a few hundredths of a second.'], warn: '**A fuse does not protect you.** A 13 A fuse needs amperes to melt, but a current of a few tens of milliamps through the chest can stop the heart. Fuses and breakers protect cables and appliances from overheating; RCDs and good insulation protect people. The 230 V figure is also an r.m.s. value: the live wire actually peaks at about 325 V.' }
      ],
      eqs: [[R`I = P/V`, 'normal current, to choose a fuse'], [R`P = I^2R`, 'heating in a cable carrying current I'], [R`230\ \text{V},\ 50\ \text{Hz}`, 'UK mains supply']],
      how: ['Find the normal current with I = P/V.', 'Pick the smallest fuse rating above that current.', 'Trace what happens in a fault: where does the current go, and what stops it?', 'Distinguish protecting equipment (fuses, breakers) from protecting people (RCDs, insulation, earthing).'],
      sum: ['Live (brown), neutral (blue), earth (green/yellow).', 'Fuses and switches go in the live wire.', 'Fuse rating: just above the normal current.', 'Earthed metal cases send fault current to earth and blow the fuse.', 'Double-insulated appliances need no earth; RCDs protect people.'],
      probs: [
        { l: 1, q: 'Give the colours of the live, neutral and earth wires in a UK plug.', a: 'Brown, blue, green and yellow', s: ['Live: brown. Neutral: blue. Earth: green and yellow stripes.'] },
        { l: 1, q: 'Why is the fuse placed in the live wire rather than the neutral?', a: 'So a blown fuse disconnects the appliance from the dangerous voltage', s: ['A fuse in the neutral would stop the current but leave the appliance connected to the live wire.'] },
        { l: 1, q: 'Name three electrical hazards in the home.', a: 'Damaged insulation, overloaded sockets or cables, water near electricity', s: ['Each can lead to shocks or fires.'] },
        { l: 2, q: 'Choose a fuse (3 A, 5 A or 13 A) for a 60 W lamp, a 1.2 kW iron and a 2.8 kW kettle on 230 V mains.', a: '3 A; 13 A; 13 A', s: ['Lamp: 60 ÷ 230 = 0.26 A → 3 A.', 'Iron: 1200 ÷ 230 = 5.2 A, more than 5 A → 13 A.', 'Kettle: 2800 ÷ 230 = 12.2 A → 13 A.'] },
        { l: 2, q: 'The live wire inside a toaster comes loose and touches its metal case. Explain how the earth wire and the fuse make it safe.', a: 'A large current flows to earth and blows the fuse', s: ['The earth wire connects the case to the ground through a very low resistance.', 'A large current flows from live, through the case, to earth.', 'That current melts the fuse, disconnecting the live supply before anyone touches the case.'] },
        { l: 2, q: 'Why does a hairdryer with a plastic case not need an earth wire?', a: 'It is double insulated: no live part can touch an outer surface you can reach', s: ['The plastic case does not conduct, so a loose wire cannot make it live.'] },
        { l: 2, q: 'A 3.0 kW heater, a 2.0 kW kettle and a 0.5 kW toaster are all plugged into one extension lead rated at 13 A. What current do they draw together on 230 V, and why is this dangerous?', a: 'About 24 A: the lead overheats', s: ['Total power 5.5 kW: I = 5500 ÷ 230 = 23.9 A.', 'That is nearly twice the rating, so the cable heats up (P = I²R), the insulation can melt and a fire can start.'] },
        { l: 2, q: 'Give two advantages of a trip switch over a fuse.', a: 'It acts faster and can be reset', s: ['No replacement fuse is needed, and it cuts off quickly, reducing damage.'] },
        { l: 3, q: 'A person touching a live wire while standing on damp ground carries 40 mA to earth. Would a 13 A fuse blow? What would a 30 mA RCD do, and why?', a: 'No; the RCD trips', s: ['40 mA is far below 13 A, so the fuse is unaffected.', 'The 40 mA leaving through the person does not return through the neutral, so live and neutral currents differ by 40 mA.', 'That exceeds 30 mA, so the RCD cuts the supply, typically within a few hundredths of a second: quickly enough to make survival likely.'] },
        { l: 3, q: 'A cooker draws 40 A along a 10 m cable. A thick cable has a resistance of 0.10 Ω; a thinner one 0.30 Ω. How much power is wasted heating each cable, and why are high-power appliances given their own thick cables?', a: '160 W and 480 W', s: ['P = I²R = 40² × 0.10 = 160 W.', 'Thinner: 40² × 0.30 = 480 W, concentrated in a cable that could overheat dangerously.', 'Thicker cables have lower resistance, so less heating for the same current.'] }
      ]
    },

    'gcse-electromagnets': {
      big: 'An electric current makes a magnetic field. Around a straight wire the field lines are circles; wind the wire into a coil (a solenoid) and the field becomes like a bar magnet’s, strong and uniform inside. Add an iron core and you have an electromagnet: a magnet you can switch on and off.',
      sec: [
        { h: 'Field around a straight wire', p: ['The magnetic field around a long straight current-carrying wire is a set of concentric circles centred on the wire. The field is stronger closer to the wire and with a larger current; reversing the current reverses the field’s direction.', 'Right-hand grip rule: point your right thumb along the conventional current and your fingers curl in the direction of the field.'] },
        { h: 'The solenoid', p: ['A long coil of wire (a solenoid) has a field like a bar magnet’s outside, with north and south poles at its ends. Inside, the field is strong and nearly uniform: parallel, evenly spaced lines along the axis.', 'Looking at one end: if the current flows anticlockwise, that end is a north pole; clockwise, a south pole. (Or grip the coil with your right hand, fingers along the current: your thumb points to north.)'] },
        { h: 'Making it stronger', list: ['Increase the current.', 'Increase the number of turns (more turns per unit length).', 'Add a soft iron core, which becomes strongly magnetised and multiplies the field many times over.'], p: ['Soft iron is used because it magnetises easily and loses its magnetism as soon as the current stops; steel would stay magnetised.'] },
        { h: 'Uses', list: ['Scrapyard cranes: lift steel, then drop it by switching off.', 'Relays: a small current in a coil attracts an iron armature that closes a separate switch in a high-current circuit, as in a car’s starter motor.', 'Electric bells: the electromagnet pulls a hammer, which breaks the circuit, so the hammer springs back and remakes it, over and over.', 'MRI scanners and particle accelerators use superconducting electromagnets for very strong fields.'], warn: '**Iron does not multiply without limit.** An iron core boosts the field hundreds or thousands of times, but only until the iron saturates at around 2 tesla; beyond that, extra current helps only as much as an air core would. Real “long solenoid” formulas also assume the coil is much longer than it is wide; short coils have weaker, less uniform fields inside.' }
      ],
      eqs: [[R`B = \frac{\mu_0 I}{2\pi r}`, 'extension: field near a long straight wire'], [R`B = \mu_0 n I`, 'extension: field inside a long solenoid (n = turns per metre)'], [R`\mu_0 = 4\pi\times10^{-7}\ \text{T m/A}`, 'permeability of free space']],
      how: ['Use the right-hand grip rule for direction around a wire.', 'For a solenoid, find which end is north from the current direction seen end-on.', 'To strengthen: more current, more turns, iron core.', 'For devices, trace the sequence: current on → core magnetised → iron part attracted → effect.'],
      sum: ['Current creates a magnetic field; reverse the current, reverse the field.', 'Straight wire: circular field lines, stronger closer and with more current.', 'Solenoid: bar-magnet field outside, strong uniform field inside.', 'Stronger electromagnet: more current, more turns, soft iron core.', 'Uses: cranes, relays, bells, MRI.'],
      probs: [
        { l: 1, q: 'Describe the magnetic field around a long straight wire carrying a current.', a: 'Concentric circles centred on the wire', s: ['Closer to the wire the circles are closer together: the field is stronger.'] },
        { l: 1, q: 'Give three ways to make an electromagnet stronger.', a: 'More current, more turns, a soft iron core', s: ['Each increases the field inside the coil.'] },
        { l: 1, q: 'Why is the core of an electromagnet made of soft iron and not steel?', a: 'Soft iron loses its magnetism when the current is switched off', s: ['Steel would stay magnetised, so the electromagnet could not be switched off properly.'] },
        { l: 2, q: 'A vertical wire carries a current upwards, towards you, as you look down on it from above. Which way does the field circle, seen from above?', a: 'Anticlockwise', s: ['Right thumb pointing up towards you: your fingers curl anticlockwise as you see them.'] },
        { l: 2, q: 'Looking at one end of a solenoid, you see the current flowing clockwise. Is that end a north or a south pole?', a: 'South', s: ['Clockwise current seen end-on: south pole. Anticlockwise: north.'] },
        { l: 2, q: 'Explain how a relay lets a small current switch on a large current, as in a car starter motor.', a: 'The small current magnetises a coil that pulls a switch closed in a separate circuit', s: ['Turning the key sends a small current through the relay coil.', 'The electromagnet attracts an iron armature, closing contacts in the thick-wired starter circuit.', 'The ignition switch never carries the hundreds of amps the starter motor needs.'] },
        { l: 2, q: 'Explain how an electric bell keeps ringing while its button is pressed.', a: 'A make-and-break contact switches the electromagnet on and off repeatedly', s: ['Current magnetises the coil, which pulls the iron armature and hammer towards it, striking the gong.', 'This movement opens a contact, breaking the circuit; the magnetism stops and a spring pulls the armature back.', 'That closes the contact again, and the cycle repeats many times a second.'] },
        { l: 2, q: 'Why does a scrapyard crane use an electromagnet rather than a permanent magnet?', a: 'It can be switched off to drop the load', s: ['A permanent magnet could pick up the steel but never let go of it.'] },
        { l: 3, q: 'Using B = μ₀I/(2πr), find the magnetic field 5.0 cm from a wire carrying 10 A. Compare it with Earth’s field, about 5 × 10⁻⁵ T. Why can large currents upset a compass?', a: '4.0 × 10⁻⁵ T: about the same as Earth’s field', s: ['B = 4π × 10⁻⁷ × 10 ÷ (2π × 0.050) = 4.0 × 10⁻⁵ T.', 'That is comparable with Earth’s field, so a compass near the wire points somewhere between the two field directions.'] },
        { l: 3, q: 'A solenoid has 500 turns over 0.25 m and carries 2.0 A. Using B = μ₀nI, find the field inside. Roughly what does a soft iron core do to it, and what limits that?', a: '5.0 × 10⁻³ T; the core can raise it hundreds of times, up to about 2 T', s: ['n = 500 ÷ 0.25 = 2000 turns per metre.', 'B = 4π × 10⁻⁷ × 2000 × 2.0 = 5.0 × 10⁻³ T.', 'The iron becomes magnetised and adds its own field, many times larger, until it saturates at about 2 T.'] }
      ]
    },

    'gcse-motor': {
      big: 'A current-carrying wire in a magnetic field feels a force. Bend the wire into a coil and the forces on its two sides point opposite ways, so the coil turns. A split-ring commutator reverses the current every half-turn, which keeps the coil turning the same way: that is the d.c. motor, in everything from toys to electric cars.',
      sec: [
        { h: 'Force on a wire in a field', p: ['A wire carrying a current at right angles to a magnetic field feels a force at right angles to both. Fleming’s left-hand rule gives the direction: First finger along the Field (north to south), seCond finger along the Current, and the thuMb points along the Motion (force). Reversing either the current or the field reverses the force.'] },
        { h: 'Why a coil turns', p: ['Place a rectangular coil between the poles of a magnet. Current flows one way along one side and the opposite way along the other, so the forces on the two sides point in opposite directions, one up and one down. Being on opposite sides of the axle, they make a turning effect (a couple).', 'The turning effect is largest when the coil’s plane is parallel to the field, because then the forces act furthest from the axle. When the coil is at right angles to the field, the forces pull straight outwards in line with the axle and the turning effect is zero.'] },
        { h: 'The split-ring commutator', p: ['If the current always flowed the same way round the coil, the forces would turn it to the vertical position and then pull it back: it would just rock. The split-ring commutator, two half-rings attached to the coil, swaps the coil’s connections to the supply every half-turn, just as the coil passes the vertical. The current in each side reverses, so the force on whichever side is on the left always points the same way, and the coil keeps turning.', 'Carbon brushes press against the rotating commutator, keeping the electrical contact while it spins. The coil’s momentum carries it past the vertical position where the turning effect is momentarily zero.'] },
        { h: 'Making it turn faster or harder', list: ['Increase the current.', 'Use more turns of wire on the coil.', 'Use a stronger magnet.', 'Use a larger coil (more area), so the forces act further from the axle.'], p: ['Practical motors also wind several coils at different angles onto a soft iron core, giving a smoother, stronger turning effect with no “dead” position.'] },
        { h: 'Motors are also generators', p: ['A spinning coil in a magnetic field has an e.m.f. induced in it. In a running motor this “back e.m.f.” opposes the supply, so the current is large when the motor starts and falls once it is up to speed. A motor that jams draws its full starting current and can overheat.'], warn: '**Idealisations in the textbook motor.** The simple picture assumes a uniform field and ignores the resistance of the coil, friction in the bearings and the back e.m.f. Real motors are designed around the back e.m.f.: it is what limits their speed and makes their efficiency high (often above 90% for large motors), because current only flows strongly when the motor is doing work against a load.' }
      ],
      eqs: [[R`F = BIL`, 'extension: force on a length L of wire at right angles to a field B'], [R`\tau_{\max} = N B I A`, 'extension: largest torque on a coil of N turns and area A'], [R`I = \frac{V - E_{\text{back}}}{R}`, 'extension: current in a running motor']],
      how: ['Use Fleming’s left-hand rule for the force on each side of the coil.', 'Check the forces on opposite sides point opposite ways: a turning effect.', 'Explain the commutator by what would happen without it (rocking about the vertical).', 'List the factors: current, turns, field strength, coil area.'],
      sum: ['A current in a magnetic field feels a force: Fleming’s left-hand rule.', 'Opposite forces on opposite sides of a coil make it turn.', 'Turning effect largest when the coil is parallel to the field, zero at right angles.', 'The split-ring commutator reverses the current every half-turn; brushes keep contact.', 'Faster: more current, more turns, stronger magnet, bigger coil.'],
      probs: [
        { l: 1, q: 'Give three ways to make a simple d.c. motor turn faster.', a: 'More current, more turns, stronger magnet (or a larger coil)', s: ['Each increases the forces on the coil, or their turning effect.'] },
        { l: 1, q: 'What is the job of the brushes in a d.c. motor?', a: 'To keep electrical contact with the spinning commutator', s: ['They press against the rotating split ring, connecting it to the supply.'] },
        { l: 1, q: 'What happens to a d.c. motor if the battery is connected the other way round?', a: 'It turns the other way', s: ['Reversing the current reverses the forces on the coil.'] },
        { l: 2, q: 'Explain why the forces on the two long sides of a motor coil make it turn rather than just pushing it sideways.', a: 'The forces are equal, opposite and on opposite sides of the axle', s: ['The current flows in opposite directions along the two sides, so one is pushed up and the other down.', 'Equal and opposite forces cancel as a push, but acting on either side of the axle they form a turning couple.'] },
        { l: 2, q: 'At which position of the coil is the turning effect greatest, and where is it zero?', a: 'Greatest with the coil parallel to the field; zero at right angles to it', s: ['The forces are always vertical (for a horizontal field). Their perpendicular distance from the axle is largest when the coil is horizontal and zero when it is vertical.'] },
        { l: 2, q: 'Explain what would happen to a simple motor coil without a split-ring commutator.', a: 'It would turn to the vertical position and rock about it, not spin', s: ['With a fixed current direction, once the coil passes vertical the forces turn it back.', 'The commutator reverses the current at that moment, so the turning effect keeps the same sense.'] },
        { l: 2, q: 'A wire runs north–south between magnet poles, with the field pointing east. The current flows north. Which way is the force on the wire?', a: 'Vertically downwards', s: ['Point your left hand’s first finger east (field) and second finger north (current): the thumb points straight down.', 'Check: turn the current round to flow south and the force flips to upwards.'] },
        { l: 2, q: 'Why do practical motors have many coils wound at different angles on an iron core?', a: 'For a steady, stronger turning effect with no dead spot', s: ['At any instant some coil is near the position of maximum turning effect.', 'The iron core concentrates the magnetic field through the coils.'] },
        { l: 3, q: 'A 100-turn coil has sides 5.0 cm long in a 0.20 T field, carries 2.0 A, and is 4.0 cm wide. Using F = BIL for each wire, find the force on each long side and the largest turning moment.', a: '2.0 N per side; 0.080 N m', s: ['Per side: F = N × BIL = 100 × 0.20 × 2.0 × 0.050 = 2.0 N.', 'Each side is 0.020 m from the axle, so the largest moment = 2 × 2.0 × 0.020 = 0.080 N m.'] },
        { l: 3, q: 'A 12 V motor has a coil resistance of 2.0 Ω. What current does it draw at the instant it starts? When running, it generates a back e.m.f. of 10 V; what current does it draw then? Why does a jammed motor overheat?', a: '6.0 A at start; 1.0 A running', s: ['At rest there is no back e.m.f.: I = 12 ÷ 2.0 = 6.0 A.', 'Running: I = (12 − 10) ÷ 2.0 = 1.0 A.', 'A jammed motor has no back e.m.f., so it keeps drawing 6.0 A and heats its coil at I²R = 72 W.'] }
      ]
    }
  });
})();
/* ---- notes-gcse5.js ---- */
/* Geodesic: notes and ten-problem sets for GCSE outline topics, part 4 (IGCSE 0625 sections 4.5, 5 and 6). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'gcse-induction': {
      big: 'Move a wire through a magnetic field, or change the field through a coil, and an e.m.f. appears. That is electromagnetic induction, discovered by Faraday in 1831, and it generates almost all the world’s electricity. The induced current always pushes back against the change that causes it, which is just energy conservation in disguise.',
      sec: [
        { h: 'Inducing an e.m.f.', p: ['Push a magnet into a coil connected to a sensitive meter and the needle flicks; hold it still and the needle returns to zero; pull it out and the needle flicks the other way. An e.m.f. is induced only while the magnetic field through the coil is changing, or while a wire is cutting through field lines.', 'If the coil is part of a complete circuit, the e.m.f. drives an induced current.'] },
        { h: 'What makes it bigger', list: ['Moving the magnet or wire faster (changing the field more quickly).', 'Using a stronger magnet.', 'Using more turns on the coil (each turn adds its own e.m.f.).'], p: ['Reversing the direction of motion, or turning the magnet round, reverses the e.m.f.'] },
        { h: 'Lenz’s law: which way?', p: ['The induced current flows in the direction that opposes the change producing it. Push a north pole into a coil and the coil’s nearer end becomes a north pole, repelling the magnet; pull it out and that end becomes a south pole, attracting it back.', 'This has to be so. If the induced current helped the motion, the magnet would speed up and generate ever more energy from nothing. Instead, you must do work pushing against the opposition, and that work becomes the electrical energy.', 'For a straight wire, Fleming’s right-hand rule gives the direction: thuMb along the Motion, First finger along the Field, seCond finger along the induced Current.'] },
        { h: 'The a.c. generator', p: ['A coil rotating in a magnetic field cuts through field lines, so an alternating e.m.f. is induced. Slip rings (two complete rings, one on each end of the coil) and carbon brushes carry the current out without the wires twisting.', 'The e.m.f. is largest when the coil’s plane is parallel to the field (its sides cut the field lines fastest) and zero when the coil is at right angles to the field (its sides move along the lines). The output is a sine-shaped wave. Spinning faster increases both the peak e.m.f. and the frequency.'] },
        { h: 'Generators everywhere', p: ['Power-station turbines, wind turbines and bicycle dynamos all spin magnets and coils past each other. UK generators turn at speeds that produce exactly 50 Hz. A motor and a generator are the same machine: feed in current and it turns; turn it and it gives out current.'], warn: '**What the simple rules hide.** “E.m.f. only while the field changes” is Faraday’s law: the e.m.f. equals the rate of change of the magnetic flux linkage. The textbook generator assumes a uniform field and ignores the resistance and self-induction of the coil; real generators are designed so the output stays sinusoidal and stable under load, because the induced current in the coil also opposes the turbine (Lenz), so a generator gets harder to turn as more power is drawn.' }
      ],
      eqs: [[R`\mathcal{E} \propto N\,\frac{\Delta\Phi}{\Delta t}`, 'extension: Faraday’s law (rate of change of flux through N turns)'], [R`\mathcal{E} = BLv`, 'extension: wire of length L moving at speed v across a field B'], [R`f = \frac{\text{turns}}{\text{second}}`, 'frequency of a simple generator’s output']],
      how: ['Ask what is changing: is the wire cutting field lines, or is the field through the coil changing?', 'For size, think speed, field strength and number of turns.', 'For direction, apply Lenz’s law (opposes the change) or Fleming’s right-hand rule.', 'For generator graphs, peaks when the coil is parallel to the field, zeros when it is at right angles.'],
      sum: ['A changing field (or a wire cutting field lines) induces an e.m.f.', 'Bigger: faster, stronger magnet, more turns.', 'Lenz: the induced current opposes the change, so work must be done.', 'a.c. generator: rotating coil, slip rings and brushes, sine-wave output.', 'Faster rotation: higher peak e.m.f. and higher frequency.'],
      probs: [
        { l: 1, q: 'Give three ways to increase the e.m.f. induced by pushing a magnet into a coil.', a: 'Move it faster, use a stronger magnet, use more turns', s: ['Each makes the change in field linking the coil bigger or quicker.'] },
        { l: 1, q: 'A magnet is held still inside a coil. What does the meter read, and why?', a: 'Zero: the field is not changing', s: ['An e.m.f. is only induced while the field through the coil changes.'] },
        { l: 1, q: 'Name the parts of an a.c. generator that let the current leave the spinning coil.', a: 'Slip rings and brushes', s: ['The slip rings turn with the coil; the brushes press on them and stay still.'] },
        { l: 2, q: 'The north pole of a magnet is pushed into one end of a coil. Which pole forms at that end of the coil? What if the magnet is pulled out?', a: 'North when pushed in; south when pulled out', s: ['The induced current opposes the change: a north pole repels the approaching north pole.', 'Pulling out, a south pole forms to attract the magnet back.'] },
        { l: 2, q: 'Explain why Lenz’s law is a consequence of conservation of energy.', a: 'The opposing force means work must be done to generate electrical energy', s: ['If the induced current helped the motion, the magnet would accelerate and produce electrical energy for free.', 'Because it opposes, you must push, and your work becomes the electrical energy.'] },
        { l: 2, q: 'Sketch how the e.m.f. of an a.c. generator varies during one turn, starting with the coil at right angles to the field. Where are the peaks and zeros?', a: 'Zero at the start, peak a quarter-turn later, zero at half a turn, negative peak at three-quarters', s: ['At right angles to the field the sides move along the field lines: zero e.m.f.', 'Parallel to the field they cut the lines fastest: maximum e.m.f., with opposite signs on the two halves of the turn.'] },
        { l: 2, q: 'The generator is turned twice as fast. What happens to the peak e.m.f. and the frequency?', a: 'Both double', s: ['The field lines are cut twice as fast, doubling the e.m.f.; the coil completes twice as many turns per second.'] },
        { l: 2, q: 'A simple generator produces a 50 Hz output. How many times a second does its coil rotate, and what is the period of the output?', a: '50 times per second (3000 rpm); 0.020 s', s: ['One turn gives one complete cycle, so 50 turns per second.', 'T = 1/50 = 0.020 s.'] },
        { l: 3, q: 'A bar magnet falls through a coil connected to a data logger. The trace shows a pulse one way as it enters, then a pulse the other way as it leaves, and the second pulse is taller and shorter. Explain each feature.', a: 'Opposite signs from entering and leaving; the second is bigger and quicker because the magnet is falling faster', s: ['Entering, the field through the coil grows; leaving, it shrinks: opposite changes give opposite e.m.f.s (Lenz).', 'The magnet accelerates, so it leaves faster than it enters: the change is quicker, giving a larger e.m.f. for a shorter time.', 'The areas under the two pulses are about equal: the same total change in field, in opposite senses.'] },
        { l: 3, q: 'An aircraft with a 40 m wingspan flies at 250 m/s where the vertical part of Earth’s field is 4.0 × 10⁻⁵ T. Using E = BLv, find the e.m.f. between its wingtips. Why can’t this be used to power the plane’s lights?', a: '0.40 V; any wire loop on the plane has the same e.m.f. induced in it', s: ['E = 4.0 × 10⁻⁵ × 40 × 250 = 0.40 V.', 'A circuit connecting the wingtips would move with the plane, and its own wires would have the same e.m.f. induced in them, cancelling it. No current flows round the loop.'] }
      ]
    },

    'gcse-transformer': {
      big: 'A transformer changes the voltage of an alternating supply using two coils on an iron core and nothing that moves. The voltage ratio equals the turns ratio. Power stations use transformers to send electricity at hundreds of thousands of volts, because a high voltage means a low current, and a low current wastes far less energy heating the cables.',
      sec: [
        { h: 'How it works', p: ['An alternating current in the primary coil produces a constantly changing magnetic field. The soft iron core guides this changing field through the secondary coil, where it induces an alternating e.m.f.', 'With direct current the field would be steady, so nothing would be induced in the secondary (except a brief pulse when the current is switched on or off). Transformers only work with a.c.'] },
        { h: 'The turns ratio', p: ['Each turn of either coil has the same changing field through it, so each turn has the same e.m.f. induced in it. The voltages are therefore in the same ratio as the numbers of turns.', 'A step-up transformer has more turns on the secondary (higher output voltage); a step-down transformer has fewer.'], eq: R`\frac{V_p}{V_s} = \frac{N_p}{N_s}` },
        { h: 'Power in and power out', p: ['An ideal (100% efficient) transformer delivers all its input power: VpIp = VsIs. So stepping the voltage up steps the current down by the same factor. Real large transformers are about 98–99% efficient; the losses are heating in the coils’ resistance and in the core.'], eq: R`V_pI_p = V_sI_s` },
        { h: 'Why the grid uses high voltages', p: ['The power wasted heating a cable is P = I²R. For a given power to deliver, P = IV, so raising the voltage lowers the current. Raising the voltage 16 times cuts the current 16 times and the cable heating 256 times.', 'Power stations generate at around 25 kV, step up to 275 kV or 400 kV for the national grid, and step down in stages to 230 V for homes, which is far safer to have in a house.'], warn: '**Hidden assumptions.** VpIp = VsIs assumes no losses. In a real core, the changing field also induces swirling “eddy currents” in the iron, which heat it; cores are made from thin insulated sheets (laminations) to block them. And very high voltages bring their own losses and costs: insulators, tall pylons, and leakage (corona discharge) in damp air, so grid voltages are a compromise, not “as high as possible”.' }
      ],
      eqs: [[R`V_p/V_s = N_p/N_s`, 'voltage ratio = turns ratio'], [R`V_pI_p = V_sI_s`, '100% efficient transformer'], [R`P_{\text{loss}} = I^2R`, 'heating in transmission cables'], [R`I = P/V`, 'current needed to deliver power P at voltage V']],
      how: ['Use the turns ratio for voltages; check step-up or step-down makes sense.', 'Use VpIp = VsIs for currents (then allow for efficiency if given).', 'For transmission, find I = P/V first, then the loss I²R.', 'Remember: no a.c., no changing field, no output.'],
      sum: ['Primary a.c. → changing field in iron core → induced a.c. in secondary.', 'Vp/Vs = Np/Ns; more secondary turns = step-up.', 'Ideal: VpIp = VsIs, so higher voltage means lower current.', 'Cable loss P = I²R falls with the square of the current.', 'Transformers do not work with d.c.'],
      probs: [
        { l: 1, q: 'A transformer has 200 turns on the primary and 50 on the secondary. With 240 V a.c. on the primary, what is the secondary voltage? Is it step-up or step-down?', a: '60 V; step-down', s: ['Vs = Vp × Ns/Np = 240 × 50/200 = 60 V.'] },
        { l: 1, q: 'Why does a transformer not work with a steady d.c. supply?', a: 'The magnetic field would not change, so no e.m.f. would be induced', s: ['Induction needs a changing field through the secondary coil.'] },
        { l: 1, q: 'Why is the core made of soft iron?', a: 'It is easily magnetised and demagnetised, carrying the changing field from one coil to the other', s: ['It links almost all the primary’s field through the secondary and follows the a.c. changes readily.'] },
        { l: 2, q: 'A charger steps 230 V down to 5.0 V. The primary has 2300 turns. How many turns does the secondary need?', a: '50 turns', s: ['Ns = Np × Vs/Vp = 2300 × 5.0/230 = 50.'] },
        { l: 2, q: 'An ideal transformer takes 0.50 A from a 230 V supply and gives 11.5 V. What current does it supply?', a: '10 A', s: ['Power in = 230 × 0.50 = 115 W = power out.', 'Is = 115 ÷ 11.5 = 10 A.'] },
        { l: 2, q: 'A power station sends 100 MW through cables of total resistance 2.0 Ω. Compare the cable losses when the power is sent at 25 kV and at 400 kV.', a: '32 MW against 125 kW', s: ['At 25 kV: I = 10⁸ ÷ 25 000 = 4000 A; loss = 4000² × 2.0 = 3.2 × 10⁷ W.', 'At 400 kV: I = 250 A; loss = 250² × 2.0 = 1.25 × 10⁵ W.', '16 times the voltage, 256 times less loss.'] },
        { l: 2, q: 'Why is electricity stepped down again before it reaches homes?', a: 'For safety', s: ['400 kV would arc across gaps and need enormous insulation; 230 V can be handled safely with ordinary plugs and cables.'] },
        { l: 2, q: 'A doorbell transformer steps 230 V down to 8.0 V and has 4600 primary turns. How many secondary turns does it have?', a: '160 turns', s: ['Ns = 4600 × 8.0/230 = 160.'] },
        { l: 3, q: 'A 95%-efficient transformer takes 2.0 kW from the mains and gives 12 V. What current does it supply, and where does the missing energy go?', a: 'About 160 A; heating of the coils and core', s: ['Output power = 0.95 × 2000 = 1900 W.', 'Is = 1900 ÷ 12 = 158 A.', 'The other 100 W heats the coil wires (I²R) and the iron core (eddy currents and repeated magnetising).'] },
        { l: 3, q: 'Explain, using the idea that each turn has the same e.m.f. induced in it, why Vp/Vs = Np/Ns.', a: 'Both coils share the same changing field, so the e.m.f. per turn is the same', s: ['The iron core carries the same changing magnetic field through every turn of both coils.', 'Each turn of the secondary has an e.m.f. e induced, so Vs = Ns e.', 'In an ideal transformer the primary’s turns develop the same e.m.f. per turn, balancing the supply: Vp = Np e.', 'Dividing, Vp/Vs = Np/Ns.'] }
      ]
    },

    'gcse-atom': {
      big: 'An atom is mostly empty space: a tiny, dense, positive nucleus surrounded by electrons. Firing alpha particles at gold foil revealed this. The nucleus is made of protons and neutrons; the number of protons fixes the element, and different numbers of neutrons make different isotopes. Splitting heavy nuclei (fission) and joining light ones (fusion) both release enormous energy.',
      sec: [
        { h: 'Inside the atom', p: ['An atom has a positively charged nucleus, made of protons and neutrons, with negatively charged electrons around it. A neutral atom has equal numbers of protons and electrons. An atom that gains or loses electrons becomes an ion: losing electrons makes a positive ion, gaining them a negative ion.'], list: ['Proton: charge +1 (that is, +e), mass about 1 unit.', 'Neutron: no charge, mass about 1 unit.', 'Electron: charge −1, mass about 1/1840 of a proton.'] },
        { h: 'The alpha-scattering experiment', p: ['In 1909 Geiger and Marsden fired alpha particles (small, fast, positive) at very thin gold foil. Most went straight through. A few were deflected through large angles, and about 1 in 8000 bounced back towards the source.', 'Rutherford (1911) explained it: most of the atom is empty space (most alphas pass straight through); the positive charge and almost all the mass are concentrated in a tiny nucleus (only an alpha passing very close to it feels a big enough repulsion to be turned back). The nucleus is about 100 000 times smaller across than the atom.'] },
        { h: 'Nuclide notation and isotopes', p: ['The proton number Z (atomic number) is the number of protons. The nucleon number A (mass number) is the number of protons plus neutrons. A nuclide is written ᴬ_Z X: for example ¹⁴₆C has 6 protons and 8 neutrons.', 'Isotopes are atoms of the same element (same Z) with different numbers of neutrons (different A), such as carbon-12 and carbon-14. They behave the same chemically, but some isotopes have unstable nuclei and are radioactive.'], eq: R`{}^{A}_{Z}\mathrm{X}:\quad \text{neutrons} = A - Z` },
        { h: 'Fission', p: ['A heavy nucleus such as uranium-235 absorbs a slow neutron, becomes unstable and splits into two smaller nuclei, releasing two or three neutrons and a lot of energy (mostly kinetic energy of the fragments). The released neutrons can split more nuclei: a chain reaction, controlled in reactors and uncontrolled in bombs.'], eq: R`{}^{235}_{92}\mathrm{U} + {}^{1}_{0}\mathrm{n} \rightarrow {}^{141}_{56}\mathrm{Ba} + {}^{92}_{36}\mathrm{Kr} + 3\,{}^{1}_{0}\mathrm{n}` },
        { h: 'Fusion', p: ['Two light nuclei join to form a heavier one, releasing energy. In the Sun hydrogen nuclei fuse, in steps, into helium. Because nuclei are positive and repel each other, fusion needs extremely high temperatures and pressures so they collide fast enough to get close.', 'In every nuclear equation both the nucleon numbers and the proton numbers must balance on the two sides.'], eq: R`{}^{2}_{1}\mathrm{H} + {}^{3}_{1}\mathrm{H} \rightarrow {}^{4}_{2}\mathrm{He} + {}^{1}_{0}\mathrm{n}`, warn: '**Models are stages, not final truths.** Rutherford’s planetary atom explained scattering but could not explain why orbiting electrons do not spiral into the nucleus or why atoms emit sharp spectral lines; quantum mechanics replaced the orbits with probability clouds. The scattering itself also hid an assumption: only the electric force acts. Faster alpha particles that get closer than about 10⁻¹⁴ m start to feel the strong nuclear force, and the simple Rutherford pattern breaks down: that is how the size of the nucleus was first measured.' }
      ],
      eqs: [[R`A = Z + N`, 'nucleon number = protons + neutrons'], [R`{}^{A}_{Z}\mathrm{X}`, 'nuclide notation'], [R`\sum A_{\text{before}} = \sum A_{\text{after}},\ \sum Z_{\text{before}} = \sum Z_{\text{after}}`, 'balancing nuclear equations'], [R`r_{\text{atom}} \sim 10^{-10}\ \text{m},\ r_{\text{nucleus}} \sim 10^{-15}\ \text{m}`, 'sizes']],
      how: ['Read Z (bottom) and A (top); neutrons = A − Z.', 'Balance top numbers and bottom numbers separately in nuclear equations.', 'Explain each alpha-scattering observation with one feature of the nucleus.', 'Fission: heavy nucleus splits, neutrons released. Fusion: light nuclei join, needs huge temperatures.'],
      sum: ['Atom: tiny positive nucleus (protons + neutrons) with electrons around it.', 'Alpha scattering: mostly empty space, tiny dense positive nucleus.', 'Z = protons; A = protons + neutrons; isotopes differ in neutrons.', 'Fission splits heavy nuclei and releases neutrons; fusion joins light nuclei.', 'Nuclear equations balance A and Z.'],
      probs: [
        { l: 1, q: 'How many protons, neutrons and electrons are there in a neutral atom of ¹⁴₆C?', a: '6 protons, 8 neutrons, 6 electrons', s: ['Z = 6; neutrons = 14 − 6 = 8; neutral, so 6 electrons.'] },
        { l: 1, q: 'What are isotopes? Give an example.', a: 'Atoms with the same number of protons but different numbers of neutrons; carbon-12 and carbon-14', s: ['Same element, different nucleon numbers.'] },
        { l: 1, q: 'A sodium atom loses one electron. What does it become?', a: 'A positive ion, Na⁺', s: ['It now has one more proton than electrons.'] },
        { l: 2, q: 'State two observations from the alpha-scattering experiment and what each showed about the atom.', a: 'Most passed straight through (mostly empty space); a few bounced back (a tiny, dense, positive nucleus)', s: ['Undeflected alphas met almost nothing.', 'Large deflections need a strong repulsion from concentrated positive charge and mass.'] },
        { l: 2, q: 'A nucleus is about 10⁻¹⁵ m across and an atom about 10⁻¹⁰ m. If a nucleus were the size of a 1 cm marble, how big would the atom be?', a: 'About 1 km across', s: ['The ratio is 10⁵.', '1 cm × 10⁵ = 10⁵ cm = 1 km.'] },
        { l: 2, q: 'Check that this fission equation balances: ²³⁵₉₂U + ¹₀n → ¹⁴¹₅₆Ba + ⁹²₃₆Kr + 3 ¹₀n.', a: 'It balances', s: ['Nucleon numbers: 235 + 1 = 236; 141 + 92 + 3 = 236.', 'Proton numbers: 92 + 0 = 92; 56 + 36 + 0 = 92.'] },
        { l: 2, q: 'Complete: ²³⁵₉₂U + ¹₀n → ¹⁴⁴₅₆Ba + ᴬ_Z Kr + 3 ¹₀n.', a: '⁸⁹₃₆Kr', s: ['A = 236 − 144 − 3 = 89.', 'Z = 92 − 56 = 36 (krypton).'] },
        { l: 2, q: 'Show that ²₁H + ³₁H → ⁴₂He + ¹₀n balances, and name the process.', a: 'Fusion; A: 5 = 5, Z: 2 = 2', s: ['Top: 2 + 3 = 4 + 1. Bottom: 1 + 1 = 2 + 0.', 'Two light nuclei joining: fusion (the reaction planned for fusion power stations).'] },
        { l: 3, q: 'Why does fusion need temperatures of millions of degrees, while fission can happen at room temperature?', a: 'Fusing nuclei must overcome their electric repulsion; the neutron that triggers fission has no charge', s: ['Both nuclei in fusion are positive and repel strongly; only very fast collisions (very high temperature) bring them close enough for the strong force to take over.', 'A neutron is uncharged, so it can enter a uranium nucleus even moving slowly.'] },
        { l: 3, q: 'Each fission of uranium-235 releases about 200 MeV (3.2 × 10⁻¹¹ J). One kilogram of U-235 contains 2.6 × 10²⁴ nuclei. How much energy could it release, and how does that compare with burning 1 kg of coal (about 3 × 10⁷ J)?', a: 'About 8 × 10¹³ J: millions of times more', s: ['E = 2.6 × 10²⁴ × 3.2 × 10⁻¹¹ = 8.3 × 10¹³ J.', 'Ratio ≈ 8.3 × 10¹³ ÷ 3 × 10⁷ ≈ 3 million.', 'Chemical reactions rearrange electrons (a few eV per atom); nuclear reactions rearrange nucleons (millions of eV).'] }
      ]
    },

    'gcse-radiation': {
      big: 'Unstable nuclei emit radiation: alpha particles, beta particles or gamma rays. All three are ionising, knocking electrons off atoms in their path, which is what makes them useful and dangerous. They differ hugely in how far they penetrate, from a sheet of paper to centimetres of lead, and that decides both how we use them and how we stay safe.',
      sec: [
        { h: 'Background radiation', p: ['We are exposed to a low level of radiation all the time. Natural sources include radon gas seeping from rocks, rocks and building materials, cosmic rays from space, and food and drink (our bodies contain potassium-40 and carbon-14). Artificial sources include medical X-rays and scans, and tiny amounts from past weapons tests and nuclear power.'] },
        { h: 'Detecting it', p: ['A Geiger–Müller tube produces a pulse each time ionising radiation passes through it, and a counter records the pulses. The count rate is the number of counts per second or per minute.', 'Because background radiation is always there, measure it first with the source away; then subtract it from each reading to get the corrected count rate due to the source alone.'], eq: R`\text{corrected count rate} = \text{measured count rate} - \text{background count rate}` },
        { h: 'Alpha, beta and gamma', list: ['Alpha (α): a helium nucleus, 2 protons and 2 neutrons, charge +2. Very strongly ionising; stopped by a sheet of paper or a few centimetres of air.', 'Beta (β): a fast electron from the nucleus, charge −1. Moderately ionising; stopped by a few millimetres of aluminium.', 'Gamma (γ): a high-energy electromagnetic wave, no charge. Weakly ionising; only reduced by thick lead or concrete.'], p: ['The more strongly a radiation ionises, the faster it loses energy, so the less far it penetrates.'] },
        { h: 'Deflection in fields', p: ['In an electric or magnetic field, alpha and beta are deflected in opposite directions because their charges are opposite. Beta is deflected far more, because although its charge is half as big, its mass is about 7000 times smaller. Gamma, being uncharged, goes straight on.'] },
        { h: 'Safety', p: ['Ionising radiation can damage or kill living cells and alter DNA, which can cause cancer; high doses cause radiation burns and sickness. Outside the body alpha is the least dangerous (it cannot get through skin), but inside the body (inhaled or swallowed) it is the most dangerous, because all its ionisation is concentrated in nearby cells.', 'Sources are handled with tongs, held away from the body, never pointed at people, and kept in lead-lined boxes. Exposure is reduced by limiting the time, increasing the distance and using shielding.'], warn: '**Rules of thumb, not sharp cut-offs.** “Gamma is stopped by lead” really means reduced: each centimetre or so of lead roughly halves the intensity of typical gamma rays, but never to exactly zero. Beta particles come out with a range of energies, so their range in aluminium is a spread, not one number. And the danger depends on the dose actually absorbed, so the same source can be harmless at a metre and harmful in your pocket.' }
      ],
      eqs: [[R`\text{corrected} = \text{measured} - \text{background}`, 'count rate due to the source'], [R`\alpha = {}^{4}_{2}\mathrm{He},\quad \beta = {}^{\ \,0}_{-1}\mathrm{e},\quad \gamma`, 'what each radiation is'], [R`I \propto \frac{1}{d^2}`, 'extension: gamma from a small source spreads out with distance']],
      how: ['Subtract background before comparing count rates.', 'Identify radiation from absorbers: stopped by paper → α; by aluminium → β; only reduced by lead → γ.', 'In fields: α and β bend opposite ways, β much more; γ straight.', 'For safety, think time, distance, shielding, and inside versus outside the body.'],
      sum: ['Background radiation comes from radon, rocks, cosmic rays, food and medical use.', 'Corrected count rate = measured − background.', 'α: +2, most ionising, stopped by paper. β: −1, stopped by mm of aluminium. γ: EM wave, needs thick lead.', 'α and β deflect opposite ways in fields; γ does not deflect.', 'Reduce exposure: less time, more distance, more shielding.'],
      probs: [
        { l: 1, q: 'Put alpha, beta and gamma in order of penetrating power, least first.', a: 'Alpha, beta, gamma', s: ['Paper stops alpha; aluminium stops beta; thick lead reduces gamma.'] },
        { l: 1, q: 'Name two natural sources and one artificial source of background radiation.', a: 'For example radon gas and cosmic rays; medical X-rays', s: ['Rocks, buildings and food are other natural sources.'] },
        { l: 1, q: 'Why is an alpha source safe to handle with tongs but dangerous to swallow?', a: 'Alpha cannot get through skin, but inside the body it damages nearby cells intensely', s: ['Its ionisation is concentrated in the cells right next to it.'] },
        { l: 2, q: 'A counter reads 520 counts per minute near a source and 25 counts per minute with the source removed. What is the corrected count rate?', a: '495 counts per minute', s: ['520 − 25 = 495 counts per minute.'] },
        { l: 2, q: 'A source gives 300 counts/min with no absorber, 298 with paper, 30 with 3 mm of aluminium and 29 with lead. The background is 28 counts/min. What does it emit?', a: 'Beta only', s: ['Paper makes no difference: no alpha.', 'Aluminium cuts it to background: beta, stopped by aluminium.', 'Nothing gets through the aluminium, so no significant gamma.'] },
        { l: 2, q: 'A beam containing α, β and γ passes between two charged plates. Describe what happens to each.', a: 'α bends slightly towards the negative plate; β bends strongly towards the positive plate; γ goes straight', s: ['Opposite charges, opposite deflections; gamma has no charge.'] },
        { l: 2, q: 'Beta particles have half the charge of alpha particles, yet they are deflected much more. Why?', a: 'They have much less mass', s: ['An alpha particle has about 7000 times the mass of an electron, so the same kind of force accelerates it far less.'] },
        { l: 2, q: 'List four precautions when using radioactive sources in a lab.', a: 'Use tongs; keep them at arm’s length and away from people; minimise time; store in lead-lined boxes', s: ['Also: wash hands afterwards, and never eat or drink in the lab.'] },
        { l: 3, q: 'A small gamma source gives 400 counts/min above background at 0.50 m. Assuming the inverse-square law, what is the corrected count rate at 1.0 m and at 2.0 m? What does this say about handling sources?', a: '100 and 25 counts/min', s: ['Doubling the distance quarters the intensity: 400 → 100 → 25.', 'Distance is a very effective protection: tongs that double your distance from a source cut your dose to a quarter.'] },
        { l: 3, q: 'Smoke detectors contain americium-241, an alpha emitter with a half-life of 432 years. Explain why an alpha source is chosen and why its long half-life matters.', a: 'Alpha ionises air strongly but is stopped easily; the long half-life keeps the source steady', s: ['The alphas ionise the air between two plates, so a small current flows; smoke particles absorb the alphas, the current falls and the alarm sounds.', 'Alpha cannot escape the detector’s case or travel far in air, so it is safe.', 'With a 432-year half-life, the activity hardly changes over the detector’s life.'] }
      ]
    },

    'gcse-earth-moon': {
      big: 'Earth spins once a day, which gives day and night, and orbits the Sun once a year with its axis tilted by 23.4°, which gives the seasons. The Moon orbits Earth roughly once a month, and as it goes round we see more or less of its sunlit half: its phases.',
      sec: [
        { h: 'Day and night', p: ['Earth rotates on its axis once in about 24 hours. The half facing the Sun has day; the other half has night. The Sun appears to rise in the east and set in the west because Earth turns from west to east.'] },
        { h: 'The year and the seasons', p: ['Earth orbits the Sun once in about 365¼ days. Its axis is tilted at about 23.4° to the line perpendicular to its orbit, and it keeps pointing the same way in space.', 'When the northern hemisphere tilts towards the Sun (around June), the Sun climbs higher in its sky and days are longer, so sunlight is more concentrated and shines for more hours: northern summer. Six months later the tilt is away from the Sun: northern winter, with low Sun and short days. The southern hemisphere has the opposite seasons.'] },
        { h: 'The Moon and its phases', p: ['The Moon orbits Earth about once every 27 days and always keeps the same face towards us. The Sun always lights half of the Moon. The phase we see depends on how much of that lit half faces Earth.', 'New Moon (Moon between Earth and Sun, its dark side facing us) → waxing crescent → first quarter → waxing gibbous → full Moon (Earth roughly between Sun and Moon) → waning gibbous → last quarter → waning crescent → new Moon. The full cycle of phases takes about 29.5 days.'] },
        { h: 'Orbital speed', p: ['For a roughly circular orbit, the distance travelled in one orbit is the circumference 2πr, covered in one period T.'], eq: R`v = \frac{2\pi r}{T}` },
        { h: 'Why 29.5 days and not 27.3?', p: ['The Moon goes round Earth once relative to the stars in 27.3 days. But in that time Earth has moved about a thirteenth of its way round the Sun, so the Moon must travel about two more days to line up with the Sun again and repeat its phase.'], warn: '**Seasons are not caused by distance.** Earth’s orbit is slightly elliptical, but Earth is closest to the Sun in early January (about 147 million km) and furthest in early July (about 152 million km): the northern hemisphere’s winter happens at the closest point. The tilt, not the distance, controls the seasons. Likewise, phases are not caused by Earth’s shadow; that only happens during a lunar eclipse.' }
      ],
      eqs: [[R`v = 2\pi r/T`, 'speed in a circular orbit (or of a point on a spinning planet)'], [R`23.4^\circ`, 'tilt of Earth’s axis'], [R`T_{\text{phases}} \approx 29.5\ \text{days},\ T_{\text{orbit}} \approx 27.3\ \text{days}`, 'the Moon’s two periods']],
      how: ['For seasons, describe the tilt’s effect on the Sun’s height and day length.', 'For phases, draw the Sun’s light from one side and ask how much of the lit half Earth sees.', 'For v = 2πr/T, put r in m and T in s.'],
      sum: ['Rotation (24 h) → day and night.', 'Orbit (365¼ days) + 23.4° tilt → seasons.', 'Phases: how much of the Moon’s lit half we see; cycle 29.5 days.', 'v = 2πr/T.', 'Earth is closest to the Sun in January: distance does not cause seasons.'],
      probs: [
        { l: 1, q: 'Why do we have day and night?', a: 'Earth rotates on its axis', s: ['Each place turns into sunlight and then out of it once every 24 hours.'] },
        { l: 1, q: 'What causes the seasons?', a: 'The tilt of Earth’s axis', s: ['The hemisphere tilted towards the Sun gets higher Sun and longer days.'] },
        { l: 1, q: 'Where is the Moon at full Moon, relative to Earth and the Sun?', a: 'On the opposite side of Earth from the Sun', s: ['We then see all of its sunlit half. (If it were exactly in line, there would be a lunar eclipse.)'] },
        { l: 2, q: 'Earth orbits the Sun at a radius of 1.5 × 10¹¹ m once every 365 days. Find its orbital speed.', a: 'About 30 km/s', s: ['T = 365 × 24 × 3600 = 3.15 × 10⁷ s.', 'v = 2π × 1.5 × 10¹¹ ÷ 3.15 × 10⁷ = 3.0 × 10⁴ m/s.'] },
        { l: 2, q: 'The Moon orbits at 3.84 × 10⁸ m from Earth with a period of 27.3 days. Find its orbital speed.', a: 'About 1.0 km/s', s: ['T = 27.3 × 86 400 = 2.36 × 10⁶ s.', 'v = 2π × 3.84 × 10⁸ ÷ 2.36 × 10⁶ = 1020 m/s.'] },
        { l: 2, q: 'Earth’s radius is 6.37 × 10⁶ m. How fast is a point on the equator moving because of Earth’s rotation?', a: 'About 460 m/s', s: ['v = 2π × 6.37 × 10⁶ ÷ 86 400 = 463 m/s, over 1600 km/h.'] },
        { l: 2, q: 'Explain why days are longer in summer.', a: 'The tilt means more of that hemisphere is in daylight as Earth spins', s: ['With the pole tilted towards the Sun, a place in that hemisphere spends more of each rotation on the lit side.', 'Inside the Arctic Circle the Sun does not set at all near midsummer.'] },
        { l: 2, q: 'List the phases of the Moon in order, starting from new Moon.', a: 'New, waxing crescent, first quarter, waxing gibbous, full, waning gibbous, last quarter, waning crescent', s: ['“Waxing” means the lit part is growing; “waning” means shrinking.'] },
        { l: 3, q: 'Show that a 27.3-day orbit gives a 29.5-day cycle of phases, using 1/T_{phases} = 1/T_{orbit} − 1/T_{year}.', a: 'About 29.5 days', s: ['1/27.32 − 1/365.25 = 0.03660 − 0.00274 = 0.03387 per day.', 'T_{phases} = 1 ÷ 0.03387 = 29.5 days.', 'The subtraction appears because Earth moves round the Sun in the same direction as the Moon orbits.'] },
        { l: 3, q: 'At latitude 52° N, the midday Sun is 38° above the horizon at the equinoxes. How high is it at midsummer and midwinter? The heating effect on level ground is proportional to the sine of the Sun’s height: compare the two.', a: '61° and 15°; summer sunlight is about 3.5 times as concentrated', s: ['Midsummer: 38 + 23.4 = 61.4°. Midwinter: 38 − 23.4 = 14.6°.', 'sin 61.4° = 0.88; sin 14.6° = 0.25; ratio ≈ 3.5.', 'Combined with days about twice as long, summer delivers roughly seven times as much solar energy each day.'] }
      ]
    },

    'gcse-solar-system': {
      big: 'The Solar System formed about 4.6 billion years ago from a spinning cloud of gas and dust. The Sun holds over 99.8% of its mass, and its gravity keeps eight planets, dwarf planets, asteroids and comets in orbit. The orbits are ellipses, and every body moves fastest when it is closest to the Sun.',
      sec: [
        { h: 'What is out there', list: ['The Sun, a star.', 'Eight planets. Inner, rocky: Mercury, Venus, Earth, Mars. Outer, giant: Jupiter, Saturn (gas giants), Uranus, Neptune (ice giants).', 'Dwarf planets such as Pluto and Ceres.', 'Moons orbiting planets; Earth has one, Jupiter and Saturn dozens.', 'Asteroids, mostly in a belt between Mars and Jupiter, and comets: lumps of ice and dust on long, stretched orbits.'] },
        { h: 'How it formed: accretion', p: ['A cloud of gas and dust collapsed under its own gravity and began to spin, flattening into a disc. Most of the material fell to the centre and became the Sun. In the disc, dust grains stuck together and grew into larger and larger bodies (accretion), eventually planets.', 'Near the hot young Sun only rock and metal could stay solid, so the inner planets are small and rocky. Further out, ices could also condense, so planets grew big enough to capture huge amounts of hydrogen and helium gas: the giants.', 'That is also why all the planets orbit in the same direction and nearly the same plane.'] },
        { h: 'Gravity and orbits', p: ['The Sun’s gravity provides the force that keeps each planet moving in its curved path; without it, a planet would fly off in a straight line. The gravitational field strength at a planet’s surface depends on its mass and radius: about 3.7 N/kg on Mars, 9.8 N/kg on Earth, 25 N/kg at the cloud tops of Jupiter.', 'The Sun’s pull weakens with distance, so the outer planets move more slowly and have much further to go: their years are far longer. Neptune takes 165 Earth years to go round once.'] },
        { h: 'Elliptical orbits', p: ['Planetary orbits are ellipses with the Sun at one focus, not at the centre. Most are nearly circular; comets’ orbits are very stretched.', 'As a body falls inwards towards the Sun, it loses gravitational potential energy and gains kinetic energy, so it is fastest at its closest point and slowest at its furthest. A comet whips round the Sun in weeks, then spends decades crawling through the outer Solar System.'] },
        { h: 'Light travel times', p: ['Light from the Sun takes about 8.3 minutes to reach Earth, and over 4 hours to reach Neptune. Radio commands to distant spacecraft take just as long, so probes must run themselves.'], eq: R`t = \frac{d}{c},\qquad c = 3.0\times10^8\ \text{m/s}`, warn: '**Patterns in planetary data have exceptions.** Surface temperature mostly falls with distance from the Sun, but Venus (about 465 °C) is hotter than Mercury because its thick carbon dioxide atmosphere traps heat. Orbital periods follow T² ∝ r³ (Kepler’s third law) remarkably well, but only because the planets’ masses are tiny compared with the Sun’s; the law also needs the small corrections from planets tugging on each other, which is how Neptune was discovered in 1846.' }
      ],
      eqs: [[R`t = d/c`, 'light travel time'], [R`v = 2\pi r/T`, 'average orbital speed'], [R`T^2 \propto r^3`, 'extension: Kepler’s third law (T in years, r in AU: T² = r³)'], [R`W = mg`, 'weight on another planet']],
      how: ['Use the inner/outer split (rocky/giant) and explain it with temperature in the early disc.', 'For orbital speed changes, use energy: closer → less potential energy → more kinetic energy.', 'For light times, divide distance by 3.0 × 10⁸ m/s and convert to minutes or hours.', 'For data tables, look for trends and explain any exceptions.'],
      sum: ['Eight planets: four rocky inner, four giant outer; plus dwarf planets, moons, asteroids, comets.', 'Formed by accretion in a collapsing, spinning disc 4.6 billion years ago.', 'The Sun’s gravity keeps everything in orbit; further out means slower and longer orbits.', 'Orbits are ellipses; bodies move fastest when closest to the Sun.', 'Sunlight reaches Earth in about 8.3 minutes.'],
      probs: [
        { l: 1, q: 'List the eight planets in order from the Sun.', a: 'Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune', s: ['A common memory aid: My Very Easy Method Just Speeds Up Naming.'] },
        { l: 1, q: 'What keeps the planets in orbit around the Sun?', a: 'The Sun’s gravitational pull', s: ['It provides the force towards the Sun that bends their paths into orbits.'] },
        { l: 1, q: 'Why are the inner planets rocky and the outer ones giants?', a: 'Near the young Sun only rock and metal could condense; further out ices could too, and the planets grew big enough to capture gas', s: ['Temperature in the early disc decided which materials were solid.'] },
        { l: 2, q: 'The Sun is 1.5 × 10¹¹ m from Earth. How long does its light take to reach us?', a: '500 s, about 8.3 minutes', s: ['t = 1.5 × 10¹¹ ÷ 3.0 × 10⁸ = 500 s.'] },
        { l: 2, q: 'Neptune is about 4.5 × 10¹² m from Earth. How long does a radio signal take to reach a probe there?', a: 'About 4.2 hours', s: ['t = 4.5 × 10¹² ÷ 3.0 × 10⁸ = 1.5 × 10⁴ s = 4.2 h.', 'A question and its answer take over 8 hours.'] },
        { l: 2, q: 'Where on its orbit is a comet moving fastest? Explain using energy.', a: 'At its closest point to the Sun', s: ['Falling inwards, it loses gravitational potential energy and gains kinetic energy.', 'It is lowest in the Sun’s gravitational field, so fastest, at its closest approach.'] },
        { l: 2, q: 'A 70 kg astronaut visits Mars (g = 3.7 N/kg) and floats near Jupiter’s cloud tops (g = 25 N/kg). Find her weight in each place.', a: '259 N on Mars; 1750 N at Jupiter', s: ['W = 70 × 3.7 = 259 N.', 'W = 70 × 25 = 1750 N, about two and a half times her Earth weight of 686 N.'] },
        { l: 2, q: 'Jupiter orbits at 5.2 times Earth’s distance from the Sun. Use T² = r³ (T in years, r in Earth–Sun distances) to find its orbital period.', a: 'About 11.9 years', s: ['T = 5.2^1.5 = √(5.2³) = √140.6 = 11.9 years.'] },
        { l: 3, q: 'Mars orbits at 1.52 times Earth’s distance from the Sun. Find its period from Kepler’s third law, and its average orbital speed relative to Earth’s 30 km/s.', a: '1.87 years; about 24 km/s', s: ['T = 1.52^1.5 = 1.87 years.', 'v = 2πr/T, so v_{Mars}/v_{Earth} = (1.52 ÷ 1.87) = 0.81, giving 24 km/s.', 'Further out, the planet is slower as well as having further to go.'] },
        { l: 3, q: 'Mercury is closer to the Sun than Venus, yet Venus has the hotter surface (about 465 °C). Explain, and say what this shows about using simple trends.', a: 'Venus’s thick CO₂ atmosphere causes a runaway greenhouse effect', s: ['Venus’s atmosphere is about 90 times as massive as Earth’s and mostly CO₂, which traps outgoing infrared.', 'Mercury has almost no atmosphere: its day side reaches about 430 °C but its night side falls below −170 °C.', 'Distance from the Sun is not the only factor: atmospheres can dominate.'] }
      ]
    },

    'gcse-stars': {
      big: 'The Sun is a star: a huge ball of hydrogen and helium held together by gravity and powered by nuclear fusion in its core. Every star is born in a collapsing cloud of gas and dust, shines steadily for most of its life, and ends as a white dwarf, a neutron star or a black hole depending on its mass. Distances to stars are so vast that we measure them in light-years.',
      sec: [
        { h: 'The Sun as a star', p: ['The Sun is a medium-sized star made mostly of hydrogen (about three quarters of its mass) and helium. It radiates most of its energy as infrared, visible light and ultraviolet.', 'In its core, at about 15 million °C, hydrogen nuclei fuse in a series of steps to make helium. Each second the Sun turns about 600 million tonnes of hydrogen into helium and converts about 4 million tonnes of mass into energy.'] },
        { h: 'Galaxies and light-years', p: ['The Sun is one of 100 billion or more stars in the Milky Way galaxy, a spiral about 100 000 light-years across. The observable Universe contains billions of galaxies.', 'A light-year is the distance light travels in one year: about 9.5 × 10¹⁵ m. The nearest star after the Sun, Proxima Centauri, is 4.2 light-years away. Looking at distant objects means looking back in time: we see Proxima as it was 4.2 years ago.'], eq: R`1\ \text{light-year} = c \times 1\ \text{year} \approx 9.5\times10^{15}\ \text{m}` },
        { h: 'Birth and the main sequence', p: ['A star forms when a cloud of gas and dust (a nebula) collapses under its own gravity. The collapsing protostar heats up until its core is hot and dense enough for hydrogen to fuse into helium.', 'The star then becomes stable, on the main sequence: the outward pressure of its hot gas, kept hot by fusion, balances the inward pull of gravity. The Sun has been in this phase for about 4.6 billion years and will stay in it for about another 5 billion.'] },
        { h: 'How stars end', list: ['A star like the Sun: when hydrogen in the core runs out, it swells into a red giant, then gently sheds its outer layers as a planetary nebula, leaving a hot, dense core: a white dwarf, which slowly cools.', 'A star much more massive than the Sun (above about 8 solar masses): it swells into a red supergiant, then its core collapses and it explodes as a supernova, leaving a neutron star or, for the most massive, a black hole.'], p: ['Supernovae scatter elements made inside stars into space. New nebulae containing these elements form the next generations of stars and planets: the iron in your blood and the calcium in your bones were made in stars.'] },
        { h: 'Balancing gravity', p: ['Every stage of a star’s life is a contest between gravity pulling inwards and pressure pushing outwards. When fusion slows, gravity wins and the core contracts and heats until a new fuel ignites or something else (the resistance of tightly packed electrons in a white dwarf, or of neutrons in a neutron star) stops the collapse.'], warn: '**“Medium-sized” depends on how you count.** Across the full range of stars, from a tenth of the Sun’s mass to over a hundred times, the Sun is in the middle. But most stars are small, dim red dwarfs, and the Sun is more massive than about 90% of the stars in the Milky Way. The neat life-cycle chart also simplifies: stars in close pairs swap mass, and the mass boundaries between outcomes are still being refined.' }
      ],
      eqs: [[R`1\ \text{ly} \approx 9.5\times10^{15}\ \text{m}`, 'light-year'], [R`d = c\,t`, 'distance from light travel time'], [R`E = mc^2`, 'extension: mass converted to energy in fusion']],
      how: ['For distances, multiply light-years by 9.5 × 10¹⁵ m (or divide metres by it).', 'For life cycles, decide first whether the star is Sun-like or much more massive.', 'Explain stability as a balance between gravity and outward pressure.', 'Remember that distant light is old light.'],
      sum: ['The Sun: a medium-sized star of hydrogen and helium, powered by fusion.', 'Milky Way: 100 billion+ stars; a light-year ≈ 9.5 × 10¹⁵ m.', 'Nebula → protostar → main sequence (gravity balanced by pressure).', 'Sun-like: red giant → planetary nebula → white dwarf.', 'Massive: red supergiant → supernova → neutron star or black hole.'],
      probs: [
        { l: 1, q: 'What is a light-year?', a: 'The distance light travels in one year', s: ['It is a distance, not a time: about 9.5 × 10¹⁵ m.'] },
        { l: 1, q: 'What two elements make up most of the Sun?', a: 'Hydrogen and helium', s: ['About three quarters hydrogen and a quarter helium by mass.'] },
        { l: 1, q: 'What process releases energy in the Sun’s core?', a: 'Nuclear fusion of hydrogen into helium', s: ['Light nuclei join to make heavier ones, releasing energy.'] },
        { l: 2, q: 'Show that a light-year is about 9.5 × 10¹⁵ m.', a: '3.0 × 10⁸ m/s × 3.16 × 10⁷ s', s: ['One year = 365.25 × 24 × 3600 = 3.16 × 10⁷ s.', 'd = 3.0 × 10⁸ × 3.16 × 10⁷ = 9.5 × 10¹⁵ m.'] },
        { l: 2, q: 'Proxima Centauri is 4.2 light-years away. How far is that in metres, and how long would a spacecraft travelling at 17 km/s (like Voyager 1) take to get there?', a: '4.0 × 10¹⁶ m; about 74 000 years', s: ['d = 4.2 × 9.5 × 10¹⁵ = 4.0 × 10¹⁶ m.', 't = 4.0 × 10¹⁶ ÷ 1.7 × 10⁴ = 2.3 × 10¹² s, about 74 000 years.'] },
        { l: 2, q: 'Describe the life cycle of a star like the Sun.', a: 'Nebula → protostar → main sequence → red giant → planetary nebula + white dwarf', s: ['Fusion of hydrogen keeps it stable for about 10 billion years; then the core runs out and the star swells, sheds its outer layers and leaves a white dwarf.'] },
        { l: 2, q: 'Describe how a star much more massive than the Sun ends its life.', a: 'Red supergiant → supernova → neutron star or black hole', s: ['Its core eventually cannot be supported, collapses, and the star explodes.', 'The remaining core is a neutron star, or a black hole if massive enough.'] },
        { l: 2, q: 'Why does a main-sequence star stay the same size for billions of years?', a: 'Gravity inwards is balanced by gas pressure outwards', s: ['Fusion keeps the core hot, so the gas pressure stays high enough to support the weight of the layers above.'] },
        { l: 3, q: 'The Sun radiates 3.8 × 10²⁶ W. Using E = mc², how much mass does it convert to energy each second? Over a 10-billion-year lifetime (3.2 × 10¹⁷ s), what fraction of its 2.0 × 10³⁰ kg mass is that?', a: '4.2 × 10⁹ kg/s; about 0.07%', s: ['Δm/Δt = 3.8 × 10²⁶ ÷ (3.0 × 10⁸)² = 4.2 × 10⁹ kg/s, about 4 million tonnes per second.', 'Total = 4.2 × 10⁹ × 3.2 × 10¹⁷ = 1.3 × 10²⁷ kg.', 'Fraction = 1.3 × 10²⁷ ÷ 2.0 × 10³⁰ ≈ 0.07%: fusion only ever uses the core’s hydrogen, and converts under 1% of that mass to energy.'] },
        { l: 3, q: 'The Andromeda galaxy is 2.5 million light-years away. How far is that in metres, and what are we really seeing when we look at it?', a: '2.4 × 10²² m; Andromeda as it was 2.5 million years ago', s: ['d = 2.5 × 10⁶ × 9.5 × 10¹⁵ = 2.4 × 10²² m.', 'Its light left 2.5 million years ago, long before modern humans existed: the further we look, the further back in time we see.'] }
      ]
    }
  });
})();
/* ---- notes-ks3b.js ---- */
/* Geodesic: notes and ten-problem sets for KS3 outline topics, part 1 (energy, forces, density, heat, climate, sound). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'ks3-energy': {
      big: 'Energy is never made or destroyed. In every event, from a kettle boiling to a ball bouncing, it only moves from one store to another. But each time it moves, some of it spreads out into the surroundings as heat, where it is much harder to use. That spreading out, dissipation, is why things run down.',
      sec: [
        { h: 'Energy stores', p: ['It helps to imagine energy kept in different stores:'], list: ['Kinetic: anything moving.', 'Gravitational potential: anything raised up.', 'Elastic: anything stretched or squashed.', 'Thermal: anything warm (its particles move faster).', 'Chemical: fuels, food and batteries.', 'Nuclear: inside the nuclei of atoms.', 'Magnetic and electrostatic: magnets and charges pushing or pulling.'] },
        { h: 'Energy transfers', p: ['Energy moves between stores in four ways: by a force moving something (mechanical work), by an electric current, by heating, and by waves such as light and sound. A torch transfers energy from the chemical store of its battery, electrically, to the lamp, which sends it out as light (and heats up).'] },
        { h: 'Conservation of energy', p: ['The total amount of energy never changes. If a battery gives out 100 J, then exactly 100 J ends up somewhere else: perhaps 20 J as light and 80 J heating the room. Energy is measured in joules (J).'] },
        { h: 'Dissipation: energy spreading out', p: ['In every real process some energy ends up warming the surroundings, often through friction or sound. That energy is not lost, but it is spread thinly and becomes much less useful.', 'A bouncing ball rises a little less each time: on every bounce some of its energy is transferred to sound and to heating the ball and floor. Eventually it lies still and all its energy has been dissipated.'] },
        { h: 'Useful and wasted energy', p: ['We call the energy that does the job we want “useful” and the rest “wasted”. Efficiency compares them: the bigger the share of useful energy, the more efficient the device. A Sankey diagram draws energy as arrows whose width shows how much.'], eq: R`\text{efficiency} = \frac{\text{useful energy out}}{\text{total energy in}}`, warn: '**“Using up energy” is not quite right.** When we say a car “uses up” petrol, the energy is not destroyed: it ends up as thermal energy in the air, the road and the brakes. What really gets used up is energy in a concentrated, useful form. That is why we can run out of fuel even though energy is always conserved.' }
      ],
      eqs: [[R`\text{energy in} = \text{useful out} + \text{wasted}`, 'conservation of energy'], [R`\text{efficiency} = \frac{\text{useful out}}{\text{total in}}`, 'often written as a percentage'], [R`1\ \text{kJ} = 1000\ \text{J}`, 'kilojoules']],
      how: ['Name the store the energy starts in and the store it ends in.', 'Name how it is transferred (force, electricity, heating, waves).', 'Check the energy adds up: in = useful + wasted.', 'Look for friction, sound and heating: that is where energy is dissipated.'],
      sum: ['Energy is stored in kinetic, gravitational, elastic, thermal, chemical, nuclear, magnetic and electrostatic stores.', 'It moves by forces, electricity, heating and waves.', 'It is never created or destroyed.', 'Some always spreads into the surroundings and becomes less useful.', 'Efficiency = useful out ÷ total in.'],
      probs: [
        { l: 1, q: 'Name the energy store in: a stretched rubber band, a battery, a moving car, a book on a high shelf.', a: 'Elastic, chemical, kinetic, gravitational potential', s: ['Stretched: elastic. Fuel or battery: chemical. Moving: kinetic. Raised: gravitational.'] },
        { l: 1, q: 'What does “conservation of energy” mean?', a: 'Energy cannot be created or destroyed, only transferred', s: ['The total amount of energy stays the same.'] },
        { l: 1, q: 'For an electric kettle, what is the useful energy and what is wasted?', a: 'Useful: heating the water. Wasted: heating the kettle and air, and sound.', s: ['Only the energy that goes into the water does the job we want.'] },
        { l: 2, q: 'A lamp takes in 100 J of electrical energy every second and gives out 10 J of light. How much is wasted, and what is its efficiency?', a: '90 J; 10%', s: ['Wasted = 100 − 10 = 90 J (heating the lamp and room).', 'Efficiency = 10 ÷ 100 = 0.1 = 10%.'] },
        { l: 2, q: 'Why does a dropped ball never bounce back to the height it fell from?', a: 'Some energy is dissipated as sound and heat at each bounce', s: ['At each bounce some energy goes into sound and into heating the ball and the ground.', 'Less energy is left in the kinetic store, so it cannot climb as high.'] },
        { l: 2, q: 'A Sankey diagram shows 200 J going into a motor and 50 J of useful kinetic energy coming out. How much energy is wasted?', a: '150 J', s: ['200 − 50 = 150 J, mostly heating the motor.'] },
        { l: 2, q: 'Describe the energy changes in a wind-up torch, from winding to light.', a: 'Chemical (in you) → elastic or kinetic → electrical → light and heat', s: ['Your muscles do work winding the spring or spinning a generator.', 'The generator transfers the energy electrically to the lamp, which gives out light and some heat.'] },
        { l: 2, q: 'A biscuit releases 300 kJ when digested. Lifting a 600 N person up a 3 m staircase needs 600 × 3 = 1800 J. How many staircases could the biscuit’s energy lift them up, in theory? Why far fewer in practice?', a: 'About 167; the body is only about a quarter efficient', s: ['300 000 ÷ 1800 = 167.', 'Most of the food energy is dissipated as heat in your muscles, so only about 40 staircases in reality.'] },
        { l: 3, q: 'A car drives along a level road and stops back where it started. Where has all the energy from the petrol it burned gone?', a: 'Into the thermal store of the surroundings', s: ['The car ends with no kinetic energy and at the same height.', 'All the energy has been transferred to heating the air (drag), the tyres and road (friction), the brakes and the exhaust gases.'] },
        { l: 3, q: 'An inventor claims a machine that, once started, will run forever and also power a light bulb. Use energy ideas to explain why it cannot work.', a: 'It would create energy, and real machines always dissipate some', s: ['Lighting the bulb transfers energy out, and friction dissipates more, so the machine must lose energy.', 'With no energy coming in, it must slow down and stop. Running forever while giving out energy would break conservation of energy.'] }
      ]
    },

    'ks3-forces': {
      big: 'A force is a push or a pull, measured in newtons. When the forces on something balance, its motion does not change: it stays still or keeps going at a steady speed. When they do not balance, it speeds up, slows down or changes direction. Gravity is the force that pulls every mass towards every other mass.',
      sec: [
        { h: 'Contact and non-contact forces', p: ['Contact forces act when objects touch: friction, air resistance, water resistance, tension in a rope, and the push of the ground on your feet. Non-contact forces act at a distance: gravity, magnetism and the electric force.', 'Forces are drawn as arrows: the length shows how big, the direction shows which way.'] },
        { h: 'Gravity, mass and weight', p: ['Every mass attracts every other mass. The pull is bigger for bigger masses and weaker when they are further apart. Earth is so massive that its pull on us is easy to feel; the pull between two people is far too small to notice.', 'Mass is the amount of matter, in kilograms. Weight is the force of gravity on it, in newtons. On Earth each kilogram weighs about 10 N; on the Moon only about 1.6 N, because the Moon has less mass.'], eq: R`\text{weight (N)} = \text{mass (kg)} \times g,\qquad g \approx 10\ \text{N/kg on Earth}` },
        { h: 'Balanced and unbalanced forces', p: ['If the forces on an object are balanced (they cancel), its motion does not change: a parked car stays still and a car cruising at a steady 30 mph keeps that speed, because the forward force from the engine equals the backward forces.', 'If the forces are unbalanced, the resultant (overall) force changes the motion: forwards speeds it up, backwards slows it down, sideways turns it.'] },
        { h: 'Friction and air resistance', p: ['Friction acts between surfaces to oppose motion; it lets us walk and brake but wastes energy as heat in machines. Air resistance (drag) opposes things moving through air and gets bigger the faster they go.', 'A skydiver speeds up until air resistance grows to equal her weight; then the forces balance and she falls at a steady top speed (terminal velocity). Her parachute increases the air resistance, slowing her to a safe speed.'] },
        { h: 'Falling in a vacuum', p: ['With no air there is no air resistance, so everything falls together whatever its mass. In 1971 Apollo 15 astronaut David Scott dropped a hammer and a feather on the Moon and they landed at the same moment.'], warn: '**Why don’t heavy things fall faster?** A heavier object does have a bigger weight, but it also has more mass to get moving. The two effects cancel exactly, so without air resistance every object falls with the same acceleration. Air resistance breaks the tie, because it depends on shape and size, not on mass.' }
      ],
      eqs: [[R`W = m g`, 'weight in N; g ≈ 10 N/kg on Earth, 1.6 N/kg on the Moon'], [R`\text{resultant} = \text{forward} - \text{backward}`, 'forces along one line']],
      how: ['Draw the object and an arrow for every force on it.', 'Add the forces along one line, counting one direction as positive.', 'Zero resultant: no change in motion. Not zero: it speeds up, slows down or turns.', 'For weight, multiply the mass by g.'],
      sum: ['Forces are pushes or pulls in newtons.', 'Weight = mass × g; mass stays the same everywhere.', 'Balanced forces: no change in motion. Unbalanced: speeding up, slowing down or turning.', 'Air resistance grows with speed, leading to terminal velocity.', 'In a vacuum all objects fall together.'],
      probs: [
        { l: 1, q: 'What is the weight of a 50 kg person on Earth (g = 10 N/kg)?', a: '500 N', s: ['W = 50 × 10 = 500 N.'] },
        { l: 1, q: 'A car travels at a steady 30 mph along a straight road. What can you say about the forces on it?', a: 'They are balanced', s: ['The driving force equals the friction and air resistance, so the speed does not change.'] },
        { l: 1, q: 'Why does a feather fall more slowly than a hammer on Earth but not on the Moon?', a: 'Air resistance on Earth; no air on the Moon', s: ['Air resistance slows the feather much more. On the airless Moon both fall together.'] },
        { l: 2, q: 'A cyclist pushes forward with 800 N against 300 N of air resistance and friction. What is the resultant force, and what happens to her speed?', a: '500 N forwards; she speeds up', s: ['800 − 300 = 500 N forwards: unbalanced, so she accelerates.'] },
        { l: 2, q: 'Describe the forces on a skydiver just after jumping, halfway down before opening the parachute, and at terminal velocity.', a: 'Weight only; weight bigger than drag; weight equals drag', s: ['Just after jumping she is slow, so air resistance is tiny: she speeds up quickly.', 'As she speeds up, air resistance grows, so she speeds up less quickly.', 'At terminal velocity air resistance equals her weight: steady speed.'] },
        { l: 2, q: 'What would a 50 kg person weigh on the Moon (g = 1.6 N/kg)? What is their mass there?', a: '80 N; still 50 kg', s: ['W = 50 × 1.6 = 80 N.', 'Mass does not depend on where you are.'] },
        { l: 2, q: 'Give one example where friction is useful and one where it is a nuisance.', a: 'Useful: brakes, grip when walking. Nuisance: wear and heating in machines.', s: ['Friction opposes motion; whether that helps depends on what you want.'] },
        { l: 2, q: 'Why do racing cyclists crouch low over their handlebars?', a: 'To reduce air resistance', s: ['A smaller area facing the air means less air resistance, so the same effort gives a higher speed.'] },
        { l: 3, q: 'Astronauts on the International Space Station, 400 km up, still feel about 89% of the gravity they feel on the ground. So why do they float?', a: 'They are in free fall, falling round Earth together with the station', s: ['Gravity is still strong there; it is what keeps the station in orbit.', 'The station and the astronauts fall together, so nothing pushes on them: they feel weightless even though they have weight.'] },
        { l: 3, q: 'Two identical bricks are dropped together, and a single brick is dropped beside them. Without air resistance, which lands first? Explain using weight and mass.', a: 'They land together', s: ['The pair has twice the weight but also twice the mass to accelerate.', 'Twice the force on twice the mass gives the same acceleration.'] }
      ]
    },

    'ks3-density': {
      big: 'Whether something floats has nothing to do with how heavy it is and everything to do with its density: how much mass is packed into each cubic centimetre. Anything less dense than water floats in water, which is why a huge steel ship floats while a small pebble sinks.',
      sec: [
        { h: 'What density means', p: ['Density is mass divided by volume. Water has a density of 1 g/cm³: each cubic centimetre has a mass of one gram. Iron is about 7.9 g/cm³, so a cube of iron is nearly eight times heavier than the same-sized cube of water. Cork is only about 0.25 g/cm³.'], eq: R`\text{density} = \frac{\text{mass}}{\text{volume}}` },
        { h: 'Density and particles', p: ['Density depends on how heavy a substance’s particles are and how tightly they are packed. Solids and liquids have their particles packed closely, so they are much denser than gases, whose particles are far apart: air is about 800 times less dense than water.'] },
        { h: 'Measuring density', list: ['Regular block: measure length, width and height, multiply to get the volume, and weigh it on a balance.', 'Irregular object: lower it into a measuring cylinder of water; the rise in the water level is its volume.', 'Liquid: weigh an empty measuring cylinder, pour in a known volume of liquid, and weigh again.'] },
        { h: 'Floating and sinking', p: ['Water pushes up on anything in it with a force called upthrust. An object sinks until the upthrust balances its weight. If it is less dense than the water, it can do this while still partly above the surface, so it floats. If it is denser, even the upthrust when it is completely under water is not enough, so it sinks.', 'Liquids that do not mix settle in layers by density: oil floats on water, and water floats on syrup.'] },
        { h: 'How a steel ship floats', p: ['Steel is far denser than water, but a ship is mostly a steel shell full of air. What matters is its average density: total mass divided by total volume, including all the air inside. That is less than water’s, so it floats. Fill it with water through a hole and its average density rises above water’s, and it sinks.'], warn: '**Density changes too.** Warm water is slightly less dense than cold, and seawater (about 1.03 g/cm³) is denser than fresh water, so a ship floats a little higher in the sea than in a river. Gases change density hugely with temperature: that is why hot-air balloons rise.' }
      ],
      eqs: [[R`\rho = \frac{m}{V}`, 'density in g/cm³ (or kg/m³)'], [R`V = V_{\text{after}} - V_{\text{before}}`, 'volume by displacement'], [R`\rho_{\text{water}} = 1\ \text{g/cm}^3`, 'density of water']],
      how: ['Find the mass (balance) and volume (measuring or displacement).', 'Divide mass by volume, keeping units matched (g with cm³).', 'Compare with the liquid’s density: less dense floats, denser sinks.', 'For hollow objects, use the average density.'],
      sum: ['Density = mass ÷ volume.', 'Water is 1 g/cm³.', 'Measure irregular volumes by displacement.', 'Less dense than the liquid → floats; denser → sinks.', 'Ships float because their average density (steel plus air) is less than water’s.'],
      probs: [
        { l: 1, q: 'A block has a mass of 200 g and a volume of 100 cm³. What is its density?', a: '2 g/cm³', s: ['200 ÷ 100 = 2 g/cm³.'] },
        { l: 1, q: 'Wood has a density of 0.6 g/cm³. Will it float in water?', a: 'Yes', s: ['0.6 is less than water’s 1 g/cm³.'] },
        { l: 1, q: 'Why does ice float on water?', a: 'Ice is less dense than water', s: ['Water expands when it freezes, so ice (about 0.92 g/cm³) is less dense than liquid water.'] },
        { l: 2, q: 'A metal object of mass 120 g makes the water in a measuring cylinder rise from 30 cm³ to 45 cm³. What is its density?', a: '8 g/cm³', s: ['Volume = 45 − 30 = 15 cm³.', 'Density = 120 ÷ 15 = 8 g/cm³ (close to steel).'] },
        { l: 2, q: 'A 10 cm cube has a mass of 800 g. Does it float in water? In alcohol (0.79 g/cm³)?', a: 'Floats in water; just sinks in alcohol', s: ['Volume = 10 × 10 × 10 = 1000 cm³; density = 0.80 g/cm³.', '0.80 < 1.0 so it floats in water; 0.80 > 0.79 so it (slowly) sinks in alcohol.'] },
        { l: 2, q: 'Olive oil has a density of 0.92 g/cm³. What is the mass of 2.0 litres (2000 cm³) of it?', a: '1840 g', s: ['Mass = density × volume = 0.92 × 2000 = 1840 g.'] },
        { l: 2, q: 'Honey (1.4 g/cm³), water (1.0 g/cm³) and oil (0.92 g/cm³) are poured into a jar. In what order do they settle, from the bottom?', a: 'Honey, water, oil', s: ['The densest liquid sinks to the bottom.'] },
        { l: 2, q: 'Steel is much denser than water. Explain how a steel ship floats.', a: 'Its average density, including the air inside, is less than water’s', s: ['The ship is a thin steel shell around a large volume of air.', 'Total mass ÷ total volume is less than 1 g/cm³.'] },
        { l: 3, q: 'A “gold” crown has a mass of 1000 g. Pure gold is 19.3 g/cm³. What volume of water should the crown displace if it is pure gold? It actually displaces 60 cm³. What does that tell you?', a: '51.8 cm³; it is not pure gold', s: ['Pure gold: V = 1000 ÷ 19.3 = 51.8 cm³.', 'Measured density = 1000 ÷ 60 = 16.7 g/cm³, too low for gold.', 'A less dense metal such as silver must be mixed in: the test Archimedes is said to have used.'] },
        { l: 3, q: 'Hot air (0.95 kg/m³) fills a 2000 m³ balloon in cold air (1.2 kg/m³). How much more mass of cold air does the balloon push aside than the hot air inside it has? What does that mean for the load it can lift?', a: '500 kg; it can lift about 500 kg including the balloon itself', s: ['Mass of cold air displaced = 1.2 × 2000 = 2400 kg.', 'Mass of hot air inside = 0.95 × 2000 = 1900 kg.', 'The difference, 500 kg, is the most the balloon, basket and people can weigh.'] }
      ]
    },

    'ks3-heat': {
      big: 'Temperature tells you how hot something is; thermal energy is how much energy it holds because its particles are moving. Energy always flows from hotter to colder, by conduction, convection or radiation, until everything reaches the same temperature. And when a liquid evaporates, the fastest particles escape, which is why sweating cools you down.',
      sec: [
        { h: 'Temperature and thermal energy', p: ['Temperature, measured in °C with a thermometer, depends on how fast the particles are moving on average. Thermal energy depends on that and on how many particles there are.', 'So a bath of warm water holds far more thermal energy than a cup of boiling water: its temperature is lower, but it has so much more water.'] },
        { h: 'Heat flows from hot to cold', p: ['When two objects at different temperatures touch, energy is transferred from the hotter to the colder until they are at the same temperature (thermal equilibrium). A cup of tea cools down to room temperature; it never heats up by itself.'] },
        { h: 'Three ways energy moves', list: ['Conduction: through solids, as vibrating particles pass energy to their neighbours. Metals are good conductors; wood, plastic and air are poor conductors (insulators).', 'Convection: in liquids and gases. Warm fluid expands, becomes less dense and rises; cooler fluid sinks, making a convection current.', 'Radiation: infrared waves, which can even cross empty space. Dark, dull surfaces absorb and give out radiation best; shiny, light surfaces reflect it.'] },
        { h: 'Keeping warm, keeping cool', p: ['Insulation works by trapping air, a poor conductor, so that it cannot move and carry energy by convection: woolly jumpers, loft insulation and double glazing all do this.'] },
        { h: 'Cooling by evaporation', p: ['Particles in a liquid move at different speeds. The fastest ones near the surface can escape: that is evaporation. Because the fastest particles leave, the average speed of those left behind drops, so the liquid cools.', 'Sweat evaporating from your skin cools you. Evaporation is faster when it is warm, when the air is dry and when there is a breeze carrying vapour away, which is why a wet swimsuit feels so cold on a windy beach.'], warn: '**Heat and temperature are easy to mix up.** “Heat” means energy being transferred because of a temperature difference; it is not a substance that objects contain. A metal bench feels colder than a wooden one at the same temperature because the metal conducts energy away from your hand faster, not because it is colder.' }
      ],
      eqs: [[R`\text{hot} \rightarrow \text{cold}`, 'direction of thermal energy transfer'], [R`T_{\text{mix}} = \frac{m_1T_1 + m_2T_2}{m_1 + m_2}`, 'mixing amounts of the same liquid (no losses)']],
      how: ['Decide whether the question is about temperature (how hot) or energy (how much).', 'Name the route: conduction (solids), convection (fluids), radiation (waves).', 'For insulation, look for trapped air.', 'For evaporation, think about the fastest particles leaving.'],
      sum: ['Temperature: how hot. Thermal energy: how much energy, which also depends on mass.', 'Energy flows from hotter to colder until temperatures are equal.', 'Conduction, convection, radiation.', 'Trapped air insulates.', 'Evaporation removes the fastest particles, so it cools.'],
      probs: [
        { l: 1, q: 'What is the difference between temperature and thermal energy?', a: 'Temperature is how hot; thermal energy is how much energy, which also depends on how much stuff there is', s: ['A big object at a low temperature can hold more energy than a small hot one.'] },
        { l: 1, q: 'Hot tea is poured into a metal cup and a plastic cup. Which feels hotter to hold, and why?', a: 'The metal cup: metal conducts energy to your hand faster', s: ['Plastic is an insulator.'] },
        { l: 1, q: 'How does sweating help to cool you?', a: 'Sweat evaporates and takes energy from your skin', s: ['The fastest particles escape, leaving the rest cooler.'] },
        { l: 2, q: 'Which has more thermal energy: a full bath at 40 °C or a cup of water at 90 °C?', a: 'The bath', s: ['It has a lower temperature but hundreds of times more water.'] },
        { l: 2, q: 'Why does the handle of a metal spoon left in hot soup become hot?', a: 'Conduction along the metal', s: ['Hot particles at the bottom vibrate more and pass the energy along to their neighbours, all the way up the spoon.'] },
        { l: 2, q: 'Why are radiators usually fixed low down on a wall?', a: 'So they warm the air at the bottom, which rises and sets up a convection current', s: ['Warm air rises across the room and cool air sinks back down to the radiator.'] },
        { l: 2, q: 'Why do you feel colder in wet clothes on a windy day than in dry clothes?', a: 'The wind speeds up evaporation, which takes energy from you', s: ['Moving air carries away the water vapour so evaporation continues quickly.'] },
        { l: 2, q: '1 kg of water at 80 °C is mixed with 1 kg of water at 20 °C. What is the final temperature if no energy is lost?', a: '50 °C', s: ['Equal amounts of the same liquid meet in the middle: (80 + 20) ÷ 2 = 50 °C.'] },
        { l: 3, q: '0.2 kg of water at 90 °C is poured into 0.8 kg of water at 20 °C. Find the final temperature, ignoring losses.', a: '34 °C', s: ['T = (0.2 × 90 + 0.8 × 20) ÷ (0.2 + 0.8) = (18 + 16) ÷ 1.0 = 34 °C.', 'The larger amount of cold water dominates.'] },
        { l: 3, q: 'A vacuum flask keeps hot drinks hot. Explain why it also keeps cold drinks cold.', a: 'It blocks energy transfer in both directions', s: ['The vacuum stops conduction and convection, and the shiny walls cut radiation.', 'These work whichever way the energy is trying to flow: into a cold drink or out of a hot one.'] }
      ]
    },

    'ks3-climate': {
      big: 'The air around Earth is mostly nitrogen and oxygen, with a tiny but vital amount of carbon dioxide. Water and carbon move constantly between the air, the oceans, rocks and living things in great cycles. Burning fossil fuels has pushed extra carbon dioxide into the air, trapping more heat and changing the climate.',
      sec: [
        { h: 'What clean air is made of', list: ['Nitrogen: about 78%.', 'Oxygen: about 21%.', 'Argon: about 0.9%.', 'Carbon dioxide: about 0.04% (around 420 parts per million).', 'Plus a variable amount of water vapour, and traces of other gases.'], p: ['Pollution adds gases such as sulfur dioxide and nitrogen oxides (which cause acid rain) and tiny particles of soot.'] },
        { h: 'The water cycle', p: ['Energy from the Sun evaporates water from the oceans, lakes and plants. The vapour rises, cools and condenses into clouds. It falls back as rain or snow (precipitation), and runs back to the sea in rivers or soaks into the ground. The same water has been going round for billions of years.'] },
        { h: 'The carbon cycle', p: ['Plants take carbon dioxide from the air in photosynthesis. Animals eat plants, and living things return carbon dioxide to the air through respiration. When they die, decomposers break them down, releasing more. The oceans absorb and release huge amounts too.', 'Over millions of years some carbon got locked away as coal, oil and gas. Burning these fossil fuels returns that ancient carbon to the air very quickly, much faster than the cycle can take it back.'] },
        { h: 'The greenhouse effect', p: ['Sunlight passes through the air and warms Earth’s surface. The warm surface gives out infrared radiation. Greenhouse gases (carbon dioxide, water vapour, methane) absorb some of this infrared and send part of it back down, keeping Earth about 33 °C warmer than it would otherwise be. Without any greenhouse effect, Earth would be frozen.', 'Adding more greenhouse gas strengthens the effect, so the planet warms.'] },
        { h: 'Weather, climate and climate change', p: ['Weather is the state of the air on a particular day; climate is the average weather of a place over decades. One cold winter does not disprove a warming climate.', 'Carbon dioxide has risen from about 280 parts per million before the industrial age to around 420 today, and the world has warmed by about 1.3 °C since the late 1800s. Effects include rising sea levels (about 20 cm since 1900), melting glaciers and ice sheets, more intense heatwaves and heavy rain, and more acidic oceans.'], warn: '**Not all melting ice raises sea level.** Floating sea ice already displaces its own weight of water, so when it melts the level hardly changes (try it with ice in a glass). Sea level rises because ice on land, such as glaciers and the Greenland ice sheet, melts into the sea, and because warmer water expands.' }
      ],
      eqs: [[R`1\%\ = 10\,000\ \text{ppm}`, 'converting percentages and parts per million'], [R`\text{climate} = \text{average weather over decades}`, 'definition']],
      how: ['For cycles, follow one substance (water or carbon) from store to store.', 'Name the process for each arrow: evaporation, condensation, photosynthesis, respiration, combustion.', 'Distinguish weather (days) from climate (decades).', 'For sea level, ask whether the ice was floating or on land.'],
      sum: ['Air: about 78% nitrogen, 21% oxygen, 0.9% argon, 0.04% CO₂.', 'The water cycle is driven by the Sun.', 'Carbon moves by photosynthesis, respiration, decomposition and combustion.', 'Greenhouse gases trap infrared and keep Earth warm; more of them warms it further.', 'Climate is long-term average weather.'],
      probs: [
        { l: 1, q: 'Name the two most common gases in dry air and give their approximate percentages.', a: 'Nitrogen (78%) and oxygen (21%)', s: ['Together they make up about 99% of dry air.'] },
        { l: 1, q: 'What is the difference between weather and climate?', a: 'Weather is day to day; climate is the average over many years', s: ['Climate is usually averaged over 30 years.'] },
        { l: 1, q: 'Name the stages of the water cycle.', a: 'Evaporation, condensation, precipitation, collection (run-off)', s: ['The Sun’s energy drives evaporation.'] },
        { l: 2, q: 'Carbon dioxide is about 420 parts per million of the air. What percentage is that?', a: '0.042%', s: ['1% = 10 000 ppm, so 420 ppm = 420 ÷ 10 000 = 0.042%.'] },
        { l: 2, q: 'Name two processes that remove carbon dioxide from the air and two that add it.', a: 'Remove: photosynthesis, dissolving in the oceans. Add: respiration, burning fuels.', s: ['Decomposition and volcanoes also add carbon dioxide.'] },
        { l: 2, q: 'Explain the greenhouse effect in three steps.', a: 'Sunlight warms the surface; the surface gives out infrared; greenhouse gases absorb some and send it back down', s: ['The result is a warmer surface than there would be with no greenhouse gases.'] },
        { l: 2, q: 'Why does burning fossil fuels upset the carbon cycle, when living things release carbon dioxide all the time?', a: 'It releases carbon stored for millions of years, faster than it can be absorbed', s: ['Respiration returns carbon that was taken in recently; fossil fuels add old carbon on top.', 'Plants and oceans cannot take it back up as fast as we release it.'] },
        { l: 2, q: 'Air bubbles trapped in Antarctic ice show that carbon dioxide stayed between about 180 and 300 ppm for the last 800 000 years. How does today’s level compare?', a: 'It is about 420 ppm, far above that whole range', s: ['Today’s level is about 40% higher than the highest value in 800 000 years.'] },
        { l: 3, q: 'Carbon dioxide at Mauna Loa, Hawaii, was 316 ppm in 1959 and 419 ppm in 2023. Find the average rise per year. Recent years have risen by about 2.4 ppm per year; what does that tell you?', a: 'About 1.6 ppm per year; the rise is speeding up', s: ['(419 − 316) ÷ 64 years = 1.6 ppm per year.', 'Recent rises are larger than the average, so the increase is accelerating.'] },
        { l: 3, q: 'A friend says melting sea ice in the Arctic is the main cause of sea-level rise. Explain why that is wrong, and give the two main real causes.', a: 'Floating ice already displaces its own weight; land ice melting and warm water expanding raise sea level', s: ['Floating ice displaces the same mass of water it will become when melted, so it barely changes the level.', 'Melting glaciers and ice sheets on land add new water to the sea.', 'Water expands as it warms, so a warmer ocean takes up more room.'] }
      ]
    },

    'ks3-sound': {
      big: 'Sound is a vibration passed from particle to particle. Because it needs particles, it cannot cross empty space. How big the vibrations are decides how loud a sound is; how fast they are decides its pitch. When two sounds meet they add together, and they can even cancel each other out.',
      sec: [
        { h: 'How sound travels', p: ['A vibrating object, like a guitar string or a loudspeaker, pushes on the air particles next to it. They push on their neighbours, and the vibration passes along as a wave. The particles only jiggle back and forth; it is the energy that travels.', 'In a vacuum there are no particles, so sound cannot travel: a ringing bell in a jar goes silent as the air is pumped out, and space is silent.'] },
        { h: 'Speed of sound', p: ['Sound travels at about 340 m/s in air: fast, but much slower than light, which is why you see lightning before you hear thunder. It travels faster in water (about 1500 m/s) and faster still in solids like steel (about 5000 m/s), because the particles are closer together and more tightly linked.'] },
        { h: 'Echoes', p: ['An echo is sound reflected from a hard surface. The sound travels to the surface and back, so the distance to the surface is half of speed × time. Soft materials like curtains absorb sound and reduce echoes.'], eq: R`\text{distance} = \frac{\text{speed} \times \text{time}}{2}` },
        { h: 'Loudness and pitch', p: ['On an oscilloscope, a sound appears as a wave. A taller wave (bigger amplitude) is a louder sound. More waves squeezed onto the screen (higher frequency) is a higher pitch. Frequency is measured in hertz (Hz): vibrations per second.', 'Humans hear from about 20 Hz to 20 000 Hz; the top limit falls as we get older. Dogs and bats hear much higher frequencies; sound above our range is called ultrasound.'] },
        { h: 'Waves adding and cancelling', p: ['When two sound waves meet, they add together. If crests meet crests, they reinforce and the sound is louder. If crests meet troughs, they cancel and it is quieter. Noise-cancelling headphones listen to outside noise and play the opposite wave, so the two cancel.'], warn: '**What the simple picture leaves out.** “Louder = bigger amplitude” is true, but how loud a sound seems also depends on its pitch: our ears are most sensitive around 2000–5000 Hz, so a low hum needs much more energy to seem as loud. And noise cancelling works best for steady, low sounds; sudden or high-pitched sounds change too quickly to cancel.' }
      ],
      eqs: [[R`\text{speed} = \frac{\text{distance}}{\text{time}}`, 'about 340 m/s in air'], [R`d = \frac{v t}{2}`, 'echo distance'], [R`f = \frac{1}{T}`, 'frequency from the time T for one wave']],
      how: ['For echoes, halve the total distance (there and back).', 'On an oscilloscope: height → loudness; waves per screen → pitch.', 'For frequency, find the time for one wave and divide 1 by it.', 'Remember sound needs a medium.'],
      sum: ['Sound is a vibration passed through particles; no sound in a vacuum.', 'Air ~340 m/s; faster in liquids and solids.', 'Echo distance = speed × time ÷ 2.', 'Amplitude → loudness; frequency → pitch; we hear 20–20 000 Hz.', 'Waves can reinforce or cancel.'],
      probs: [
        { l: 1, q: 'Why can’t astronauts hear sounds through empty space?', a: 'There are no particles to carry the vibrations', s: ['Sound needs a medium; space is almost a vacuum.'] },
        { l: 1, q: 'On an oscilloscope, how does the trace change when a sound gets louder?', a: 'The waves get taller (bigger amplitude)', s: ['The number of waves on the screen stays the same if the pitch does not change.'] },
        { l: 1, q: 'How does the trace change when the pitch gets higher?', a: 'The waves get closer together (more waves on the screen)', s: ['Higher frequency means more vibrations per second.'] },
        { l: 2, q: 'You shout towards a cliff and hear the echo 2.0 s later. How far away is the cliff? (Sound travels at 340 m/s.)', a: '340 m', s: ['The sound travels 340 × 2.0 = 680 m there and back.', 'Distance = 680 ÷ 2 = 340 m.'] },
        { l: 2, q: 'You hear thunder 6.0 s after you see the lightning. How far away was it?', a: 'About 2 km', s: ['Light arrives almost instantly; sound takes 6.0 s: 340 × 6.0 = 2040 m.'] },
        { l: 2, q: 'One complete wave takes 4 milliseconds (0.004 s) on an oscilloscope. What is the frequency?', a: '250 Hz', s: ['f = 1 ÷ 0.004 = 250 Hz.'] },
        { l: 2, q: 'How do noise-cancelling headphones work?', a: 'They play a sound wave that is the opposite of the noise, so the two cancel', s: ['Where the noise has a crest, the headphones produce a trough.'] },
        { l: 2, q: 'A dog whistle produces sound at about 30 000 Hz. Why can dogs hear it but people cannot?', a: 'It is above the human limit of about 20 000 Hz', s: ['Dogs can hear up to about 45 000 Hz.'] },
        { l: 3, q: 'Two loudspeakers play the same steady note. As you walk across the room, the sound gets louder and quieter, louder and quieter. Explain why.', a: 'The two waves reinforce in some places and cancel in others', s: ['At some spots crests from both speakers arrive together: louder.', 'At others a crest from one meets a trough from the other: quieter.'] },
        { l: 3, q: 'Someone hits a steel railway line 1 km away. Sound travels at 5000 m/s in steel and 340 m/s in air. How long does each sound take to reach you, and why might you hear two bangs?', a: '0.2 s through the rail; 2.9 s through the air', s: ['Through steel: 1000 ÷ 5000 = 0.2 s.', 'Through air: 1000 ÷ 340 = 2.9 s.', 'The sound through the rail arrives about 2.7 s before the sound through the air.'] }
      ]
    }
  });
})();
/* ---- notes-ks3c.js ---- */
/* Geodesic: notes and ten-problem sets for KS3 outline topics, part 2 (colour, circuits, magnets, tides, space, plate tectonics). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'ks3-colour': {
      big: 'White light is not one colour but a mixture of all the colours of the rainbow. A prism spreads them apart because each colour bends by a different amount. Objects look coloured because they reflect some colours and absorb the rest, and filters let only their own colour through.',
      sec: [
        { h: 'Dispersion: splitting white light', p: ['When white light passes through a prism, each colour refracts (bends) by a slightly different amount: violet bends most and red least. The colours spread out into a spectrum: red, orange, yellow, green, blue, indigo, violet. Newton showed in 1666 that a second prism can recombine them into white light, proving the colours were in the white light all along.', 'Rainbows are the same effect, with raindrops acting as tiny prisms.'] },
        { h: 'Adding coloured lights', p: ['The primary colours of light are red, green and blue. Shining them together on a white screen adds them:'], list: ['Red + green = yellow.', 'Red + blue = magenta.', 'Green + blue = cyan.', 'Red + green + blue = white.'] },
        { h: 'Filters subtract colours', p: ['A coloured filter lets its own colour through and absorbs the rest. A red filter passes red light only. White light through a red filter and then a blue filter gives no light at all: the red filter removes the blue, and the blue filter removes the red.'] },
        { h: 'Why objects look coloured', p: ['A surface reflects some colours and absorbs others; we see the colours it reflects. A red apple reflects red and absorbs the rest. A white surface reflects all colours; a black one absorbs them all.', 'Under coloured light things can change colour. In pure red light, a green leaf has no green light to reflect and absorbs the red, so it looks black.'] },
        { h: 'Seeing colour', p: ['Our eyes have three kinds of colour-sensing cells (cones), most sensitive to red, green and blue light. The brain compares their signals to produce the colour we see. That is why screens can make every colour from tiny red, green and blue pixels.'], warn: '**Colour is partly in the eye.** A pure yellow light (one wavelength, like a sodium street lamp) and a mixture of red and green light look exactly the same to us, but they are physically different, and a prism would split the mixture while leaving the pure yellow alone. Pigments also behave differently from lights: mixing paints subtracts colours, which is why paint primaries are usually magenta, yellow and cyan.' }
      ],
      eqs: [[R`\text{R} + \text{G} + \text{B} = \text{white}`, 'adding coloured lights'], [R`\text{violet bends most, red least}`, 'dispersion in a prism']],
      how: ['For a filter, ask which colours get through.', 'For a surface, ask which colours arrive and which of those it reflects.', 'If none of the arriving colours is reflected, it looks black.', 'For lights, add them using the colour-mixing rules.'],
      sum: ['White light is a mixture of colours.', 'Prisms disperse light: violet bends most.', 'Light primaries: red, green, blue; all three make white.', 'Filters transmit their own colour only.', 'Objects reflect their own colour and absorb the rest.'],
      probs: [
        { l: 1, q: 'List the colours of the spectrum in order, starting with red.', a: 'Red, orange, yellow, green, blue, indigo, violet', s: ['A memory aid: Richard Of York Gave Battle In Vain.'] },
        { l: 1, q: 'Why does a red apple look red in white light?', a: 'It reflects red light and absorbs the other colours', s: ['Only the red part of the white light reaches our eyes from the apple.'] },
        { l: 1, q: 'What does a green filter do to white light?', a: 'Lets green through and absorbs the other colours', s: ['The light that comes out is green.'] },
        { l: 2, q: 'What colour does a green leaf look in red light?', a: 'Black', s: ['The leaf only reflects green; the red light is absorbed, so no light comes back.'] },
        { l: 2, q: 'A red light and a green light shine on the same white screen. What colour do you see?', a: 'Yellow', s: ['Red + green light add to make yellow.'] },
        { l: 2, q: 'White light passes through a red filter and then a blue filter. What comes out?', a: 'No light', s: ['After the red filter only red is left, and the blue filter absorbs red.'] },
        { l: 2, q: 'Why do TV and phone screens use only red, green and blue pixels?', a: 'Our eyes have three kinds of colour cells, so mixing those three can match almost any colour we see', s: ['Different brightnesses of red, green and blue stimulate the cones in the same way as other colours would.'] },
        { l: 2, q: 'Which colour is bent most by a prism, and which least?', a: 'Violet most, red least', s: ['Glass slows violet light slightly more than red.'] },
        { l: 3, q: 'What colour does a yellow banana look under blue light? Explain.', a: 'Black (very dark)', s: ['A yellow surface reflects red and green (which our eyes see as yellow) and absorbs blue.', 'Under blue light, there is nothing it can reflect.'] },
        { l: 3, q: 'A sodium street lamp gives out pure yellow light. A screen makes “yellow” from red and green pixels. They look identical. How could you show they are physically different?', a: 'Pass each through a prism: the screen’s yellow splits into red and green, the lamp’s does not', s: ['A prism separates light by colour (wavelength).', 'The lamp’s single wavelength stays one line of yellow; the screen’s mixture splits.', 'Our eyes cannot tell them apart because they stimulate our cones the same way.'] }
      ]
    },

    'ks3-parallel': {
      big: 'In a series circuit there is one path, so the current is the same everywhere. In a parallel circuit the current splits between branches and joins up again, and each branch gets the full voltage of the supply. Resistance, the voltage divided by the current, tells you how hard it is to push current through a component.',
      sec: [
        { h: 'Current: series and parallel', p: ['Current is the flow of charge, measured in amps (A) with an ammeter connected in series. In a series circuit the current is the same at every point. In a parallel circuit the current splits at a junction: the currents in the branches add up to the current from the supply, because charge cannot vanish or pile up.'] },
        { h: 'Voltage', p: ['Voltage (potential difference) measures the energy given to or taken from the charge, in volts (V), using a voltmeter connected in parallel across a component.', 'In series, the supply voltage is shared between the components. In parallel, every branch has the full supply voltage across it. That is why two lamps in parallel are each as bright as one lamp alone, while two in series are dimmer.'] },
        { h: 'Resistance', p: ['Resistance is how much a component opposes the current, measured in ohms (Ω). It is the voltage across the component divided by the current through it. For the same voltage, a bigger resistance means a smaller current.'], eq: R`R = \frac{V}{I}` },
        { h: 'Why homes are wired in parallel', list: ['Every appliance gets the full mains voltage.', 'Each can be switched on and off on its own.', 'If one breaks, the others keep working (unlike old series fairy lights, where one broken bulb put them all out).'] },
        { h: 'Adding branches', p: ['Each new parallel branch gives the current another path, so the total current from the supply goes up and the total resistance of the circuit goes down. That is why plugging too many appliances into one socket can draw a dangerously large current.'], warn: '**Ideal meters and wires.** These rules assume connecting wires have no resistance, ammeters do not slow the current and voltmeters take no current. Real meters disturb a circuit slightly, and real batteries lose voltage when they supply big currents, so measured values never match the ideal numbers exactly.' }
      ],
      eqs: [[R`R = V/I`, 'resistance in Ω, voltage in V, current in A'], [R`I_{\text{supply}} = I_1 + I_2`, 'currents in parallel branches add'], [R`V_{\text{supply}} = V_1 + V_2`, 'voltages in series add']],
      how: ['Decide whether components are in series (one path) or parallel (separate branches).', 'Series: same current, voltages share. Parallel: same voltage, currents share.', 'Use R = V/I for each component.', 'Ammeters in series, voltmeters in parallel.'],
      sum: ['Series: one path, same current everywhere, voltage shared.', 'Parallel: branches; currents add up; each branch has the full voltage.', 'Resistance R = V ÷ I, in ohms.', 'Homes are wired in parallel.', 'More parallel branches: more total current, less total resistance.'],
      probs: [
        { l: 1, q: 'In a series circuit an ammeter by the cell reads 0.4 A. What does an ammeter between two lamps read?', a: '0.4 A', s: ['In series the current is the same everywhere.'] },
        { l: 1, q: 'A current of 3 A splits into two branches. One carries 1 A. What does the other carry?', a: '2 A', s: ['The branch currents add up to the total: 3 − 1 = 2 A.'] },
        { l: 1, q: 'A component has 6 V across it and 2 A through it. What is its resistance?', a: '3 Ω', s: ['R = V/I = 6 ÷ 2 = 3 Ω.'] },
        { l: 2, q: 'Two identical lamps are connected to a 6 V battery, first in series, then in parallel. What is the voltage across each lamp in each case, and which arrangement is brighter?', a: '3 V each in series; 6 V each in parallel, which is brighter', s: ['Series shares the voltage; parallel gives each lamp the full voltage.'] },
        { l: 2, q: 'What current flows through a 12 Ω resistor with 6 V across it?', a: '0.5 A', s: ['I = V/R = 6 ÷ 12 = 0.5 A.'] },
        { l: 2, q: 'In a parallel circuit of three lamps, one lamp breaks. What happens to the other two?', a: 'They stay lit', s: ['Each has its own complete path to the supply.'] },
        { l: 2, q: 'Two resistors in series are connected to a 9 V battery. The voltage across one is 4 V. What is the voltage across the other?', a: '5 V', s: ['The voltages in series add up to the supply: 9 − 4 = 5 V.'] },
        { l: 2, q: 'Old Christmas lights were wired in series. Why did one broken bulb make them all go out?', a: 'It broke the only path for the current', s: ['In series there is one loop; a gap anywhere stops the current everywhere.'] },
        { l: 3, q: 'A 6 Ω and a 3 Ω resistor are connected in parallel to a 6 V battery. Find the current in each, the total current and the total resistance. Is the total resistance bigger or smaller than either resistor?', a: '1 A and 2 A; 3 A; 2 Ω, smaller than either', s: ['Each has 6 V across it: 6 ÷ 6 = 1 A and 6 ÷ 3 = 2 A.', 'Total current = 3 A, so total resistance = 6 ÷ 3 = 2 Ω.', 'Adding a path always lowers the total resistance.'] },
        { l: 3, q: 'A kettle (10 A), a heater (8 A) and a toaster (4 A) are all plugged into one extension lead rated at 13 A. Why is this dangerous?', a: 'Together they draw 22 A, far more than the lead is designed for', s: ['They are in parallel, so their currents add: 10 + 8 + 4 = 22 A.', 'The wires heat up and could melt the insulation and start a fire.'] }
      ]
    },

    'ks3-magnets': {
      big: 'Magnets attract iron, steel, nickel and cobalt, and push or pull each other: like poles repel and unlike poles attract. Around every magnet is a magnetic field. An electric current makes a magnetic field too, so a coil of wire with a current becomes an electromagnet that can be switched on and off.',
      sec: [
        { h: 'Magnetic materials and poles', p: ['Only a few materials are magnetic: iron, steel, nickel and cobalt. Copper, aluminium, plastic and wood are not.', 'Every magnet has a north pole and a south pole. Like poles (north–north or south–south) repel; unlike poles (north–south) attract. A magnet attracts a magnetic material by making it into a temporary magnet.'] },
        { h: 'Magnetic fields', p: ['A magnetic field is the region around a magnet where magnetic materials and other magnets feel a force. We draw it with field lines that go from the north pole to the south pole; where the lines are close together the field is strongest, near the poles.', 'You can map a field with iron filings or a small plotting compass, whose needle lines up with the field.'] },
        { h: 'Earth is a magnet', p: ['Earth has a magnetic field, as if a huge bar magnet were buried inside it. A compass needle’s north pole points towards the Arctic. Since unlike poles attract, Earth’s magnetic pole up in the Arctic must actually be a south magnetic pole.', 'Earth’s field shields us from charged particles from the Sun; where they leak in near the poles they make the aurora.'] },
        { h: 'Electromagnets', p: ['A wire carrying an electric current has a magnetic field around it. Winding the wire into a coil concentrates the field, and putting an iron core inside makes it much stronger. This is an electromagnet. Its great advantage is that it can be switched on and off, and its strength can be changed.'], list: ['More current: stronger.', 'More turns of wire on the coil: stronger.', 'An iron core: much stronger.'] },
        { h: 'Uses', list: ['Scrapyard cranes lift steel and drop it when switched off.', 'Electric bells, door locks and relays.', 'Loudspeakers and electric motors.', 'MRI scanners in hospitals use very strong electromagnets.'], warn: '**Earth’s magnet is not a bar magnet.** The “buried bar magnet” is only a picture. The field is really made by electric currents in Earth’s molten iron outer core, and it wanders and even flips: north and south have swapped hundreds of times, which is recorded in volcanic rocks on the sea floor.' }
      ],
      eqs: [[R`\text{like poles repel, unlike poles attract}`, 'the rule for magnets'], [R`\text{field lines: N} \rightarrow \text{S}`, 'direction of field lines outside a magnet']],
      how: ['Check whether a material is magnetic (iron, steel, nickel, cobalt).', 'Decide which poles face each other to predict attraction or repulsion.', 'Draw field lines from N to S, never crossing.', 'To strengthen an electromagnet: more current, more turns, iron core.'],
      sum: ['Magnetic materials: iron, steel, nickel, cobalt.', 'Like poles repel; unlike poles attract.', 'Field lines run from N to S; closest together where the field is strongest.', 'Earth has a magnetic field; compasses point north.', 'Electromagnets: current + coil + iron core, and can be switched off.'],
      probs: [
        { l: 1, q: 'Which of these are attracted to a magnet: iron, copper, aluminium, nickel, steel, plastic?', a: 'Iron, nickel and steel', s: ['Copper, aluminium and plastic are not magnetic.'] },
        { l: 1, q: 'Two north poles are brought together. What happens?', a: 'They repel', s: ['Like poles repel.'] },
        { l: 1, q: 'Give three ways to make an electromagnet stronger.', a: 'More current, more turns, an iron core', s: ['Each increases the magnetic field of the coil.'] },
        { l: 2, q: 'Describe the field lines around a bar magnet.', a: 'They leave the north pole, curve round and enter the south pole; they are closest near the poles', s: ['Field lines never cross.'] },
        { l: 2, q: 'The north pole of a compass needle points towards the Arctic. What kind of magnetic pole must be there? Explain.', a: 'A south magnetic pole', s: ['Unlike poles attract, so the compass’s north pole must be pulled by a south pole.'] },
        { l: 2, q: 'Why does a scrapyard use an electromagnet rather than a permanent magnet to move scrap cars?', a: 'It can be switched off to drop the load', s: ['A permanent magnet could never let go of the steel.'] },
        { l: 2, q: 'A student counts how many paper clips an electromagnet picks up with 10, 20 and 30 turns of wire, getting 4, 8 and 12. Name the variable changed, the variable measured, and one variable kept the same. What pattern do the results show?', a: 'Changed: turns. Measured: paper clips. Kept the same: current (or core, clip size). Clips are proportional to turns.', s: ['Doubling the turns doubles the clips: 10 → 4, 20 → 8, 30 → 12.'] },
        { l: 2, q: 'Why would a copper core not make an electromagnet stronger?', a: 'Copper is not a magnetic material', s: ['Only magnetic materials such as iron become magnetised and add to the field.'] },
        { l: 3, q: 'A magnetic-levitation (maglev) train floats above its track. Use what you know about magnets to explain how it can float and why this lets it go very fast.', a: 'Magnetic forces hold it up instead of wheels, so there is no wheel friction', s: ['Electromagnets in the train and track repel (or attract from below), balancing the train’s weight.', 'With no wheels touching the rail, there is no rolling friction or wheel wear; only air resistance limits its speed.'] },
        { l: 3, q: 'Rocks on the sea floor on either side of a mid-ocean ridge are magnetised in stripes, alternately pointing north and south, and the pattern on one side mirrors the other. What does this show?', a: 'Earth’s field flips from time to time, and the sea floor spreads out from the ridge', s: ['New rock forms at the ridge and records the field direction as it cools.', 'When the field flips, the next rock is magnetised the other way.', 'The spreading carries the stripes away on both sides, producing a mirror-image pattern: key evidence for plate tectonics.'] }
      ]
    },

    'ks3-tides-eclipses': {
      big: 'The Moon’s gravity pulls on Earth’s oceans and raises two bulges of water; as Earth spins through them, most coasts get two high tides a day. When the Sun, Earth and Moon line up exactly, one casts its shadow on the other: an eclipse.',
      sec: [
        { h: 'How tides happen', p: ['The Moon pulls on everything on Earth, but more strongly on the near side than on the far side, because gravity weakens with distance. The ocean facing the Moon is pulled towards it a little more than Earth as a whole, and Earth as a whole is pulled a little more than the ocean on the far side. So the oceans are stretched into two bulges, one towards the Moon and one away from it.', 'Earth spins once a day underneath these bulges, so most places pass through two high tides and two low tides each day. High tides come about 12 hours 25 minutes apart, because the Moon moves on in its orbit while Earth turns.'] },
        { h: 'Spring and neap tides', p: ['The Sun raises tides too, about half as big as the Moon’s. At new Moon and full Moon, the Sun, Earth and Moon are lined up and their tides add: extra-high and extra-low spring tides (nothing to do with the season). At first and last quarter, the Sun and Moon pull at right angles and partly cancel: small neap tides.'] },
        { h: 'Solar eclipses', p: ['A solar eclipse happens when the Moon passes between the Sun and Earth and its shadow falls on Earth. It can only happen at new Moon. Where the Moon blocks the Sun completely, there is a total eclipse: the sky darkens and the Sun’s faint outer atmosphere, the corona, appears. Nearby there is only a partial eclipse.', 'Never look at the Sun directly, even during a partial eclipse: use eclipse glasses or a pinhole projector.'] },
        { h: 'Lunar eclipses', p: ['A lunar eclipse happens when Earth passes between the Sun and the Moon, and the Moon moves into Earth’s shadow. It can only happen at full Moon, and it is safe to watch. The Moon often turns a coppery red, because Earth’s atmosphere bends some red sunlight into the shadow, like all the world’s sunsets lighting the Moon.'] },
        { h: 'Why not every month?', p: ['The Moon’s orbit is tilted by about 5° to Earth’s orbit round the Sun. Most months the new Moon passes a little above or below the Sun, and the full Moon a little above or below Earth’s shadow. Eclipses only happen when a new or full Moon occurs near where the two orbits cross.'], warn: '**Two bulges, not one.** A common mistake is to think the Moon simply pulls the water towards it, which would give one bulge and one high tide a day. The far-side bulge exists because tides come from the difference in the Moon’s pull across Earth. Real tides are also shaped by coastlines and ocean basins, so their timing and size vary a lot from place to place: the Bay of Fundy has tides over 15 m high, while most of the Mediterranean has less than half a metre.' }
      ],
      eqs: [[R`\text{high tides} \approx 12\ \text{h}\ 25\ \text{min apart}`, 'tidal timing'], [R`\text{solar eclipse: new Moon};\ \text{lunar eclipse: full Moon}`, 'when eclipses can happen']],
      how: ['For tides, think of the Moon’s pull being stronger on the near side and weaker on the far side.', 'For spring and neap tides, check whether the Sun and Moon are lined up or at right angles.', 'For eclipses, decide which body is in the middle: Moon (solar) or Earth (lunar).'],
      sum: ['The Moon’s gravity raises two tidal bulges; two high tides a day.', 'Spring tides: Sun and Moon aligned. Neap tides: at right angles.', 'Solar eclipse: Moon between Sun and Earth (new Moon).', 'Lunar eclipse: Earth between Sun and Moon (full Moon); the Moon turns red.', 'The Moon’s 5° tilt means eclipses do not happen every month.'],
      probs: [
        { l: 1, q: 'What causes the tides?', a: 'Mainly the Moon’s gravity (with help from the Sun’s)', s: ['It pulls the oceans into two bulges.'] },
        { l: 1, q: 'How many high tides do most places have each day?', a: 'Two', s: ['Earth spins through both bulges each day.'] },
        { l: 1, q: 'Which body is in the middle during a solar eclipse?', a: 'The Moon', s: ['The Moon is between the Sun and Earth, casting its shadow on Earth.'] },
        { l: 2, q: 'High tide at a harbour is at 06:00. Roughly when is the next high tide?', a: 'About 18:25', s: ['High tides are about 12 hours 25 minutes apart.'] },
        { l: 2, q: 'What are spring and neap tides, and when do they happen?', a: 'Spring: largest tides, at new and full Moon. Neap: smallest, at first and last quarter.', s: ['Spring tides happen when the Sun and Moon line up; neap tides when they pull at right angles.'] },
        { l: 2, q: 'Why does the Moon often look red during a total lunar eclipse?', a: 'Earth’s atmosphere bends red sunlight into Earth’s shadow', s: ['Blue light is scattered away in the air (which is why sunsets are red); the red light reaches the Moon.'] },
        { l: 2, q: 'Why don’t we get a solar eclipse every new Moon?', a: 'The Moon’s orbit is tilted about 5°, so it usually passes above or below the Sun', s: ['The Sun, Moon and Earth must line up exactly.'] },
        { l: 2, q: 'Why should you never look directly at a partial solar eclipse?', a: 'The uncovered part of the Sun is still bright enough to damage your eyes', s: ['Use certified eclipse glasses or project an image through a pinhole.'] },
        { l: 3, q: 'The Sun is 1 390 000 km across and 150 000 000 km away; the Moon is 3474 km across and on average 384 000 km away. Compare how big each looks (diameter ÷ distance). When the Moon is furthest away (406 000 km), what kind of solar eclipse do you get?', a: 'Almost exactly the same size; at its furthest the Moon looks smaller, giving a ring (annular) eclipse', s: ['Sun: 1 390 000 ÷ 150 000 000 = 0.0093. Moon: 3474 ÷ 384 000 = 0.0090.', 'At 406 000 km: 3474 ÷ 406 000 = 0.0086, smaller than the Sun.', 'Then the Moon cannot cover the Sun completely and a ring of sunlight remains.'] },
        { l: 3, q: 'Explain why there is a high tide on the side of Earth facing away from the Moon.', a: 'The Moon pulls Earth’s centre more strongly than the far-side ocean, so the ocean is left behind', s: ['Gravity weakens with distance: the near-side ocean is pulled most, Earth’s centre less, the far-side ocean least.', 'Compared with Earth’s centre, the near ocean is pulled towards the Moon and the far ocean is effectively left behind, away from it.', 'Both effects stretch the oceans into two bulges.'] }
      ]
    },

    'ks3-solar-system': {
      big: 'Stars and planets are born in huge clouds of gas and dust called nebulae, pulled together by gravity. Our Solar System formed this way about 4.6 billion years ago, leaving behind planets, moons, asteroids and comets. The Sun is one of billions of stars in our galaxy, the Milky Way, which is one of billions of galaxies.',
      sec: [
        { h: 'From nebula to Solar System', p: ['A nebula is a cloud of gas and dust in space. When part of it collapses under its own gravity, it spins faster and flattens into a disc. Most of the material falls to the centre and becomes a star. In the disc, dust grains stick together, growing into rocks, then bigger and bigger bodies that sweep up more material, until planets form.', 'That is why all the planets orbit the Sun in the same direction and in nearly the same flat plane.'] },
        { h: 'Leftovers: asteroids, comets and meteors', p: ['Asteroids are rocky leftovers, mostly in the asteroid belt between Mars and Jupiter. Comets are lumps of ice and dust from the outer Solar System that grow glowing tails when they come close to the Sun.', 'A meteor is the streak of light from a small piece of rock burning up in our atmosphere; a meteorite is a piece that reaches the ground. Large impacts leave craters, and an asteroid about 10 km across that hit Mexico 66 million years ago helped wipe out the dinosaurs.'] },
        { h: 'How the Moon formed', p: ['The best explanation is the giant-impact idea: about 4.5 billion years ago, a body about the size of Mars crashed into the young Earth. Rock thrown out from the collision gathered in orbit and formed the Moon. Evidence includes Moon rocks that are very similar to Earth’s outer rocks, and the Moon’s small iron core.'] },
        { h: 'Galaxies', p: ['A galaxy is an enormous group of stars, gas and dust held together by gravity. Our galaxy, the Milky Way, contains over 100 billion stars and is about 100 000 light-years across; the Sun is roughly halfway from the centre to the edge. There are billions of galaxies in the observable Universe.', 'A light-year is the distance light travels in a year, about 9.5 million million km. Light from the Sun takes about 8 minutes to reach us, so we see the Sun as it was 8 minutes ago.'] },
        { h: 'The scale of space', p: ['Space is mostly empty. If the Sun were a 1 m ball, Earth would be a 9 mm pea about 107 m away, Neptune would be over 3 km away, and the nearest other star would be about 29 000 km away.'], warn: '**Scientific ideas carry different weights of evidence.** The nebula model is supported by images of discs around young stars, where planets can be seen forming. The giant-impact idea for the Moon is the best current explanation, but some details still do not fit (for example, why the Moon’s rocks are so similar to Earth’s that little of the impactor seems to be left), so scientists are still testing versions of it.' }
      ],
      eqs: [[R`1\ \text{light-year} \approx 9.5\times10^{12}\ \text{km}`, 'distance light travels in one year'], [R`\text{time} = \frac{\text{distance}}{\text{speed}}`, 'light travel times']],
      how: ['For formation questions, follow the steps: cloud → collapse → disc → star in the middle → planets from dust.', 'Sort objects by size: moon < planet < star < solar system < galaxy < Universe.', 'For light travel time, divide the distance by the speed of light.', 'Say what evidence supports an idea, and how strong it is.'],
      sum: ['Stars and planets form from collapsing nebulae.', 'Asteroids, comets and meteoroids are leftovers; impacts make craters.', 'The Moon probably formed from a giant impact on the early Earth.', 'The Milky Way has over 100 billion stars; there are billions of galaxies.', 'A light-year is a distance; looking far away means looking back in time.'],
      probs: [
        { l: 1, q: 'What is a nebula?', a: 'A cloud of gas and dust in space', s: ['Stars and planets form inside nebulae.'] },
        { l: 1, q: 'What is a galaxy?', a: 'A huge group of stars, gas and dust held together by gravity', s: ['Ours is the Milky Way.'] },
        { l: 1, q: 'Where is the asteroid belt?', a: 'Between the orbits of Mars and Jupiter', s: ['It holds millions of rocky bodies.'] },
        { l: 2, q: 'Put these in order of size, smallest first: galaxy, planet, Universe, star, Solar System.', a: 'Planet, star, Solar System, galaxy, Universe', s: ['A star is bigger than its planets; the Solar System includes the Sun and all its planets.'] },
        { l: 2, q: 'Give two pieces of evidence for the giant-impact idea of how the Moon formed.', a: 'Moon rocks are very like Earth’s outer rocks; the Moon has only a small iron core', s: ['Both fit the Moon forming from material blasted out of Earth’s outer layers.'] },
        { l: 2, q: 'Why does the Moon show many more craters than Earth, though both have been hit just as often?', a: 'The Moon has no air, weather or moving plates to remove them', s: ['On Earth, small rocks burn up in the atmosphere, and craters are worn away by weather or destroyed as the crust moves.'] },
        { l: 2, q: 'What is the difference between a meteor and a meteorite?', a: 'A meteor is the streak of light; a meteorite is a piece that reaches the ground', s: ['Most meteors burn up completely.'] },
        { l: 2, q: 'Light from the Sun takes about 8 minutes to reach Earth. What does that mean about what we see?', a: 'We see the Sun as it was 8 minutes ago', s: ['If the Sun changed, we would not know for 8 minutes.'] },
        { l: 3, q: 'The asteroid that hit Earth 66 million years ago was about 10 km across, with a mass of about 1.6 × 10¹⁵ kg, travelling at about 20 000 m/s. Using kinetic energy = ½ × mass × speed², estimate its energy. The largest nuclear bomb ever tested released about 2 × 10¹⁷ J. Compare.', a: 'About 3 × 10²³ J: over a million times the largest bomb', s: ['KE = ½ × 1.6 × 10¹⁵ × (2 × 10⁴)² = 3.2 × 10²³ J.', '3.2 × 10²³ ÷ 2 × 10¹⁷ ≈ 1.6 million.'] },
        { l: 3, q: 'Make a scale model: if the Sun (1 390 000 km across) were a 1 m ball, how big would Earth (12 700 km across) be, and how far away would it be (150 000 000 km)?', a: 'About 9 mm across, about 108 m away', s: ['Scale factor = 1 m ÷ 1 390 000 km.', 'Earth: 12 700 ÷ 1 390 000 = 0.0091 m = 9 mm.', 'Distance: 150 000 000 ÷ 1 390 000 = 108 m. Space is mostly empty.'] }
      ]
    },

    'ks3-earth': {
      big: 'Earth’s outer shell is cracked into giant tectonic plates that move a few centimetres a year, carried by slow flow in the hot rock beneath. Where plates pull apart, new crust forms; where they collide, mountains rise and volcanoes erupt; where they grind past each other, earthquakes strike.',
      sec: [
        { h: 'Inside the Earth', list: ['Crust: the thin rocky outer layer, 5–70 km thick.', 'Mantle: hot rock nearly 2900 km deep. It is solid, but over millions of years it flows very slowly, like extremely thick putty.', 'Outer core: liquid iron and nickel. Its flowing creates Earth’s magnetic field.', 'Inner core: solid iron and nickel, as hot as the surface of the Sun but squeezed solid by the pressure.'], p: ['The crust and the rigid top of the mantle together form the lithosphere, which is broken into tectonic plates.'] },
        { h: 'Why plates move', p: ['The mantle is hotter at the bottom than at the top. Hot rock slowly rises and cooler rock sinks, setting up convection currents that drag on the plates above. At the same time, the cold, heavy edge of a plate sinking back into the mantle pulls the rest of the plate along.'] },
        { h: 'Plate boundaries', list: ['Constructive (pulling apart): magma rises to fill the gap and makes new crust, as along the Mid-Atlantic Ridge and in Iceland.', 'Destructive (colliding): a denser ocean plate sinks beneath another (subduction), causing deep earthquakes and explosive volcanoes, as along the Andes and in Japan. When two continents collide, neither sinks easily and the crust crumples into fold mountains: the Himalayas.', 'Conservative (sliding past): plates grind past each other, sticking and then suddenly slipping, causing earthquakes, as on the San Andreas Fault in California.'] },
        { h: 'Evidence for moving plates', list: ['The coastlines of South America and Africa fit together like jigsaw pieces.', 'The same fossils (such as the reptile Mesosaurus) and the same rock types are found on continents now separated by oceans.', 'Earthquakes and volcanoes are concentrated in lines along plate boundaries.', 'The sea floor is youngest at mid-ocean ridges and older further away, with mirror-image magnetic stripes on either side.', 'Satellite measurements now track the plates moving directly.'] },
        { h: 'An idea that waited for evidence', p: ['Alfred Wegener proposed “continental drift” in 1912, using the jigsaw fit and the fossils. Most geologists rejected it for decades, because he could not explain what force could move continents. In the 1960s, maps of the sea floor revealed spreading ridges and magnetic stripes, supplying the mechanism, and plate tectonics was accepted.'], warn: '**Two common misconceptions.** The mantle is not a sea of molten lava: it is solid rock that creeps very slowly, and magma forms only in particular places, such as above sinking plates. And “convection currents push the plates” is a simplification: measurements suggest the pull of sinking plate edges is often the bigger driving force.' }
      ],
      eqs: [[R`\text{distance} = \text{speed} \times \text{time}`, 'plate movement over long times'], [R`2.5\ \text{cm/yr} \times 10^6\ \text{yr} = 25\ \text{km}`, 'a typical plate speed adds up']],
      how: ['Name the layer, then its state (solid or liquid) and what it is made of.', 'Identify the boundary type from how the plates move, then its features.', 'Link each piece of evidence to what it shows.', 'For speeds, convert cm per year into km over millions of years.'],
      sum: ['Crust, mantle (solid but slowly flowing), liquid outer core, solid inner core.', 'The lithosphere is broken into plates moving a few cm per year.', 'Constructive: new crust. Destructive: subduction, volcanoes, fold mountains. Conservative: earthquakes.', 'Evidence: continental fit, fossils, earthquake and volcano belts, sea-floor stripes.', 'Wegener’s idea was accepted once a mechanism was found.'],
      probs: [
        { l: 1, q: 'Name the four main layers of the Earth, from the outside in.', a: 'Crust, mantle, outer core, inner core', s: ['The outer core is liquid; the inner core is solid.'] },
        { l: 1, q: 'What are tectonic plates?', a: 'Large pieces of Earth’s rigid outer layer (the lithosphere) that move slowly', s: ['They carry continents and ocean floor.'] },
        { l: 1, q: 'Name the three types of plate boundary.', a: 'Constructive, destructive and conservative', s: ['Pulling apart, colliding, and sliding past.'] },
        { l: 2, q: 'A plate moves 2.5 cm per year. How far does it move in 1 million years? In 100 million years?', a: '25 km; 2500 km', s: ['2.5 cm × 1 000 000 = 2 500 000 cm = 25 km.', '× 100 = 2500 km: about the width of an ocean.'] },
        { l: 2, q: 'Give two pieces of evidence that the continents were once joined.', a: 'Matching coastlines (South America and Africa); the same fossils and rocks on different continents', s: ['Either could also be explained another way on its own, but together they point the same way.'] },
        { l: 2, q: 'Why are there volcanoes along the west coast of South America?', a: 'An ocean plate is sinking beneath South America (subduction)', s: ['The sinking plate releases water that helps the mantle above it melt; the magma rises to form volcanoes.'] },
        { l: 2, q: 'How were the Himalayas formed?', a: 'India collided with Asia and the crust crumpled into fold mountains', s: ['Continental crust is too light to sink, so it buckles upwards. The Himalayas are still rising.'] },
        { l: 2, q: 'Why does the San Andreas Fault produce earthquakes but few volcanoes?', a: 'The plates slide past each other: friction builds up and releases suddenly, but no crust melts', s: ['There is no subduction and no pulling apart, so little magma forms.'] },
        { l: 3, q: 'Rock magnetised in a reversal of Earth’s field 780 000 years ago is found 39 km from a mid-ocean ridge. How fast is this side of the sea floor moving away from the ridge? How fast are the two plates separating?', a: '5 cm per year; 10 cm per year', s: ['39 km = 3 900 000 cm.', '3 900 000 ÷ 780 000 = 5 cm per year.', 'The other side moves away just as fast, so the plates separate at 10 cm per year.'] },
        { l: 3, q: 'Wegener had good evidence that the continents had moved, yet most scientists rejected his idea for about 50 years. Why, and what changed?', a: 'He could not explain how continents move; sea-floor spreading supplied the mechanism', s: ['Scientists wanted a mechanism, not just patterns.', 'In the 1960s, ridges, magnetic stripes and young sea floor showed new crust forming and plates moving.', 'Good science weighs evidence and mechanism together, and changes its mind when the evidence demands.'] }
      ]
    }
  });
})();
/* ---- notes-al3.js ---- */
/* Geodesic: notes and ten-problem sets for A Level outline topics, part 1 (Cambridge 9702 sections 1–5). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'al-units': {
      big: 'Physics is built on measurement, so it needs agreed units, a way to say how far to trust each number, and a way to handle quantities that have direction. Seven SI base units underpin every other unit; uncertainties combine by simple rules; and vectors are added nose to tail or split into perpendicular components.',
      sec: [
        { h: 'SI base units and homogeneity', p: ['The SI system has seven base units: kilogram (kg), metre (m), second (s), ampere (A), kelvin (K), mole (mol) and candela (cd). Every other unit is a product of powers of these: the newton is kg m s⁻², the joule kg m² s⁻², the volt kg m² s⁻³ A⁻¹.', 'An equation is homogeneous if every term has the same base units. A correct physical equation must be homogeneous, but a homogeneous equation is not necessarily correct: base units cannot detect a missing ½ or 2π.'], eq: R`[F] = \text{kg m s}^{-2},\quad [E] = \text{kg m}^2\text{s}^{-2},\quad [P] = \text{kg m}^2\text{s}^{-3}` },
        { h: 'Prefixes and estimates', list: ['pico p 10⁻¹², nano n 10⁻⁹, micro μ 10⁻⁶, milli m 10⁻³, centi c 10⁻².', 'kilo k 10³, mega M 10⁶, giga G 10⁹, tera T 10¹².'], p: ['Useful estimates: an adult’s mass 70 kg, walking speed 1.5 m/s, a car’s mass 1000–1500 kg, room height 3 m, the power of a kettle 2 kW.'] },
        { h: 'Errors: accuracy and precision', p: ['A systematic error shifts every reading the same way (a zero error, a miscalibrated meter, a consistent parallax). It makes results inaccurate and is not reduced by repeating.', 'Random errors scatter readings either side of the true value (reaction time, fluctuating readings). They make results imprecise and are reduced by repeating and averaging.', 'Accuracy is how close a result is to the true value; precision is how close repeated results are to each other.'] },
        { h: 'Combining uncertainties', p: ['The absolute uncertainty has the units of the quantity; the fractional uncertainty is the absolute uncertainty divided by the value (multiply by 100 for a percentage).'], list: ['Adding or subtracting quantities: add the absolute uncertainties.', 'Multiplying or dividing: add the fractional (percentage) uncertainties.', 'Raising to a power n: multiply the fractional uncertainty by n.'], eq: R`y = \frac{ab^2}{c}\;\Rightarrow\;\frac{\Delta y}{y} = \frac{\Delta a}{a} + 2\frac{\Delta b}{b} + \frac{\Delta c}{c}` },
        { h: 'Vectors', p: ['Vectors add nose to tail (triangle rule). Subtracting B means adding −B. A vector F at angle θ to the x-axis resolves into perpendicular components F cos θ and F sin θ, which can be handled separately and recombined with Pythagoras.'], eq: R`F_x = F\cos\theta,\qquad F_y = F\sin\theta,\qquad F = \sqrt{F_x^2 + F_y^2}`, warn: '**These uncertainty rules are worst-case.** Adding fractional uncertainties assumes every error pushes the same way at once. When errors are independent and random, they partly cancel, and university physics combines them in quadrature (√(Σ(Δ/x)²)), giving smaller totals. Neither rule rescues a result from an unnoticed systematic error, which is why independent methods are compared.' }
      ],
      eqs: [[R`\text{N} = \text{kg m s}^{-2},\ \text{J} = \text{kg m}^2\text{s}^{-2},\ \text{W} = \text{kg m}^2\text{s}^{-3}`, 'derived units in base units'], [R`\frac{\Delta(ab)}{ab} = \frac{\Delta a}{a} + \frac{\Delta b}{b}`, 'products and quotients'], [R`\Delta(a \pm b) = \Delta a + \Delta b`, 'sums and differences'], [R`\frac{\Delta(a^n)}{a^n} = n\frac{\Delta a}{a}`, 'powers'], [R`F_x = F\cos\theta`, 'resolving a vector']],
      how: ['For units, reduce each side to base units and compare.', 'Work out percentage uncertainties for each measured quantity first.', 'Combine with the rules, then convert back to an absolute uncertainty and round it to one or two significant figures.', 'For vectors, resolve everything along two perpendicular directions.'],
      sum: ['Seven SI base units; all others are combinations.', 'Homogeneity is necessary, not sufficient.', 'Systematic errors affect accuracy; random errors affect precision.', 'Add absolute uncertainties for sums, fractional ones for products; multiply by n for powers.', 'Resolve vectors into perpendicular components.'],
      probs: [
        { l: 1, q: 'Express the joule in SI base units.', a: 'kg m² s⁻²', s: ['J = N m = (kg m s⁻²) × m = kg m² s⁻².'] },
        { l: 1, q: 'Write 3.2 GHz and 470 nm in standard form with SI units.', a: '3.2 × 10⁹ Hz; 4.70 × 10⁻⁷ m', s: ['G = 10⁹; n = 10⁻⁹.'] },
        { l: 1, q: 'Explain the difference between accuracy and precision.', a: 'Accuracy: closeness to the true value. Precision: closeness of repeated readings to each other.', s: ['Precise results can still be inaccurate if there is a systematic error.'] },
        { l: 2, q: 'Show that v² = u² + 2as is homogeneous.', a: 'Every term has units m² s⁻²', s: ['v², u²: (m s⁻¹)² = m² s⁻².', '2as: (m s⁻²)(m) = m² s⁻² (2 has no units).'] },
        { l: 2, q: 'A pendulum has length L = 1.000 ± 0.005 m and period T = 2.00 ± 0.02 s. Find g = 4π²L/T² and its absolute uncertainty.', a: '(9.9 ± 0.3) m/s²', s: ['g = 4π² × 1.000 ÷ 2.00² = 9.87 m/s².', '% uncertainty = 0.5% + 2 × 1.0% = 2.5%.', 'Δg = 0.025 × 9.87 = 0.25 m/s², rounded to (9.9 ± 0.3) m/s². The period’s uncertainty counts twice because T is squared.'] },
        { l: 2, q: 'V = 6.0 ± 0.1 V and I = 0.50 ± 0.02 A. Find R = V/I with its uncertainty.', a: '12.0 ± 0.7 Ω', s: ['R = 12.0 Ω.', '% uncertainty = 1.7% + 4.0% = 5.7%.', 'ΔR = 0.057 × 12.0 = 0.7 Ω.'] },
        { l: 2, q: 'Resolve a 50 N force acting at 30° above the horizontal into horizontal and vertical components.', a: '43 N horizontal, 25 N vertical', s: ['50 cos 30° = 43.3 N; 50 sin 30° = 25.0 N.'] },
        { l: 2, q: 'A car going east at 20 m/s turns and goes north at 20 m/s. Find its change in velocity.', a: '28 m/s towards the north-west', s: ['Δv = v_{final} − v_{initial} = (20 north) + (20 west).', '|Δv| = √(20² + 20²) = 28.3 m/s, pointing north-west.'] },
        { l: 3, q: 'The drag on a car is F = ½CρAv², where ρ is air density and A the frontal area. Show that C has no units. If instead F = kv², what are the base units of k?', a: 'C is dimensionless; k is in kg m⁻¹', s: ['ρAv² has units (kg m⁻³)(m²)(m² s⁻²) = kg m s⁻², the same as F, so C has no units.', 'k = F/v²: (kg m s⁻²) ÷ (m² s⁻²) = kg m⁻¹.'] },
        { l: 3, q: 'A wire of diameter d = 0.50 ± 0.01 mm and length L = 1.20 ± 0.01 m has resistance R = 2.4 ± 0.1 Ω. Find its resistivity ρ = RA/L, where A = πd²/4, with its uncertainty. Which measurement contributes most?', a: '(3.9 ± 0.4) × 10⁻⁷ Ω m; the resistance and diameter together dominate', s: ['A = π × (0.25 × 10⁻³)² = 1.96 × 10⁻⁷ m²; ρ = 2.4 × 1.96 × 10⁻⁷ ÷ 1.20 = 3.9 × 10⁻⁷ Ω m.', '% uncertainty = 4.2% (R) + 2 × 2.0% (d) + 0.8% (L) = 9.0%.', 'Δρ = 0.35 × 10⁻⁷ Ω m. The diameter is squared, so a micrometer reading matters as much as the resistance.'] }
      ]
    },

    'al-kinematics': {
      big: 'Kinematics describes motion without asking what causes it. Displacement, velocity and acceleration are linked by gradients and areas of graphs, and for constant acceleration those links become the four SUVAT equations, each derived directly from one straight-line velocity–time graph.',
      sec: [
        { h: 'Definitions', p: ['Displacement s is distance in a stated direction. Velocity is the rate of change of displacement; acceleration is the rate of change of velocity. Speed and distance are their scalar counterparts.'], eq: R`v = \frac{\Delta s}{\Delta t},\qquad a = \frac{\Delta v}{\Delta t}` },
        { h: 'Graphs', list: ['Displacement–time: gradient = velocity.', 'Velocity–time: gradient = acceleration; area under the line = displacement (areas below the time axis count as negative).', 'Acceleration–time: area = change in velocity.'], p: ['For curved graphs, the gradient at an instant is the gradient of the tangent there.'] },
        { h: 'Deriving SUVAT', p: ['For constant acceleration the v–t graph is a straight line from u to v over time t. Its gradient gives v = u + at. Its area is a trapezium: s = ½(u + v)t. Substituting v = u + at into that gives s = ut + ½at², and eliminating t between the first two gives v² = u² + 2as.'], eq: R`v = u + at,\quad s = \tfrac12(u+v)t,\quad s = ut + \tfrac12at^2,\quad v^2 = u^2 + 2as` },
        { h: 'Free fall and measuring g', p: ['Without air resistance, everything near Earth falls with acceleration g ≈ 9.81 m/s². To measure it, drop an object from rest through a measured height h and time the fall, perhaps with an electromagnet release and a trapdoor switch, or with light gates: g = 2h/t².', 'Two light gates measuring the speed at two heights avoid needing the exact release moment: g = (v₂² − v₁²)/(2Δh).'] },
        { h: 'Two dimensions', p: ['Horizontal and vertical motions are independent. A projectile with no air resistance moves at constant horizontal velocity while accelerating downwards at g, so its path is a parabola. Each direction gets its own SUVAT, linked only by the common time.'], warn: '**SUVAT’s hidden assumption is constant acceleration.** It fails whenever forces change: drag that grows with speed, a car whose engine force changes with gear, or a spring. And g itself is not quite constant: it is 9.78 m/s² at the equator and 9.83 m/s² at the poles, and falls with altitude. For short drops in a lab, air resistance and timing are usually the biggest sources of error.' }
      ],
      eqs: [[R`v = u + at`, 'no s'], [R`s = \tfrac12(u + v)t`, 'no a'], [R`s = ut + \tfrac12at^2`, 'no v'], [R`v^2 = u^2 + 2as`, 'no t'], [R`g = 9.81\ \text{m s}^{-2}`, 'free-fall acceleration']],
      how: ['Choose a positive direction and give every vector a sign.', 'List s, u, v, a, t; pick the equation without the unknown you do not need.', 'For graphs, decide whether you need a gradient or an area.', 'In 2D, split into horizontal and vertical, connected by time.'],
      sum: ['v = ds/dt, a = dv/dt; vectors with signs.', 's–t gradient = v; v–t gradient = a, area = s.', 'Four SUVAT equations for constant a only.', 'g = 2h/t² from rest; or (v₂² − v₁²)/2Δh with light gates.', 'Perpendicular components are independent.'],
      probs: [
        { l: 1, q: 'A car accelerates uniformly from rest to 27 m/s in 9.0 s. Find its acceleration.', a: '3.0 m/s²', s: ['a = (27 − 0) ÷ 9.0 = 3.0 m/s².'] },
        { l: 1, q: 'A runner moves at 10 m/s for 5.0 s, then slows uniformly to rest in 4.0 s. How far does she travel?', a: '70 m', s: ['Rectangle: 10 × 5.0 = 50 m. Triangle: ½ × 10 × 4.0 = 20 m. Total 70 m.'] },
        { l: 1, q: 'What does the gradient of a displacement–time graph represent?', a: 'Velocity', s: ['Gradient = Δs/Δt.'] },
        { l: 2, q: 'Derive v² = u² + 2as from v = u + at and s = ½(u + v)t.', a: 'Eliminate t', s: ['t = (v − u)/a.', 's = ½(u + v)(v − u)/a = (v² − u²)/(2a).', 'So v² = u² + 2as.'] },
        { l: 2, q: 'A ball is dropped from rest from 20 m. How long does it take to fall, and how fast is it going at the bottom? (g = 9.81 m/s²)', a: '2.02 s; 19.8 m/s', s: ['t = √(2s/g) = √(40/9.81) = 2.02 s.', 'v = √(2gs) = 19.8 m/s.'] },
        { l: 2, q: 'A ball released from rest falls 0.800 m in 0.404 s. Calculate g.', a: '9.80 m/s²', s: ['s = ½gt² ⇒ g = 2s/t² = 1.600 ÷ 0.1632 = 9.80 m/s².'] },
        { l: 2, q: 'A stone is thrown upwards at 15 m/s from the top of a 25 m cliff. When does it hit the ground below, and how fast?', a: '4.26 s; 26.7 m/s', s: ['Up positive: −25 = 15t − 4.905t².', '4.905t² − 15t − 25 = 0 ⇒ t = [15 + √(225 + 490.5)] ÷ 9.81 = 4.26 s.', 'v² = 15² + 2 × 9.81 × 25 = 715.5 ⇒ 26.7 m/s downwards.'] },
        { l: 2, q: 'A 5.0 cm card blocks light gate 1 for 25 ms and light gate 2, 0.50 m further along a track, for 12.5 ms. Find the trolley’s acceleration, assuming it is uniform.', a: '12 m/s²', s: ['v₁ = 0.050 ÷ 0.025 = 2.0 m/s; v₂ = 0.050 ÷ 0.0125 = 4.0 m/s.', 'a = (v₂² − v₁²)/(2s) = (16 − 4) ÷ 1.0 = 12 m/s².'] },
        { l: 3, q: 'In a reaction-time test a ruler falls 20 cm before it is caught. What is the reaction time? Why does this matter when timing a 1 m drop by hand?', a: '0.20 s; it is nearly half of the 0.45 s fall time', s: ['t = √(2 × 0.20 ÷ 9.81) = 0.20 s.', 'A 1 m drop takes √(2 ÷ 9.81) = 0.45 s, so hand timing could be out by tens of percent; use electronic timing.'] },
        { l: 3, q: 'A falling ball passes light gate A at 2.00 m/s and light gate B, 0.600 m lower, at 3.97 m/s. Find g. Why is this method better than timing from release?', a: '9.80 m/s²; it does not need the release instant', s: ['g = (v_B² − v_A²)/(2Δh) = (15.76 − 4.00) ÷ 1.20 = 9.80 m/s².', 'Release mechanisms add uncertain delays; two speed measurements avoid them, though the gates must be exactly 0.600 m apart vertically.'] }
      ]
    },

    'al-dynamics': {
      big: 'Newton’s laws link force to motion through momentum. A resultant force equals the rate of change of momentum, which for a constant mass is ma. Forces always come in equal and opposite pairs on different bodies. Drag, which grows with speed, explains why falling objects reach a terminal velocity.',
      sec: [
        { h: 'Momentum and Newton’s laws', p: ['Linear momentum is p = mv, a vector in kg m s⁻¹.'], list: ['First law: a body stays at rest or moves with constant velocity unless a resultant force acts on it.', 'Second law: the resultant force is proportional to the rate of change of momentum and in the same direction: F = Δp/Δt. For constant mass, F = ma.', 'Third law: if body A exerts a force on body B, then B exerts an equal and opposite force of the same type on A.'] },
        { h: 'Mass and weight', p: ['Mass is the property that resists changes in motion (inertia). Weight is the gravitational force on a mass in a gravitational field, W = mg. On the Moon an object’s weight is about a sixth of its Earth value, but its mass, and so the force needed to accelerate it horizontally, is unchanged.'] },
        { h: 'Using F = Δp/Δt', p: ['When mass flows (a jet of water, a rocket’s exhaust) or when a collision reverses a velocity, work with momentum change directly. A ball rebounding from a wall changes momentum by m(u + v), not m(v − u), because the direction reverses.'], eq: R`F = \frac{\Delta p}{\Delta t} = \frac{\Delta m}{\Delta t}v\quad(\text{steady stream of mass})` },
        { h: 'Friction and drag', p: ['Friction opposes relative motion of surfaces. Drag (air resistance) opposes motion through a fluid and increases with speed, roughly as v² for everyday objects (and as v for tiny, slow ones such as oil drops).', 'A falling object accelerates at g at first; as its speed rises, drag grows and the acceleration falls; when drag equals weight, the acceleration is zero and it moves at terminal velocity. The velocity–time graph is a curve that levels off.'], eq: R`mg = kv_t^2\;\Rightarrow\; v_t = \sqrt{\frac{mg}{k}}` },
        { h: 'Third-law pairs', p: ['A third-law pair acts on two different bodies and is the same kind of force. Earth pulls a book down (gravity on the book); the book pulls Earth up (gravity on Earth): a pair. The table’s push up on the book is not the pair of the book’s weight, even when they are equal: both act on the book, and they are different kinds of force.'], warn: '**Where Newton’s laws need care.** They hold in inertial (non-accelerating) frames; in an accelerating car you seem to feel forces with no third-law partner. F = ma assumes constant mass: a rocket needs F = Δp/Δt with the exhaust included. And at speeds near light, momentum is γmv, so F = ma fails while F = dp/dt survives.' }
      ],
      eqs: [[R`p = mv`, 'momentum'], [R`F = \frac{\Delta p}{\Delta t}`, 'Newton’s second law (general)'], [R`F = ma`, 'constant mass'], [R`W = mg`, 'weight'], [R`v_t = \sqrt{mg/k}`, 'terminal velocity for drag kv²']],
      how: ['Draw a free-body diagram for one body at a time.', 'Resolve forces along and perpendicular to the acceleration.', 'Use F = ma for fixed mass, F = Δp/Δt for streams of mass and rebounds.', 'For third-law pairs, check: different bodies, same type of force.'],
      sum: ['p = mv; F = Δp/Δt (= ma for constant mass).', 'Third-law pairs: equal, opposite, same type, different bodies.', 'Weight W = mg; mass is inertia.', 'Drag grows with speed → terminal velocity when drag = weight.', 'Rebounds: Δp = m(u + v).'],
      probs: [
        { l: 1, q: 'Find the momentum of a 1200 kg car moving at 15 m/s.', a: '1.8 × 10⁴ kg m s⁻¹', s: ['p = 1200 × 15 = 18 000 kg m s⁻¹.'] },
        { l: 1, q: 'What resultant force gives a 0.15 kg ball an acceleration of 400 m/s²?', a: '60 N', s: ['F = ma = 0.15 × 400 = 60 N.'] },
        { l: 1, q: 'Earth pulls a book downwards. What is the Newton’s-third-law partner of this force?', a: 'The book’s gravitational pull upwards on Earth', s: ['Same type (gravity), equal and opposite, on the other body.'] },
        { l: 2, q: 'A 0.40 kg ball hits a wall at 12 m/s and rebounds at 8.0 m/s, in contact for 0.050 s. Find the average force on it.', a: '160 N', s: ['Δp = 0.40 × (12 + 8.0) = 8.0 kg m s⁻¹ (the velocity reverses).', 'F = 8.0 ÷ 0.050 = 160 N.'] },
        { l: 2, q: 'A hose sends 2.0 kg of water per second at 15 m/s horizontally against a wall, where it stops. What force does it exert on the wall?', a: '30 N', s: ['F = (Δm/Δt) × v = 2.0 × 15 = 30 N.'] },
        { l: 2, q: 'A 70 kg person stands on scales in a lift accelerating upwards at 2.0 m/s². What do the scales read?', a: '830 N', s: ['R − mg = ma ⇒ R = 70 × (9.81 + 2.0) = 827 N.'] },
        { l: 2, q: 'An 80 kg skydiver experiences drag F = kv² with k = 0.25 kg m⁻¹. Find her terminal velocity.', a: '56 m/s', s: ['kv² = mg ⇒ v = √(80 × 9.81 ÷ 0.25) = 56 m/s (about 200 km/h).'] },
        { l: 2, q: 'A 10 kg box is pulled across a floor by a horizontal 50 N force against 20 N of friction. Find its acceleration.', a: '3.0 m/s²', s: ['a = (50 − 20) ÷ 10 = 3.0 m/s².'] },
        { l: 3, q: 'A rocket of mass 60 000 kg ejects 250 kg of exhaust per second at 3000 m/s relative to itself. Find the thrust and the initial acceleration at launch.', a: '750 kN; 2.7 m/s²', s: ['Thrust = (Δm/Δt) × u = 250 × 3000 = 7.5 × 10⁵ N.', 'a = (7.5 × 10⁵ − 60 000 × 9.81) ÷ 60 000 = 2.69 m/s².', 'As fuel burns the mass drops, so the acceleration grows.'] },
        { l: 3, q: 'Blocks of 3.0 kg and 2.0 kg sit side by side on a frictionless surface. A 10 N force pushes the 3.0 kg block, which pushes the 2.0 kg block. Find the acceleration and the contact force between the blocks.', a: '2.0 m/s²; 4.0 N', s: ['Both together: a = 10 ÷ 5.0 = 2.0 m/s².', 'For the 2.0 kg block alone, the only horizontal force is the contact force: F = 2.0 × 2.0 = 4.0 N.', 'By the third law the 2.0 kg block pushes back on the 3.0 kg block with 4.0 N; check: 10 − 4.0 = 3.0 × 2.0.'] }
      ]
    },

    'al-momentum': {
      big: 'In any collision or explosion where no external resultant force acts, the total momentum is the same before and after. Kinetic energy is conserved only in perfectly elastic collisions; then the speed at which the bodies approach equals the speed at which they separate. In two dimensions, momentum is conserved separately along each direction.',
      sec: [
        { h: 'Conservation of momentum', p: ['For a closed system (no external resultant force), the total momentum is constant. This follows from Newton’s second and third laws: during a collision the two bodies exert equal and opposite forces on each other for the same time, so their momentum changes are equal and opposite.'], eq: R`m_1u_1 + m_2u_2 = m_1v_1 + m_2v_2` },
        { h: 'Elastic and inelastic collisions', p: ['In an elastic collision total kinetic energy is also conserved. In an inelastic collision some kinetic energy becomes internal energy, sound or deformation; if the bodies stick together it is perfectly inelastic, and the largest possible share of kinetic energy is lost while momentum is still conserved.'] },
        { h: 'Relative speed in elastic collisions', p: ['For a head-on elastic collision, combining momentum and energy conservation gives a simpler linear condition: the relative speed of approach equals the relative speed of separation. This is easier to use than kinetic energy directly.'], eq: R`u_1 - u_2 = v_2 - v_1\quad(\text{elastic, head-on})` },
        { h: 'Explosions', p: ['When a body at rest explodes or recoils, the total momentum stays zero: the parts fly apart with equal and opposite momenta. The lighter part moves faster and carries most of the kinetic energy.'] },
        { h: 'Collisions in two dimensions', p: ['Momentum is a vector, so it is conserved separately in any two perpendicular directions. A useful special case: when a moving ball hits an identical stationary ball elastically (not head-on), the two move off at right angles to each other.'], warn: '**“Closed system” is an approximation.** Friction and gravity do act during a collision, but because the collision lasts only milliseconds while the collision forces are huge, the external impulses are tiny by comparison. Over longer times (a car skidding after a crash) they cannot be ignored. Kinetic energy “lost” in an inelastic collision is not destroyed: it heats and deforms the bodies.' }
      ],
      eqs: [[R`\sum p_{\text{before}} = \sum p_{\text{after}}`, 'closed system'], [R`u_1 - u_2 = v_2 - v_1`, 'elastic head-on collision'], [R`E_k = \frac{p^2}{2m}`, 'kinetic energy in terms of momentum'], [R`v = \frac{m_1u_1 + m_2u_2}{m_1 + m_2}`, 'bodies that stick together']],
      how: ['Choose a positive direction; give every velocity a sign.', 'Write total momentum before = total after.', 'For elastic collisions add the relative-speed equation; solve the pair.', 'In 2D, conserve momentum in x and y separately.', 'Check kinetic energy to classify the collision.'],
      sum: ['Momentum is conserved in every collision and explosion of a closed system.', 'Elastic: kinetic energy conserved; relative speed of approach = of separation.', 'Inelastic: kinetic energy lost to internal energy; sticking together loses the most.', 'Explosions from rest: equal and opposite momenta.', 'In 2D, conserve each component.'],
      probs: [
        { l: 1, q: 'A 2.0 kg trolley moving at 3.0 m/s hits a stationary 1.0 kg trolley and they stick together. Find their common velocity.', a: '2.0 m/s', s: ['6.0 = 3.0v ⇒ v = 2.0 m/s.'] },
        { l: 1, q: 'For the collision above, find the kinetic energy before and after.', a: '9.0 J before; 6.0 J after', s: ['Before: ½ × 2.0 × 3.0² = 9.0 J. After: ½ × 3.0 × 2.0² = 6.0 J; 3.0 J became internal energy.'] },
        { l: 1, q: 'A 4.0 kg rifle fires a 0.010 kg bullet at 400 m/s. Find the rifle’s recoil velocity.', a: '1.0 m/s backwards', s: ['0 = 0.010 × 400 + 4.0v ⇒ v = −1.0 m/s.'] },
        { l: 2, q: 'A 1.0 kg ball at 4.0 m/s hits an identical stationary ball head-on and elastically. Find both velocities afterwards.', a: 'First stops; second moves at 4.0 m/s', s: ['Momentum: 4.0 = v₁ + v₂. Relative speed: 4.0 = v₂ − v₁.', 'Adding: v₂ = 4.0 m/s, v₁ = 0: equal masses swap velocities (as in Newton’s cradle).'] },
        { l: 2, q: 'A 2.0 kg ball at 3.0 m/s hits a stationary 1.0 kg ball head-on, elastically. Find both final velocities and check kinetic energy.', a: '1.0 m/s and 4.0 m/s', s: ['6.0 = 2.0v₁ + 1.0v₂ and 3.0 = v₂ − v₁.', 'Substituting v₂ = 3.0 + v₁: 6.0 = 3.0v₁ + 3.0 ⇒ v₁ = 1.0, v₂ = 4.0 m/s.', 'KE: 9.0 J before; 1.0 + 8.0 = 9.0 J after.'] },
        { l: 2, q: 'A 3.0 kg ball moving at 4.0 m/s and a 2.0 kg ball moving at 6.0 m/s towards it collide head-on and stick. What happens, and how much kinetic energy is lost?', a: 'Both stop; all 60 J is lost', s: ['Total momentum = 3.0 × 4.0 − 2.0 × 6.0 = 0.', 'So the combined body is at rest; KE before = 24 + 36 = 60 J, all converted.'] },
        { l: 2, q: 'A 5.0 kg shell at rest explodes into two pieces. A 2.0 kg piece moves east at 30 m/s. Find the velocity of the other piece and the kinetic energy released.', a: '20 m/s west; 1500 J', s: ['0 = 2.0 × 30 + 3.0v ⇒ v = −20 m/s.', 'KE = ½ × 2.0 × 900 + ½ × 3.0 × 400 = 900 + 600 = 1500 J.'] },
        { l: 2, q: 'A 0.50 kg ball at 6.0 m/s hits a stationary 1.5 kg ball. Afterwards the first moves at 3.0 m/s backwards and the second at 3.0 m/s forwards. Is momentum conserved? Was the collision elastic?', a: 'Yes; yes', s: ['Momentum: 3.0 before; −1.5 + 4.5 = 3.0 after.', 'KE: 9.0 J before; 2.25 + 6.75 = 9.0 J after: elastic.', 'Relative speeds: 6.0 approach, 3.0 − (−3.0) = 6.0 separation.'] },
        { l: 3, q: 'A 1.0 kg puck moving at 5.0 m/s strikes an identical stationary puck. Afterwards the first moves at 4.0 m/s at 36.9° to its original direction. Find the velocity of the second, show the collision is elastic, and find the angle between the final paths.', a: '3.0 m/s at 53.1° on the other side; elastic; 90°', s: ['x: 5.0 = 4.0 cos 36.9° + v cos θ = 3.2 + v cos θ ⇒ v cos θ = 1.8.', 'y: 0 = 4.0 sin 36.9° − v sin θ ⇒ v sin θ = 2.4.', 'v = √(1.8² + 2.4²) = 3.0 m/s at θ = 53.1°.', 'KE: 12.5 J before; 8.0 + 4.5 = 12.5 J after. 36.9° + 53.1° = 90°.'] },
        { l: 3, q: 'A 20 g bullet embeds itself in a 2.0 kg wooden block hanging as a pendulum, which then swings up 10 cm. Find the bullet’s speed. What fraction of its kinetic energy was lost in the impact?', a: '141 m/s; 99%', s: ['After impact: ½(M + m)V² = (M + m)gh ⇒ V = √(2 × 9.81 × 0.10) = 1.40 m/s.', 'Momentum during the impact: mu = (M + m)V ⇒ u = (2.02 ÷ 0.020) × 1.40 = 141 m/s.', 'KE kept = m/(M + m) = 1%: 99% became internal energy. Energy is not conserved in the impact, so momentum must be used for that step.'] }
      ]
    },

    'al-equilibrium': {
      big: 'A body is in equilibrium when there is no resultant force and no resultant moment on it. Moments about any point then balance, and three coplanar forces in equilibrium form a closed triangle when drawn nose to tail. These two ideas solve everything from shelf brackets to ladders and suspension bridges.',
      sec: [
        { h: 'Moments and couples', p: ['The moment of a force about a point is the force times the perpendicular distance from the point to the line of action of the force.', 'A couple is a pair of equal and opposite forces whose lines of action do not coincide. It produces rotation without translation. Its torque is one of the forces times the perpendicular distance between them, and it is the same about every point.'], eq: R`\text{moment} = Fd_\perp,\qquad \text{torque of a couple} = F \times d` },
        { h: 'Conditions for equilibrium', list: ['No resultant force: the forces in any two perpendicular directions each sum to zero.', 'No resultant moment about any point: the sum of clockwise moments equals the sum of anticlockwise moments (principle of moments).'], p: ['Choose the point about which you take moments where an unknown force acts, to eliminate it.'] },
        { h: 'Centre of gravity', p: ['The centre of gravity is the point through which the whole weight of a body may be considered to act. For a uniform beam it is at the middle; a beam is “light” only if its weight is negligible.'] },
        { h: 'Vector triangles', p: ['If three coplanar forces keep a body in equilibrium, they must all pass through one point (otherwise they would form a turning effect), and drawn nose to tail they form a closed triangle. The triangle can be solved with trigonometry or a scale drawing.'] },
        { h: 'Why tight lines need huge tensions', p: ['A weight W hung from the middle of a string whose halves each make a small angle θ with the horizontal needs a tension T = W/(2 sin θ). As θ → 0 the tension grows without limit: a washing line or a guitar string can never be pulled perfectly straight under a load.'], warn: '**The rigid-body assumption.** These methods treat beams as perfectly rigid. Real beams bend, and a beam on three or more supports is “statically indeterminate”: the equilibrium equations alone cannot fix the support forces, which depend on how the beam and supports deform. Ladders also hide assumptions: “smooth wall” means no friction there, which is never exactly true.' }
      ],
      eqs: [[R`M = Fd_\perp`, 'moment of a force'], [R`\tau = Fd`, 'torque of a couple'], [R`\sum F_x = 0,\ \sum F_y = 0,\ \sum M = 0`, 'equilibrium'], [R`T = \frac{W}{2\sin\theta}`, 'load hung from a string at angle θ to the horizontal']],
      how: ['Draw every force, including the weight at the centre of gravity and reactions at supports.', 'Resolve horizontally and vertically.', 'Take moments about a point where an unknown force acts.', 'For three forces, draw the closed vector triangle.'],
      sum: ['Moment = F × perpendicular distance.', 'Couple: torque = F × separation; turns without translating.', 'Equilibrium: no resultant force and no resultant moment.', 'Three forces in equilibrium: concurrent, closed triangle.', 'Small angles give large tensions.'],
      probs: [
        { l: 1, q: 'A couple consists of two 15 N forces 0.40 m apart. Find its torque.', a: '6.0 N m', s: ['τ = 15 × 0.40 = 6.0 N m.'] },
        { l: 1, q: 'State the two conditions for a body to be in equilibrium.', a: 'No resultant force and no resultant moment', s: ['Both are needed: a couple has zero resultant force but still turns a body.'] },
        { l: 1, q: 'Find the moment of a 20 N force acting at right angles to a lever 0.50 m from the pivot.', a: '10 N m', s: ['M = 20 × 0.50 = 10 N m.'] },
        { l: 2, q: 'A uniform 4.0 m beam weighing 200 N is pivoted 1.0 m from its left end. What weight hung at the left end balances it?', a: '200 N', s: ['The beam’s weight acts at 2.0 m from the left, 1.0 m right of the pivot: 200 × 1.0 = 200 N m.', 'W × 1.0 = 200 ⇒ W = 200 N.'] },
        { l: 2, q: 'A 50 N picture hangs from a wire whose two halves each make 30° with the horizontal. Find the tension.', a: '50 N', s: ['2T sin 30° = 50 ⇒ T = 50 N.'] },
        { l: 2, q: 'The same picture hangs from a wire at 10° to the horizontal. Find the tension, and explain why the wire can never be horizontal.', a: '144 N; the tension would have to be infinite', s: ['T = 50 ÷ (2 sin 10°) = 144 N.', 'As the angle tends to zero, sin θ → 0, so T → ∞: a horizontal wire has no vertical component to hold the weight.'] },
        { l: 2, q: 'A uniform 5.0 m ladder weighing 200 N leans against a smooth wall at 60° to the ground. Find the wall’s push and the friction at the ground.', a: 'Both 58 N', s: ['Moments about the foot: R × 5.0 sin 60° = 200 × 2.5 cos 60°.', 'R = 250 ÷ 4.33 = 57.7 N.', 'Horizontal forces balance, so friction = 57.7 N; the ground’s normal force = 200 N.'] },
        { l: 2, q: 'Three forces of 3.0 N, 4.0 N and 5.0 N keep a body in equilibrium. What is the angle between the 3.0 N and 4.0 N forces?', a: '90°', s: ['They form a closed triangle with sides 3, 4, 5: a right-angled triangle.', 'The 3 N and 4 N sides are perpendicular in the triangle, so the forces are at 90° to each other.'] },
        { l: 3, q: 'A uniform 20 m bridge weighing 1.0 × 10⁵ N rests on supports at its ends. A 2.0 × 10⁴ N truck stands 5.0 m from the left end. Find both support forces.', a: '65 kN (left), 55 kN (right)', s: ['Moments about the left end: R_{right} × 20 = 1.0 × 10⁵ × 10 + 2.0 × 10⁴ × 5.0 = 1.1 × 10⁶ ⇒ R_{right} = 55 kN.', 'R_{left} = 1.2 × 10⁵ − 55 000 = 65 kN.'] },
        { l: 3, q: 'A driver turns a steering wheel of diameter 0.38 m by pushing up with 25 N on one side and down with 25 N on the other. Find the torque. Why does the steering column feel no sideways push?', a: '9.5 N m; a couple has no resultant force', s: ['τ = F × d = 25 × 0.38 = 9.5 N m.', 'The two forces are equal and opposite, so their resultant is zero: pure rotation.'] }
      ]
    },

    'al-fluids': {
      big: 'Pressure in a fluid grows with depth because of the weight of fluid above. The pressure is therefore larger on the bottom of a submerged object than on its top, and that difference is the upthrust. It equals the weight of the fluid displaced: Archimedes’ principle, which decides what floats and how low it sits.',
      sec: [
        { h: 'Density and pressure', p: ['Density ρ = m/V. Pressure is the normal force per unit area, p = F/A, in pascals (N m⁻²).'] },
        { h: 'Pressure in a fluid', p: ['Consider a column of fluid of height Δh and cross-section A. Its weight is ρAΔhg, and it rests on area A, so the pressure below it is greater by ρgΔh. At a given depth the pressure acts equally in all directions, and the shape of the container does not matter.'], eq: R`\Delta p = \rho g\Delta h` },
        { h: 'Upthrust from the pressure difference', p: ['A cuboid of height L and area A submerged with its top at depth h has pressure ρgh on its top and ρg(h + L) on its bottom. The net upward force is ρgLA = ρgV: the weight of fluid with the same volume as the object, whatever the depth.'], eq: R`F_{\text{up}} = \rho_{\text{fluid}}\,g\,V_{\text{displaced}}` },
        { h: 'Archimedes’ principle and floating', p: ['The upthrust on a body in a fluid equals the weight of the fluid it displaces. A floating body sinks until it displaces its own weight of fluid, so the fraction of its volume submerged equals ρ_{body}/ρ_{fluid}. A hydrometer floats deeper in less dense liquids, which is how it measures density.'] },
        { h: 'Measuring pressures', p: ['A U-tube manometer compares a gas pressure with the atmosphere: the difference is ρgΔh, where Δh is the difference in liquid levels. A mercury barometer balances the atmosphere against a column about 0.76 m high.'], warn: '**Constant density and a still fluid.** Δp = ρgΔh assumes the fluid is incompressible and at rest. Water is very slightly compressible: at the bottom of the Mariana Trench it is about 5% denser, so the simple formula is a few percent off. Moving fluids add dynamic effects (lift, Bernoulli), and for very small objects surface tension matters: a steel needle can rest on water although it is far denser.' }
      ],
      eqs: [[R`p = F/A`, 'pressure in Pa'], [R`\Delta p = \rho g\Delta h`, 'depth pressure'], [R`F_{\text{up}} = \rho g V`, 'upthrust (Archimedes)'], [R`\frac{V_{\text{sub}}}{V} = \frac{\rho_{\text{body}}}{\rho_{\text{fluid}}}`, 'floating body']],
      how: ['Use vertical depth below the free surface.', 'Decide whether to include atmospheric pressure.', 'For upthrust, use the volume of fluid displaced, not the object’s mass.', 'For floating, set upthrust equal to weight.'],
      sum: ['ρ = m/V; p = F/A.', 'Δp = ρgΔh, independent of container shape.', 'Upthrust comes from the pressure difference between bottom and top.', 'Archimedes: upthrust = weight of fluid displaced.', 'Floating fraction submerged = ρ_{body}/ρ_{fluid}.'],
      probs: [
        { l: 1, q: 'Find the pressure due to the water at the bottom of a 2.0 m deep pool.', a: '19.6 kPa', s: ['Δp = 1000 × 9.81 × 2.0 = 1.96 × 10⁴ Pa.'] },
        { l: 1, q: 'Find the upthrust on an object of volume 0.0020 m³ fully submerged in water.', a: '19.6 N', s: ['F = ρgV = 1000 × 9.81 × 0.0020 = 19.6 N.'] },
        { l: 1, q: 'State Archimedes’ principle.', a: 'The upthrust on a body in a fluid equals the weight of the fluid displaced', s: ['It holds for floating and submerged bodies alike.'] },
        { l: 2, q: 'A stone weighs 5.0 N in air and 3.0 N when fully submerged in water. Find its density.', a: '2500 kg m⁻³', s: ['Upthrust = 2.0 N = ρ_w g V ⇒ V = 2.04 × 10⁻⁴ m³.', 'Mass = 5.0 ÷ 9.81 = 0.510 kg; ρ = 0.510 ÷ 2.04 × 10⁻⁴ = 2500 kg m⁻³.', 'Shortcut: ρ/ρ_w = weight ÷ upthrust = 5.0 ÷ 2.0.'] },
        { l: 2, q: 'Derive the upthrust on a submerged cuboid of height L and top area A, with its top at depth h.', a: 'ρgLA = ρgV', s: ['Force on the bottom = (p₀ + ρg(h + L))A upwards; on the top = (p₀ + ρgh)A downwards.', 'Net = ρgLA = ρgV; the sides’ forces cancel, and h drops out.'] },
        { l: 2, q: 'A water manometer connected to a gas supply shows a 12 cm difference in levels. How much above atmospheric pressure is the gas?', a: '1.18 kPa', s: ['Δp = 1000 × 9.81 × 0.12 = 1180 Pa.'] },
        { l: 2, q: 'A block of wood of density 600 kg m⁻³ floats in water. What fraction is submerged? And in brine of density 1200 kg m⁻³?', a: '60%; 50%', s: ['Fraction = ρ_{body}/ρ_{fluid}: 600/1000 = 0.60 and 600/1200 = 0.50.'] },
        { l: 2, q: 'A hydraulic lift has pistons of area 5.0 cm² and 500 cm². What force on the small piston lifts a 1200 kg car?', a: '118 N', s: ['The pressure is the same: F_{small} = 1200 × 9.81 × (5.0/500) = 118 N.'] },
        { l: 3, q: 'A 0.010 m³ helium balloon (helium 0.18 kg m⁻³) has a rubber skin of mass 3.0 g. Air has a density of 1.29 kg m⁻³. Find the upthrust, the total weight and the extra mass it can lift.', a: '0.127 N; 0.047 N; about 8 g', s: ['Upthrust = 1.29 × 9.81 × 0.010 = 0.127 N.', 'Weight = (0.0018 + 0.0030) × 9.81 = 0.047 N.', 'Spare = 0.080 N, enough to lift 8.1 g.'] },
        { l: 3, q: 'Estimate the pressure due to the sea at the bottom of the Mariana Trench (10 900 m deep, seawater 1030 kg m⁻³). Why does the simple formula slightly underestimate it?', a: 'About 1.1 × 10⁸ Pa (over 1000 atmospheres)', s: ['Δp = 1030 × 9.81 × 10 900 = 1.10 × 10⁸ Pa.', 'Water compresses a little under such pressures, so the deep water is a few percent denser than at the surface, and the true pressure is slightly higher than the constant-density estimate.'] }
      ]
    },

    'al-energy': {
      big: 'Work is done when a force moves its point of application: W = Fs cos θ. The work–energy idea gives the formulas for kinetic and gravitational potential energy directly from Newton’s laws, and power, the rate of doing work, becomes P = Fv for anything moving steadily against a force.',
      sec: [
        { h: 'Work done', p: ['The work done by a force is the force times the displacement in the direction of the force. A force at right angles to the motion does no work, which is why a circular orbit can continue without any energy input.'], eq: R`W = Fs\cos\theta` },
        { h: 'Deriving the energy formulas', p: ['Gravitational potential energy: lifting a mass m at steady speed through Δh in a uniform field needs a force mg, so the work done is mgΔh.', 'Kinetic energy: a constant resultant force F accelerates a mass from rest over distance s. Then W = Fs = mas, and v² = 2as gives as = ½v², so W = ½mv².'], eq: R`\Delta E_p = mg\Delta h,\qquad E_k = \tfrac12mv^2` },
        { h: 'Conservation of energy and efficiency', p: ['Energy is conserved: the total energy of a closed system is constant. In real systems some energy is dissipated as internal energy of the surroundings. Efficiency is the useful energy (or power) output divided by the total input.'], eq: R`\text{efficiency} = \frac{\text{useful output}}{\text{total input}}` },
        { h: 'Power and P = Fv', p: ['Power is the rate of doing work, in watts. A force F moving its point of application at speed v along its own direction does work Fv every second.'], eq: R`P = \frac{W}{t} = Fv` },
        { h: 'Energy with slopes and resistance', p: ['A vehicle climbing a slope of angle θ at steady speed needs a driving force mg sin θ + F_{resistance}, so its power is (mg sin θ + F_{resistance})v. At constant speed all that power goes into potential energy and dissipation.'], warn: '**Range of validity.** ΔEp = mgΔh needs a uniform field: for a rocket rising 1000 km it overestimates the energy by about 16%, and GMm(1/r₁ − 1/r₂) is needed. Eₖ = ½mv² is the low-speed limit of (γ − 1)mc²; for electrons accelerated through a million volts it is badly wrong. P = Fv assumes the force is along the velocity; otherwise use Fv cos θ.' }
      ],
      eqs: [[R`W = Fs\cos\theta`, 'work done'], [R`\Delta E_p = mg\Delta h`, 'uniform field only'], [R`E_k = \tfrac12mv^2`, 'non-relativistic'], [R`P = W/t = Fv`, 'power'], [R`\eta = \frac{\text{useful}}{\text{total}}`, 'efficiency']],
      how: ['Identify every force that does work and the displacement along it.', 'Write energy at the start = energy at the end + energy dissipated.', 'For power at steady speed, find the total driving force and multiply by v.', 'Use efficiency to link useful output and total input.'],
      sum: ['W = Fs cos θ; perpendicular forces do no work.', 'ΔEp = mgΔh and Eₖ = ½mv² follow from W = Fs.', 'Energy is conserved; efficiency = useful ÷ total.', 'P = W/t = Fv.', 'Uphill at steady speed: P = (mg sin θ + F_{res})v.'],
      probs: [
        { l: 1, q: 'A sledge is pulled 10 m by a 40 N force at 30° above the horizontal. How much work is done?', a: '346 J', s: ['W = 40 × 10 × cos 30° = 346 J.'] },
        { l: 1, q: 'Find the kinetic energy of a 0.15 kg ball moving at 30 m/s.', a: '67.5 J', s: ['Eₖ = ½ × 0.15 × 30² = 67.5 J.'] },
        { l: 1, q: 'A motor lifts a 50 kg load at a steady 0.40 m/s. What useful power does it develop?', a: '196 W', s: ['P = Fv = mgv = 50 × 9.81 × 0.40 = 196 W.'] },
        { l: 2, q: 'Derive Eₖ = ½mv² for a body accelerated from rest by a constant resultant force.', a: 'W = Fs = mas = ½mv²', s: ['W = Fs and F = ma.', 'From v² = 0 + 2as, as = ½v².', 'So W = m(as) = ½mv², which is stored as kinetic energy.'] },
        { l: 2, q: 'A roller-coaster car starts from rest 40 m above the ground. Ignoring friction, how fast is it moving 15 m above the ground?', a: '22 m/s', s: ['mg(40 − 15) = ½mv² ⇒ v = √(2 × 9.81 × 25) = 22.1 m/s.'] },
        { l: 2, q: 'For the same drop, 20% of the lost potential energy is dissipated by friction. Find the speed now.', a: '19.8 m/s', s: ['½mv² = 0.80 × mg × 25 ⇒ v = √(0.80 × 2 × 9.81 × 25) = 19.8 m/s.'] },
        { l: 2, q: 'A 1000 kg car climbs a slope with sin θ = 0.050 at a steady 30 m/s against 500 N of resistance. Find the power needed.', a: '29.7 kW', s: ['Driving force = mg sin θ + 500 = 490.5 + 500 = 990.5 N.', 'P = 990.5 × 30 = 2.97 × 10⁴ W.'] },
        { l: 2, q: 'A pump lifts 120 kg of water through 8.0 m every minute using 250 W of electrical power. Find its efficiency.', a: '63%', s: ['Useful power = 120 × 9.81 × 8.0 ÷ 60 = 157 W.', 'η = 157 ÷ 250 = 0.63.'] },
        { l: 3, q: 'A 70 kg bungee jumper uses a 20 m cord with stiffness 250 N/m. Ignoring air resistance, how far does the cord stretch at the lowest point, and what is her acceleration there?', a: '13.6 m; about 39 m/s² upwards (4 g)', s: ['From rest at the top to rest at the bottom: mg(20 + x) = ½kx².', '686.7(20 + x) = 125x² ⇒ x = [686.7 + √(686.7² + 4 × 125 × 13 734)] ÷ 250 = 13.6 m.', 'At the bottom: a = (kx − mg)/m = (3396 − 687) ÷ 70 = 38.7 m/s² upwards.'] },
        { l: 3, q: 'Using mgh for a satellite raised 1000 km above Earth’s surface overestimates the energy needed compared with GMm(1/R − 1/(R + h)). By what factor, given R = 6370 km?', a: 'By (R + h)/R ≈ 1.16, about 16%', s: ['GMm(1/R − 1/(R + h)) = GMm h/[R(R + h)] = mgh × R/(R + h), using g = GM/R².', 'So mgh is too big by (R + h)/R = 7370/6370 = 1.157.', 'g weakens with height, so less work is needed than mgh suggests.'] }
      ]
    }
  });
})();
/* ---- notes-al4.js ---- */
/* Geodesic: notes and ten-problem sets for A Level outline topics, part 2 (Cambridge 9702 sections 6–9 and 17.3). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'al-materials': {
      big: 'Pull on a wire and it stretches. Divide the force by the area and the extension by the length, and you get stress and strain, which describe the material rather than the particular sample. Their ratio, the Young modulus, is a material’s stiffness. Beyond the elastic limit the stretch becomes permanent; the area under the force–extension graph is the energy stored or spent.',
      sec: [
        { h: 'Hooke’s law and the spring constant', p: ['For small extensions, the extension x of a spring or wire is proportional to the load F, up to the limit of proportionality. The spring constant k = F/x depends on the sample: a longer or thinner wire of the same metal stretches more.', 'Springs in series share the same force, so their extensions add (1/k = 1/k₁ + 1/k₂); springs in parallel share the extension, so their forces add (k = k₁ + k₂).'], eq: R`F = kx` },
        { h: 'Stress, strain and the Young modulus', p: ['Tensile stress is force per unit cross-sectional area; tensile strain is extension per unit original length. In the linear region their ratio is the Young modulus E, a property of the material: about 2.0 × 10¹¹ Pa for steel, 1.2 × 10¹¹ Pa for copper, 7 × 10¹⁰ Pa for glass.'], eq: R`\sigma = \frac{F}{A},\qquad \varepsilon = \frac{x}{L},\qquad E = \frac{\sigma}{\varepsilon} = \frac{FL}{Ax}` },
        { h: 'Measuring E', p: ['Hang a long, thin wire from a rigid support. Measure its length with a metre rule and its diameter at several places with a micrometer. Add loads in steps and read the extension with a vernier scale or a marker against a scale; plot load against extension. The gradient of the straight part is EA/L.', 'A long, thin wire gives a large extension for a given stress, reducing the percentage uncertainty. A second, unloaded reference wire beside it (Searle’s apparatus) cancels effects of temperature changes and sagging supports.'] },
        { h: 'Elastic and plastic behaviour', p: ['Elastic deformation disappears when the load is removed; plastic deformation is permanent. Beyond the elastic limit, a ductile metal such as copper stretches plastically a great deal before breaking; a brittle material such as glass breaks with almost no plastic deformation. The ultimate tensile stress is the largest stress the material can withstand.'] },
        { h: 'Strain energy', p: ['The work done stretching a sample is the area under its force–extension graph. In the linear region that is a triangle, so the elastic potential energy stored is ½Fx = ½kx².'], eq: R`E_p = \tfrac12Fx = \tfrac12kx^2`, warn: '**Loading is not always the reverse of unloading.** For metals within the elastic limit it nearly is, but rubber follows a different curve when unloaded (hysteresis): the area between the curves is energy turned into heat each cycle, which is why a stretched and released rubber band warms up. E also depends on temperature, and the “original length” matters: for large rubber stretches, engineers use true stress and strain.' }
      ],
      eqs: [[R`F = kx`, 'Hooke’s law'], [R`\sigma = F/A`, 'stress in Pa'], [R`\varepsilon = x/L`, 'strain (no units)'], [R`E = \sigma/\varepsilon`, 'Young modulus in Pa'], [R`E_p = \tfrac12Fx`, 'strain energy (linear region)']],
      how: ['Convert areas to m² (1 mm² = 10⁻⁶ m²) and use A = πd²/4 for wires.', 'Use stress and strain for materials, F and x for particular samples.', 'Read E from the gradient of a stress–strain graph’s straight part.', 'Energy = area under the force–extension graph.'],
      sum: ['F = kx up to the limit of proportionality.', 'Stress = F/A; strain = x/L; E = stress/strain.', 'Long, thin wires make E measurements more precise.', 'Elastic: recovers. Plastic: permanent. Ductile vs brittle.', 'Strain energy = area under F–x graph = ½Fx when linear.'],
      probs: [
        { l: 1, q: 'A spring of constant 25 N/m is stretched by 0.040 m. Find the force and the energy stored.', a: '1.0 N; 0.020 J', s: ['F = 25 × 0.040 = 1.0 N.', 'E = ½ × 1.0 × 0.040 = 0.020 J.'] },
        { l: 1, q: 'A 200 N load hangs from a wire of cross-sectional area 0.50 mm². Find the stress.', a: '4.0 × 10⁸ Pa', s: ['σ = 200 ÷ 0.50 × 10⁻⁶ = 4.0 × 10⁸ Pa.'] },
        { l: 1, q: 'A 2.000 m wire extends by 1.0 mm. Find the strain.', a: '5.0 × 10⁻⁴', s: ['ε = 0.0010 ÷ 2.000 = 5.0 × 10⁻⁴ (no units).'] },
        { l: 2, q: 'A steel wire 2.0 m long and 0.50 mm in diameter extends 2.5 mm under a 50 N load. Find the Young modulus.', a: '2.0 × 10¹¹ Pa', s: ['A = π(0.25 × 10⁻³)² = 1.96 × 10⁻⁷ m²; σ = 2.55 × 10⁸ Pa.', 'ε = 2.5 × 10⁻³ ÷ 2.0 = 1.25 × 10⁻³.', 'E = 2.55 × 10⁸ ÷ 1.25 × 10⁻³ = 2.0 × 10¹¹ Pa.'] },
        { l: 2, q: 'How far does a 3.0 m copper wire (E = 1.2 × 10¹¹ Pa) of area 1.0 mm² stretch under 60 N?', a: '1.5 mm', s: ['x = FL/(AE) = 60 × 3.0 ÷ (1.0 × 10⁻⁶ × 1.2 × 10¹¹) = 1.5 × 10⁻³ m.'] },
        { l: 2, q: 'Two springs of 200 N/m are joined in series, then in parallel. Find the combined spring constant each time.', a: '100 N/m; 400 N/m', s: ['Series: each carries F, so the extensions add: 1/k = 1/200 + 1/200 ⇒ k = 100 N/m.', 'Parallel: each extends x, so the forces add: k = 400 N/m.'] },
        { l: 2, q: 'A force–extension graph is a straight line from the origin to 12 N at 0.060 m. How much energy is stored?', a: '0.36 J', s: ['Area = ½ × 12 × 0.060 = 0.36 J.'] },
        { l: 2, q: 'Distinguish ductile and brittle materials, with an example of each.', a: 'Ductile: large plastic deformation before breaking (copper). Brittle: breaks with little plastic deformation (glass).', s: ['Ductile metals can be drawn into wires; brittle materials crack suddenly.'] },
        { l: 3, q: 'In a Young modulus experiment, why is the wire long and thin, and why is a second, unloaded wire hung beside it?', a: 'To make the extension large; to cancel temperature and support effects', s: ['x = FL/(AE): a long, thin wire gives a bigger extension for the same load, so its percentage uncertainty is smaller.', 'Temperature changes and sagging of the support affect both wires equally; measuring the extension relative to the reference wire removes them.'] },
        { l: 3, q: 'A 5.0 m steel cable (E = 2.0 × 10¹¹ Pa) of area 2.0 cm² carries 40 kN. Find the stress, strain, extension and stored energy.', a: '2.0 × 10⁸ Pa; 1.0 × 10⁻³; 5.0 mm; 100 J', s: ['σ = 40 000 ÷ 2.0 × 10⁻⁴ = 2.0 × 10⁸ Pa.', 'ε = σ/E = 1.0 × 10⁻³; x = εL = 5.0 mm.', 'E = ½Fx = ½ × 40 000 × 0.0050 = 100 J.'] }
      ]
    },

    'al-damping': {
      big: 'Real oscillators lose energy, so their amplitude dies away: they are damped. Drive an oscillator with a periodic force and it settles into oscillating at the driving frequency; when that frequency matches its natural frequency, the amplitude becomes largest. That is resonance, useful in tuning circuits and musical instruments and dangerous in bridges and machinery.',
      sec: [
        { h: 'Damping', p: ['Resistive forces such as friction and drag take energy from an oscillator, reducing its amplitude.'], list: ['Light damping: the system still oscillates at almost its natural frequency, with an amplitude that decreases gradually (often exponentially).', 'Critical damping: the system returns to equilibrium in the shortest possible time without overshooting.', 'Heavy (over) damping: the system returns slowly, without oscillating.'], after: ['Car suspensions and the needles of analogue meters are designed to be close to critically damped.'] },
        { h: 'Forced oscillations', p: ['A periodic driving force makes a system oscillate at the driving frequency, not its own. Its amplitude depends on how close the driving frequency is to the natural frequency.'] },
        { h: 'Resonance', p: ['When the driving frequency equals the natural frequency, energy is fed in at exactly the right moment each cycle, and the amplitude is a maximum. With little damping the resonance peak is tall and sharp; more damping makes it lower and broader, and the peak moves slightly to a lower frequency.'], eq: R`f_0 = \frac{1}{2\pi}\sqrt{\frac{k}{m}}\quad(\text{mass on a spring})` },
        { h: 'Useful and harmful resonance', list: ['Useful: tuning a radio (an electrical circuit resonates at one station’s frequency), musical instruments, MRI (nuclei resonate in a magnetic field), quartz clocks.', 'Harmful: machinery shaking at certain speeds, buildings in earthquakes, bridges driven by wind or walkers. London’s Millennium Bridge (2000) swayed because walkers’ sideways steps, at about 1 Hz, fell into step with its sway; dampers fixed it.'] },
        { h: 'Exponential decay of amplitude', p: ['For light viscous damping the amplitude falls by the same fraction every cycle: A = A₀e^{−t/τ}. Energy is proportional to amplitude squared, so it falls twice as fast.'], warn: '**Not every collapse is resonance.** The Tacoma Narrows Bridge (1940) is often quoted as resonance, but the wind was steady, not periodic: the bridge’s own twisting changed the airflow so that it pumped energy in (aeroelastic flutter), a self-excited instability. And real damping is not always proportional to speed; dry friction makes the amplitude fall by a fixed amount per cycle instead of a fixed fraction.' }
      ],
      eqs: [[R`f_0 = \frac{1}{2\pi}\sqrt{k/m}`, 'natural frequency of a mass on a spring'], [R`A = A_0 e^{-t/\tau}`, 'light viscous damping'], [R`E \propto A^2`, 'energy of an oscillation']],
      how: ['Identify the natural frequency and the driving frequency.', 'At resonance they are equal; amplitude is largest.', 'More damping: lower, broader peak, slightly lower peak frequency.', 'For decay, use constant fractional loss per cycle; square it for energy.'],
      sum: ['Damping removes energy; light, critical and heavy damping.', 'Forced oscillations occur at the driving frequency.', 'Resonance: driving frequency = natural frequency, maximum amplitude.', 'Damping lowers and broadens the resonance peak.', 'Energy ∝ amplitude².'],
      probs: [
        { l: 1, q: 'What is resonance?', a: 'Maximum amplitude when the driving frequency equals the natural frequency', s: ['Energy is supplied in step with the natural oscillation.'] },
        { l: 1, q: 'What type of damping is wanted in a car’s suspension, and why?', a: 'About critical: the car returns to level quickly without bouncing', s: ['Light damping would bounce; heavy damping would respond too slowly to the next bump.'] },
        { l: 1, q: 'Describe how the amplitude of a lightly damped pendulum changes with time.', a: 'It decreases gradually, by roughly the same fraction each swing', s: ['The period stays almost the same.'] },
        { l: 2, q: 'A lightly damped oscillator loses 10% of its amplitude each cycle. What fraction of the amplitude, and of the energy, remains after 5 cycles?', a: '59% of the amplitude; 35% of the energy', s: ['0.90⁵ = 0.59.', 'Energy ∝ A²: 0.59² = 0.35.'] },
        { l: 2, q: 'Find the natural frequency of a 0.50 kg mass on a spring with k = 80 N/m.', a: '2.0 Hz', s: ['f₀ = (1/2π)√(80/0.50) = (1/2π) × 12.6 = 2.0 Hz.'] },
        { l: 2, q: 'That mass–spring system is driven at 0.5 Hz, 2.0 Hz and 5.0 Hz with the same driving force. Compare the amplitudes.', a: 'Largest at 2.0 Hz; small at 0.5 Hz; smallest at 5.0 Hz', s: ['At 2.0 Hz it resonates.', 'Well below f₀, it follows the driver with a modest amplitude; well above, it cannot keep up and the amplitude is very small.'] },
        { l: 2, q: 'A washing machine shakes violently at one spin speed, then calms down as it speeds up further. Explain.', a: 'At that speed the drum’s rotation frequency matches a natural frequency of the machine', s: ['It passes through resonance; above it, the driving frequency is no longer matched.'] },
        { l: 2, q: 'Why are soldiers told to break step when marching over a bridge?', a: 'To avoid driving a bridge mode at resonance', s: ['Marching in step applies a periodic force; if its frequency matches a natural frequency of the bridge, the amplitude could grow dangerously.'] },
        { l: 3, q: 'An oscillator’s amplitude halves every 4.0 s. How long until it falls to an eighth? How long does its energy take to halve?', a: '12 s; 2.0 s', s: ['An eighth = (½)³: three halving times, 12 s.', 'E ∝ A², so energy halves when A falls by 1/√2: half the time, 2.0 s.'] },
        { l: 3, q: 'The Millennium Bridge’s sideways sway mode had a frequency of about 1 Hz. Walkers take about two steps per second. Explain why walking excited the sway, and why adding dampers rather than stiffening was chosen.', a: 'Sideways foot forces repeat once per stride (about 1 Hz); dampers flatten the resonance peak', s: ['Each step pushes slightly sideways, alternating left and right, so the sideways force repeats at half the step rate: about 1 Hz.', 'Once the bridge swayed, walkers fell into step with it, feeding in more energy: resonance with feedback.', 'Dampers remove energy every cycle, lowering the peak amplitude without rebuilding the bridge.'] }
      ]
    },

    'al-waves': {
      big: 'A progressive wave carries energy from one place to another. Every point oscillates with the same frequency but a different phase; the wavelength is the distance over which the phase repeats. The wave’s intensity, power per unit area, is proportional to the square of its amplitude and, from a point source, falls off as the inverse square of distance.',
      sec: [
        { h: 'Describing waves', list: ['Displacement: distance of a point from its equilibrium position. Amplitude: maximum displacement.', 'Period T: time for one oscillation; frequency f = 1/T.', 'Wavelength λ: distance between adjacent points in phase.', 'Phase difference: how far one oscillation is ahead of another, as a fraction of a cycle, in degrees or radians. Points one wavelength apart are in phase; half a wavelength apart, in antiphase (180°).'], eq: R`\Delta\phi = \frac{\Delta x}{\lambda} \times 360^\circ` },
        { h: 'The wave equation', p: ['In one period the wave travels one wavelength, so its speed is λ/T = fλ.'], eq: R`v = f\lambda` },
        { h: 'Transverse and longitudinal', p: ['In transverse waves (light, waves on strings) the oscillations are perpendicular to the direction of energy transfer; in longitudinal waves (sound) they are parallel to it, forming compressions and rarefactions. Graphs of displacement against distance (a snapshot) and displacement against time (one point) look alike but answer different questions.'] },
        { h: 'Using an oscilloscope', p: ['A cathode-ray oscilloscope (or digital scope) plots voltage against time. The time-base (s per division) converts horizontal divisions to time, so the period is the number of divisions for one cycle times the time-base; the Y-gain (V per division) converts vertical divisions to voltage, giving the amplitude.'] },
        { h: 'Intensity', p: ['Intensity is the power transmitted per unit area at right angles to the wave. For a given wave it is proportional to the amplitude squared. A point source radiating power P equally in all directions spreads it over a sphere of area 4πr², so the intensity falls as 1/r² and the amplitude as 1/r.'], eq: R`I = \frac{P}{A},\qquad I \propto A^2,\qquad I = \frac{P}{4\pi r^2}`, warn: '**Assumptions behind the inverse square law.** It assumes a point source, emission equal in all directions, and no absorption or reflection. Loudspeakers are directional, rooms reflect sound, and the atmosphere absorbs, so real intensities depart from 1/r², especially indoors and at high frequencies. I ∝ A² also assumes the same medium and frequency throughout.' }
      ],
      eqs: [[R`v = f\lambda`, 'wave equation'], [R`f = 1/T`, 'frequency and period'], [R`\Delta\phi = 2\pi\frac{\Delta x}{\lambda}`, 'phase difference in radians'], [R`I \propto A^2`, 'intensity and amplitude'], [R`I = \frac{P}{4\pi r^2}`, 'point source']],
      how: ['For phase, find the path separation as a fraction of λ.', 'For an oscilloscope, count divisions and multiply by the settings.', 'For intensity changes, square amplitude ratios; for distances, use 1/r².', 'Distinguish snapshot (vs distance) and single-point (vs time) graphs.'],
      sum: ['v = fλ; f = 1/T.', 'Phase difference = (Δx/λ) × 360°.', 'Transverse ⟂, longitudinal ∥ to energy transfer.', 'Intensity = power/area ∝ amplitude².', 'Point source: I = P/4πr².'],
      probs: [
        { l: 1, q: 'What is the phase difference between two points a quarter of a wavelength apart?', a: '90° (π/2 rad)', s: ['¼ × 360° = 90°.'] },
        { l: 1, q: 'A sound wave has frequency 200 Hz and wavelength 1.7 m. Find its speed.', a: '340 m/s', s: ['v = 200 × 1.7 = 340 m/s.'] },
        { l: 1, q: '60 W of radiation falls evenly on 2.0 m². What is the intensity?', a: '30 W m⁻²', s: ['I = 60 ÷ 2.0 = 30 W m⁻².'] },
        { l: 2, q: 'On an oscilloscope set to 2.0 ms/div and 0.50 V/div, one cycle spans 4.0 divisions and the trace is 6.0 divisions from peak to trough. Find the frequency and amplitude.', a: '125 Hz; 1.5 V', s: ['T = 4.0 × 2.0 ms = 8.0 ms ⇒ f = 125 Hz.', 'Peak-to-peak = 6.0 × 0.50 = 3.0 V ⇒ amplitude 1.5 V.'] },
        { l: 2, q: 'What happens to the intensity if the amplitude doubles? If it falls to a third?', a: '×4; ÷9', s: ['I ∝ A².'] },
        { l: 2, q: 'A 100 W point source radiates equally in all directions. Find the intensity at 2.0 m and at 4.0 m.', a: '2.0 W m⁻²; 0.50 W m⁻²', s: ['I = 100 ÷ (4π × 2.0²) = 1.99 W m⁻².', 'Doubling the distance quarters it: 0.50 W m⁻².'] },
        { l: 2, q: 'Two points on a wave of wavelength 2.4 m are 0.60 m apart along the direction of travel. Find their phase difference.', a: '90°', s: ['Δφ = (0.60 ÷ 2.4) × 360° = 90°.'] },
        { l: 2, q: 'The Sun’s luminosity is 3.85 × 10²⁶ W and Earth is 1.50 × 10¹¹ m away. Find the intensity of sunlight above the atmosphere.', a: 'About 1360 W m⁻²', s: ['I = 3.85 × 10²⁶ ÷ (4π × (1.50 × 10¹¹)²) = 1360 W m⁻².'] },
        { l: 3, q: 'At 3.0 m from a small loudspeaker the intensity is 0.010 W m⁻². At what distance is the amplitude halved? Estimate the speaker’s total acoustic power, stating your assumption.', a: '6.0 m; about 1.1 W', s: ['Half amplitude ⇒ quarter intensity ⇒ double the distance: 6.0 m.', 'P = I × 4πr² = 0.010 × 4π × 9.0 = 1.1 W, assuming it radiates equally in all directions with no absorption.'] },
        { l: 3, q: 'A transverse wave y = A sin(kx − ωt) travels in the +x direction. At t = 0 the point at x = λ/4 is at a crest. Where is that point a quarter of a period later, and which way is it moving?', a: 'At equilibrium, moving downwards', s: ['At x = λ/4: y = A sin(π/2 − ωt) = A cos ωt.', 'At t = T/4, y = A cos(π/2) = 0.', 'dy/dt = −Aω sin ωt < 0 there: moving down. (The crest has moved on by λ/4.)'] }
      ]
    },

    'al-doppler': {
      big: 'When a source of waves moves towards you, its wavefronts bunch up in front of it, so you receive a higher frequency; as it moves away, they spread out and the frequency drops. That is the Doppler effect, heard in every passing siren and used by radar guns, ultrasound scanners and astronomers.',
      sec: [
        { h: 'Why the frequency changes', p: ['A source emits wavefronts at frequency f_s. If it moves towards an observer at speed v_s, each new wavefront starts a little closer than the last, so the wavelength in front of it shortens to (v − v_s)/f_s, where v is the wave speed in the medium. The waves still travel at v, so the observed frequency rises.'] },
        { h: 'The formula', p: ['For a moving source and a stationary observer:'], eq: R`f_o = \frac{f_s\,v}{v \mp v_s}\qquad(-\ \text{approaching},\ +\ \text{receding})` },
        { h: 'A passing siren', p: ['As an ambulance approaches, you hear a steady higher pitch; as it passes, the pitch drops suddenly to a steady lower one. The frequency does not depend on the distance, only on the component of the source’s velocity along the line to you, which changes sign as it passes.'] },
        { h: 'Uses', list: ['Radar and laser speed guns: waves reflected from a moving car return with a frequency shift of about 2v/c times the original.', 'Doppler ultrasound: the shift of echoes from moving blood measures its speed.', 'Astronomy: the shift of spectral lines measures how fast stars and galaxies move towards or away from us.'] },
        { h: 'Moving faster than the waves', p: ['As v_s approaches v, the wavefronts pile up in front of the source and the formula predicts an infinite frequency. A source faster than its waves (a supersonic plane) leaves a cone-shaped shock wave behind it, heard on the ground as a sonic boom.'], warn: '**Conditions of the formula.** It assumes the medium is at rest (a wind changes the effective speeds), that the source speed is below the wave speed, and that the observer is stationary. A moving observer needs f_o = f_s(v ± v_o)/v, which is not the same: for sound, it matters which one moves relative to the air. For light there is no medium, and at high speeds the relativistic formula must be used.' }
      ],
      eqs: [[R`f_o = \frac{f_s v}{v - v_s}`, 'source approaching'], [R`f_o = \frac{f_s v}{v + v_s}`, 'source receding'], [R`\lambda_o = \frac{v - v_s}{f_s}`, 'wavelength in front of the source'], [R`\frac{\Delta f}{f} \approx \frac{2v}{c}`, 'reflection from a slowly moving target (radar)']],
      how: ['Decide approaching (−) or receding (+).', 'Use the wave speed in the medium for v.', 'For two measurements, divide the equations to eliminate f_s.', 'Check the answer: approaching must give a higher frequency.'],
      sum: ['Moving source: wavefronts compressed ahead, stretched behind.', 'f_o = f_s v/(v ∓ v_s).', 'The shift depends on speed along the line of sight, not distance.', 'Used in radar, ultrasound and astronomy.', 'Fails for v_s ≥ v (shock waves).'],
      probs: [
        { l: 1, q: 'A 500 Hz siren approaches at 30 m/s. What frequency do you hear? (Speed of sound 340 m/s)', a: '548 Hz', s: ['f = 500 × 340 ÷ (340 − 30) = 548 Hz.'] },
        { l: 1, q: 'What frequency do you hear once it has passed and is moving away at 30 m/s?', a: '459 Hz', s: ['f = 500 × 340 ÷ 370 = 459 Hz.'] },
        { l: 1, q: 'Explain why the pitch of a siren drops as the vehicle passes you.', a: 'Approaching, wavefronts are compressed; receding, they are stretched', s: ['The component of the source’s velocity towards you changes from positive to negative as it passes.'] },
        { l: 2, q: 'A car horn is heard at 520 Hz as the car approaches and 480 Hz as it recedes. Find the car’s speed and the horn’s frequency (v = 340 m/s).', a: '13.6 m/s; about 500 Hz', s: ['Dividing: (v + u)/(v − u) = 520/480.', 'u = v × 40/1000 = 13.6 m/s.', 'f_s = 520 × (340 − 13.6)/340 = 499 Hz.'] },
        { l: 2, q: 'A 400 Hz source moves at 20 m/s. What is the wavelength just in front of it, compared with when it is stationary?', a: '0.80 m instead of 0.85 m', s: ['In front: (340 − 20)/400 = 0.80 m.', 'Stationary: 340/400 = 0.85 m.'] },
        { l: 2, q: 'A train sounds a 300 Hz horn while travelling at 40 m/s. What frequencies does a person on the platform hear as it approaches and as it leaves?', a: '340 Hz and 268 Hz', s: ['300 × 340/300 = 340 Hz.', '300 × 340/380 = 268 Hz.'] },
        { l: 2, q: 'Why does the frequency you hear not change as an approaching siren gets nearer at constant speed, though it gets louder?', a: 'The shift depends only on the velocity along the line of sight', s: ['Loudness depends on distance (intensity), but the wavefront spacing depends only on the source’s velocity.'] },
        { l: 2, q: 'A police radar gun emits 24 GHz microwaves at a car moving towards it at 30 m/s. Using Δf ≈ 2vf/c, find the shift in the reflected frequency.', a: '4.8 kHz', s: ['Δf = 2 × 30 × 24 × 10⁹ ÷ 3.0 × 10⁸ = 4800 Hz.', 'The factor 2 appears because the car acts first as a moving observer and then as a moving source.'] },
        { l: 3, q: 'Derive f_o = f_s v/(v − v_s) for a source approaching a stationary observer.', a: 'Wavelength ahead = (v − v_s)/f_s', s: ['In one period T = 1/f_s, the first wavefront travels vT while the source moves v_sT.', 'So the next wavefront is emitted (v − v_s)T behind the first: λ_o = (v − v_s)/f_s.', 'The observer receives waves at speed v: f_o = v/λ_o = f_s v/(v − v_s).'] },
        { l: 3, q: 'What does the formula predict as an approaching source’s speed tends to the speed of sound? What actually happens for a supersonic aircraft?', a: 'An infinite frequency; a shock wave forms instead', s: ['As v_s → v, the denominator → 0 and f_o → ∞: all wavefronts pile up at the source.', 'Beyond v, the formula no longer applies: wavefronts form a cone (Mach cone) trailing the aircraft, and its passage is heard as a sonic boom.'] }
      ]
    },

    'al-polarisation': {
      big: 'Light, radio waves and X-rays are all electromagnetic waves, travelling at 3.0 × 10⁸ m/s in a vacuum and differing only in wavelength. Because they are transverse, they can be polarised: their oscillations confined to one plane. A polarising filter transmits a fraction cos²θ of polarised light, which explains sunglasses, LCD screens and stress patterns in plastic.',
      sec: [
        { h: 'The electromagnetic spectrum', list: ['Radio: longer than about 0.1 m.', 'Microwaves: about 1 mm to 0.1 m.', 'Infrared: about 700 nm to 1 mm.', 'Visible: about 400 nm (violet) to 700 nm (red).', 'Ultraviolet: about 10 nm to 400 nm.', 'X-rays: about 10⁻¹² m to 10⁻⁸ m.', 'Gamma rays: shorter than about 10⁻¹⁰ m (X-rays and gamma overlap; they are named by their origin).'], p: ['All travel at c = 3.00 × 10⁸ m/s in a vacuum, so f = c/λ.'] },
        { h: 'Polarisation', p: ['In a plane-polarised wave the oscillations (for light, of the electric field) are in one plane only. Only transverse waves can be polarised; sound in air, being longitudinal, cannot.', 'Ordinary light from the Sun or a lamp is unpolarised: the oscillation direction changes randomly. A polarising filter transmits only the component of the oscillation along its transmission axis.'] },
        { h: 'Malus’s law', p: ['Plane-polarised light of intensity I₀ meets a polariser (analyser) whose axis is at angle θ to the light’s plane. The transmitted amplitude is A₀ cos θ, and since intensity ∝ amplitude², the intensity is I₀ cos²θ. Unpolarised light through one ideal polariser loses half its intensity.'], eq: R`I = I_0\cos^2\theta` },
        { h: 'Uses', list: ['Polaroid sunglasses: light reflected from water or roads is partly polarised horizontally; vertical transmission axes block much of the glare.', 'LCD screens: liquid crystals rotate the plane of polarisation between crossed polarisers to switch pixels.', 'Stress analysis: stressed transparent plastic rotates polarisation by different amounts, showing coloured fringes between crossed polarisers.', 'Radio and TV aerials must be aligned with the plane of the transmitted wave.'] },
        { h: 'The three-polariser surprise', p: ['Two crossed polarisers (at 90°) let no light through. Put a third between them at 45°, and light gets through: an eighth of the original. The middle filter does not add light; it re-orients the polarisation so that part of it can pass the last filter.'], warn: '**Ideal versus real.** Malus’s law assumes perfect polarisers. Real ones transmit less than half of unpolarised light and leak a little at 90°. Reflected light is completely polarised only at one particular angle (Brewster’s angle, about 53° for water); at other angles it is partly polarised, so sunglasses reduce glare without removing it.' }
      ],
      eqs: [[R`c = f\lambda = 3.00\times10^8\ \text{m s}^{-1}`, 'all EM waves in a vacuum'], [R`I = I_0\cos^2\theta`, 'Malus’s law'], [R`I = \tfrac12 I_0`, 'unpolarised light through one polariser']],
      how: ['Classify EM waves by wavelength using the ranges.', 'For each polariser, apply cos² of the angle between the light’s plane and the axis.', 'Start with ½ for unpolarised light.', 'Track the plane of polarisation after each filter: it becomes the filter’s axis.'],
      sum: ['EM spectrum: radio, microwave, IR, visible (400–700 nm), UV, X-ray, gamma; all at c.', 'Only transverse waves can be polarised.', 'Malus: I = I₀cos²θ.', 'Unpolarised through one polariser: I₀/2.', 'Uses: sunglasses, LCDs, stress analysis, aerials.'],
      probs: [
        { l: 1, q: 'State the wavelength range of visible light.', a: 'About 400 nm to 700 nm', s: ['Violet ≈ 400 nm, red ≈ 700 nm.'] },
        { l: 1, q: 'Why can sound in air not be polarised?', a: 'It is longitudinal', s: ['Its oscillations are along the direction of travel, so there is no plane to select.'] },
        { l: 1, q: 'Unpolarised light of intensity 40 W m⁻² passes through an ideal polariser. What intensity emerges?', a: '20 W m⁻²', s: ['Half the intensity passes.'] },
        { l: 2, q: 'Plane-polarised light of 20 W m⁻² meets an analyser at 60° to its plane. Find the transmitted intensity.', a: '5.0 W m⁻²', s: ['I = 20 × cos²60° = 20 × 0.25 = 5.0 W m⁻².'] },
        { l: 2, q: 'At what angle must an analyser be set to transmit 75% of plane-polarised light?', a: '30°', s: ['cos²θ = 0.75 ⇒ cos θ = 0.866 ⇒ θ = 30°.'] },
        { l: 2, q: 'Unpolarised light passes through polarisers at 0°, 45° and 90° in turn. What fraction emerges? What if the middle one is removed?', a: 'One eighth; none', s: ['After the first: ½. After the second: ½ × cos²45° = ¼. After the third: ¼ × cos²45° = ⅛.', 'Without the middle filter, the last is at 90° to the first: cos²90° = 0.'] },
        { l: 2, q: 'Name the region of the spectrum for wavelengths of 3 cm, 500 nm, 0.1 nm and 10 μm.', a: 'Microwave, visible (green), X-ray, infrared', s: ['Compare each with the ranges.'] },
        { l: 2, q: 'Find the frequency of 600 nm light.', a: '5.0 × 10¹⁴ Hz', s: ['f = c/λ = 3.0 × 10⁸ ÷ 600 × 10⁻⁹ = 5.0 × 10¹⁴ Hz.'] },
        { l: 3, q: 'Unpolarised light passes through seven polarisers, the first at 0° and each further one turned 15° from the previous one, ending at 90°. What fraction emerges? What happens as the number of steps becomes very large?', a: 'About 33%; it approaches 50%', s: ['After the first: ½. Each of the six further steps transmits cos²15° = 0.933.', 'Fraction = ½ × 0.933⁶ = 0.33.', 'With more, smaller steps, cos² of the step angle → 1 faster than the number of steps grows, so the fraction → ½: the polarisation is rotated almost without loss.'] },
        { l: 3, q: 'Glare from a lake is partly polarised horizontally. Explain why Polaroid sunglasses have vertical transmission axes, and what you would notice if you tilted your head through 90°.', a: 'They block horizontally polarised glare; tilting your head lets the glare through', s: ['A vertical axis transmits little of the horizontally polarised reflection (cos²90° ≈ 0).', 'Tilt your head 90° and the axes become horizontal, so the glare reappears, while unpolarised light from the rest of the scene is unchanged.'] }
      ]
    },

    'al-stationary': {
      big: 'When two identical waves travel through each other in opposite directions, they produce a stationary wave: a pattern of fixed nodes, where nothing moves, and antinodes, where the oscillation is largest. Strings and air columns support stationary waves only at particular frequencies, which is why musical instruments play definite notes.',
      sec: [
        { h: 'How stationary waves form', p: ['A wave reflected back on itself superposes with the incoming wave. Where the two always cancel there are nodes; halfway between, where they reinforce, are antinodes. Adjacent nodes are half a wavelength apart.'], eq: R`\text{node to node} = \frac{\lambda}{2}` },
        { h: 'Stationary versus progressive', list: ['Energy: a progressive wave transfers energy; a stationary wave stores it.', 'Amplitude: the same everywhere in a progressive wave; varies from zero (nodes) to maximum (antinodes) in a stationary wave.', 'Phase: changes continuously along a progressive wave; in a stationary wave, all points between two adjacent nodes move in phase, and points either side of a node are in antiphase.'] },
        { h: 'Strings', p: ['A string fixed at both ends has nodes at the ends. It can vibrate when its length holds a whole number of half-wavelengths: L = nλ/2. The lowest (fundamental) frequency is v/2L, and the others are whole-number multiples (harmonics). The wave speed on the string depends on its tension T and mass per unit length μ.'], eq: R`f_n = \frac{n v}{2L},\qquad v = \sqrt{\frac{T}{\mu}}` },
        { h: 'Air columns', p: ['A pipe closed at one end has a node at the closed end and an antinode at the open end, so L = λ/4, 3λ/4, 5λ/4…: only odd harmonics. A pipe open at both ends has antinodes at both ends and all harmonics. In a resonance tube, the difference between the first two resonance lengths is λ/2, which removes the need to know the end correction.'] },
        { h: 'Microwaves and diffraction', p: ['Microwaves reflected from a metal plate form a stationary wave; moving a detector along it finds nodes λ/2 apart, giving λ directly.', 'Diffraction is the spreading of waves through a gap or round an edge. It is most noticeable when the gap is comparable to the wavelength; a gap much wider than λ lets waves through with little spreading.'], warn: '**End corrections and stiffness.** The antinode at an open end lies slightly outside the pipe (about 0.6 of its radius), so L = λ/4 underestimates λ unless corrected. Real strings are slightly stiff, so their higher harmonics are a little sharp (inharmonicity), noticeably in pianos. The node-at-the-end idea assumes perfectly rigid supports.' }
      ],
      eqs: [[R`d_{\text{NN}} = \lambda/2`, 'node spacing'], [R`f_n = nv/2L`, 'string fixed at both ends'], [R`f = \frac{(2n-1)v}{4L}`, 'pipe closed at one end'], [R`v = \sqrt{T/\mu}`, 'wave speed on a string'], [R`L_2 - L_1 = \lambda/2`, 'resonance tube']],
      how: ['Sketch the pattern with nodes at fixed ends and antinodes at open ends.', 'Count half-wavelengths (or quarter-wavelengths for closed pipes) along the length.', 'Use v = fλ to link frequency and wavelength.', 'Use differences between resonance positions to cancel end corrections.'],
      sum: ['Stationary waves: two waves travelling in opposite directions superpose.', 'Nodes λ/2 apart; antinodes halfway between.', 'No energy transfer; amplitude varies; points between nodes in phase.', 'Strings: f = nv/2L; closed pipes: odd harmonics only.', 'Diffraction is greatest when gap ≈ λ.'],
      probs: [
        { l: 1, q: 'Adjacent nodes in a stationary wave are 0.30 m apart. What is the wavelength?', a: '0.60 m', s: ['Node to node = λ/2.'] },
        { l: 1, q: 'Give two differences between a stationary wave and a progressive wave.', a: 'A stationary wave transfers no energy, and its amplitude varies with position', s: ['Also: all points between adjacent nodes oscillate in phase.'] },
        { l: 1, q: 'A guitar string 0.65 m long carries waves at 286 m/s. Find its fundamental frequency.', a: '220 Hz', s: ['f₁ = v/2L = 286 ÷ 1.30 = 220 Hz.'] },
        { l: 2, q: 'What are the second and third harmonics of that string?', a: '440 Hz and 660 Hz', s: ['f_n = nf₁.'] },
        { l: 2, q: 'Microwaves reflected from a metal plate form a stationary wave. The first and eleventh nodes found by a detector are 14.0 cm apart. Find the wavelength and frequency.', a: '2.80 cm; 1.07 × 10¹⁰ Hz', s: ['Ten node spacings in 14.0 cm: λ/2 = 1.40 cm ⇒ λ = 2.80 cm.', 'f = c/λ = 3.0 × 10⁸ ÷ 0.0280 = 1.07 × 10¹⁰ Hz.'] },
        { l: 2, q: 'Ignoring end corrections, what is the fundamental frequency of a 0.25 m pipe closed at one end? (v = 340 m/s)', a: '340 Hz', s: ['L = λ/4 ⇒ λ = 1.0 m ⇒ f = 340 Hz.'] },
        { l: 2, q: 'With a 512 Hz tuning fork, a resonance tube resonates at air-column lengths of 0.165 m and 0.505 m. Find the speed of sound and the end correction.', a: '348 m/s; 5 mm', s: ['λ/2 = 0.505 − 0.165 = 0.340 m ⇒ λ = 0.680 m.', 'v = 512 × 0.680 = 348 m/s.', 'First resonance: L₁ + e = λ/4 = 0.170 m ⇒ e = 0.005 m.'] },
        { l: 2, q: 'Microwaves of wavelength 3.0 cm pass through gaps of 3.0 cm and 30 cm. Compare the diffraction.', a: 'Strong spreading through the 3 cm gap; little through the 30 cm gap', s: ['Diffraction is greatest when the gap is about one wavelength.'] },
        { l: 3, q: 'Explain why a pipe closed at one end produces only odd harmonics.', a: 'It needs a node at the closed end and an antinode at the open end', s: ['That requires L to be an odd number of quarter-wavelengths: L = (2n − 1)λ/4.', 'So f = (2n − 1)v/4L: 1, 3, 5… times the fundamental, giving the clarinet its hollow tone.'] },
        { l: 3, q: 'A string 0.50 m long with mass per unit length 1.0 × 10⁻³ kg m⁻¹ is under 100 N tension. Find its fundamental frequency, and the tension needed to raise it by an octave.', a: '316 Hz; 400 N', s: ['v = √(T/μ) = √(100 ÷ 1.0 × 10⁻³) = 316 m/s; f₁ = 316 ÷ 1.0 = 316 Hz.', 'An octave doubles f, which needs double v, so four times the tension: 400 N.'] }
      ]
    },

    'al-current': {
      big: 'An electric current is a flow of charged particles. Its size depends on how many carriers there are, how fast they drift and the area they flow through: I = Anvq. Electrons in a metal drift astonishingly slowly, yet they carry energy whose rate of delivery, the power, is simply VI.',
      sec: [
        { h: 'Current and charge', p: ['Current is the rate of flow of charge. Charge is quantised: it comes in multiples of the elementary charge e = 1.60 × 10⁻¹⁹ C. Conventional current flows from + to −; in metals the carriers are electrons moving the other way.'], eq: R`I = \frac{\Delta Q}{\Delta t}` },
        { h: 'Deriving I = Anvq', p: ['Consider a wire of cross-sectional area A with n charge carriers per unit volume, each of charge q, drifting at speed v. In time t the carriers move a distance vt, so all those in a volume Avt pass a given point: a charge nAvtq. Dividing by t gives the current.'], eq: R`I = Anvq` },
        { h: 'Drift speed', p: ['Copper has about 8.5 × 10²⁸ free electrons per cubic metre. A current of a few amps in a 1 mm² wire gives a drift speed of only about a tenth of a millimetre per second. A lamp still lights instantly because the electric field that pushes the electrons is set up along the whole circuit almost at the speed of light.'] },
        { h: 'Potential difference and power', p: ['The potential difference between two points is the energy transferred per unit charge from electrical to other forms as charge moves between them. The power is the energy per second: V joules per coulomb times I coulombs per second.'], eq: R`V = \frac{W}{Q},\qquad P = VI = I^2R = \frac{V^2}{R}` },
        { h: 'Semiconductors', p: ['In a semiconductor, n is far smaller than in a metal, so the same current needs a much larger drift speed. That is why semiconductors have high resistances, and why the Hall voltage (proportional to 1/nq) is large enough in them to make sensitive magnetic-field probes.'], warn: '**What the drift picture simplifies.** I = Anvq uses an average drift velocity; individual electrons move randomly at about 10⁶ m/s and only drift slowly on average. The model treats n as fixed, but in semiconductors n rises steeply with temperature, so resistance falls as they warm, the opposite of metals.' }
      ],
      eqs: [[R`I = \Delta Q/\Delta t`, 'current'], [R`I = Anvq`, 'current from carrier density and drift speed'], [R`V = W/Q`, 'potential difference'], [R`P = VI = I^2R = V^2/R`, 'power'], [R`e = 1.60\times10^{-19}\ \text{C}`, 'elementary charge']],
      how: ['Convert areas to m² and times to s.', 'For drift speed, rearrange I = Anvq.', 'Pick the power formula that uses the quantities given.', 'Remember the same current flows in every part of a series circuit, even where the wire is thinner.'],
      sum: ['I = ΔQ/Δt; charge is quantised in units of e.', 'I = Anvq.', 'Drift speeds in metals are about 0.1 mm/s.', 'V = W/Q; P = VI = I²R = V²/R.', 'Semiconductors: few carriers, large drift speeds, large Hall voltages.'],
      probs: [
        { l: 1, q: 'A current of 3.0 A flows for 2.0 minutes. How much charge passes?', a: '360 C', s: ['Q = It = 3.0 × 120 = 360 C.'] },
        { l: 1, q: 'How many electrons pass a point each second in a current of 1.0 A?', a: '6.25 × 10¹⁸', s: ['n = 1.0 ÷ 1.60 × 10⁻¹⁹ = 6.25 × 10¹⁸ per second.'] },
        { l: 1, q: 'A heater takes 4.0 A from the 230 V mains. What is its power?', a: '920 W', s: ['P = VI = 230 × 4.0 = 920 W.'] },
        { l: 2, q: 'A copper wire of area 1.0 mm² carries 2.0 A, with n = 8.5 × 10²⁸ m⁻³. Find the drift speed.', a: '1.5 × 10⁻⁴ m/s', s: ['v = I/(Anq) = 2.0 ÷ (1.0 × 10⁻⁶ × 8.5 × 10²⁸ × 1.6 × 10⁻¹⁹) = 1.5 × 10⁻⁴ m/s.'] },
        { l: 2, q: 'The same current passes from that wire into one of half the diameter. How does the drift speed change?', a: 'It becomes four times larger', s: ['Half the diameter gives a quarter of the area; with I and n unchanged, v ∝ 1/A.'] },
        { l: 2, q: 'How much energy does a 12 V battery transfer when 5.0 C of charge flows round the circuit?', a: '60 J', s: ['W = QV = 5.0 × 12 = 60 J.'] },
        { l: 2, q: 'A current of 0.50 A flows through a 20 Ω resistor. Find the p.d. and the power, and check with P = V²/R.', a: '10 V; 5.0 W', s: ['V = IR = 10 V; P = I²R = 0.25 × 20 = 5.0 W.', 'V²/R = 100 ÷ 20 = 5.0 W.'] },
        { l: 2, q: 'If electrons drift at about 0.1 mm/s, why does a lamp 2 m from the switch light almost instantly?', a: 'The field driving the electrons is set up throughout the circuit almost instantly', s: ['The wire is already full of free electrons; they all start drifting at once when the field reaches them, at nearly the speed of light.'] },
        { l: 3, q: 'Pure silicon at room temperature has about 1 × 10¹⁶ free charge carriers per cubic metre, compared with 8.5 × 10²⁸ for copper. For the same current in the same area, how do the drift speeds compare? What does this suggest about their resistances?', a: 'Silicon’s drift speed is about 10¹³ times larger; silicon has a far higher resistance', s: ['v ∝ 1/n for fixed I and A: ratio 8.5 × 10²⁸ ÷ 1 × 10¹⁶ ≈ 10¹³.', 'Such drift speeds are impossible, so with a practical voltage the current through silicon is tiny: its resistivity is enormous compared with copper’s.'] },
        { l: 3, q: 'An old television’s electron beam carried 1.0 mA, with each electron accelerated through 25 kV. Find the number of electrons per second, the energy of each in joules and electronvolts, and the beam power.', a: '6.25 × 10¹⁵ s⁻¹; 4.0 × 10⁻¹⁵ J = 25 keV; 25 W', s: ['n = 1.0 × 10⁻³ ÷ 1.6 × 10⁻¹⁹ = 6.25 × 10¹⁵ per second.', 'E = eV = 1.6 × 10⁻¹⁹ × 25 000 = 4.0 × 10⁻¹⁵ J = 25 keV.', 'P = VI = 25 000 × 1.0 × 10⁻³ = 25 W.'] }
      ]
    }
  });
})();
/* ---- notes-al5.js ---- */
/* Geodesic: notes and ten-problem sets for A Level outline topics, part 3 (Cambridge 9702 sections 9.3–10, 14, 16, 20, 21). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'al-resistivity': {
      big: 'Resistance tells you how much voltage it takes to push a given current through a component. For a uniform wire it depends on its length, its area and a material property, the resistivity. Plotting current against voltage reveals how each component behaves: straight lines for ohmic resistors, curves for lamps, and one-way conduction for diodes.',
      sec: [
        { h: 'Resistance and Ohm’s law', p: ['Resistance is defined as R = V/I, in ohms. Ohm’s law states that the current in a metallic conductor is proportional to the potential difference across it, provided its temperature (and other physical conditions) stay constant. Components obeying it are ohmic.'], eq: R`R = \frac{V}{I}` },
        { h: 'Resistivity', p: ['For a uniform wire, R is proportional to length and inversely proportional to cross-sectional area. The constant is the resistivity ρ, a property of the material at a given temperature: about 1.7 × 10⁻⁸ Ω m for copper, 2.8 × 10⁻⁸ Ω m for aluminium, 1.1 × 10⁻⁶ Ω m for nichrome.'], eq: R`R = \frac{\rho L}{A}` },
        { h: 'I–V characteristics', list: ['Ohmic resistor at constant temperature: a straight line through the origin.', 'Filament lamp: a curve that flattens at higher voltages, because the filament heats up and its resistance rises.', 'Semiconductor diode: almost no current in reverse; in the forward direction, little current until about 0.6–0.7 V (silicon), then the current rises steeply.'] },
        { h: 'Why metals’ resistance rises with temperature', p: ['In a metal, the number of free electrons is fixed. Hotter ions vibrate more, scattering the drifting electrons more often, so the resistance increases (for copper, by about 0.4% per kelvin).'] },
        { h: 'Sensors: LDRs and thermistors', p: ['A light-dependent resistor’s resistance falls as light intensity increases. An NTC thermistor’s resistance falls as temperature increases. In both, more energy frees more charge carriers, which outweighs any extra scattering.'], warn: '**Ohm’s law is not a universal law.** It is an empirical rule that holds for metals at constant temperature, not a definition of resistance. R = V/I applies to any component at any point on its characteristic, but for a lamp or diode the ratio changes with V. And ρ is only “constant” at a fixed temperature and for samples much thicker than the electrons’ mean free path; very thin films have higher resistivity.' }
      ],
      eqs: [[R`R = V/I`, 'definition of resistance'], [R`R = \rho L/A`, 'resistivity'], [R`R \propto L,\ R \propto 1/A`, 'dependence on shape'], [R`V_F \approx 0.7\ \text{V}`, 'silicon diode forward voltage']],
      how: ['Convert areas: A = πd²/4, with d in metres.', 'For reshaped wires, fixed volume means L × A is constant.', 'Read resistance at a point as V/I, not as the gradient.', 'For sensors, decide how carrier numbers change with light or temperature.'],
      sum: ['R = V/I; Ohm’s law: I ∝ V at constant temperature.', 'R = ρL/A.', 'Lamp: resistance rises as it heats. Diode: conducts one way above about 0.7 V.', 'Metals: resistance rises with temperature (more scattering).', 'LDR and NTC thermistor: resistance falls with light or heat (more carriers).'],
      probs: [
        { l: 1, q: 'Find the resistance of 2.0 m of nichrome wire (ρ = 1.1 × 10⁻⁶ Ω m) with cross-sectional area 0.20 mm².', a: '11 Ω', s: ['R = 1.1 × 10⁻⁶ × 2.0 ÷ 0.20 × 10⁻⁶ = 11 Ω.'] },
        { l: 1, q: 'State Ohm’s law.', a: 'For a metallic conductor at constant temperature, the current is proportional to the p.d.', s: ['Its I–V graph is a straight line through the origin.'] },
        { l: 1, q: 'Describe the I–V graph of a filament lamp and explain its shape.', a: 'A curve that gets less steep at higher voltages, because the hot filament has higher resistance', s: ['Higher current heats the filament; more ion vibration scatters electrons more.'] },
        { l: 2, q: 'A 1.50 m wire of diameter 0.32 mm has a resistance of 9.0 Ω. Find its resistivity.', a: '4.8 × 10⁻⁷ Ω m', s: ['A = π(0.16 × 10⁻³)² = 8.04 × 10⁻⁸ m².', 'ρ = RA/L = 9.0 × 8.04 × 10⁻⁸ ÷ 1.50 = 4.8 × 10⁻⁷ Ω m (close to constantan).'] },
        { l: 2, q: 'A wire is drawn out to twice its length while keeping the same volume. By what factor does its resistance change?', a: '×4', s: ['L doubles; A halves (same volume): R ∝ L/A grows by 2 × 2 = 4.'] },
        { l: 2, q: 'A 12 V, 24 W lamp has a resistance of only 0.6 Ω when cold. Find its hot resistance and the current at the instant it is switched on.', a: '6 Ω; about 20 A', s: ['Hot: R = V²/P = 144 ÷ 24 = 6.0 Ω.', 'Cold: I = 12 ÷ 0.6 = 20 A, ten times the running current: why filament lamps usually failed at switch-on.'] },
        { l: 2, q: 'A silicon diode drops 0.70 V when it carries 20 mA. What series resistor lets it run at 20 mA from a 5.0 V supply?', a: 'About 215 Ω (use 220 Ω)', s: ['The resistor takes 5.0 − 0.7 = 4.3 V.', 'R = 4.3 ÷ 0.020 = 215 Ω.'] },
        { l: 2, q: 'An LDR has 500 Ω in bright light and 50 kΩ in the dark. What current flows with 6.0 V across it in each case?', a: '12 mA; 0.12 mA', s: ['I = 6.0 ÷ 500 = 12 mA; I = 6.0 ÷ 50 000 = 0.12 mA.'] },
        { l: 3, q: 'A copper coil has a resistance of 10.0 Ω at 20 °C and copper’s resistance rises by 0.39% per kelvin. Find its resistance at 80 °C, and explain the rise microscopically.', a: 'About 12.3 Ω', s: ['R = 10.0 × (1 + 0.0039 × 60) = 12.3 Ω.', 'The number of free electrons is fixed, but the ions vibrate more strongly, scattering electrons more often and reducing their drift speed for a given p.d.'] },
        { l: 3, q: 'Overhead power cables use aluminium (ρ = 2.8 × 10⁻⁸ Ω m, density 2700 kg m⁻³) rather than copper (1.7 × 10⁻⁸ Ω m, 8960 kg m⁻³). For the same resistance per metre, compare the masses per metre.', a: 'Aluminium is about half the mass', s: ['Same R/L needs A ∝ ρ: A_{Al}/A_{Cu} = 2.8/1.7 = 1.65.', 'Mass per metre ∝ density × A: 1.65 × 2700/8960 = 0.50.', 'Lighter cables need fewer, lighter pylons, outweighing aluminium’s higher resistivity.'] }
      ]
    },

    'al-dc-circuits': {
      big: 'A real battery has internal resistance, so its terminal p.d. falls as it delivers more current. Kirchhoff’s two laws, one for charge and one for energy, solve any d.c. network: the currents into a junction add up to the currents out, and the e.m.f.s round any loop equal the sum of the p.d.s.',
      sec: [
        { h: 'e.m.f. and potential difference', p: ['The e.m.f. of a source is the energy transferred from other forms (chemical, mechanical) to electrical energy per unit charge driven round the circuit. The p.d. across a component is the energy transferred from electrical to other forms per unit charge passing through it.'] },
        { h: 'Internal resistance', p: ['A real source behaves like a perfect e.m.f. E in series with an internal resistance r. Some energy per coulomb, Ir, is lost inside, so the terminal p.d. is less than the e.m.f. whenever current flows. A graph of terminal p.d. against current is a straight line with intercept E and gradient −r.'], eq: R`E = I(R + r),\qquad V = E - Ir` },
        { h: 'Kirchhoff’s laws', list: ['First law: the sum of currents into a junction equals the sum of currents out (conservation of charge).', 'Second law: round any closed loop, the sum of the e.m.f.s equals the sum of the p.d.s (conservation of energy).'] },
        { h: 'Combining resistors', p: ['Series: the same current flows through each, and the p.d.s add, so R = R₁ + R₂ + …. Parallel: the same p.d. is across each, and the currents add, so 1/R = 1/R₁ + 1/R₂ + ….'], eq: R`R_s = \sum R_i,\qquad \frac{1}{R_p} = \sum\frac{1}{R_i}` },
        { h: 'Power delivered to a load', p: ['The power in an external resistor R is P = E²R/(R + r)². It is greatest when R = r, but then half the power is wasted inside the source. Power stations and batteries are therefore designed with r much smaller than the load, while matching R to r matters in signal circuits such as aerials and amplifiers.'], warn: '**Internal resistance is a model.** Treating a battery as a fixed E plus a fixed r works over a limited range. Real internal resistance changes with temperature, state of charge and current, which is why a cold car battery struggles to turn the starter. Kirchhoff’s second law also assumes no changing magnetic fields threading the loop; with them (in a.c. circuits with transformers), induced e.m.f.s must be included.' }
      ],
      eqs: [[R`E = I(R + r)`, 'source with internal resistance'], [R`V = E - Ir`, 'terminal p.d.'], [R`\sum I_{\text{in}} = \sum I_{\text{out}}`, 'Kirchhoff’s first law'], [R`\sum E = \sum IR`, 'Kirchhoff’s second law (round a loop)'], [R`P = \frac{E^2R}{(R + r)^2}`, 'power in the load']],
      how: ['Label unknown currents with arrows; a negative answer means the real current is opposite.', 'Apply the first law at junctions to reduce the unknowns.', 'Apply the second law round enough independent loops.', 'Include internal resistance as a resistor inside the source.'],
      sum: ['e.m.f.: energy given per coulomb; p.d.: energy taken per coulomb.', 'V = E − Ir; V–I graph: intercept E, gradient −r.', 'Kirchhoff I (charge) and II (energy).', 'Series resistances add; parallel reciprocals add.', 'Maximum power when R = r, at 50% efficiency.'],
      probs: [
        { l: 1, q: 'A battery of e.m.f. 9.0 V and internal resistance 1.0 Ω drives current through an 8.0 Ω resistor. Find the current and the terminal p.d.', a: '1.0 A; 8.0 V', s: ['I = 9.0 ÷ (8.0 + 1.0) = 1.0 A.', 'V = 9.0 − 1.0 × 1.0 = 8.0 V.'] },
        { l: 1, q: 'State Kirchhoff’s first law and the principle it expresses.', a: 'Current into a junction = current out; conservation of charge', s: ['Charge cannot accumulate at a junction.'] },
        { l: 1, q: 'Use Kirchhoff’s second law to show that resistors in series add.', a: 'E = IR₁ + IR₂ = I(R₁ + R₂)', s: ['The same current flows through each; the p.d.s add to the e.m.f.', 'So the combination behaves as R₁ + R₂.'] },
        { l: 2, q: 'A cell gives a terminal p.d. of 1.40 V at 0.20 A and 1.20 V at 0.60 A. Find its e.m.f. and internal resistance.', a: '1.50 V; 0.50 Ω', s: ['1.40 = E − 0.20r and 1.20 = E − 0.60r.', 'Subtracting: 0.20 = 0.40r ⇒ r = 0.50 Ω; E = 1.40 + 0.10 = 1.50 V.'] },
        { l: 2, q: 'How do you find E and r from a graph of terminal p.d. against current?', a: 'E is the intercept on the V axis; r is minus the gradient', s: ['V = E − Ir is a straight line with gradient −r.'] },
        { l: 2, q: 'A 12.0 V car battery with internal resistance 0.020 Ω supplies 150 A to the starter motor. Find the terminal p.d. and the power wasted in the battery.', a: '9.0 V; 450 W', s: ['V = 12.0 − 150 × 0.020 = 9.0 V (why the lights dim).', 'P = I²r = 150² × 0.020 = 450 W.'] },
        { l: 2, q: 'Two identical cells (E = 1.5 V, r = 1.0 Ω) are connected in parallel across a 2.5 Ω resistor. Find the current in the resistor.', a: '0.50 A', s: ['In parallel the combination has E = 1.5 V and r = 0.50 Ω.', 'I = 1.5 ÷ (2.5 + 0.50) = 0.50 A.'] },
        { l: 2, q: 'A 12 V and a 6.0 V battery are connected in a single loop facing opposite ways, with 3.0 Ω of total resistance. Find the current.', a: '2.0 A, driven by the 12 V battery', s: ['Net e.m.f. = 12 − 6.0 = 6.0 V round the loop.', 'I = 6.0 ÷ 3.0 = 2.0 A; the 6.0 V battery is being charged.'] },
        { l: 3, q: 'A 10 V cell with a 2.0 Ω resistor and a 5.0 V cell with a 1.0 Ω resistor are connected in parallel branches, positive terminals at the top, across a 4.0 Ω resistor. Find the current in each branch.', a: '2.14 A from the 10 V cell; 0.71 A into the 5.0 V cell; 1.43 A through the 4.0 Ω resistor', s: ['Let V be the top node’s potential above the bottom: I₁ = (10 − V)/2.0, I₂ = (5.0 − V)/1.0, I₃ = V/4.0.', 'First law: V/4 = (10 − V)/2 + (5 − V) ⇒ 1.75V = 10 ⇒ V = 5.71 V.', 'I₁ = 2.14 A, I₂ = −0.71 A (current flows into the 5.0 V cell, charging it), I₃ = 1.43 A.'] },
        { l: 3, q: 'A source has E = 12 V and r = 2.0 Ω. Find the power in external resistors of 1.0, 2.0 and 4.0 Ω. Which gives the most power, and what is the efficiency then?', a: '16 W, 18 W, 16 W; R = r gives the maximum, at 50% efficiency', s: ['P = E²R/(R + r)²: 144 × 1/9 = 16 W; 144 × 2/16 = 18 W; 144 × 4/36 = 16 W.', 'At R = r, the same current flows through equal resistances, so half the power is wasted inside the source.'] }
      ]
    },

    'al-potential-divider': {
      big: 'Two resistors in series split a voltage in proportion to their resistances. Make one of them a sensor and the output voltage tracks light or temperature. A potentiometer goes further: by finding the point where no current flows (a null), it measures an e.m.f. without drawing any current from it.',
      sec: [
        { h: 'The potential divider', p: ['Two resistors R₁ and R₂ in series across a supply V_{in} carry the same current, so the p.d.s are in the ratio of the resistances. The output across R₂ is a fixed fraction of the input.'], eq: R`V_{\text{out}} = V_{\text{in}}\frac{R_2}{R_1 + R_2},\qquad \frac{V_1}{V_2} = \frac{R_1}{R_2}` },
        { h: 'Variable dividers and sensors', p: ['A variable resistor or a sliding contact on a resistance track gives a continuously adjustable output from 0 to V_{in}. Replacing one resistor with an LDR or thermistor makes V_{out} depend on light or temperature. To make V_{out} rise with temperature using an NTC thermistor, take the output across the fixed resistor: as the thermistor’s resistance falls, the fixed resistor’s share of the voltage grows.'] },
        { h: 'Loading', p: ['Connecting a load (or a voltmeter) across R₂ puts it in parallel with R₂, lowering the combined resistance and therefore V_{out}. The divider equation holds only if the load’s resistance is much larger than R₂.'] },
        { h: 'The potentiometer', p: ['A driver cell maintains a steady current along a uniform resistance wire, so the p.d. along the wire is proportional to length. A test cell is connected, through a galvanometer, between one end of the wire and a sliding contact. At the balance point the galvanometer reads zero: no current flows through the test cell, so the p.d. along that length of wire equals the cell’s e.m.f. exactly, not its terminal p.d.'], eq: R`\frac{E_1}{E_2} = \frac{l_1}{l_2}` },
        { h: 'Null methods', p: ['A null method compares two quantities by adjusting until a detector reads zero. Because the detector only needs to show zero, not measure a value, its calibration does not matter, and no current is drawn from the thing being measured.'], warn: '**Hidden requirements.** The potentiometer assumes a uniform wire (p.d. proportional to length) and a driver cell whose e.m.f. stays steady during the measurement. A non-uniform wire gives a systematic error that no amount of repetition removes. The divider equation assumes ideal resistors; real sensors also self-heat if too much current flows through them, changing the very quantity they measure.' }
      ],
      eqs: [[R`V_{\text{out}} = V_{\text{in}}\,R_2/(R_1+R_2)`, 'potential divider'], [R`V_1/V_2 = R_1/R_2`, 'resistor ratio'], [R`E_1/E_2 = l_1/l_2`, 'potentiometer comparison of e.m.f.s'], [R`R_{\parallel} = \frac{R_2R_L}{R_2 + R_L}`, 'loading by R_L']],
      how: ['Find the current through the series pair, or use the ratio directly.', 'For sensors, decide whether the sensor resistance rises or falls, then which resistor gains voltage.', 'For loading, replace R₂ by its parallel combination with the load.', 'For potentiometers, use the ratio of balance lengths.'],
      sum: ['V_{out} = V_{in} R₂/(R₁ + R₂).', 'Sensors in dividers turn light or temperature into voltage.', 'Loads lower V_{out} unless their resistance is much larger than R₂.', 'Potentiometer: balance length ∝ e.m.f.; no current drawn at balance.', 'Null methods do not depend on the detector’s calibration.'],
      probs: [
        { l: 1, q: 'A 12 V supply is connected across 4.0 kΩ and 8.0 kΩ in series. Find the p.d. across the 8.0 kΩ resistor.', a: '8.0 V', s: ['V = 12 × 8.0 ÷ 12.0 = 8.0 V.'] },
        { l: 1, q: 'Why does a potentiometer at balance measure a cell’s e.m.f. rather than its terminal p.d.?', a: 'No current flows through the cell, so there is no Ir drop', s: ['V = E − Ir with I = 0 gives V = E.'] },
        { l: 1, q: 'What does a variable potential divider let you do?', a: 'Obtain any output voltage from zero up to the supply voltage', s: ['The sliding contact selects the fraction.'] },
        { l: 2, q: 'A potentiometer wire 1.000 m long has 2.00 V across it. A test cell balances at 0.745 m. Find its e.m.f.', a: '1.49 V', s: ['p.d. per metre = 2.00 V/m; E = 2.00 × 0.745 = 1.49 V.'] },
        { l: 2, q: 'A standard cell of e.m.f. 1.018 V balances at 0.509 m and an unknown cell at 0.750 m on the same wire. Find the unknown e.m.f.', a: '1.50 V', s: ['E = 1.018 × 0.750 ÷ 0.509 = 1.50 V.'] },
        { l: 2, q: 'Two 10 kΩ resistors divide 10 V. A voltmeter of resistance 10 kΩ is connected across the lower one. What does it read? What would a 1.0 MΩ voltmeter read?', a: '3.3 V; 4.99 V', s: ['10 kΩ ∥ 10 kΩ = 5.0 kΩ: V = 10 × 5.0 ÷ 15 = 3.3 V instead of 5.0 V.', '10 kΩ ∥ 1.0 MΩ = 9.90 kΩ: V = 10 × 9.90 ÷ 19.9 = 4.98 V.'] },
        { l: 2, q: 'An NTC thermistor and a fixed resistor form a divider for an overheating alarm whose output must rise with temperature. Across which component should the output be taken?', a: 'Across the fixed resistor', s: ['As temperature rises, the thermistor’s resistance falls, so the fixed resistor takes a larger share of the voltage.'] },
        { l: 2, q: 'An LDR (2.0 kΩ in light, 20 kΩ in the dark) is in series with a 10 kΩ resistor across 5.0 V. Find the voltage across the LDR in light and in the dark.', a: '0.83 V; 3.3 V', s: ['Light: 5.0 × 2.0 ÷ 12 = 0.83 V.', 'Dark: 5.0 × 20 ÷ 30 = 3.3 V.'] },
        { l: 3, q: 'For that LDR, a fixed resistor of √(2.0 × 20) kΩ ≈ 6.3 kΩ gives the largest change in output between light and dark. Find the outputs and compare with the 10 kΩ choice.', a: '1.20 V and 3.80 V: a 2.60 V swing against 2.50 V', s: ['Light: 5.0 × 2.0 ÷ 8.3 = 1.20 V. Dark: 5.0 × 20 ÷ 26.3 = 3.80 V.', 'Swing = 2.60 V, slightly better than 3.33 − 0.83 = 2.50 V with 10 kΩ.'] },
        { l: 3, q: 'A potentiometer wire is slightly thicker at one end. Explain the effect on measured e.m.f.s and whether repeating readings helps.', a: 'p.d. is no longer proportional to length: a systematic error that repeats cannot remove', s: ['The thicker part has less resistance per metre, so less p.d. per metre.', 'Balance lengths no longer scale with e.m.f., and every repeat gives the same error.', 'Calibrating against a standard cell near the measured value reduces it.'] }
      ]
    },

    'al-bfields': {
      big: 'A magnetic field pushes on moving charges, sideways to both their motion and the field. On a current-carrying wire this gives F = BIL; on a single charge, F = BQv. Because the force is always perpendicular to the velocity, a charged particle in a uniform field moves in a circle, the key to mass spectrometers, cyclotrons and the Hall-effect probes in every phone.',
      sec: [
        { h: 'Force on a current', p: ['A wire of length L carrying current I at angle θ to a uniform field B feels a force F = BIL sin θ, perpendicular to both (Fleming’s left-hand rule). This defines the tesla: 1 T is the field in which a 1 m wire carrying 1 A at right angles feels 1 N.'], eq: R`F = BIL\sin\theta` },
        { h: 'Force on a moving charge', p: ['A charge Q moving at speed v at angle θ to the field feels F = BQv sin θ. The force is perpendicular to the velocity, so it changes the direction but never the speed: magnetic fields do no work on free charges.'], eq: R`F = BQv\sin\theta` },
        { h: 'Circular motion and velocity selection', p: ['With v perpendicular to B, the magnetic force supplies the centripetal force: BQv = mv²/r, so r = mv/(BQ). Faster or heavier particles make wider circles; the time for one orbit, 2πm/(BQ), does not depend on speed.', 'Crossed electric and magnetic fields pass undeflected only particles whose electric and magnetic forces cancel: EQ = BQv, so v = E/B, whatever their charge or mass.'], eq: R`r = \frac{mv}{BQ},\qquad v = \frac{E}{B}` },
        { h: 'The Hall effect', p: ['Current flowing through a thin slice of conductor in a perpendicular field has its carriers pushed to one side. Charge builds up until the resulting electric field balances the magnetic force, leaving a Hall voltage across the slice. It is inversely proportional to the carrier density, so it is large in semiconductors and tiny in metals.'], eq: R`V_H = \frac{BI}{ntq}` },
        { h: 'Fields of currents', p: ['A long straight wire has circular field lines (right-hand grip rule); a flat circular coil has a field like a short bar magnet’s; a long solenoid has a strong, uniform field inside. An iron core multiplies the field strength. Two parallel wires carrying currents in the same direction attract; in opposite directions, they repel.'], warn: '**Idealisations.** F = BIL assumes a uniform field along the whole length of wire; real magnets have fringing fields at their edges. r = mv/BQ is non-relativistic: at high energies momentum is γmv, which is why cyclotrons fail for fast protons and synchrotrons were invented. The simple Hall formula assumes one type of carrier; some semiconductors conduct with both electrons and holes, which can even reverse the sign of V_H.' }
      ],
      eqs: [[R`F = BIL\sin\theta`, 'force on a current'], [R`F = BQv\sin\theta`, 'force on a moving charge'], [R`r = mv/BQ`, 'radius of circular path'], [R`v = E/B`, 'velocity selector'], [R`V_H = BI/(ntq)`, 'Hall voltage']],
      how: ['Use Fleming’s left-hand rule with conventional current (for electrons, current is opposite to their motion).', 'Use the component of B perpendicular to the current or velocity.', 'For circular paths, equate BQv to mv²/r.', 'For Hall probes, smaller n gives bigger V_H.'],
      sum: ['F = BIL sin θ; 1 T = 1 N A⁻¹ m⁻¹.', 'F = BQv sin θ, always perpendicular to v: no work done.', 'Circles: r = mv/BQ; period independent of speed.', 'Velocity selector: v = E/B.', 'Hall voltage V_H = BI/(ntq).'],
      probs: [
        { l: 1, q: 'A 0.20 m wire carries 3.0 A at right angles to a 0.50 T field. Find the force on it.', a: '0.30 N', s: ['F = BIL = 0.50 × 3.0 × 0.20 = 0.30 N.'] },
        { l: 1, q: 'What is the force if the wire is at 30° to the field?', a: '0.15 N', s: ['F = BIL sin 30° = 0.30 × 0.5 = 0.15 N.'] },
        { l: 1, q: 'An electron moves at 2.0 × 10⁶ m/s at right angles to a 0.010 T field. Find the force on it.', a: '3.2 × 10⁻¹⁵ N', s: ['F = Bev = 0.010 × 1.6 × 10⁻¹⁹ × 2.0 × 10⁶ = 3.2 × 10⁻¹⁵ N.'] },
        { l: 2, q: 'Find the radius of that electron’s circular path (mₑ = 9.11 × 10⁻³¹ kg).', a: '1.1 mm', s: ['r = mv/(Be) = 9.11 × 10⁻³¹ × 2.0 × 10⁶ ÷ (0.010 × 1.6 × 10⁻¹⁹) = 1.1 × 10⁻³ m.'] },
        { l: 2, q: 'Crossed fields of 2.0 × 10⁴ V/m and 0.050 T form a velocity selector. What speed passes undeflected?', a: '4.0 × 10⁵ m/s', s: ['v = E/B = 2.0 × 10⁴ ÷ 0.050 = 4.0 × 10⁵ m/s, for any charge or mass.'] },
        { l: 2, q: 'A semiconductor slice 0.50 mm thick with n = 1.0 × 10²² m⁻³ carries 0.10 A in a 0.50 T field. Find the Hall voltage. What would it be for copper (n = 8.5 × 10²⁸ m⁻³)?', a: '63 mV; about 7 nV', s: ['V_H = BI/(ntq) = 0.50 × 0.10 ÷ (1.0 × 10²² × 5.0 × 10⁻⁴ × 1.6 × 10⁻¹⁹) = 0.063 V.', 'Copper: 8500 times more carriers ⇒ 7.4 × 10⁻⁹ V: why Hall probes use semiconductors.'] },
        { l: 2, q: 'Find the period of a proton’s circular motion in a 1.5 T field (m = 1.67 × 10⁻²⁷ kg). Why doesn’t it depend on the proton’s speed?', a: '4.4 × 10⁻⁸ s (about 23 MHz)', s: ['T = 2πr/v = 2πm/(BQ) = 4.4 × 10⁻⁸ s.', 'A faster proton travels a proportionally larger circle, so it takes the same time: the principle of the cyclotron.'] },
        { l: 2, q: 'Two long parallel wires carry currents in the same direction. Explain why they attract.', a: 'Each sits in the other’s magnetic field and feels a force towards it', s: ['Wire 1’s field at wire 2 is perpendicular to wire 2; the left-hand rule gives a force on wire 2 towards wire 1, and by Newton’s third law the reverse.'] },
        { l: 3, q: 'After a velocity selector set to 4.0 × 10⁴ m/s, singly charged magnesium-24 and magnesium-26 ions enter a 0.10 T field. Find the radius of each path and the distance between where they land after a semicircle (u = 1.66 × 10⁻²⁷ kg).', a: '0.0997 m and 0.108 m; landing points 1.7 cm apart', s: ['r = mv/(Be): Mg-24: 24 × 1.66 × 10⁻²⁷ × 4.0 × 10⁴ ÷ (0.10 × 1.6 × 10⁻¹⁹) = 0.0996 m.', 'Mg-26: 0.108 m.', 'After a semicircle each lands 2r from the entrance: 2 × (0.108 − 0.0996) = 0.017 m apart.'] },
        { l: 3, q: 'A horizontal east–west power cable carries 500 A where Earth’s field component perpendicular to it is 4.0 × 10⁻⁵ T. Find the magnetic force per metre on the cable and compare it with its weight of about 10 N per metre.', a: '0.020 N per metre: 0.2% of its weight', s: ['F/L = BI = 4.0 × 10⁻⁵ × 500 = 0.020 N/m.', 'Tiny compared with gravity; but forces between parallel conductors carrying fault currents of tens of kiloamps can be large enough to bend busbars.'] }
      ]
    },

    'al-ac': {
      big: 'Mains electricity alternates, so its current and voltage swing sinusoidally between positive and negative peaks. The useful measure is the root-mean-square value, the steady current that would heat a resistor at the same average rate. Diodes turn a.c. into one-way current, and a capacitor smooths the ripples.',
      sec: [
        { h: 'Describing alternating current', p: ['A sinusoidal current I = I₀ sin(2πft) has peak value I₀, period T and frequency f = 1/T. UK mains has f = 50 Hz.'], eq: R`I = I_0\sin\omega t,\qquad \omega = 2\pi f` },
        { h: 'Root-mean-square values', p: ['The power in a resistor is I²R. Averaged over a cycle, sin² has a mean of ½, so the mean power is ½I₀²R. The r.m.s. current is the steady (d.c.) current that would give the same mean power: I_{rms} = I₀/√2. Similarly V_{rms} = V₀/√2. Mains “230 V” is an r.m.s. value; its peak is about 325 V.'], eq: R`I_{\text{rms}} = \frac{I_0}{\sqrt2},\qquad V_{\text{rms}} = \frac{V_0}{\sqrt2},\qquad \langle P\rangle = I_{\text{rms}}V_{\text{rms}} = \tfrac12I_0V_0` },
        { h: 'Mean versus r.m.s.', p: ['The mean current over a whole cycle of a sine wave is zero, which says nothing about heating. Squaring first makes every contribution positive, and the square root restores the units: hence root-mean-square. For a resistor the peak power is twice the mean power.'] },
        { h: 'Rectification', p: ['A single diode passes only one half of each cycle: half-wave rectification, which wastes half the waveform. A bridge of four diodes routes both halves through the load in the same direction: full-wave rectification, giving pulses at twice the mains frequency (100 Hz).'] },
        { h: 'Smoothing', p: ['A capacitor across the load charges up to the peak voltage on each pulse, then discharges through the load between pulses, filling in the gaps. The ripple is smaller when the time constant RC is much longer than the time between pulses: a larger capacitance or a larger load resistance gives smoother output.'], warn: '**The √2 belongs to sine waves.** I_{rms} = I₀/√2 holds only for sinusoids: a square wave of peak V₀ has V_{rms} = V₀, and a triangular wave V₀/√3. Many cheap meters assume a sine and misread other waveforms; “true r.m.s.” meters do not. Real diodes also drop about 0.7 V each (1.4 V in a bridge), so a rectifier’s output peak is a little below the a.c. peak.' }
      ],
      eqs: [[R`I_{\text{rms}} = I_0/\sqrt2`, 'sinusoidal current'], [R`V_{\text{rms}} = V_0/\sqrt2`, 'sinusoidal voltage'], [R`\langle P\rangle = I_{\text{rms}}^2R = \tfrac12I_0^2R`, 'mean power in a resistor'], [R`P_{\text{peak}} = 2\langle P\rangle`, 'peak power in a resistor'], [R`RC \gg T_{\text{ripple}}`, 'condition for good smoothing']],
      how: ['Convert r.m.s. ↔ peak with √2 (sine waves only).', 'Use r.m.s. values in P = IV for mean power.', 'Read peak voltage and period from an oscilloscope, then compute r.m.s. and f.', 'For smoothing, compare RC with the time between pulses.'],
      sum: ['I = I₀ sin ωt; f = 1/T.', 'I_{rms} = I₀/√2; mains 230 V r.m.s. peaks at 325 V.', 'Mean power = ½I₀V₀ = I_{rms} V_{rms}; peak power = twice the mean.', 'Half-wave: one diode. Full-wave: bridge of four.', 'Smoothing capacitor: ripple small when RC ≫ pulse spacing.'],
      probs: [
        { l: 1, q: 'UK mains is 230 V r.m.s. What is its peak voltage?', a: '325 V', s: ['V₀ = 230 × √2 = 325 V.'] },
        { l: 1, q: 'A 60 W lamp runs on 230 V r.m.s. Find the r.m.s. and peak currents.', a: '0.26 A; 0.37 A', s: ['I_{rms} = 60 ÷ 230 = 0.26 A; I₀ = 0.26 × √2 = 0.37 A.'] },
        { l: 1, q: 'How is the peak power in a resistor related to its mean power on a sinusoidal supply?', a: 'Peak power = 2 × mean power', s: ['P = I₀²R sin²ωt peaks at I₀²R; its mean is ½I₀²R.'] },
        { l: 2, q: 'Show that I_{rms} = I₀/√2 for a sinusoidal current.', a: 'The mean of sin² over a cycle is ½', s: ['Mean power = ⟨I₀² sin²ωt⟩R = ½I₀²R.', 'Setting I_{rms}²R = ½I₀²R gives I_{rms} = I₀/√2.'] },
        { l: 2, q: 'A sinusoidal supply is half-wave rectified by one diode feeding a resistor. How does the mean power compare with the unrectified supply? What is the effective r.m.s. current?', a: 'Half the power; I₀/2', s: ['Only half of each cycle delivers power: mean = ¼I₀²R.', 'I_{rms}² = ¼I₀² ⇒ I_{rms} = I₀/2.'] },
        { l: 2, q: 'Explain how a bridge rectifier gives full-wave rectification.', a: 'Two diodes conduct in each half-cycle, always sending current the same way through the load', s: ['On positive half-cycles one pair of opposite diodes conducts; on negative half-cycles the other pair does.', 'In both, the current through the load is in the same direction.'] },
        { l: 2, q: 'A full-wave rectified 50 Hz supply feeds a 1.0 kΩ load with a 1000 μF smoothing capacitor. Compare RC with the time between pulses and estimate the ripple as a fraction of the peak.', a: 'RC = 1.0 s ≫ 0.010 s; ripple about 1%', s: ['Pulses come at 100 Hz: every 0.010 s.', 'Between pulses the capacitor discharges by about Δt/RC = 0.010 ÷ 1.0 = 1% of its voltage.'] },
        { l: 2, q: 'On an oscilloscope (5.0 V/div, 5.0 ms/div) a sine wave has peaks 3.0 divisions above the centre and a period of 4.0 divisions. Find V_{rms} and the frequency.', a: '10.6 V; 50 Hz', s: ['V₀ = 15 V ⇒ V_{rms} = 15 ÷ √2 = 10.6 V.', 'T = 20 ms ⇒ f = 50 Hz.'] },
        { l: 3, q: 'Explain why the r.m.s. value, not the mean value, is used to describe alternating currents.', a: 'The mean of a symmetric a.c. is zero, but its heating effect is not', s: ['Heating depends on I², which is positive in both halves of the cycle.', 'Root-mean-square averages I² and takes the root, giving the equivalent steady current.'] },
        { l: 3, q: 'Find the r.m.s. value of a square wave that switches between +V₀ and −V₀. Compare its heating with a sine wave of the same peak.', a: 'V_{rms} = V₀; it heats twice as much', s: ['V² = V₀² at every instant, so its mean is V₀² and V_{rms} = V₀.', 'A sine of peak V₀ has V_{rms}² = V₀²/2: half the mean power.'] }
      ]
    },

    'al-temperature': {
      big: 'Bodies in thermal contact exchange energy until they reach the same temperature: thermal equilibrium. The thermodynamic (Kelvin) scale measures temperature without relying on any particular substance, with absolute zero as its origin. Heating a substance raises its temperature by an amount set by its specific heat capacity; changing state at constant temperature needs latent heat.',
      sec: [
        { h: 'Thermal equilibrium and temperature', p: ['Thermal energy flows from a region of higher temperature to one of lower temperature. When there is no net flow between two bodies in contact, they are in thermal equilibrium and have the same temperature. That is what lets a thermometer work: it comes to equilibrium with what it measures.'] },
        { h: 'Temperature scales', p: ['Practical thermometers use a thermometric property that varies with temperature: the expansion of a liquid, the resistance of a metal wire, the e.m.f. of a thermocouple, the pressure of a gas at constant volume. Calibrated at two fixed points, different thermometers agree there but generally not in between, because their properties are not exactly linear.', 'The thermodynamic scale does not depend on any substance. Its zero is absolute zero, where a system has minimum internal energy; its unit, the kelvin, is the same size as a degree Celsius.'], eq: R`T/\text{K} = \theta/^\circ\text{C} + 273.15` },
        { h: 'Specific heat capacity', p: ['The specific heat capacity c is the energy needed to raise the temperature of 1 kg of a substance by 1 K. Water’s is unusually large (4200 J kg⁻¹ K⁻¹), which is why the sea moderates coastal climates.', 'To measure it, heat a known mass with an electric heater of known power for a measured time, insulated to reduce losses, and record the temperature rise: c = Pt/(mΔθ). Heat losses make the measured c too large.'], eq: R`E = mc\Delta\theta` },
        { h: 'Specific latent heat', p: ['During melting or boiling, the temperature stays constant while energy is supplied: it goes into breaking bonds between molecules (increasing their potential energy), not into making them move faster. The specific latent heat is the energy per kilogram for the change of state, at constant temperature.', 'For water, the latent heat of vaporisation (2.26 MJ/kg) is about seven times that of fusion (0.334 MJ/kg): boiling separates the molecules completely and pushes back the atmosphere, whereas melting only loosens the structure.'], eq: R`E = mL` },
        { h: 'Heating curves', p: ['Supplying energy at a steady rate, a heating curve shows sloping sections (temperature rising, gradient ∝ 1/c) and flat sections (changes of state, length ∝ L).'], warn: '**Calibration and losses.** Two thermometers that agree at 0 °C and 100 °C can disagree by several tenths of a degree in between: a platinum resistance thermometer reads about 50.4 °C at a true 50.0 °C if its slight curvature is ignored. Calorimetry assumes all the heater’s energy goes into the sample; in practice losses to the surroundings dominate the uncertainty unless the temperature rise is kept small or corrected for.' }
      ],
      eqs: [[R`T = \theta + 273.15`, 'kelvin from Celsius'], [R`E = mc\Delta\theta`, 'specific heat capacity'], [R`E = mL`, 'specific latent heat'], [R`c = \frac{Pt}{m\Delta\theta}`, 'electrical method']],
      how: ['Identify each stage: warming (mcΔθ) or changing state (mL).', 'In mixing problems, energy lost by the hot part = energy gained by the cold part.', 'Use kelvin for absolute temperatures; temperature differences are equal in K and °C.', 'Say how heat losses bias an experimental result.'],
      sum: ['Equal temperature ⇔ thermal equilibrium.', 'Thermodynamic scale: independent of substance; 0 K = absolute zero.', 'E = mcΔθ; E = mL at constant temperature.', 'Latent heat raises potential energy of molecules, not their kinetic energy.', 'L_v ≫ L_f for water.'],
      probs: [
        { l: 1, q: 'Convert 25 °C to kelvin and 77 K to degrees Celsius.', a: '298 K; −196 °C', s: ['25 + 273.15 = 298.15 K; 77 − 273.15 = −196 °C.'] },
        { l: 1, q: 'How much energy raises 2.0 kg of water by 30 K? (c = 4200 J kg⁻¹ K⁻¹)', a: '252 kJ', s: ['E = 2.0 × 4200 × 30 = 252 000 J.'] },
        { l: 1, q: 'How much energy melts 0.50 kg of ice at 0 °C? (L_f = 3.34 × 10⁵ J/kg)', a: '167 kJ', s: ['E = 0.50 × 3.34 × 10⁵ = 1.67 × 10⁵ J.'] },
        { l: 2, q: 'A 50 W heater warms a 1.0 kg aluminium block from 20.0 °C to 30.6 °C in 200 s. Find c. Is the true value likely to be higher or lower?', a: '940 J kg⁻¹ K⁻¹; lower (accepted value about 900)', s: ['c = Pt/(mΔθ) = 50 × 200 ÷ (1.0 × 10.6) = 943 J kg⁻¹ K⁻¹.', 'Some energy escaped, so the true temperature rise per joule is larger: the true c is smaller.'] },
        { l: 2, q: 'A 2.0 kW kettle holds 1.5 kg of water at 20 °C. How long until it boils, and how much longer to boil off 0.20 kg? (L_v = 2.26 × 10⁶ J/kg)', a: '252 s; 226 s more', s: ['To 100 °C: 1.5 × 4200 × 80 = 504 kJ ⇒ 252 s.', 'Vaporising: 0.20 × 2.26 × 10⁶ = 452 kJ ⇒ 226 s.'] },
        { l: 2, q: '0.20 kg of ice at 0 °C is added to 1.0 kg of water at 40 °C. Find the final temperature, ignoring losses.', a: 'About 20 °C', s: ['Melting needs 0.20 × 3.34 × 10⁵ = 66 800 J.', 'Energy balance: 1.0 × 4200 × (40 − T) = 66 800 + 0.20 × 4200 × T.', '168 000 − 4200T = 66 800 + 840T ⇒ T = 20.1 °C.'] },
        { l: 2, q: 'Why is water’s latent heat of vaporisation so much larger than its latent heat of fusion?', a: 'Boiling separates molecules completely and does work against the atmosphere', s: ['Melting only loosens the solid structure; molecules stay close together.', 'In boiling, all intermolecular bonds are broken and the vapour expands by about 1600 times against atmospheric pressure.'] },
        { l: 2, q: 'Give one advantage each of a thermocouple and a resistance thermometer.', a: 'Thermocouple: small, fast, wide range. Resistance thermometer: accurate and stable', s: ['A thermocouple junction has tiny heat capacity, so it responds quickly and reaches very high temperatures.', 'Platinum resistance thermometers give precise, reproducible readings.'] },
        { l: 3, q: 'A platinum thermometer has R = R₀(1 + Aθ + Bθ²) with A = 3.9 × 10⁻³ K⁻¹ and B = −5.8 × 10⁻⁷ K⁻². If it is calibrated linearly between 0 °C and 100 °C, what does it read at a true 50.0 °C?', a: 'About 50.4 °C', s: ['R₁₀₀/R₀ = 1 + 0.39 − 0.0058 = 1.3842; R₅₀/R₀ = 1 + 0.195 − 0.00145 = 1.19355.', 'Linear scale: θ = 100 × 0.19355 ÷ 0.3842 = 50.4 °C.', 'Different thermometric properties define slightly different scales between fixed points; the thermodynamic scale avoids this.'] },
        { l: 3, q: 'How much energy turns 1.0 kg of ice at −10 °C into steam at 100 °C? (c_{ice} = 2100, c_{water} = 4200 J kg⁻¹ K⁻¹; L_f = 3.34 × 10⁵, L_v = 2.26 × 10⁶ J/kg) Which stage dominates?', a: 'About 3.0 MJ; vaporisation, about three quarters', s: ['Warm ice: 21 kJ. Melt: 334 kJ. Warm water: 420 kJ. Vaporise: 2260 kJ.', 'Total ≈ 3.04 MJ; vaporisation is 74% of it.'] }
      ]
    },

    'al-thermodynamics': {
      big: 'The internal energy of a system is the total random kinetic and potential energy of its molecules. It can be changed in only two ways: by heating the system or by doing work on it. That bookkeeping is the first law of thermodynamics, ΔU = q + W, and it explains why pumping a tyre warms it and why a gas cools when it expands.',
      sec: [
        { h: 'Internal energy', p: ['Internal energy is the sum of the random kinetic energies and the intermolecular potential energies of all the molecules in a system. Raising the temperature increases the kinetic part; changing state at constant temperature changes the potential part.', 'In an ideal gas the molecules exert no forces on each other except in collisions, so there is no potential energy: the internal energy depends only on temperature.'] },
        { h: 'Work done by and on a gas', p: ['When a gas expands at constant pressure p by ΔV, it pushes its surroundings back and does work pΔV on them; when it is compressed, work pΔV is done on it. On a p–V graph, the work is the area under the curve.'], eq: R`W = p\Delta V` },
        { h: 'The first law', p: ['The increase in internal energy equals the energy supplied to the system by heating plus the work done on the system. (Some books use W for work done by the system and write ΔU = q − W; always check the sign convention.)'], eq: R`\Delta U = q + W` },
        { h: 'Special cases', list: ['No heat exchange (adiabatic, q = 0): compressing a gas (W > 0) raises U and T; this is why a bicycle pump gets hot. Expanding (W < 0) cools it, as in a spray can.', 'Constant temperature for an ideal gas (ΔU = 0): heat supplied equals work done by the gas.', 'Constant volume (W = 0): all heat supplied goes into internal energy.', 'A complete cycle (ΔU = 0): the net work done by the gas equals the net heat supplied, and equals the area enclosed on the p–V diagram.'] },
        { h: 'Ideal-gas internal energy', p: ['For a monatomic ideal gas, U = (3/2)nRT, the total translational kinetic energy of its atoms. One mole at 300 K holds about 3.7 kJ.'], eq: R`U = \tfrac32nRT\quad(\text{monatomic ideal gas})`, warn: '**Heat and work are not things a system has.** A system has internal energy; heat and work are two ways of transferring it, and the same final state can be reached with different mixes of the two. The first law also says nothing about which processes happen by themselves: heat never flows spontaneously from cold to hot, a fact that needs the second law and entropy.' }
      ],
      eqs: [[R`\Delta U = q + W`, 'first law (W done on the system)'], [R`W = p\Delta V`, 'work at constant pressure'], [R`U = \tfrac32 nRT`, 'monatomic ideal gas'], [R`\oint p\,dV = \text{enclosed area}`, 'net work in a cycle']],
      how: ['Fix the sign convention: q in = positive, W on the gas = positive.', 'For expansion, the work done on the gas is negative.', 'For ideal gases, ΔU depends only on ΔT.', 'For cycles, use ΔU = 0 and the enclosed area.'],
      sum: ['Internal energy = random kinetic + potential energy of molecules.', 'Ideal gas: U depends only on T.', 'W = pΔV; area under a p–V curve.', 'ΔU = q + W.', 'Adiabatic compression heats; expansion cools.'],
      probs: [
        { l: 1, q: 'A gas is compressed by 2.0 × 10⁻³ m³ at a constant pressure of 1.0 × 10⁵ Pa. How much work is done on it?', a: '200 J', s: ['W = pΔV = 1.0 × 10⁵ × 2.0 × 10⁻³ = 200 J.'] },
        { l: 1, q: 'During that compression the gas also loses 50 J by heating. Find ΔU.', a: '+150 J', s: ['ΔU = q + W = −50 + 200 = 150 J.'] },
        { l: 1, q: 'Define internal energy.', a: 'The sum of the random kinetic and potential energies of the molecules', s: ['Not including the kinetic energy of the system moving as a whole.'] },
        { l: 2, q: 'Ice melting at 0 °C stays at 0 °C while absorbing energy. What happens to its internal energy, and why?', a: 'It increases: the molecules’ potential energy rises', s: ['Temperature, and so mean kinetic energy, is constant.', 'The energy breaks intermolecular bonds, raising the potential energy.'] },
        { l: 2, q: 'A gas expands at a constant 2.0 × 10⁵ Pa from 1.0 L to 3.0 L while 1000 J is supplied by heating. Find ΔU.', a: '+600 J', s: ['W on the gas = −pΔV = −2.0 × 10⁵ × 2.0 × 10⁻³ = −400 J.', 'ΔU = 1000 − 400 = 600 J.'] },
        { l: 2, q: 'Explain, using the first law, why a bicycle pump gets warm when you pump quickly.', a: 'Rapid compression: q ≈ 0 and W > 0, so U and T rise', s: ['The compression is too quick for much heat to escape.', 'Work done on the air raises its internal energy, so its temperature rises.'] },
        { l: 2, q: 'An ideal gas expands slowly at constant temperature, doing 300 J of work. How much heat does it absorb?', a: '300 J', s: ['ΔU = 0 at constant T for an ideal gas.', 'q = −W = −(−300) = 300 J.'] },
        { l: 2, q: 'Find the internal energy of 1.0 mol of a monatomic ideal gas at 300 K. (R = 8.31 J mol⁻¹ K⁻¹)', a: 'About 3.7 kJ', s: ['U = 1.5 × 1.0 × 8.31 × 300 = 3740 J.'] },
        { l: 3, q: 'A gas is taken round a rectangular cycle on a p–V diagram between 1.0 × 10⁵ and 2.0 × 10⁵ Pa and between 1.0 and 3.0 L, clockwise. Find the net work done by the gas per cycle and the net heat supplied.', a: '200 J each', s: ['Enclosed area = (2.0 − 1.0) × 10⁵ × (3.0 − 1.0) × 10⁻³ = 200 J.', 'Clockwise: the gas does net work 200 J. Over a cycle ΔU = 0, so net heat in = 200 J.'] },
        { l: 3, q: '1.0 kg of water at 100 °C becomes 1.67 m³ of steam at 1.01 × 10⁵ Pa. How much work does it do pushing back the atmosphere, and how much of the 2.26 MJ latent heat goes into internal energy?', a: '0.17 MJ of work; 2.09 MJ into internal energy', s: ['W by the steam = pΔV ≈ 1.01 × 10⁵ × 1.67 = 1.69 × 10⁵ J (the water’s own volume is negligible).', 'ΔU = q + W = 2.26 × 10⁶ − 1.69 × 10⁵ = 2.09 × 10⁶ J.', 'About 7.5% of the latent heat pays for pushing back the air.'] }
      ]
    }
  });
})();
/* ---- notes-al6.js ---- */
/* Geodesic: notes and ten-problem sets for A Level outline topics, part 4 (Cambridge 9702 sections 11, 22–25). */
(function () {
  const N = ((window.WL = window.WL || {}).notes = window.WL.notes || {}), R = String.raw;
  Object.assign(N, {
    'al-particles': {
      big: 'Protons and neutrons are not fundamental: each is three quarks. Together with leptons such as the electron and the neutrino, quarks are the building blocks of matter, and in beta decay one kind of quark turns into another. Every decay must conserve charge, baryon number and lepton number, and that bookkeeping predicted the neutrino decades before it was detected.',
      sec: [
        { h: 'Nucleus and decays', p: ['The nucleus contains protons and neutrons (nucleons). In alpha decay a nucleus emits a helium-4 nucleus: A falls by 4 and Z by 2. In β⁻ decay a neutron becomes a proton, emitting an electron and an electron antineutrino: Z rises by 1. In β⁺ decay a proton becomes a neutron, emitting a positron and a neutrino: Z falls by 1. Gamma emission releases energy without changing A or Z.'], eq: R`\beta^-:\ n \rightarrow p + e^- + \bar\nu_e\qquad \beta^+:\ p \rightarrow n + e^+ + \nu_e` },
        { h: 'Why neutrinos were needed', p: ['Alpha particles from one decay all have the same energy, but beta particles come out with a continuous spread of energies up to a maximum. If only two particles were produced, energy and momentum conservation would fix the electron’s energy. Pauli proposed in 1930 that a third, almost undetectable particle carries off the rest; neutrinos were finally detected in 1956.'] },
        { h: 'Antiparticles', p: ['Every particle has an antiparticle with the same mass and opposite charge (and other opposite quantum numbers): the positron is the antielectron. A particle and its antiparticle can annihilate into photons.'] },
        { h: 'Quarks, hadrons and leptons', list: ['Quarks: up (+⅔e), down (−⅓e), strange (−⅓e), charm (+⅔e), top (+⅔e), bottom (−⅓e). Antiquarks have the opposite charges.', 'Hadrons are made of quarks. Baryons are three quarks: proton uud (+1), neutron udd (0). Mesons are a quark and an antiquark: π⁺ = u d̄ (+1).', 'Leptons are fundamental and do not feel the strong force: electron, muon, tau and their three neutrinos.'] },
        { h: 'Beta decay at the quark level', p: ['In β⁻ decay a down quark changes into an up quark (udd → uud), emitting an electron and an antineutrino; in β⁺ decay an up quark becomes a down quark. Only the weak interaction can change a quark’s flavour.', 'Every interaction conserves charge, baryon number (+⅓ per quark, −⅓ per antiquark) and lepton number (+1 for leptons, −1 for antileptons).'], eq: R`\beta^-:\ d \rightarrow u + e^- + \bar\nu_e\qquad \beta^+:\ u \rightarrow d + e^+ + \nu_e`, warn: '**What the simple model glosses over.** Free quarks have never been seen: they are confined inside hadrons, and their existence was established by electrons scattering off point-like charges inside protons (SLAC, 1968). Neutrinos were long described as massless, but neutrino oscillations show they have small, non-zero masses, which the original Standard Model did not include.' }
      ],
      eqs: [[R`p = uud,\ n = udd`, 'quark content of nucleons'], [R`q_u = +\tfrac23e,\ q_d = -\tfrac13e`, 'quark charges'], [R`d \rightarrow u + e^- + \bar\nu_e`, 'β⁻ decay'], [R`u \rightarrow d + e^+ + \nu_e`, 'β⁺ decay'], [R`d_{\min} = \frac{kQ_1Q_2}{E_k}`, 'closest approach of an alpha particle']],
      how: ['Write the quark content of each hadron and add the charges.', 'Check charge, baryon number and lepton number on both sides of any decay.', 'Balance A and Z in nuclear equations.', 'Use antiparticles’ opposite charges and quantum numbers.'],
      sum: ['α, β⁻, β⁺ and γ change the nucleus in different ways.', 'The continuous β energy spectrum implies the (anti)neutrino.', 'Antiparticles: same mass, opposite charge.', 'Baryons = 3 quarks; mesons = quark + antiquark; leptons are fundamental.', 'β decay changes a quark’s flavour via the weak interaction.'],
      probs: [
        { l: 1, q: 'Give the quark content and charge of a proton and of a neutron.', a: 'uud, +1; udd, 0', s: ['Proton: ⅔ + ⅔ − ⅓ = +1. Neutron: ⅔ − ⅓ − ⅓ = 0.'] },
        { l: 1, q: 'Write the equation for the β⁻ decay of carbon-14.', a: '¹⁴₆C → ¹⁴₇N + ⁰₋₁e + ν̄ₑ', s: ['A stays 14; Z rises from 6 to 7.'] },
        { l: 1, q: 'State the antiparticle of the electron and how it differs.', a: 'The positron: same mass, positive charge', s: ['It also has lepton number −1.'] },
        { l: 2, q: 'What happens to a quark in β⁺ decay? Write the quark-level equation.', a: 'An up quark becomes a down quark: u → d + e⁺ + νₑ', s: ['The proton (uud) becomes a neutron (udd).'] },
        { l: 2, q: 'Find the charges of the pions π⁺ = u d̄ and π⁻ = d ū.', a: '+1 and −1', s: ['u d̄: +⅔ + ⅓ = +1. d ū: −⅓ − ⅔ = −1.'] },
        { l: 2, q: 'A free proton cannot undergo β⁺ decay, but a proton inside some nuclei can. Explain.', a: 'A free neutron is heavier than a proton, so the decay would need energy; in a nucleus, binding energy can supply it', s: ['m_n + m_e > m_p, so p → n + e⁺ + ν would violate energy conservation in isolation.', 'In a proton-rich nucleus, the daughter nucleus can be more tightly bound, releasing the extra energy.'] },
        { l: 2, q: 'Explain how the energy spectrum of beta particles led to the prediction of the neutrino.', a: 'A two-body decay would give a single energy; the observed continuous spectrum needs a third particle', s: ['With two products, conservation of energy and momentum fixes each product’s energy.', 'Beta energies vary from zero to a maximum, so an unseen particle shares the energy.'] },
        { l: 2, q: 'Find the charges of the Λ⁰ (uds), Σ⁺ (uus) and Ω⁻ (sss) baryons.', a: '0, +1, −1', s: ['uds: ⅔ − ⅓ − ⅓ = 0. uus: ⅔ + ⅔ − ⅓ = +1. sss: −1.'] },
        { l: 3, q: 'Check that n → p + e⁻ + ν̄ₑ conserves charge, baryon number and lepton number. Which law would n → p + e⁻ break?', a: 'All three are conserved; the two-body version breaks lepton number', s: ['Charge: 0 = +1 − 1 + 0.', 'Baryon number: 1 = 1 + 0 + 0.', 'Lepton number: 0 = 0 + 1 − 1.', 'Without the antineutrino, lepton number would go from 0 to 1.'] },
        { l: 3, q: 'A 5.0 MeV alpha particle heads straight for a gold nucleus (Z = 79). Find its distance of closest approach. What does this tell you about the size of the gold nucleus?', a: '4.5 × 10⁻¹⁴ m; the nucleus is smaller than this', s: ['At closest approach all kinetic energy is electric potential energy: d = kQ₁Q₂/Eₖ.', 'd = 8.99 × 10⁹ × 2 × 79 × (1.6 × 10⁻¹⁹)² ÷ (5.0 × 1.6 × 10⁻¹³) = 4.5 × 10⁻¹⁴ m.', 'Because these alphas scatter as if the nucleus were a point charge, its radius must be less than this (it is about 7 × 10⁻¹⁵ m).'] }
      ]
    },

    'al-photons': {
      big: 'Light arrives in packets of energy, photons, each carrying E = hf and momentum h/λ. Conversely, particles such as electrons behave as waves with wavelength λ = h/p, and they diffract through crystals just like X-rays. Wave and particle are two faces of the same quantum objects.',
      sec: [
        { h: 'Photons', p: ['Electromagnetic radiation is emitted and absorbed in discrete quanta. A photon of frequency f carries energy E = hf = hc/λ, where h = 6.63 × 10⁻³⁴ J s. Blue light photons carry more energy than red ones; a brighter beam of the same colour carries more photons, not bigger ones.'], eq: R`E = hf = \frac{hc}{\lambda}` },
        { h: 'The electronvolt', p: ['One electronvolt is the energy gained by an electron accelerated through a potential difference of one volt: 1 eV = 1.60 × 10⁻¹⁹ J. Visible photons carry roughly 1.8–3.1 eV. A handy rule: E (eV) ≈ 1240/λ (nm).'] },
        { h: 'Photon momentum', p: ['Photons have no mass but carry momentum p = E/c = h/λ. Absorbing light therefore exerts a small pressure (I/c for full absorption): enough to push solar sails and to shape comet tails.'], eq: R`p = \frac{E}{c} = \frac{h}{\lambda}` },
        { h: 'Electron diffraction', p: ['In an electron diffraction tube, electrons accelerated through a few kilovolts pass through a thin layer of graphite and form concentric rings on a screen, a diffraction pattern like X-rays make. The rings shrink as the voltage increases. Davisson and Germer (1927) and G. P. Thomson showed this, confirming de Broglie’s idea that matter has a wavelength.'] },
        { h: 'The de Broglie wavelength', p: ['Any particle with momentum p has a wavelength λ = h/p. For an electron accelerated from rest through a p.d. V, eV = p²/2m, so p = √(2meV) and λ falls as 1/√V. At 100 V it is about 0.12 nm, comparable to atomic spacings, which is why crystals diffract electrons.'], eq: R`\lambda = \frac{h}{p} = \frac{h}{\sqrt{2meV}}`, warn: '**Neither picture is the whole story.** “Light is a wave” explains diffraction; “light is particles” explains the photoelectric effect; neither alone explains both. Quantum mechanics treats both light and electrons as quantum fields whose detection events are particle-like and whose probabilities spread like waves. And λ = h/√(2meV) is non-relativistic: above about 100 kV, as in electron microscopes, the relativistic momentum must be used.' }
      ],
      eqs: [[R`E = hf = hc/\lambda`, 'photon energy'], [R`1\ \text{eV} = 1.60\times10^{-19}\ \text{J}`, 'electronvolt'], [R`p = h/\lambda`, 'photon or particle momentum'], [R`\lambda = h/\sqrt{2meV}`, 'electron accelerated through V'], [R`E\,(\text{eV}) \approx 1240/\lambda\,(\text{nm})`, 'shortcut']],
      how: ['Convert between J and eV with e.', 'For photons, use E = hc/λ; for momentum, p = h/λ.', 'For particles, find p (from mv or √(2mEₖ)) and then λ = h/p.', 'Compare λ with the spacing of the obstacle to judge whether diffraction is visible.'],
      sum: ['Photon: E = hf, p = h/λ.', '1 eV = 1.60 × 10⁻¹⁹ J.', 'Electron diffraction proves matter waves.', 'λ = h/p; for accelerated electrons λ ∝ 1/√V.', 'Wave and particle descriptions are complementary.'],
      probs: [
        { l: 1, q: 'Find the energy of a 500 nm photon in joules and electronvolts.', a: '4.0 × 10⁻¹⁹ J; 2.5 eV', s: ['E = hc/λ = 6.63 × 10⁻³⁴ × 3.0 × 10⁸ ÷ 500 × 10⁻⁹ = 3.98 × 10⁻¹⁹ J = 2.48 eV.'] },
        { l: 1, q: 'Convert 5.0 eV into joules.', a: '8.0 × 10⁻¹⁹ J', s: ['5.0 × 1.60 × 10⁻¹⁹ = 8.0 × 10⁻¹⁹ J.'] },
        { l: 1, q: 'Find the momentum of a 500 nm photon.', a: '1.3 × 10⁻²⁷ kg m s⁻¹', s: ['p = h/λ = 6.63 × 10⁻³⁴ ÷ 500 × 10⁻⁹ = 1.33 × 10⁻²⁷ kg m s⁻¹.'] },
        { l: 2, q: 'How many photons per second does a 1.0 mW laser emit at 633 nm?', a: '3.2 × 10¹⁵', s: ['E per photon = hc/λ = 3.14 × 10⁻¹⁹ J.', 'N = 1.0 × 10⁻³ ÷ 3.14 × 10⁻¹⁹ = 3.2 × 10¹⁵ per second.'] },
        { l: 2, q: 'Find the de Broglie wavelength of an electron accelerated from rest through 100 V.', a: '1.2 × 10⁻¹⁰ m', s: ['p = √(2meV) = √(2 × 9.11 × 10⁻³¹ × 1.6 × 10⁻¹⁷) = 5.4 × 10⁻²⁴ kg m s⁻¹.', 'λ = h/p = 1.23 × 10⁻¹⁰ m, similar to atomic spacings.'] },
        { l: 2, q: 'Find the de Broglie wavelength of a 0.15 kg cricket ball at 40 m/s. Why is it never seen to diffract?', a: '1.1 × 10⁻³⁴ m; far smaller than any gap', s: ['λ = h/(mv) = 6.63 × 10⁻³⁴ ÷ 6.0 = 1.1 × 10⁻³⁴ m.', 'Diffraction needs openings comparable to λ, about 10¹⁹ times smaller than a proton.'] },
        { l: 2, q: 'In an electron diffraction tube, what happens to the rings when the accelerating voltage is increased? Explain.', a: 'They get smaller', s: ['Higher V gives faster electrons, larger momentum and shorter wavelength (λ ∝ 1/√V).', 'Shorter wavelengths diffract through smaller angles.'] },
        { l: 2, q: 'Sunlight of intensity 1361 W m⁻² is fully absorbed by a surface. What pressure does it exert?', a: '4.5 × 10⁻⁶ Pa', s: ['Momentum per second per square metre = I/c = 1361 ÷ 3.0 × 10⁸ = 4.5 × 10⁻⁶ Pa.', 'Tiny, but over a 1000 m² solar sail it gives a steady 4.5 mN with no fuel.'] },
        { l: 3, q: 'An X-ray photon and an electron both have a wavelength of 0.10 nm. Find the photon’s energy and the electron’s kinetic energy. Why does an electron microscope reach atomic resolution with lower energies than X-rays need?', a: '12 keV for the photon; about 150 eV for the electron', s: ['Photon: E = hc/λ = 2.0 × 10⁻¹⁵ J = 12.4 keV.', 'Electron: p = h/λ = 6.6 × 10⁻²⁴; Eₖ = p²/2m = 2.4 × 10⁻¹⁷ J = 151 eV.', 'For the same momentum, a massive particle carries far less energy (p²/2m ≪ pc when p ≪ mc), so electrons achieve short wavelengths cheaply; they can also be focused with magnetic lenses.'] },
        { l: 3, q: 'Neutrons in equilibrium with a reactor’s moderator at 300 K have mean kinetic energy about (3/2)kT. Find their de Broglie wavelength (m = 1.675 × 10⁻²⁷ kg, k = 1.38 × 10⁻²³ J/K). Why are they ideal for studying crystals?', a: 'About 0.15 nm, comparable to atomic spacings', s: ['Eₖ = 1.5 × 1.38 × 10⁻²³ × 300 = 6.2 × 10⁻²¹ J.', 'p = √(2mEₖ) = 4.6 × 10⁻²⁴ kg m s⁻¹; λ = h/p = 1.45 × 10⁻¹⁰ m.', 'They diffract from crystal planes, and being neutral they penetrate deeply and are sensitive to light atoms and magnetism.'] }
      ]
    },

    'al-spectra': {
      big: 'Electrons in atoms can only have certain energies. When an electron drops from a higher level to a lower one, the atom emits a photon whose energy exactly matches the gap; when it absorbs a photon of exactly the right energy, it jumps up. The resulting line spectra are fingerprints that let us identify elements in a flame or a star billions of kilometres away.',
      sec: [
        { h: 'Discrete energy levels', p: ['An electron bound in an atom can occupy only certain energy levels. By convention the energy of a free electron at rest far from the atom is zero, so bound levels are negative. The lowest is the ground state; higher ones are excited states. For hydrogen, E_n = −13.6 eV/n².'], eq: R`E_n = -\frac{13.6\ \text{eV}}{n^2}\quad(\text{hydrogen})` },
        { h: 'Emission and absorption', p: ['An electron falling from level E₁ to a lower level E₂ emits one photon of energy hf = E₁ − E₂. A hot, low-pressure gas therefore emits a set of bright lines at particular wavelengths: an emission spectrum.', 'White light passing through a cooler gas loses exactly those photon energies that can lift electrons between levels; the gas re-emits them in all directions, so dark lines appear in the transmitted continuous spectrum: an absorption spectrum. The dark lines of an element sit at the same wavelengths as its bright emission lines.'], eq: R`hf = E_1 - E_2` },
        { h: 'Photons versus electrons as exciters', p: ['A photon is absorbed only if its energy exactly matches a gap (or exceeds the ionisation energy); otherwise it passes straight through. A colliding electron can hand over just part of its kinetic energy, so any electron with enough energy can excite an atom and carry the rest away.'] },
        { h: 'Ionisation', p: ['The ionisation energy is the energy needed to remove an electron from the ground state entirely: 13.6 eV for hydrogen. Photons with more than this can ionise, with the excess becoming the electron’s kinetic energy, so beyond each series limit the spectrum becomes continuous.'] },
        { h: 'Spectra in astronomy', p: ['The dark Fraunhofer lines in sunlight are absorption by gases in the Sun’s outer layers. In 1868 a line that matched no known element revealed a new one, named helium after the Greek for Sun, decades before it was found on Earth. The same lines, shifted in wavelength, measure the motion of stars and galaxies.'], warn: '**Lines are not perfectly sharp.** Real spectral lines have a width: from the motion of the atoms (Doppler broadening), collisions (pressure broadening) and the finite lifetime of excited states. Hydrogen’s single formula −13.6/n² also hides fine structure, tiny splittings from relativity, spin and quantum electrodynamics (the Lamb shift) that precision spectroscopy measures to many decimal places.' }
      ],
      eqs: [[R`hf = E_1 - E_2`, 'photon energy in a transition'], [R`E_n = -13.6/n^2\ \text{eV}`, 'hydrogen levels'], [R`\lambda\,(\text{nm}) \approx \frac{1240}{\Delta E\,(\text{eV})}`, 'shortcut'], [R`N_{\text{lines}} = \frac{n(n-1)}{2}`, 'possible lines from level n down']],
      how: ['Find the energy gap from the level diagram, in eV.', 'Convert: λ (nm) ≈ 1240 ÷ ΔE (eV).', 'For absorption by photons, the energy must match a gap exactly.', 'Count transitions by listing all pairs of levels.'],
      sum: ['Atoms have discrete energy levels; bound levels are negative.', 'hf = E₁ − E₂ for each emitted or absorbed photon.', 'Emission: bright lines; absorption: dark lines at the same wavelengths.', 'Photons must match a gap exactly; electrons can give part of their energy.', 'Hydrogen: E_n = −13.6/n² eV; ionisation energy 13.6 eV.'],
      probs: [
        { l: 1, q: 'An electron in hydrogen falls from −3.40 eV to −13.6 eV. Find the photon energy and wavelength.', a: '10.2 eV; 122 nm (ultraviolet)', s: ['ΔE = 10.2 eV; λ = 1240 ÷ 10.2 = 122 nm (Lyman-α).'] },
        { l: 1, q: 'Distinguish between an emission spectrum and an absorption spectrum.', a: 'Emission: bright lines on a dark background. Absorption: dark lines in a continuous spectrum.', s: ['Both lines come at the same wavelengths for a given element.'] },
        { l: 1, q: 'What is the ionisation energy of hydrogen in its ground state?', a: '13.6 eV', s: ['It takes the electron from −13.6 eV to 0.'] },
        { l: 2, q: 'Find the wavelength of the hydrogen line from n = 3 (−1.51 eV) to n = 2 (−3.40 eV).', a: '656 nm (red Hα)', s: ['ΔE = 1.89 eV; λ = 1240 ÷ 1.89 = 656 nm.'] },
        { l: 2, q: 'Hydrogen atoms are excited to n = 4. How many different spectral lines can they emit as they return to n = 1?', a: '6', s: ['Pairs among 4 levels: 4 × 3 ÷ 2 = 6 (4→3, 4→2, 4→1, 3→2, 3→1, 2→1).'] },
        { l: 2, q: 'Ground-state hydrogen is illuminated with 12.75 eV photons and with 11.0 eV photons. Which are absorbed?', a: 'The 12.75 eV photons only', s: ['−13.6 + 12.75 = −0.85 eV = E₄: absorbed.', '−13.6 + 11.0 = −2.6 eV matches no level: not absorbed.'] },
        { l: 2, q: 'A 12.0 eV electron collides with ground-state hydrogen. Can it excite the atom? What happens to the leftover energy?', a: 'Yes, to n = 2; it keeps 1.8 eV', s: ['It can give up 10.2 eV (to n = 2) but not 12.09 eV (to n = 3).', 'Unlike a photon, it carries away the remaining 1.8 eV as kinetic energy.'] },
        { l: 2, q: 'How was helium discovered in the Sun before it was found on Earth?', a: 'An unexplained line in the solar spectrum (1868)', s: ['Each element has a unique set of lines; one matched no known element, so a new element was proposed.'] },
        { l: 3, q: 'An atom has levels at −10.0, −5.0, −2.0 and −1.0 eV. Find the photon energies of all six possible emission lines and say which, if any, is visible (1.65–3.10 eV).', a: 'Only the 3.0 eV line (413 nm, violet) is visible', s: ['Gaps: 5.0, 8.0, 9.0 (to −10); 3.0, 4.0 (to −5); 1.0 (−1 to −2).', '3.0 eV → 413 nm: visible. 1.0 eV → 1240 nm: infrared. The rest are ultraviolet.'] },
        { l: 3, q: 'Find the shortest wavelengths (series limits) of hydrogen’s Lyman (to n = 1) and Balmer (to n = 2) series. What happens to photons beyond these limits?', a: '91 nm and 365 nm; they ionise the atom', s: ['Lyman limit: 13.6 eV ⇒ 91.2 nm. Balmer limit: 3.40 eV ⇒ 365 nm.', 'Photons of higher energy free the electron, the excess becoming its kinetic energy, so absorption becomes continuous beyond the limit.'] }
      ]
    },

    'al-decay': {
      big: 'Radioactive decay is spontaneous and random: nothing outside the nucleus affects it, and no one can say when a particular nucleus will decay. Yet each nucleus has a fixed probability of decaying per second, the decay constant, so a large sample decays exponentially with a fixed half-life. Activity, count rate and number of nuclei all follow the same curve.',
      sec: [
        { h: 'Spontaneous and random', p: ['Spontaneous: decay is unaffected by temperature, pressure or chemical state. Random: it is impossible to predict which nucleus will decay next or when; each has the same constant probability per unit time. Evidence for randomness: the count rate from a steady source fluctuates irregularly about its mean.'] },
        { h: 'Activity and the decay constant', p: ['The activity A is the number of decays per second, in becquerels (Bq). The decay constant λ is the probability per unit time that a nucleus decays, so for N nuclei the activity is λN.'], eq: R`A = -\frac{dN}{dt} = \lambda N` },
        { h: 'Exponential decay', p: ['Since the rate of decrease is proportional to the number left, N falls exponentially. Activity and count rate (once background is subtracted) follow the same law, because they are proportional to N.'], eq: R`x = x_0e^{-\lambda t}\qquad(x = N,\ A\ \text{or corrected count rate})` },
        { h: 'Half-life', p: ['The half-life is the time for half the nuclei (or the activity) to decay. Setting N = N₀/2 gives t½ = ln 2/λ. After n half-lives, (½)ⁿ remains. Plotting ln A against t gives a straight line of gradient −λ, which is the best way to extract λ from data.'], eq: R`t_{1/2} = \frac{\ln 2}{\lambda} \approx \frac{0.693}{\lambda}` },
        { h: 'Uses', list: ['Carbon dating: living things keep a steady proportion of carbon-14 (t½ = 5730 years); after death it decays, dating organic material up to about 50 000 years.', 'Medical tracers: technetium-99m (t½ = 6.0 h) emits gamma rays and decays away quickly.', 'Smoke detectors (americium-241, t½ = 432 years) and thickness gauges.'], warn: '**Exponential decay is a statistical law.** For a large N it is extremely accurate; for a handful of nuclei it is only a probability. Count rates fluctuate with a standard deviation of about √N counts, so a count of 400 is uncertain by about 5%. Carbon dating also assumes the atmospheric carbon-14 level was constant; it was not, so dates are corrected with calibration curves from tree rings.' }
      ],
      eqs: [[R`A = \lambda N`, 'activity'], [R`N = N_0e^{-\lambda t}`, 'exponential decay'], [R`t_{1/2} = \ln2/\lambda`, 'half-life'], [R`\ln A = \ln A_0 - \lambda t`, 'straight-line plot'], [R`N = \frac{m}{M}N_A`, 'number of nuclei in a mass m (M in kg/mol)']],
      how: ['Subtract background before using count rates.', 'Convert half-lives and times to the same unit; use seconds for activities in Bq.', 'Use x = x₀e^{−λt}, or (½)^{t/t½} for whole numbers of half-lives.', 'For ages, solve t = ln(x₀/x)/λ.'],
      sum: ['Decay is spontaneous and random; λ is the probability per second.', 'A = λN; exponential decay with t½ = ln2/λ.', 'N, A and corrected count rate all decay alike.', 'ln A against t: gradient −λ.', 'Statistical fluctuations ≈ √N counts.'],
      probs: [
        { l: 1, q: 'A sample has 5.0 × 10⁶ undecayed nuclei and λ = 1.0 × 10⁻³ s⁻¹. Find its activity.', a: '5.0 × 10³ Bq', s: ['A = λN = 1.0 × 10⁻³ × 5.0 × 10⁶ = 5000 Bq.'] },
        { l: 1, q: 'Find the half-life of a nuclide with λ = 0.10 per day.', a: '6.9 days', s: ['t½ = 0.693 ÷ 0.10 = 6.9 days.'] },
        { l: 1, q: 'What fraction of a sample remains after three half-lives?', a: 'One eighth', s: ['(½)³ = ⅛.'] },
        { l: 2, q: 'Iodine-131 has a half-life of 8.0 days. What fraction remains after 20 days?', a: '0.18', s: ['(½)^{20/8.0} = (½)^2.5 = 0.177.'] },
        { l: 2, q: 'A wooden tool has 30% of the carbon-14 activity of living wood. Estimate its age (t½ = 5730 years).', a: 'About 10 000 years', s: ['t = ln(1/0.30) × t½/ln 2 = 1.204 × 5730 ÷ 0.693 = 9950 years.'] },
        { l: 2, q: 'Find the activity of 1.0 μg of cobalt-60 (half-life 5.27 years, molar mass 60 g/mol).', a: 'About 42 MBq', s: ['N = 1.0 × 10⁻⁹ kg ÷ (60 × 1.66 × 10⁻²⁷ kg) = 1.0 × 10¹⁶.', 'λ = 0.693 ÷ (5.27 × 3.16 × 10⁷ s) = 4.2 × 10⁻⁹ s⁻¹.', 'A = λN = 4.2 × 10⁷ Bq.'] },
        { l: 2, q: 'How do you find λ from a set of count rates measured over time?', a: 'Subtract background, plot ln(corrected count rate) against time: the gradient is −λ', s: ['A straight line confirms exponential decay; scatter shows the random fluctuations.'] },
        { l: 2, q: 'If the decay of a sample follows a smooth exponential, in what sense is decay random?', a: 'Individual decays are unpredictable; the smooth curve is the average over huge numbers', s: ['Each nucleus has the same fixed probability per second.', 'With 10²⁰ nuclei the fluctuations are utterly negligible in relative terms.'] },
        { l: 3, q: 'A patient is injected with technetium-99m of activity 400 MBq (t½ = 6.0 h). What is the activity after 24 hours, and why is such a short half-life chosen?', a: '25 MBq; enough time for the scan, little lingering dose', s: ['24 h = 4 half-lives: 400 ÷ 2⁴ = 25 MBq.', 'The scan takes minutes to hours; a short half-life means the patient’s dose falls quickly afterwards, and gamma rays escape the body to reach the camera.'] },
        { l: 3, q: 'A Geiger counter records 400 counts in one minute from a steady source. What is the uncertainty from randomness alone? How many counts would be needed for 1% precision?', a: 'About ±20 counts (5%); 10 000 counts', s: ['For random decay the standard deviation is about √N = 20 counts: 5%.', 'Fractional uncertainty = 1/√N, so 1% needs N = 10 000: count for 25 minutes, or move closer.'] }
      ]
    },

    'al-medical': {
      big: 'Hospitals use physics to see inside the body without cutting it open. Ultrasound reflects from boundaries between tissues; X-rays are absorbed more by bone than by soft tissue, and CT combines many X-ray views into a 3D picture; PET follows a radioactive tracer by catching the pairs of gamma rays from positron annihilation.',
      sec: [
        { h: 'Producing and detecting ultrasound', p: ['Ultrasound is sound above 20 kHz; medical scanners use a few megahertz. A piezoelectric crystal changes shape when a p.d. is applied across it, and produces a p.d. when it is squeezed. An alternating p.d. at the crystal’s resonant frequency makes it vibrate and emit ultrasound; the same crystal then detects the returning echoes. Pulses are used so that echo times give depths.'] },
        { h: 'Acoustic impedance and reflection', p: ['Each material has an acoustic impedance Z = ρc (density × speed of sound). At a boundary, the fraction of the intensity reflected depends on the mismatch. Soft tissues differ only a little, giving weak echoes; air and tissue differ enormously, so almost everything reflects. A coupling gel removes the air between probe and skin.'], eq: R`Z = \rho c,\qquad \frac{I_R}{I_0} = \frac{(Z_2 - Z_1)^2}{(Z_2 + Z_1)^2}` },
        { h: 'X-rays', p: ['X-rays are produced when electrons, accelerated through tens of kilovolts, strike a metal target such as tungsten. Most of their energy becomes heat (hence rotating, cooled anodes); a few per cent becomes X-rays: a continuous spectrum up to a maximum photon energy eV, plus characteristic lines of the target.', 'A beam is attenuated exponentially as it passes through matter. Bone has a much larger attenuation coefficient than soft tissue, giving contrast on the image.'], eq: R`\lambda_{\min} = \frac{hc}{eV},\qquad I = I_0e^{-\mu x}` },
        { h: 'CT scanning', p: ['In computed tomography an X-ray tube and detectors rotate around the patient, recording attenuation along thousands of paths through each slice. A computer reconstructs the attenuation of every small volume element (voxel), building a 3D image of the body slice by slice, at the cost of a much larger radiation dose than a single X-ray.'] },
        { h: 'PET scanning', p: ['A tracer such as fluorodeoxyglucose labelled with fluorine-18, a β⁺ emitter, is injected and concentrates where cells use glucose rapidly (for example in tumours). Each positron soon meets an electron and they annihilate into two 511 keV gamma photons travelling in opposite directions. Detectors around the patient record pairs that arrive at the same time; the annihilation lies on the line joining them, and many lines locate the tracer.'], eq: R`E_\gamma = m_ec^2 = 0.511\ \text{MeV}`, warn: '**Images are models of the body.** Ultrasound scanners assume one speed of sound (1540 m/s) in all tissue, so depths in fat or bone are slightly misplaced. CT numbers depend on the X-ray spectrum (“beam hardening” as soft photons are absorbed first). PET’s resolution is limited because positrons travel a millimetre or so before annihilating and the photons are not exactly back to back.' }
      ],
      eqs: [[R`Z = \rho c`, 'acoustic impedance'], [R`\frac{I_R}{I_0} = \left(\frac{Z_2 - Z_1}{Z_2 + Z_1}\right)^2`, 'intensity reflection coefficient'], [R`I = I_0e^{-\mu x}`, 'attenuation'], [R`\lambda_{\min} = hc/eV`, 'shortest X-ray wavelength'], [R`E = 2m_ec^2`, 'energy released in positron–electron annihilation']],
      how: ['Compute Z for each medium, then the reflection coefficient.', 'For attenuation, use e^{−μx} with consistent length units.', 'For X-ray tubes, the maximum photon energy equals eV.', 'For PET, use conservation of energy and momentum in annihilation.'],
      sum: ['Piezoelectric transducers emit and detect ultrasound pulses.', 'Z = ρc; big mismatch → strong reflection; gel removes air.', 'X-rays: electrons hit a target; λ_{min} = hc/eV; I = I₀e^{−μx}.', 'CT reconstructs 3D attenuation from many angles.', 'PET: β⁺ tracer, annihilation into two 511 keV photons back to back.'],
      probs: [
        { l: 1, q: 'Find the acoustic impedance of soft tissue (ρ = 1060 kg m⁻³, c = 1540 m/s).', a: '1.63 × 10⁶ kg m⁻² s⁻¹', s: ['Z = ρc = 1060 × 1540 = 1.63 × 10⁶ kg m⁻² s⁻¹.'] },
        { l: 1, q: 'What is the energy of each photon produced in PET annihilation?', a: '511 keV', s: ['Each equals the rest energy of an electron, mₑc².'] },
        { l: 1, q: 'Why is gel spread between an ultrasound probe and the skin?', a: 'To remove the air layer, which would reflect almost all the ultrasound', s: ['The gel’s impedance is close to skin’s, so most ultrasound enters the body.'] },
        { l: 2, q: 'What fraction of ultrasound intensity reflects at a fat (Z = 1.38 × 10⁶) to muscle (Z = 1.70 × 10⁶) boundary?', a: 'About 1%', s: ['(1.70 − 1.38)² ÷ (1.70 + 1.38)² = 0.32² ÷ 3.08² = 0.011.'] },
        { l: 2, q: 'What fraction reflects at an air (Z = 430) to skin (Z = 1.63 × 10⁶) boundary?', a: '99.9%', s: ['((1.63 × 10⁶ − 430) ÷ (1.63 × 10⁶ + 430))² = 0.999.'] },
        { l: 2, q: 'An X-ray tube operates at 100 kV. Find the shortest wavelength produced. Why must the anode be cooled?', a: '0.0124 nm; about 99% of the electrons’ energy becomes heat', s: ['λ_{min} = hc/(eV) = 1240 ÷ 100 000 nm = 1.24 × 10⁻¹¹ m.', 'Only about 1% of the beam energy becomes X-rays; the rest heats the target.'] },
        { l: 2, q: 'X-rays with μ = 0.35 cm⁻¹ in soft tissue pass through 10 cm of it. What fraction gets through?', a: 'About 3%', s: ['I/I₀ = e^{−0.35 × 10} = e^{−3.5} = 0.030.'] },
        { l: 2, q: 'Why are the two PET photons emitted in almost exactly opposite directions?', a: 'The electron and positron are nearly at rest, so total momentum is about zero', s: ['Two photons with zero total momentum must have equal energies and opposite directions.'] },
        { l: 3, q: 'Find the wavelength of a 511 keV annihilation photon. Why are PET detectors made of dense crystals?', a: '2.4 × 10⁻¹² m; such energetic photons pass through thin, light materials', s: ['λ = hc/E = 6.63 × 10⁻³⁴ × 3.0 × 10⁸ ÷ (0.511 × 10⁶ × 1.6 × 10⁻¹⁹) = 2.4 × 10⁻¹² m.', 'Dense, high-Z scintillator crystals stop these photons efficiently and turn their energy into flashes of light.'] },
        { l: 3, q: 'An X-ray beam crosses 2.0 cm of bone (μ = 0.50 cm⁻¹) or 2.0 cm of soft tissue (μ = 0.20 cm⁻¹). Find the fraction transmitted in each case, and explain how this produces the image.', a: '37% and 67%', s: ['Bone: e^{−1.0} = 0.37. Soft tissue: e^{−0.40} = 0.67.', 'Less X-ray reaches the detector behind bone, so bone appears white against darker tissue. Contrast agents (barium, iodine) raise μ to show soft organs.'] }
      ]
    },

    'al-astro': {
      big: 'A star’s luminosity is its total power output. Measuring how bright it looks from Earth, and knowing its luminosity from some independent clue (a standard candle), gives its distance by the inverse square law. Its colour gives its surface temperature through Wien’s law, and luminosity plus temperature give its radius through the Stefan–Boltzmann law.',
      sec: [
        { h: 'Luminosity and flux', p: ['The luminosity L of a star is the total power it radiates. At distance d this power is spread over a sphere of area 4πd², so the radiant flux intensity (power per unit area) received is F = L/4πd². Our Sun: L = 3.83 × 10²⁶ W, giving about 1360 W m⁻² at Earth.'], eq: R`F = \frac{L}{4\pi d^2}` },
        { h: 'Standard candles', p: ['A standard candle is an object of known luminosity. Measure its flux and the distance follows: d = √(L/4πF). Cepheid variable stars (whose pulsation period reveals their luminosity) reach tens of millions of light-years; type Ia supernovae, all exploding with nearly the same peak luminosity, reach billions.'] },
        { h: 'Wien’s displacement law', p: ['A hot object’s spectrum peaks at a wavelength inversely proportional to its thermodynamic temperature. Stars peaking in the blue are hotter than red ones. The Sun peaks near 500 nm, giving about 5800 K.'], eq: R`\lambda_{\max}T = 2.9\times10^{-3}\ \text{m K}` },
        { h: 'Stefan–Boltzmann law', p: ['The power radiated per unit area of a black body is σT⁴, with σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴. For a spherical star of radius r, L = 4πr²σT⁴. Knowing L (from distance and flux) and T (from Wien) gives r.'], eq: R`L = 4\pi r^2\sigma T^4` },
        { h: 'Giants and dwarfs', p: ['Cool but extremely luminous stars must be huge: red giants and supergiants such as Betelgeuse, hundreds of times the Sun’s radius. Hot but faint stars must be tiny: white dwarfs, about the size of Earth.'], warn: '**Stars are not perfect black bodies, and space is not empty.** Absorption lines and atmospheres distort stellar spectra, so “temperatures” from Wien’s law are approximate. Interstellar dust dims and reddens starlight, making stars seem further away and cooler unless corrected. Standard candles also need calibrating against nearer objects with measured distances (parallax), so errors propagate up the distance ladder.' }
      ],
      eqs: [[R`F = L/4\pi d^2`, 'inverse square law'], [R`d = \sqrt{L/4\pi F}`, 'distance from a standard candle'], [R`\lambda_{\max}T = 2.9\times10^{-3}\ \text{m K}`, 'Wien’s law'], [R`L = 4\pi r^2\sigma T^4`, 'Stefan–Boltzmann law'], [R`\sigma = 5.67\times10^{-8}\ \text{W m}^{-2}\text{K}^{-4}`, 'Stefan–Boltzmann constant']],
      how: ['For distance: identify the standard candle’s L, measure F, use d = √(L/4πF).', 'For temperature: Wien’s law from λ_{max}.', 'For radius: rearrange L = 4πr²σT⁴.', 'Use ratios when comparing stars: L ∝ r²T⁴.'],
      sum: ['Luminosity = total power; flux F = L/4πd².', 'Standard candles (Cepheids, type Ia supernovae) give distances.', 'Wien: λ_{max} T = 2.9 × 10⁻³ m K.', 'Stefan–Boltzmann: L = 4πr²σT⁴.', 'Cool + luminous = giant; hot + faint = dwarf.'],
      probs: [
        { l: 1, q: 'The Sun’s spectrum peaks at 500 nm. Estimate its surface temperature.', a: '5800 K', s: ['T = 2.9 × 10⁻³ ÷ 500 × 10⁻⁹ = 5800 K.'] },
        { l: 1, q: 'At what wavelength does a 3000 K star’s spectrum peak? What colour does it look?', a: '970 nm (infrared); it looks red', s: ['λ = 2.9 × 10⁻³ ÷ 3000 = 9.7 × 10⁻⁷ m. The visible part of its spectrum is dominated by red.'] },
        { l: 1, q: 'Define luminosity and standard candle.', a: 'Luminosity: total power radiated. Standard candle: an object of known luminosity.', s: ['Comparing a standard candle’s luminosity with its observed flux gives its distance.'] },
        { l: 2, q: 'Calculate the Sun’s luminosity from its radius (6.96 × 10⁸ m) and surface temperature (5772 K).', a: '3.8 × 10²⁶ W', s: ['L = 4π × (6.96 × 10⁸)² × 5.67 × 10⁻⁸ × 5772⁴ = 3.83 × 10²⁶ W.'] },
        { l: 2, q: 'Find the solar flux at Earth, 1.50 × 10¹¹ m from the Sun.', a: 'About 1350 W m⁻²', s: ['F = 3.83 × 10²⁶ ÷ (4π × (1.50 × 10¹¹)²) = 1350 W m⁻².'] },
        { l: 2, q: 'A Cepheid of luminosity 1.0 × 10³⁰ W gives a flux of 1.0 × 10⁻¹² W m⁻² at Earth. How far away is it, in metres and light-years?', a: '2.8 × 10²⁰ m; about 30 000 ly', s: ['d = √(L/4πF) = √(1.0 × 10³⁰ ÷ (4π × 1.0 × 10⁻¹²)) = 2.8 × 10²⁰ m.', '÷ 9.46 × 10¹⁵ m per ly ≈ 30 000 ly.'] },
        { l: 2, q: 'A red supergiant has T = 3600 K and L = 1.0 × 10⁵ times the Sun’s. Find its radius in solar radii.', a: 'About 800 solar radii', s: ['L = 3.83 × 10³¹ W; r = √(L/(4πσT⁴)) = 5.7 × 10¹¹ m.', '÷ 6.96 × 10⁸ m ≈ 810 R☉: it would engulf the orbit of Mars.'] },
        { l: 2, q: 'A white dwarf has T = 20 000 K and L = 0.010 times the Sun’s. Estimate its radius.', a: 'About 5800 km, Earth-sized', s: ['r = √(3.83 × 10²⁴ ÷ (4π × 5.67 × 10⁻⁸ × (2.0 × 10⁴)⁴)) = 5.8 × 10⁶ m.'] },
        { l: 3, q: 'Why do astronomers need standard candles at all, rather than measuring distances directly? Name one source of systematic error in using them.', a: 'Direct (parallax) distances only work for nearby stars; dust dimming is a systematic error', s: ['Parallax angles become too small to measure beyond a few thousand light-years.', 'Standard candles are calibrated on nearer ones whose distances are known, then extend the ladder.', 'Interstellar dust absorbs light, so F is too small and d comes out too large unless corrected.'] },
        { l: 3, q: 'Two stars have the same luminosity, but one has twice the surface temperature of the other. Compare their radii.', a: 'The hotter one has a quarter of the radius', s: ['L ∝ r²T⁴ is the same: r² ∝ 1/T⁴, so r ∝ 1/T².', 'Doubling T requires r to be 1/4.'] }
      ]
    },

    'al-cosmology': {
      big: 'Light from distant galaxies is stretched to longer wavelengths, and the further away a galaxy is, the more it is stretched. Interpreted as motion, that means galaxies recede with speeds proportional to their distances: Hubble’s law. Run the expansion backwards and everything was once together in a hot, dense state: the Big Bang, about 14 billion years ago.',
      sec: [
        { h: 'Redshift', p: ['Spectral lines from a receding source are shifted to longer wavelengths. For speeds much less than c, the fractional shift equals v/c. A shift to shorter wavelengths (blueshift) means approach, as for the nearby Andromeda galaxy.'], eq: R`z = \frac{\Delta\lambda}{\lambda} \approx \frac{\Delta f}{f} \approx \frac{v}{c}` },
        { h: 'Hubble’s law', p: ['Measuring distances (with standard candles) and recession speeds (from redshift) of many galaxies, Hubble found in 1929 that recession speed is proportional to distance. The constant H₀ is about 70 km s⁻¹ Mpc⁻¹ (1 Mpc = 3.09 × 10²² m), which is about 2.3 × 10⁻¹⁸ s⁻¹.'], eq: R`v = H_0d` },
        { h: 'The expanding Universe', p: ['Hubble’s law does not mean we are at the centre. If space itself is expanding uniformly, every observer sees every other galaxy receding at a speed proportional to distance, like raisins in a rising loaf.'] },
        { h: 'Age of the Universe', p: ['If galaxies have always moved at their present speeds, a galaxy at distance d set off from here a time d/v = 1/H₀ ago. With H₀ = 70 km s⁻¹ Mpc⁻¹ that is about 14 billion years: close to the best current estimate, 13.8 billion years.'], eq: R`t_0 \approx \frac{1}{H_0}` },
        { h: 'Evidence for the Big Bang', list: ['The expansion itself (Hubble’s law).', 'The cosmic microwave background: radiation filling all space, a near-perfect black body at 2.7 K, the cooled glow of the hot early Universe.', 'The abundances of light elements: about a quarter of ordinary matter is helium, as predicted for nuclear fusion in the first few minutes.'], warn: '**Two hidden assumptions, and an open problem.** z ≈ v/c only holds for z ≪ 1; for distant quasars with z > 1 the redshift reflects how much space has stretched (1 + z = ratio of the Universe’s size now to then), not a speed faster than light. 1/H₀ assumes constant expansion, while gravity slowed it and dark energy now speeds it up. And H₀ itself is disputed: the cosmic microwave background implies about 67 km s⁻¹ Mpc⁻¹, while nearby standard candles give about 73. This “Hubble tension” is either an unknown systematic error or a sign of new physics.' }
      ],
      eqs: [[R`z = \Delta\lambda/\lambda \approx v/c`, 'redshift (v ≪ c)'], [R`v = H_0 d`, 'Hubble’s law'], [R`t_0 \approx 1/H_0`, 'age estimate'], [R`1\ \text{Mpc} = 3.09\times10^{22}\ \text{m}`, 'megaparsec'], [R`1 + z = \frac{a_{\text{now}}}{a_{\text{then}}}`, 'cosmological redshift (general)']],
      how: ['Find z from the shift of a known line, then v = zc.', 'Convert H₀ to s⁻¹ (or keep km s⁻¹ Mpc⁻¹ with d in Mpc).', 'For ages, take 1/H₀ in seconds and convert to years.', 'For large z, use 1 + z as a size ratio, not v/c.'],
      sum: ['Redshift z = Δλ/λ ≈ v/c for nearby galaxies.', 'Hubble’s law: v = H₀d, H₀ ≈ 70 km s⁻¹ Mpc⁻¹.', 'Uniform expansion: no centre.', 'Age ≈ 1/H₀ ≈ 14 billion years.', 'Evidence: expansion, CMB at 2.7 K, light-element abundances.'],
      probs: [
        { l: 1, q: 'The hydrogen line at 656.3 nm is observed at 662.9 nm in a galaxy’s spectrum. Find z and the galaxy’s speed.', a: 'z = 0.010; 3.0 × 10⁶ m/s, receding', s: ['z = 6.6 ÷ 656.3 = 0.0101.', 'v = zc = 3.0 × 10⁶ m/s.'] },
        { l: 1, q: 'Using H₀ = 70 km s⁻¹ Mpc⁻¹, how far away is a galaxy receding at 3000 km/s?', a: 'About 43 Mpc', s: ['d = v/H₀ = 3000 ÷ 70 = 43 Mpc.'] },
        { l: 1, q: 'List three pieces of evidence for the Big Bang.', a: 'Galaxies’ redshifts (expansion), the cosmic microwave background, the abundance of helium', s: ['Each was predicted or explained by a hot, dense, expanding early Universe.'] },
        { l: 2, q: 'Convert H₀ = 70 km s⁻¹ Mpc⁻¹ into s⁻¹ and find 1/H₀ in years.', a: '2.3 × 10⁻¹⁸ s⁻¹; 14 billion years', s: ['H₀ = 70 × 10³ ÷ 3.09 × 10²² = 2.27 × 10⁻¹⁸ s⁻¹.', '1/H₀ = 4.4 × 10¹⁷ s = 1.4 × 10¹⁰ years.'] },
        { l: 2, q: 'A galaxy is 100 Mpc away. Find its recession speed, z, and the observed shift of a 500 nm line.', a: '7000 km/s; 0.023; 11.7 nm', s: ['v = 70 × 100 = 7000 km/s; z = 7000 ÷ 300 000 = 0.023.', 'Δλ = 0.023 × 500 = 11.7 nm.'] },
        { l: 2, q: 'The Andromeda galaxy approaches us at 300 km/s. What shift does it give the 656.3 nm hydrogen line?', a: '0.66 nm towards the blue', s: ['Δλ = (v/c)λ = (300 ÷ 300 000) × 656.3 = 0.66 nm, to a shorter wavelength.', 'Local gravity beats the expansion at such small distances.'] },
        { l: 2, q: 'Why is 1/H₀ only an estimate of the Universe’s age?', a: 'It assumes the expansion rate has always been the same', s: ['Gravity slowed the early expansion and dark energy has speeded it up recently; the effects nearly cancel today, which is why 1/H₀ is close to 13.8 billion years.'] },
        { l: 2, q: 'The cosmic microwave background has a black-body temperature of 2.725 K. Where does its spectrum peak?', a: 'About 1.1 mm, in the microwave region', s: ['λ_{max} = 2.9 × 10⁻³ ÷ 2.725 = 1.06 × 10⁻³ m.'] },
        { l: 3, q: 'Measurements give H₀ = 67.4 km s⁻¹ Mpc⁻¹ from the cosmic microwave background and 73.0 from nearby standard candles. Find 1/H₀ in billions of years for each. Why does the disagreement matter?', a: '14.5 and 13.4 billion years; it may reveal new physics or an unknown error', s: ['1/H₀ in Gyr ≈ 977.8 ÷ H₀(km s⁻¹ Mpc⁻¹): 14.5 and 13.4.', 'The two methods probe the early and the late Universe. If neither has a hidden systematic error, the standard model of cosmology needs changing.'] },
        { l: 3, q: 'A quasar has z = 2.0. Explain why this does not mean it recedes at twice the speed of light, and what z tells you instead.', a: 'Cosmological redshift is the stretching of space; the Universe was a third of its present size when the light left', s: ['z ≈ v/c is only valid for small z.', 'In general 1 + z equals the factor by which space has expanded during the light’s journey: here 3.', 'So the light was emitted when distances between galaxies were one third of today’s.'] }
      ]
    }
  });
})();
